/** #RRGGBB + alpha → rgba() string (mirrors the web app gradient chrome). */
function hexA(hex: string, a: number): string {
  const n = hex.replace("#", "");
  if (n.length !== 6) return hex;
  const r = parseInt(n.slice(0, 2), 16);
  const g = parseInt(n.slice(2, 4), 16);
  const b = parseInt(n.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${a})`;
}

function DetailRow({
  icon,
  label,
  value,
}: {
  icon: keyof typeof Ionicons.glyphMap;
  label: string;
  value: string;
}) {
  return (
    <View style={s.detailRow}>
      <View style={s.detailIcon}>
        <Ionicons name={icon} size={17} color={colors.goldDark} />
      </View>
      <View style={s.detailBody}>
        <Text style={s.detailLabel}>{label}</Text>
        <Text style={s.detailValue}>{value}</Text>
      </View>
    </View>
  );
}

function goBackTeam(teamId: string) {
  if (router.canGoBack()) router.back();
  else
    router.replace({
      pathname: "/sports/[teamId]" as any,
      params: { teamId },
    });
}

export default function PlayerScreen() {
  const { teamId, player } = useLocalSearchParams<{
    teamId?: string;
    player?: string;
  }>();
  const insets = useSafeAreaInsets();

  const { data: catalog, loading, error } = useSportsCatalog();
  const { find: findClub } = useClubs();

  const team = teamId && catalog ? catalog.getTeam(teamId) : undefined;
  const rec =
    teamId && player ? catalog?.findPlayer(teamId, player) : undefined;
  const [reg, setReg] = useState<RegisteredPlayer | null>(null);
  const [checked, setChecked] = useState<boolean>(!!rec);
  const { check } = useMyRegistration();
  const [already, setAlready] = useState<MyRegistration | null>(null);
  // The "Register to join" CTA checks for an existing squad spot first and
  // opens the status sheet instead of skipping to the registration form.
  const openRegister = async () => {
    if (!team) return;
    const mine = await check();
    if (mine) {
      setAlready(mine);
      return;
    }
    router.push({
      pathname: "/sports/[teamId]/register" as any,
      params: { teamId: team.id },
    });
  };

  // Reserves and waitlist players are not part of the static squad sheet, so
  // fall back to the roster API before declaring "Player not found".
  useEffect(() => {
    if (rec || !teamId || !player) return;
    let active = true;
    fetchRoster(teamId)
      .then((payload) => {
        if (!active) return;
        const hit = (payload.registrations ?? []).find(
          (r) => playerSlug(r.name) === player,
        );
        setReg(hit ?? null);
        setChecked(true);
      })
      .catch(() => {
        if (active) setChecked(true);
      });
    return () => {
      active = false;
    };
  }, [teamId, player, rec]);

  if (loading) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={s.missingWrap}>
            <ActivityIndicator size="large" color={colors.goldDark} />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (error || !catalog) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={s.missingWrap}>
            <Ionicons
              name="alert-circle-outline"
              size={40}
              color={colors.gold}
            />
            <Text style={s.missingTitle}>Teams unavailable</Text>
            <Text style={s.missingText}>{error ?? ""}</Text>
            <TouchableOpacity
              style={s.missingBtn}
              activeOpacity={0.85}
              onPress={() => router.replace("/sports" as any)}
            >
              <Text style={s.missingBtnText}>Back to sports</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (!team || (!rec && checked && !reg)) {
    if (!team || !rec) {
      return (
        <SafeAreaProvider>
          <SafeAreaView style={s.safe} edges={["top"]}>
            <StatusBar style="dark" />
            <View style={s.missingWrap}>
              <Ionicons
                name="alert-circle-outline"
                size={40}
                color={colors.gold}
              />
              <Text style={s.missingTitle}>Player not found</Text>
              <TouchableOpacity
                style={s.missingBtn}
                activeOpacity={0.85}
                onPress={() => router.replace("/sports" as any)}
              >
                <Text style={s.missingBtnText}>Back to sports</Text>
              </TouchableOpacity>
            </View>
          </SafeAreaView>
        </SafeAreaProvider>
      );
    }
  }

  if (!rec && !checked) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={s.missingWrap}>
            <ActivityIndicator size="large" color={colors.goldDark} />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const theme = SPORT_THEME[team.sport];
  const club = findClub(team.clubSlug);
  const clubColors: [string, string] = club
    ? [club.color, club.colorDark]
    : (theme.colors as [string, string]);

  type ProfileView = {
    photo: string | null;
    number: number | null;
    name: string;
    position: string;
    chips: { icon: keyof typeof Ionicons.glyphMap; text: string }[];
    rows: {
      icon: keyof typeof Ionicons.glyphMap;
      label: string;
      value: string;
    }[];
    stats: { label: string; value: string }[];
    bio: string | null;
  };

  const view: ProfileView | null = rec
    ? {
        photo: rec.image ? imgDetail(rec.image) : null,
        number: rec.number ?? null,
        name: rec.name,
        position: rec.position,
        chips: [
          ...(rec.age != null
            ? [{ icon: "person-outline", text: `Age ${rec.age}` }]
            : []),
          ...(rec.height
            ? [{ icon: "resize-outline", text: rec.height }]
            : []),
          ...(rec.hometown
            ? [{ icon: "location-outline", text: rec.hometown }]
            : []),
        ] as ProfileView["chips"],
        rows: [
          ...(rec.number != null
            ? [
                {
                  icon: "shirt-outline",
                  label: "Squad number",
                  value: `No. ${rec.number}`,
                },
              ]
            : []),
          { icon: "locate-outline", label: "Position", value: rec.position },
          ...(rec.age != null
            ? [
                {
                  icon: "person-outline",
                  label: "Age",
                  value: `${rec.age} years`,
                },
              ]
            : []),
          ...(rec.height
            ? [{ icon: "resize-outline", label: "Height", value: rec.height }]
            : []),
          ...(rec.side
            ? [
                {
                  icon: "flag-outline",
                  label: "Preferred side",
                  value: rec.side,
                },
              ]
            : []),
          ...(rec.hometown
            ? [
                {
                  icon: "location-outline",
                  label: "Hometown",
                  value: rec.hometown,
                },
              ]
            : []),
          ...(rec.joined != null
            ? [
                {
                  icon: "calendar-outline",
                  label: "Joined",
                  value: String(rec.joined),
                },
              ]
            : []),
        ] as ProfileView["rows"],
        stats: rec.stats ?? [],
        bio: rec.bio ?? null,
      }
    : reg
      ? {
          photo: reg.photoUrl || null,
          number: null,
          name: reg.name,
          position: reg.position,
          chips: [
            { icon: "resize-outline", text: `${reg.heightCm} cm` },
            { icon: "footsteps-outline", text: `${reg.foot} foot` },
            {
              icon: "time-outline",
              text: reg.status === "waitlist" ? "Waiting list" : "Registered",
            },
          ],
          rows: [
            { icon: "shirt-outline", label: "Position", value: reg.position },
            {
              icon: "people-outline",
              label: "Squad status",
              value: reg.status === "waitlist" ? "Waiting list" : "Registered",
            },
            {
              icon: "resize-outline",
              label: "Height",
              value: `${reg.heightCm} cm`,
            },
            {
              icon: "footsteps-outline",
              label: "Preferred foot",
              value: reg.foot,
            },
            {
              icon: "list-outline",
              label: "Queue order",
              value: `#${reg.order}`,
            },
            {
              icon: "calendar-outline",
              label: "Registered",
              value: new Date(reg.createdAt).toLocaleDateString(),
            },
          ],
          stats: [
            { label: "Position code", value: reg.positionCode },
            { label: "Queue order", value: `#${reg.order}` },
            { label: "Preferred hand", value: reg.hand },
          ],
          bio: null,
        }
      : null;

  if (!view) return null;
  const first = view.name.split(" ")[0];

  return (
    <SafeAreaProvider>
      <SafeAreaView style={s.safe} edges={["top"]}>
        <StatusBar style="dark" />
        <ScrollView
          contentContainerStyle={[
            s.content,
            { paddingBottom: 40 + insets.bottom },
          ]}
          showsVerticalScrollIndicator={false}
        >
          <LinearGradient
            colors={[
              "rgba(9,23,15,0.94)",
              hexA(clubColors[1], 0.86),
              hexA(clubColors[0], 0.62),
            ]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={s.hero}
          >
            <ExpoImage
              source={{ uri: teamHeroPhoto(team) }}
              style={StyleSheet.absoluteFill}
              contentFit="cover"
              transition={250}
            />
            <View style={s.heroScrim} />
            <View
              style={[
                s.heroGlow,
                { backgroundColor: clubColors[0], opacity: 0.3 },
              ]}
            />
            <View
              style={[
                s.heroRing,
                { borderColor: `${hexA(clubColors[0], 1)}59` },
              ]}
            />

            <TouchableOpacity
              style={s.heroBack}
              activeOpacity={0.85}
              onPress={() => goBackTeam(team.id)}
              accessibilityLabel="Back to the squad"
            >
              <Ionicons name="chevron-back" size={20} color={colors.white} />
            </TouchableOpacity>
            <Text style={s.heroBrand}>
              RELATE · {team.sport.toUpperCase()} ·{" "}
              {team.initials.toUpperCase()}
            </Text>

            <View style={s.heroPhotoWrap}>
              <View style={s.heroPhotoRing}>
                {view.photo ? (
                  <ExpoImage
                    source={{ uri: getOptimizedImageUrl(view.photo, 160) }}
                    style={s.heroPhoto}
                    contentFit="cover"
                    transition={250}
                  />
                ) : (
                  <LinearGradient
                    colors={clubColors}
                    start={{ x: 0, y: 0 }}
                    end={{ x: 1, y: 1 }}
                    style={s.heroPhotoFallback}
                  >
                    <Text style={s.heroPhotoFallbackText}>
                      {view.name
                        .split(" ")
                        .map((w) => w[0])
                        .join("")
                        .slice(0, 2)
                        .toUpperCase()}
                    </Text>
                  </LinearGradient>
                )}
              </View>
              {view.number != null ? (
                <View style={s.heroNumberBadge}>
                  <Text style={s.heroNumberText}>{view.number}</Text>
                </View>
              ) : null}
            </View>

            <Text style={s.heroEyebrow}>
              {club?.name ?? "Relate"} · {team.name}
            </Text>
            <Text style={s.heroTitle}>{view.name}</Text>
            <Text style={s.heroPosition}>{view.position}</Text>

            <View style={s.heroChips}>
              {view.chips.map((c) => (
                <View key={c.text} style={s.heroChip}>
                  <Ionicons
                    name={c.icon}
                    size={12}
                    color="rgba(255,255,255,0.9)"
                  />
                  <Text style={s.heroChipText}>{c.text}</Text>
                </View>
              ))}
            </View>
          </LinearGradient>

          <View style={s.body}>
            <Text style={s.sectionEyebrow}>Player profile</Text>
            <Text style={s.sectionTitle}>At a glance</Text>
            <View style={s.detailCard}>
              {view.rows.map((r) => (
                <DetailRow
                  key={r.label}
                  icon={r.icon}
                  label={r.label}
                  value={r.value}
                />
              ))}
            </View>

            <View style={s.sectionGap}>
              <Text style={s.sectionEyebrow}>This season</Text>
              <Text style={s.sectionTitle}>{team.initials} stats</Text>
              <View style={s.statsGrid}>
                {view.stats.map((st) => (
                  <View key={st.label} style={s.statCard}>
                    <Text style={s.statValue}>{st.value}</Text>
                    <Text style={s.statLabel}>{st.label}</Text>
                  </View>
                ))}
              </View>
            </View>

            {view.bio ? (
              <View style={[s.aboutCard, s.sectionGap]}>
                <Text style={s.aboutTitle}>About {first}</Text>
                <Text style={s.aboutText}>{view.bio}</Text>
              </View>
            ) : null}

            <LinearGradient
              colors={[clubColors[0], clubColors[1]]}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={[s.ctaCard, s.sectionGap]}
            >
              <Text style={s.ctaTitle}>Want to play alongside {first}?</Text>
              <Text style={s.ctaSub}>
                Register for {team.name} and join the squad.
              </Text>
              <TouchableOpacity
                style={s.ctaBtn}
                activeOpacity={0.9}
                onPress={() => void openRegister()}
                accessibilityLabel={`Register to join ${team.name}`}
              >
                <Text style={s.ctaBtnText}>Register to join</Text>
                <Ionicons
                  name="arrow-forward"
                  size={16}
                  color={colors.forestDark}
                />
              </TouchableOpacity>
            </LinearGradient>

            <TouchableOpacity
              style={s.backLink}
              activeOpacity={0.7}
              onPress={() => goBackTeam(team.id)}
            >
              <Ionicons name="chevron-back" size={14} color={colors.goldDark} />
              <Text style={s.backLinkText}>Back to the {team.name} squad</Text>
            </TouchableOpacity>
          </View>
        </ScrollView>
      </SafeAreaView>
      <AlreadyOnTeamModal
        registration={already}
        currentTeamId={team?.id}
        onClose={() => setAlready(null)}
      />
    </SafeAreaProvider>
  );
}

