const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

/** Report periods are free text; accept "July 2026" / "Jul 2026". */
function parsePeriod(period: string): { year: number; month: number } | null {
  const m = period
    .trim()
    .match(
      /^(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+(\d{4})$/i,
    );
  if (!m) return null;
  const month = MONTHS.findIndex(
    (name) => name.slice(0, 3).toLowerCase() === m[1].slice(0, 3).toLowerCase(),
  );
  if (month < 0) return null;
  return { year: parseInt(m[2], 10), month };
}

/** Older API responses have no `raised`; they still carry the balance inside income. */
const raisedOf = (r: FinancialReportSummary) =>
  r.raised ?? r.income - (r.balanceBroughtDown ?? 0);

function chartLabel(period: string): string {
  const parsed = parsePeriod(period);
  if (parsed) return MONTHS[parsed.month].slice(0, 3);
  return period.trim().slice(0, 3) || "—";
}

function chartSortKey(r: FinancialReportSummary): number {
  const parsed = parsePeriod(r.period);
  if (parsed) return Date.UTC(parsed.year, parsed.month, 1);
  const created = new Date(r.createdAt).getTime();
  return Number.isFinite(created) ? created : 0;
}

/** Short money for table cells: R12.5k, -R800. */
const fmtCompact = (n: number) => {
  const sign = n < 0 ? "-" : "";
  const abs = Math.abs(n);
  const body =
    abs >= 1000 ? `${(abs / 1000).toFixed(1).replace(/\.0$/, "")}k` : `${Math.round(abs)}`;
  return `${sign}R${body}`;
};

const toNum = (value: string) => {
  const n = parseFloat(value.replace(/[^\d.]/g, ""));
  return Number.isFinite(n) && n > 0 ? Math.round(n * 100) / 100 : 0;
};

