function SectionCard({
  icon,
  title,
  fields,
  form,
  set,
}: {
  icon: React.ComponentProps<typeof Ionicons>["name"];
  title: string;
  fields: FieldDef[];
  form: Record<string, string>;
  set: (key: string, value: string) => void;
}) {
  return (
    <View style={styles.card}>
      <View style={styles.cardHead}>
        <Ionicons name={icon} size={16} color={colors.goldDark} />
        <Text style={styles.cardTitle}>{title}</Text>
      </View>
      <View style={styles.fields}>
        {fields.map((f) => {
          const descKey = f.descKey;
          return (
            <View key={f.key} style={styles.field}>
              <Text style={styles.fieldLabel}>{f.label}</Text>
              <TextInput
                style={styles.input}
                placeholder={f.placeholder}
                placeholderTextColor={colors.muted}
                value={form[f.key] ?? ""}
                onChangeText={(t) => set(f.key, t)}
                keyboardType="numeric"
              />
              {descKey ? (
                <TextInput
                  style={[styles.input, styles.descInput]}
                  placeholder={f.descPlaceholder}
                  placeholderTextColor={colors.muted}
                  value={form[descKey] ?? ""}
                  onChangeText={(t) => set(descKey, t)}
                />
              ) : null}
            </View>
          );
        })}
      </View>
    </View>
  );
}

function LineRow({
  label,
  value,
  note,
  positive,
  money = true,
}: {
  label: string;
  value: number;
  note?: string;
  positive?: boolean;
  money?: boolean;
}) {
  return (
    <View style={styles.lineRow}>
      <View style={styles.lineBody}>
        <Text style={styles.lineLabel}>{label}</Text>
        {!!note && <Text style={styles.lineNote}>{note}</Text>}
      </View>
      <Text
        style={[
          styles.lineValue,
          positive != null && (positive ? styles.linePositive : styles.lineNegative),
        ]}
      >
        {money ? fmtMoney(value) : value.toLocaleString("en-US")}
      </Text>
    </View>
  );
}

const fmtDate = (value?: string) => {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-ZA", { day: "numeric", month: "short", year: "numeric" });
};

function StatTile({ label, value, tint }: { label: string; value: number; tint: string }) {
  return (
    <View style={styles.statTile}>
      <Text style={styles.statLabel}>{label}</Text>
      <Text style={[styles.statValue, { color: tint }]} numberOfLines={1} adjustsFontSizeToFit>
        {fmtCompact(value)}
      </Text>
    </View>
  );
}

function Figure({ label, value, tint }: { label: string; value: number; tint: string }) {
  return (
    <View style={styles.figure}>
      <Text style={styles.figureLabel}>{label}</Text>
      <Text style={[styles.figureValue, { color: tint }]} numberOfLines={1}>
        {fmtCompact(value)}
      </Text>
    </View>
  );
}

export default function FinancialReport() {
  const [authorized, setAuthorized] = useState(false);
  const [checking, setChecking] = useState(true);
  const [mode, setMode] = useState<"list" | "form" | "compiled">("list");
  const financialDraftKey = "form-draft:admin:financial-report";
  const [form, setForm] = usePersistentFormState<Record<string, string>>(financialDraftKey, { ...EMPTY_FORM });
  const [compiled, setCompiled] = useState<FinancialReportInput | null>(null);
  const [saving, setSaving] = useState(false);
  const [published, setPublished] = useState<FinancialReportSummary[]>([]);
  const [loadingList, setLoadingList] = useState(true);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [customFields, setCustomFields] = useState<{ title: string; content: string }[]>([]);
  const { width: screenWidth } = useWindowDimensions();
  const [selectedMonth, setSelectedMonth] = useState<number | null>(null);

  /** Oldest → newest, capped so the bars stay readable on a phone. */
  const chartReports = useMemo(
    () =>
      [...published]
        .sort((a, b) => chartSortKey(a) - chartSortKey(b))
        .slice(-8),
    [published],
  );

  const chartMonths = useMemo<PerformanceMonth[]>(
    () =>
      chartReports.map((r, index) => ({
        month: index,
        label: chartLabel(r.period),
        period: r.period,
        income: raisedOf(r),
        expenses: r.expenses,
        net: r.net,
        raised: raisedOf(r),
      })),
    [chartReports],
  );

  const overview = useMemo(() => {
    const raised = published.reduce((sum, r) => sum + raisedOf(r), 0);
    const spent = published.reduce((sum, r) => sum + r.expenses, 0);
    return { raised, spent, balance: published[0]?.net ?? 0 };
  }, [published]);

  // Two reports can share a period label, so the bar index picks the report.
  const selectedReport =
    selectedMonth === null ? null : (chartReports[selectedMonth] ?? null);

  const addCustomField = () =>
    setCustomFields((prev) => [...prev, { title: "", content: "" }]);
  const removeCustomField = (i: number) =>
    setCustomFields((prev) => prev.filter((_, idx) => idx !== i));
  const updateCustomField = (i: number, key: "title" | "content", value: string) =>
    setCustomFields((prev) =>
      prev.map((item, idx) => (idx === i ? { ...item, [key]: value } : item)),
    );

  const set = (key: string, value: string) =>
    setForm((prev) => ({ ...prev, [key]: value }));

  useEffect(() => {
    (async () => {
      const session = await getSession();
      if (!session?.user || session.user.role !== "admin") {
        setAuthorized(false);
        setChecking(false);
        return;
      }
      setAuthorized(true);
      setChecking(false);
    })();
  }, []);

  const loadPublished = useCallback(async () => {
    try {
      const res = await financialApi.list();
      setPublished(res.data);
    } catch {
      setPublished([]);
    }
  }, []);

  useEffect(() => {
    if (!authorized) return;
    financialApi
      .list()
      .then((res) => {
        const sorted = [...res.data].sort(
          (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
        );
        setPublished(sorted);
      })
      .catch(() => setPublished([]))
      .finally(() => setLoadingList(false));
  }, [authorized]);

  const [fetchedData, setFetchedData] = useState<{
    foundersFund: number;
    amountsUsed: number;
    balanceBroughtDown: number;
    schoolKit: SchoolKitStatement | null;
  } | null>(null);
  const [fetchingData, setFetchingData] = useState(false);

  const fetchReportData = useCallback(async (period: string) => {
    if (!period.trim()) return;
    setFetchingData(true);
    try {
      const res = await financialReportDataApi.get(period.trim());
      setFetchedData(res.data);
    } catch {
      setFetchedData(null);
    }
    setFetchingData(false);
  }, []);

  const handlePeriodBlur = () => {
    const period = form.period.trim();
    if (period) fetchReportData(period);
  };

  const importFoundersFund = () => {
    if (!fetchedData) return;
    set("incFoundersFund", String(fetchedData.foundersFund));
  };

  const importAmountsFromRecords = () => {
    if (!fetchedData) return;
    set("incAmountsFromRecords", String(fetchedData.amountsUsed));
  };

  const importBalanceBD = () => {
    if (!fetchedData) return;
    set("incBalanceBD", String(fetchedData.balanceBroughtDown));
  };

  const importKitSpend = () => {
    if (!fetchedData?.schoolKit) return;
    set("expMaterials", String(toNum(form.expMaterials) + fetchedData.schoolKit.spend));
  };

  const importKitImpact = () => {
    const kit = fetchedData?.schoolKit?.impact;
    if (!kit) return;
    set("impKitLearners", String(kit.learners));
    set("impKitBooks", String(kit.books));
    set("impKitPencils", String(kit.pencils));
    set("impKitPens", String(kit.pens));
  };

  const handleCompile = () => {
    const period = form.period.trim();
    if (!period) {
      Alert.alert("Required", "Enter the report period, e.g. June 2026.");
      return;
    }
    const input: FinancialReportInput = {
      period,
      preparedBy: form.preparedBy.trim(),
      income: {
        balanceBroughtDown: toNum(form.incBalanceBD),
        foundersFund: toNum(form.incFoundersFund),
        events: toNum(form.incEvents),
        donations: toNum(form.incDonations),
        books: toNum(form.incBooks),
        other: toNum(form.incOther),
        otherDescription: form.incOtherDesc.trim(),
      },
      expenses: {
        meals: toNum(form.expMeals),
        groceries: toNum(form.expGroceries),
        tuition: toNum(form.expTuition),
        transport: toNum(form.expTransport),
        employment: toNum(form.expEmployment),
        materials: toNum(form.expMaterials),
        other: toNum(form.expOther),
        otherDescription: form.expOtherDesc.trim(),
        amountsFromRecords: toNum(form.incAmountsFromRecords),
      },
      impact: {
        families: toNum(form.impFamilies),
        mealsServed: toNum(form.impMeals),
        children: toNum(form.impChildren),
        placements: toNum(form.impPlacements),
        events: toNum(form.impEvents),
      },
      otherActivities: form.otherActivities.trim(),
      notes: form.notes.trim(),
      customFields: customFields.filter(
        (f) => f.title.trim() !== "" || f.content.trim() !== "",
      ),
      schoolKit: {
        learners: toNum(form.impKitLearners),
        books: toNum(form.impKitBooks),
        pencils: toNum(form.impKitPencils),
        pens: toNum(form.impKitPens),
      },
    };
    setCompiled(input);
    setMode("compiled");
  };

  const totals = (r: FinancialReportInput) => {
    const income =
      r.income.balanceBroughtDown +
      r.income.foundersFund +
      r.income.events +
      r.income.donations +
      r.income.books +
      r.income.other;
    const expenses =
      r.expenses.meals +
      r.expenses.groceries +
      r.expenses.tuition +
      r.expenses.transport +
      r.expenses.employment +
      r.expenses.materials +
      r.expenses.other +
      r.expenses.amountsFromRecords;
    return { income, expenses, net: income - expenses };
  };

  const buildShareText = (r: FinancialReportInput) => {
    const t = totals(r);
    const lines = [
      "RELATE — FINANCIAL REPORT",
      `Period: ${r.period}`,
      `Prepared by: ${r.preparedBy || "Relate Admin"}`,
      "",
      "INCOME",
      `  Balance brought down: ${fmtMoney(r.income.balanceBroughtDown)}`,
      `  Founders’ Fund: ${fmtMoney(r.income.foundersFund)}`,
      `  Events: ${fmtMoney(r.income.events)}`,
      `  Donations: ${fmtMoney(r.income.donations)}`,
      `  Book and resource sales: ${fmtMoney(r.income.books)}`,
      `  Other: ${fmtMoney(r.income.other)}${r.income.otherDescription ? ` (${r.income.otherDescription})` : ""}`,
      `  Total income: ${fmtMoney(t.income)}`,
      "",
      "EXPENSES",
      `  Meals: ${fmtMoney(r.expenses.meals)}`,
      `  Groceries: ${fmtMoney(r.expenses.groceries)}`,
      `  Tuition support: ${fmtMoney(r.expenses.tuition)}`,
      `  Transport and travel: ${fmtMoney(r.expenses.transport)}`,
      `  Skills and employment: ${fmtMoney(r.expenses.employment)}`,
      `  Materials and printing: ${fmtMoney(r.expenses.materials)}`,
      `  Other: ${fmtMoney(r.expenses.other)}${r.expenses.otherDescription ? ` (${r.expenses.otherDescription})` : ""}`,
      r.expenses.amountsFromRecords > 0 ? `  Amounts used from records: ${fmtMoney(r.expenses.amountsFromRecords)}` : null,
      `  Total expenses: ${fmtMoney(t.expenses)}`,
      "",
      `NET FUNDS: ${fmtMoney(t.net)}`,
      "",
      "IMPACT",
      `  Families supported: ${r.impact.families}`,
      `  Meals served: ${r.impact.mealsServed}`,
      `  Children supported: ${r.impact.children}`,
      `  Skills and employment placements: ${r.impact.placements}`,
      `  Events hosted: ${r.impact.events}`,
      ...(r.schoolKit &&
      (r.schoolKit.learners > 0 ||
        r.schoolKit.books > 0 ||
        r.schoolKit.pencils > 0 ||
        r.schoolKit.pens > 0)
        ? [
            "",
            "SCHOOL KIT",
            `  Learners with a kit: ${r.schoolKit.learners}`,
            `  Exercise books issued: ${r.schoolKit.books}`,
            `  HB pencils issued: ${r.schoolKit.pencils}`,
            `  Ballpoint pens issued: ${r.schoolKit.pens}`,
          ]
        : []),
    ];
    if (r.otherActivities) lines.push("", "OTHER ACTIVITIES", r.otherActivities);
    if (r.notes) lines.push("", "NOTES", r.notes);
    if (r.customFields?.length) {
      lines.push("", "ADDITIONAL ITEMS");
      for (const f of r.customFields) {
        lines.push(`  ${f.title}: ${f.content}`);
      }
    }
    return lines.join("\n");
  };

  const handleShare = () => {
    if (!compiled) return;
    Share.share({ message: buildShareText(compiled) }).catch(() => {});
  };

  const handleSave = async () => {
    if (!compiled) return;
    setSaving(true);
    try {
      if (editingId) {
        await financialApi.update(editingId, compiled);
        Alert.alert("Report updated", `${compiled.period} has been updated.`);
      } else {
        await sponsorApi.saveFinancialReport(compiled);
        Alert.alert("Report saved", `${compiled.period} has been filed.`);
      }
      await loadPublished();
      await clearPersistentFormDraft(financialDraftKey);
      setEditingId(null);
      setForm({ ...EMPTY_FORM });
      setCustomFields([]);
      setCompiled(null);
      setMode("list");
    } catch (e: any) {
      Alert.alert("Error", e?.message || "Failed to save report.");
    }
    setSaving(false);
  };

  const handleEdit = async (r: FinancialReportSummary) => {
    try {
      const res = await financialApi.get(r._id);
      const f = res.data;
      setForm({
        period: f.period,
        preparedBy: f.preparedBy || "",
        notes: f.notes || "",
        otherActivities: f.otherActivities || "",
        incBalanceBD: String(f.income.balanceBroughtDown ?? 0),
        incFoundersFund: String(foundersFundOf(f.income)),
        incEvents: String(f.income.events ?? 0),
        incDonations: String(f.income.donations ?? 0),
        incBooks: String(f.income.books ?? 0),
        incOther: String(f.income.other ?? 0),
        incOtherDesc: f.income.otherDescription || "",
        expMeals: String(f.expenses.meals ?? 0),
        expGroceries: String(f.expenses.groceries ?? 0),
        expTuition: String(f.expenses.tuition ?? 0),
        expTransport: String(f.expenses.transport ?? 0),
        expEmployment: String(f.expenses.employment ?? 0),
        expMaterials: String(f.expenses.materials ?? 0),
        expOther: String(f.expenses.other ?? 0),
        expOtherDesc: f.expenses.otherDescription || "",
        incAmountsFromRecords: String(f.expenses.amountsFromRecords ?? 0),
        impFamilies: String(f.impact.families ?? 0),
        impMeals: String(f.impact.mealsServed ?? 0),
        impChildren: String(f.impact.children ?? 0),
        impPlacements: String(f.impact.placements ?? 0),
        impEvents: String(f.impact.events ?? 0),
        impKitLearners: String(f.schoolKit?.learners ?? 0),
        impKitBooks: String(f.schoolKit?.books ?? 0),
        impKitPencils: String(f.schoolKit?.pencils ?? 0),
        impKitPens: String(f.schoolKit?.pens ?? 0),
      });
      setCustomFields(f.customFields || []);
      setEditingId(r._id);
      setCompiled(null);
      setMode("form");
    } catch (e: any) {
      Alert.alert("Error", e?.message || "Failed to load report.");
    }
  };

  const handleCancelEdit = () => {
    setEditingId(null);
    setForm({ ...EMPTY_FORM });
    setCustomFields([]);
    setCompiled(null);
    setMode("list");
  };

  const handleCreate = async () => {
    await clearPersistentFormDraft(financialDraftKey);
    setEditingId(null);
    setForm({ ...EMPTY_FORM });
    setCustomFields([]);
    setCompiled(null);
    setMode("form");
  };

  const handleDelete = (r: FinancialReportSummary) => {
    Alert.alert(
      "Delete report?",
      `${r.period} will be permanently removed.`,
      [
        { text: "Cancel", style: "cancel" },
        {
          text: "Delete",
          style: "destructive",
          onPress: async () => {
            try {
              await financialApi.remove(r._id);
              if (editingId === r._id) {
                setEditingId(null);
                setCustomFields([]);
                setCompiled(null);
                setMode("list");
              }
              await loadPublished();
            } catch (e: any) {
              Alert.alert("Error", e?.message || "Failed to delete report.");
            }
          },
        },
      ],
    );
  };

  const handleBack = () => {
    if (mode === "compiled") {
      setMode("form");
      return;
    }
    if (mode === "form") {
      if (editingId) {
        setEditingId(null);
        setCustomFields([]);
      }
      setCompiled(null);
      setMode("list");
      return;
    }
    router.back();
  };

  if (checking) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <View style={styles.center}>
            <ActivityIndicator color={colors.goldDark} size="large" />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (!authorized) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <View style={styles.header}>
            <TouchableOpacity onPress={() => router.back()} style={styles.closeBtn}>
              <Ionicons name="close" size={20} color={colors.darkGreen} />
            </TouchableOpacity>
            <Text style={styles.headerTitle}>Financials</Text>
            <View style={{ width: 36 }} />
          </View>
          <View style={styles.center}>
            <Ionicons name="lock-closed-outline" size={40} color={colors.muted} />
            <Text style={styles.deniedTitle}>Admin access required</Text>
            <Text style={styles.deniedText}>
              Only Relate administrators can file or edit financial reports.
            </Text>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.header}>
          <TouchableOpacity onPress={handleBack} style={styles.closeBtn}>
            <Ionicons
              name={mode === "list" ? "close" : "chevron-back"}
              size={20}
              color={colors.darkGreen}
            />
          </TouchableOpacity>
          <Text style={styles.headerTitle}>Financials</Text>
          {mode === "compiled" ? (
            <TouchableOpacity
              onPress={handleShare}
              style={styles.closeBtn}
              accessibilityLabel="Share report"
            >
              <Ionicons name="share-outline" size={19} color={colors.darkGreen} />
            </TouchableOpacity>
          ) : (
            <View style={{ width: 36 }} />
          )}
        </View>

        {mode === "list" ? (
          <ScrollView
            contentContainerStyle={styles.scroll}
            showsVerticalScrollIndicator={false}
          >
            <LinearGradient
              colors={HERO_GRADIENT}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={styles.hero}
            >
              <View style={styles.heroTop}>
                <View style={styles.heroBadge}>
                  <Ionicons name="stats-chart" size={12} color={colors.goldDark} />
                  <Text style={styles.heroBadgeText}>RELATE FINANCIALS</Text>
                </View>
                <Text style={styles.heroCount}>
                  {published.length} report{published.length === 1 ? "" : "s"}
                </Text>
              </View>

              <Text style={styles.heroHeading}>Where the money went</Text>
              <Text style={styles.heroCaption}>
                {published[0]
                  ? `Latest period ${published[0].period} · prepared by ${published[0].preparedBy || "Relate Admin"}`
                  : "Publish a report to see the trend across periods."}
              </Text>

              <View style={styles.statRow}>
                <StatTile label="Raised" value={overview.raised} tint={colors.goldDark} />
                <StatTile label="Spent" value={overview.spent} tint={colors.forest} />
                <StatTile
                  label="Balance"
                  value={overview.balance}
                  tint={overview.balance < 0 ? "#e11d48" : colors.emeraldDark}
                />
              </View>

              {chartMonths.length > 0 ? (
                <View style={styles.chartPanel}>
                  <View style={styles.legendRow}>
                    <View style={styles.legendItem}>
                      <View style={[styles.legendDot, { backgroundColor: CHART_INCOME }]} />
                      <Text style={styles.legendText}>Raised</Text>
                    </View>
                    <View style={styles.legendItem}>
                      <View style={[styles.legendDot, { backgroundColor: CHART_EXPENSE }]} />
                      <Text style={styles.legendText}>Spent</Text>
                    </View>
                    <Text style={styles.legendHint}>Tap a month</Text>
                  </View>
                  <IncomeExpenseBars
                    months={chartMonths}
                    width={Math.max(220, screenWidth - 86)}
                    height={186}
                    selectedMonth={selectedMonth}
                    onSelectMonth={(m) =>
                      setSelectedMonth((prev) => (prev === m ? null : m))
                    }
                  />
                  <Text style={styles.chartCaption}>
                    {selectedReport
                      ? `${selectedReport.period} · raised ${fmtMoney(raisedOf(selectedReport))} · spent ${fmtMoney(selectedReport.expenses)} · balance ${fmtMoney(selectedReport.net)}`
                      : "Balance brought down is carried funds, not income — it stays out of the raised bars."}
                  </Text>
                </View>
              ) : null}

              <TouchableOpacity
                style={styles.heroActionWrap}
                onPress={handleCreate}
                activeOpacity={0.85}
              >
                <LinearGradient
                  colors={ACTION_GRADIENT}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 1 }}
                  style={styles.heroAction}
                >
                  <Ionicons name="add" size={18} color={colors.forest} />
                  <Text style={styles.heroActionText}>Create report</Text>
                </LinearGradient>
              </TouchableOpacity>
            </LinearGradient>

            <View style={styles.sectionHead}>
              <Text style={styles.sectionTitle}>Reports</Text>
              <Text style={styles.sectionMeta}>Newest first</Text>
            </View>

            {loadingList ? (
              <View style={styles.reportCard}>
                {[0, 1, 2].map((i) => (
                  <View key={i} style={styles.skelRow}>
                    <View style={[styles.skelLine, { width: "45%" }]} />
                    <View style={[styles.skelLine, { width: "75%", height: 10 }]} />
                  </View>
                ))}
              </View>
            ) : published.length === 0 ? (
              <View style={styles.emptyCard}>
                <Ionicons name="document-text-outline" size={26} color={colors.muted} />
                <Text style={styles.emptyTitle}>No reports yet</Text>
                <Text style={styles.emptyText}>
                  File the first period and it will show up here with its own breakdown.
                </Text>
              </View>
            ) : (
              <>
                {published.map((r) => (
                  <View key={r._id} style={styles.reportCard}>
                    <TouchableOpacity
                      style={styles.reportMain}
                      activeOpacity={0.7}
                      onPress={() =>
                        router.push(`/financial-report-view?reportId=${r._id}`)
                      }
                    >
                      <View style={styles.reportHead}>
                        <Text style={styles.reportPeriod} numberOfLines={1}>
                          {r.period}
                        </Text>
                        <Ionicons
                          name="chevron-forward"
                          size={16}
                          color={colors.muted}
                        />
                      </View>
                      <Text style={styles.reportSub} numberOfLines={1}>
                        {r.preparedBy || "Relate Admin"} · {fmtDate(r.createdAt)}
                      </Text>
                      <View style={styles.figureRow}>
                        <Figure label="Raised" value={raisedOf(r)} tint={colors.goldDark} />
                        <Figure label="Spent" value={r.expenses} tint={colors.forest} />
                        <Figure
                          label="Balance"
                          value={r.net}
                          tint={r.net < 0 ? "#e11d48" : colors.emeraldDark}
                        />
                      </View>
                    </TouchableOpacity>
                    <View style={styles.reportActions}>
                      <TouchableOpacity
                        style={styles.reportActionBtn}
                        onPress={() => handleEdit(r)}
                        accessibilityLabel={`Edit ${r.period} report`}
                      >
                        <Ionicons name="create-outline" size={15} color={colors.info} />
                        <Text style={styles.reportActionText}>Edit</Text>
                      </TouchableOpacity>
                      <TouchableOpacity
                        style={styles.reportActionBtn}
                        onPress={() => handleDelete(r)}
                        accessibilityLabel={`Delete ${r.period} report`}
                      >
                        <Ionicons name="trash-outline" size={15} color="#be123c" />
                        <Text style={[styles.reportActionText, { color: "#be123c" }]}>
                          Delete
                        </Text>
                      </TouchableOpacity>
                    </View>
                  </View>
                ))}

                <View style={styles.summaryCard}>
                  <Text style={styles.summaryTitle}>
                    Across {published.length} report{published.length === 1 ? "" : "s"}
                  </Text>
                  <View style={styles.figureRow}>
                    <Figure label="Raised" value={overview.raised} tint={colors.goldDark} />
                    <Figure label="Spent" value={overview.spent} tint={colors.forest} />
                    <Figure
                      label="Balance"
                      value={overview.balance}
                      tint={overview.balance < 0 ? "#e11d48" : colors.emeraldDark}
                    />
                  </View>
                </View>
              </>
            )}
          </ScrollView>
        ) : mode === "form" ? (
          <KeyboardAvoidingView
            style={{ flex: 1 }}
            behavior={Platform.OS === "ios" ? "padding" : "height"}
          >
            <ScrollView
              contentContainerStyle={styles.scroll}
              keyboardShouldPersistTaps="handled"
              showsVerticalScrollIndicator={false}
            >
              <View style={styles.introCard}>
                <Ionicons name="document-text-outline" size={18} color={colors.goldDark} />
                <Text style={styles.introText}>
                  Enter the figures for each Relate activity this period, then
                  compile the report. Amounts are in South African Rand (ZAR).
                </Text>
              </View>

              {editingId ? (
                <View style={styles.editBanner}>
                  <Ionicons name="create-outline" size={16} color={colors.forest} />
                  <Text style={styles.editBannerText}>
                    Editing{" "}
                    <Text style={styles.editBannerStrong}>
                      {form.period || "this report"}
                    </Text>
                    . Save to apply your changes, or cancel to go back.
                  </Text>
                  <TouchableOpacity onPress={handleCancelEdit} hitSlop={8}>
                    <Ionicons name="close" size={18} color={colors.muted} />
                  </TouchableOpacity>
                </View>
              ) : null}

              <View style={styles.card}>
                <View style={styles.cardHead}>
                  <Ionicons name="calendar-outline" size={16} color={colors.goldDark} />
                  <Text style={styles.cardTitle}>Report details</Text>
                </View>
                <View style={styles.fields}>
                  <View style={styles.field}>
                    <Text style={styles.fieldLabel}>
                      Report period <Text style={styles.req}>*</Text>
                    </Text>
                    <TextInput
                      style={styles.input}
                      placeholder="e.g. June 2026"
                      placeholderTextColor={colors.muted}
                      value={form.period}
                      onChangeText={(t) => set("period", t)}
                      onBlur={handlePeriodBlur}
                    />
                  </View>
                  <View style={styles.field}>
                    <Text style={styles.fieldLabel}>Prepared by</Text>
                    <TextInput
                      style={styles.input}
                      placeholder="Your name"
                      placeholderTextColor={colors.muted}
                      value={form.preparedBy}
                      onChangeText={(t) => set("preparedBy", t)}
                    />
                  </View>
                </View>
              </View>

              {fetchedData ? (
                <View style={styles.fetchedCard}>
                  <View style={styles.fetchedHead}>
                    <Ionicons name="bar-chart-outline" size={16} color={colors.goldDark} />
                    <Text style={styles.fetchedTitle}>Data for this period</Text>
                    <TouchableOpacity onPress={() => fetchReportData(form.period.trim())} hitSlop={8}>
                      <Ionicons name="refresh" size={16} color={colors.forest} />
                    </TouchableOpacity>
                  </View>
                  <View style={styles.fetchedRow}>
                    <View style={styles.fetchedItem}>
                      <Text style={styles.fetchedLabel}>Founders’ Fund</Text>
                      <Text style={styles.fetchedValue}>{fmtMoney(fetchedData.foundersFund)}</Text>
                    </View>
                    <TouchableOpacity style={styles.importBtn} onPress={importFoundersFund}>
                      <Ionicons name="download-outline" size={14} color={colors.forest} />
                      <Text style={styles.importBtnText}>Import</Text>
                    </TouchableOpacity>
                  </View>
                  <View style={styles.fetchedRow}>
                    <View style={styles.fetchedItem}>
                      <Text style={styles.fetchedLabel}>Amounts used from records</Text>
                      <Text style={styles.fetchedValue}>{fmtMoney(fetchedData.amountsUsed)}</Text>
                    </View>
                    <TouchableOpacity style={styles.importBtn} onPress={importAmountsFromRecords}>
                      <Ionicons name="download-outline" size={14} color={colors.forest} />
                      <Text style={styles.importBtnText}>Import</Text>
                    </TouchableOpacity>
                  </View>
                  {fetchedData.balanceBroughtDown !== 0 ? (
                    <View style={styles.fetchedRow}>
                      <View style={styles.fetchedItem}>
                        <Text style={styles.fetchedLabel}>Balance from previous month</Text>
                        <Text style={[styles.fetchedValue, fetchedData.balanceBroughtDown < 0 && { color: "#be123c" }]}>
                          {fmtMoney(fetchedData.balanceBroughtDown)}
                        </Text>
                      </View>
                      <TouchableOpacity style={styles.importBtn} onPress={importBalanceBD}>
                        <Ionicons name="download-outline" size={14} color={colors.forest} />
                        <Text style={styles.importBtnText}>Import</Text>
                      </TouchableOpacity>
                    </View>
                  ) : null}

                  {fetchedData.schoolKit ? (
                    <View style={styles.kitSection}>
                      <Text style={styles.kitTitle}>
                        School Kit — {fetchedData.schoolKit.period}
                      </Text>
                      {KIT_ITEM_LABELS.map(({ key, label }) => (
                        <Text key={key} style={styles.kitLine}>
                          {label}: {fetchedData.schoolKit!.opening[key]} →{" "}
                          {fetchedData.schoolKit!.closing[key]} (
                          {fetchedData.schoolKit!.received[key]} in ·{" "}
                          {fetchedData.schoolKit!.issued[key]} out)
                        </Text>
                      ))}
                      <View style={styles.fetchedRow}>
                        <View style={styles.fetchedItem}>
                          <Text style={styles.fetchedLabel}>Stationery spend</Text>
                          <Text style={styles.fetchedValue}>
                            {fmtMoney(fetchedData.schoolKit.spend)}
                          </Text>
                        </View>
                        <TouchableOpacity style={styles.importBtn} onPress={importKitSpend}>
                          <Ionicons name="download-outline" size={14} color={colors.forest} />
                          <Text style={styles.importBtnText}>To Materials</Text>
                        </TouchableOpacity>
                      </View>
                      <View style={styles.fetchedRow}>
                        <View style={styles.fetchedItem}>
                          <Text style={styles.fetchedLabel}>Learners helped</Text>
                          <Text style={styles.fetchedValue}>
                            {fetchedData.schoolKit.learners} learners
                          </Text>
                        </View>
                        <TouchableOpacity style={styles.importBtn} onPress={importKitImpact}>
                          <Ionicons name="download-outline" size={14} color={colors.forest} />
                          <Text style={styles.importBtnText}>Import</Text>
                        </TouchableOpacity>
                      </View>
                    </View>
                  ) : null}
                </View>
              ) : fetchingData ? (
                <View style={styles.fetchedCard}>
                  <ActivityIndicator size="small" color={colors.goldDark} />
                </View>
              ) : null}

              <SectionCard
                icon="trending-up"
                title="Income"
                fields={INCOME_FIELDS}
                form={form}
                set={set}
              />

              <SectionCard
                icon="trending-down"
                title="Expenses"
                fields={EXPENSE_FIELDS}
                form={form}
                set={set}
              />

              <SectionCard
                icon="heart-outline"
                title="Impact"
                fields={IMPACT_FIELDS}
                form={form}
                set={set}
              />

              <SectionCard
                icon="book-outline"
                title="School Kit (impact)"
                fields={KIT_FIELDS}
                form={form}
                set={set}
              />

              <View style={styles.card}>
                <View style={styles.cardHead}>
                  <Ionicons name="finger-print-outline" size={16} color={colors.goldDark} />
                  <Text style={styles.cardTitle}>Other activities</Text>
                </View>
                <TextInput
                  style={[styles.input, styles.notesInput]}
                  placeholder="Services, outreach, community events, etc."
                  placeholderTextColor={colors.muted}
                  value={form.otherActivities}
                  onChangeText={(t) => set("otherActivities", t)}
                  multiline
                  textAlignVertical="top"
                />
              </View>

              <View style={styles.card}>
                <View style={styles.cardHead}>
                  <Ionicons name="add-circle-outline" size={16} color={colors.goldDark} />
                  <Text style={styles.cardTitle}>Additional items</Text>
                </View>
                <Text style={styles.sectionDesc}>
                  Add any extra income, expense, or other line items.
                </Text>
                {customFields.map((item, i) => (
                  <View key={i} style={styles.customRow}>
                    <View style={styles.customInputs}>
                      <TextInput
                        style={[styles.input, styles.customTitle]}
                        placeholder="Title"
                        placeholderTextColor={colors.muted}
                        value={item.title}
                        onChangeText={(t) => updateCustomField(i, "title", t)}
                      />
                      <TextInput
                        style={[styles.input, styles.customContent]}
                        placeholder="Content or description"
                        placeholderTextColor={colors.muted}
                        value={item.content}
                        onChangeText={(t) => updateCustomField(i, "content", t)}
                      />
                    </View>
                    <TouchableOpacity
                      style={styles.customRemoveBtn}
                      onPress={() => removeCustomField(i)}
                      hitSlop={6}
                    >
                      <Ionicons name="close-circle" size={20} color="#e11d48" />
                    </TouchableOpacity>
                  </View>
                ))}
                <TouchableOpacity style={styles.customAddBtn} onPress={addCustomField}>
                  <Ionicons name="add" size={18} color={colors.forest} />
                  <Text style={styles.customAddText}>Add field</Text>
                </TouchableOpacity>
              </View>

              <View style={styles.card}>
                <View style={styles.cardHead}>
                  <Ionicons name="chatbox-ellipses-outline" size={16} color={colors.goldDark} />
                  <Text style={styles.cardTitle}>Notes</Text>
                </View>
                <TextInput
                  style={[styles.input, styles.notesInput]}
                  placeholder="Anything to add to the report (optional)"
                  placeholderTextColor={colors.muted}
                  value={form.notes}
                  onChangeText={(t) => set("notes", t)}
                  multiline
                  textAlignVertical="top"
                />
              </View>

              <TouchableOpacity
                style={styles.compileBtnWrap}
                onPress={handleCompile}
                activeOpacity={0.85}
              >
                <LinearGradient
                  colors={ACTION_GRADIENT}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 1 }}
                  style={styles.compileBtn}
                >
                  <Text style={styles.compileBtnText}>Compile report</Text>
                  <Ionicons name="arrow-forward" size={16} color={colors.forest} />
                </LinearGradient>
              </TouchableOpacity>
            </ScrollView>
          </KeyboardAvoidingView>
        ) : compiled ? (
          <ScrollView
            contentContainerStyle={styles.scroll}
            showsVerticalScrollIndicator={false}
          >
            <LinearGradient
              colors={HERO_GRADIENT}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={styles.heroCard}
            >
              <Text style={styles.heroEyebrow}>FINANCIAL REPORT</Text>
              <Text style={styles.heroTitle}>{compiled.period}</Text>
              <Text style={styles.heroSub}>
                Prepared by {compiled.preparedBy || "Relate Admin"}
              </Text>
            </LinearGradient>

            <View style={styles.totalsCard}>
              <LineRow label="Total income" value={totals(compiled).income} />
              <View style={styles.totalsDivider} />
              <LineRow label="Total expenses" value={totals(compiled).expenses} />
              <View style={styles.totalsDivider} />
              <LineRow
                label="Net funds"
                value={totals(compiled).net}
                positive={totals(compiled).net >= 0}
              />
            </View>

            <View style={styles.card}>
              <View style={styles.cardHead}>
                <Ionicons name="trending-up" size={16} color={colors.goldDark} />
                <Text style={styles.cardTitle}>Income</Text>
              </View>
              {compiled.income.balanceBroughtDown > 0 ? (
                <LineRow label="Balance brought down" value={compiled.income.balanceBroughtDown} />
              ) : null}
              <LineRow label="Founders’ Fund" value={compiled.income.foundersFund} />
              <LineRow label="Event registrations and fees" value={compiled.income.events} />
              <LineRow label="Donations" value={compiled.income.donations} />
              <LineRow label="Book and resource sales" value={compiled.income.books} />
              {compiled.income.other > 0 || compiled.income.otherDescription ? (
                <LineRow
                  label="Other income"
                  value={compiled.income.other}
                  note={compiled.income.otherDescription || undefined}
                />
              ) : null}
            </View>

            <View style={styles.card}>
              <View style={styles.cardHead}>
                <Ionicons name="trending-down" size={16} color={colors.goldDark} />
                <Text style={styles.cardTitle}>Expenses</Text>
              </View>
              <LineRow label="Meals" value={compiled.expenses.meals} />
              <LineRow label="Groceries" value={compiled.expenses.groceries} />
              <LineRow label="Tuition support" value={compiled.expenses.tuition} />
              <LineRow label="Transport and travel" value={compiled.expenses.transport} />
              <LineRow label="Skills and employment" value={compiled.expenses.employment} />
              <LineRow label="Materials and printing" value={compiled.expenses.materials} />
              {compiled.expenses.amountsFromRecords > 0 ? (
                <LineRow label="Amounts used from records" value={compiled.expenses.amountsFromRecords} />
              ) : null}
              {compiled.expenses.other > 0 || compiled.expenses.otherDescription ? (
                <LineRow
                  label="Other expenses"
                  value={compiled.expenses.other}
                  note={compiled.expenses.otherDescription || undefined}
                />
              ) : null}
            </View>

            <View style={styles.card}>
              <View style={styles.cardHead}>
                <Ionicons name="heart-outline" size={16} color={colors.goldDark} />
                <Text style={styles.cardTitle}>Impact</Text>
              </View>
              <LineRow label="Families supported" value={compiled.impact.families} money={false} />
              <LineRow label="Meals served" value={compiled.impact.mealsServed} money={false} />
              <LineRow label="Children supported" value={compiled.impact.children} money={false} />
              <LineRow
                label="Skills and employment placements"
                value={compiled.impact.placements}
                money={false}
              />
              <LineRow label="Events hosted" value={compiled.impact.events} money={false} />
            </View>

            {compiled.schoolKit &&
            (compiled.schoolKit.learners > 0 ||
              compiled.schoolKit.books > 0 ||
              compiled.schoolKit.pencils > 0 ||
              compiled.schoolKit.pens > 0) ? (
              <View style={styles.card}>
                <View style={styles.cardHead}>
                  <Ionicons name="book-outline" size={16} color={colors.goldDark} />
                  <Text style={styles.cardTitle}>School Kit</Text>
                </View>
                <LineRow
                  label="Learners with a kit"
                  value={compiled.schoolKit.learners}
                  money={false}
                />
                {compiled.schoolKit.books > 0 ? (
                  <LineRow
                    label="Exercise books issued"
                    value={compiled.schoolKit.books}
                    money={false}
                  />
                ) : null}
                {compiled.schoolKit.pencils > 0 ? (
                  <LineRow
                    label="HB pencils issued"
                    value={compiled.schoolKit.pencils}
                    money={false}
                  />
                ) : null}
                {compiled.schoolKit.pens > 0 ? (
                  <LineRow
                    label="Ballpoint pens issued"
                    value={compiled.schoolKit.pens}
                    money={false}
                  />
                ) : null}
              </View>
            ) : null}

            {compiled.otherActivities ? (
              <View style={styles.card}>
                <View style={styles.cardHead}>
                  <Ionicons name="finger-print-outline" size={16} color={colors.goldDark} />
                  <Text style={styles.cardTitle}>Other activities</Text>
                </View>
                <Text style={styles.notesText}>{compiled.otherActivities}</Text>
              </View>
            ) : null}

            {compiled.customFields.length > 0 ? (
              <View style={styles.card}>
                <View style={styles.cardHead}>
                  <Ionicons name="add-circle-outline" size={16} color={colors.goldDark} />
                  <Text style={styles.cardTitle}>Additional items</Text>
                </View>
                {compiled.customFields.map((cf, i) => (
                  <View key={i} style={styles.customPreviewRow}>
                    <Text style={styles.customPreviewTitle}>{cf.title}</Text>
                    <Text style={styles.customPreviewContent}>{cf.content}</Text>
                  </View>
                ))}
              </View>
            ) : null}

            {compiled.notes ? (
              <View style={styles.card}>
                <View style={styles.cardHead}>
                  <Ionicons name="chatbox-ellipses-outline" size={16} color={colors.goldDark} />
                  <Text style={styles.cardTitle}>Notes</Text>
                </View>
                <Text style={styles.notesText}>{compiled.notes}</Text>
              </View>
            ) : null}

            <TouchableOpacity
              style={[styles.compileBtnWrap, saving && styles.compileBtnDisabled]}
              onPress={handleSave}
              disabled={saving}
              activeOpacity={0.85}
            >
              <LinearGradient
                colors={ACTION_GRADIENT}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={styles.compileBtn}
              >
                {saving ? (
                  <ActivityIndicator color={colors.forest} />
                ) : (
                  <Text style={styles.compileBtnText}>
                    {editingId ? "Update report" : "Save report"}
                  </Text>
                )}
              </LinearGradient>
            </TouchableOpacity>

            <View style={styles.secondaryRow}>
              <TouchableOpacity
                style={styles.secondaryBtn}
                onPress={handleShare}
                activeOpacity={0.85}
              >
                <Ionicons name="share-outline" size={16} color={colors.forest} />
                <Text style={styles.secondaryBtnText}>Share</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={styles.secondaryBtn}
                onPress={() => setMode("form")}
                activeOpacity={0.85}
              >
                <Ionicons name="create-outline" size={16} color={colors.forest} />
                <Text style={styles.secondaryBtnText}>Edit report</Text>
              </TouchableOpacity>
            </View>
          </ScrollView>
        ) : null}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

