/**
 * Club Skills framework — GET /api/skills?club=<slug>.
 *
 * Skills, levels and requirements come from the backend. The mobile copy in
 * `src/constants/skills.ts` is used as a fallback when the API is unavailable
 * or returns malformed data, so screens always render safely.
 *
 * `useSkillsCatalog()` shares one request per app session; the settled promise
 * is cached at module level.
 */

import { useEffect, useState } from "react";
import { API_BASE } from "@/services/config";

export type SkillLevelId = string;

export type SkillRequirement = {
  text: string;
  criteria: string[];
};

export type SkillLevel = {
  id: SkillLevelId;
  name: string;
  levelNumber: number;
  color: string;
  colorDark: string;
  description?: string;
  requirements: SkillRequirement[];
};

export type SkillProject = {
  title: string;
  tier: string;
  fee?: string;
};

/** Curriculum domain a module belongs to (Pulse tracks; Prime's single track). */
export type SkillTrackCategory =
  | "smart_saver"
  | "career_launch"
  | "digital_productivity"
  | "wellness_fitness";

/** One curriculum module inside a skill (spec: SkillModule). */
export type SkillModule = {
  id: string;
  trackCategory: SkillTrackCategory;
  title: string;
  description: string;
  order: number;
  durationMinutes: number;
  deliverableDescription: string;
};

/** The member's saved row for one module (spec: MemberModuleProgress). */
export type ModuleProgress = {
  id?: string;
  skillId?: string;
  moduleId: string;
  completed: boolean;
  completedAt?: string | null;
  deliverableSubmitted: boolean;
  deliverableUrl?: string | null;
  updatedAt?: string;
};

/** Everything the detail screen layers on top of the level requirements. */
export type SkillDetail = {
  tools?: string[];
  learningProvider?: string;
  learningUrl?: string;
  appFeatures?: string[];
  pathways?: { sproutGraduate?: string; directEntrant?: string };
  projects?: SkillProject[];
  unlockRule?: string;
  unlockAfter?: string;
  launchFund?: {
    goalName?: string;
    targetAmount?: number;
    autoRouting?: string;
    disbursementRule?: string;
  };
};

export type Skill = {
  id: string;
  name: string;
  description: string;
  icon: string;
  /** Royalty-free photo shown on the skill card. */
  image?: string;
  clubSlug?: string;
  /** The level this skill sits under (progress rows are keyed by it). */
  levelId?: SkillLevelId;
  color?: string;
  /** Compulsory or Elective — shown as the card/hero badge. */
  type?: "Compulsory" | "Elective";
  /** "You walk away with …" callout on the detail screen. */
  output?: string;
  detail?: SkillDetail;
  /** Curriculum modules — progress tracked per module (see ModuleProgress). */
  modules?: SkillModule[];
  /** Level-1 requirements alias (same shape as levels[0].requirements). */
  requirements?: SkillRequirement[];
  levels: SkillLevel[];
};

/** One level's saved progress row (GET/POST /api/skills/<id>?levelId=). */
export type SkillProgress = {
  checks: boolean[];
  criteria?: boolean[][];
  status: "not_started" | "in_progress" | "complete";
  enrolledAt?: string | null;
  updatedAt?: string;
  completedAt?: string | null;
};

export type ClubSkills = {
  clubSlug: string;
  clubName: string;
  clubColor: string;
  clubColorDark: string;
  skills: Skill[];
};

export type SkillsCatalog = {
  clubSlug: string;
  clubName: string;
  clubColor: string;
  clubColorDark: string;
  skills: Skill[];
  /** Club-wide level definitions, ordered. */
  levels: SkillLevel[];
  levelById: Record<SkillLevelId, SkillLevel>;
  skillsByLevel(levelId: SkillLevelId): Skill[];
  getSkill(id: string): Skill | undefined;
  count: number;
};

const FALLBACK_ERROR =
  "The skills framework couldn't be loaded — check your connection and try again.";

type RawLevel = {
  id?: unknown;
  name?: unknown;
  levelNumber?: unknown;
  /** Club-wide level lists from the API carry `order` instead. */
  order?: unknown;
  color?: unknown;
  colorDark?: unknown;
  description?: unknown;
  requirements?: unknown;
};

type RawSkill = {
  id?: unknown;
  name?: unknown;
  description?: unknown;
  icon?: unknown;
  image?: unknown;
  clubSlug?: unknown;
  levelId?: unknown;
  color?: unknown;
  type?: unknown;
  output?: unknown;
  detail?: unknown;
  modules?: unknown;
  requirements?: unknown;
  levels?: unknown;
};

type SkillsPayload = {
  clubSlug?: unknown;
  clubName?: unknown;
  clubColor?: unknown;
  clubColorDark?: unknown;
  skills?: unknown;
  levels?: unknown;
};

function toRequirements(value: unknown): SkillRequirement[] {
  if (!Array.isArray(value)) return [];
  return value
    .filter(
      (r): r is SkillRequirement =>
        !!r &&
        typeof r === "object" &&
        typeof (r as SkillRequirement).text === "string" &&
        Array.isArray((r as SkillRequirement).criteria),
    )
    .map((r) => ({ text: r.text, criteria: r.criteria }));
}

function toLevel(value: unknown): SkillLevel | null {
  if (!value || typeof value !== "object") return null;
  const raw = value as RawLevel;
  if (typeof raw.id !== "string" || typeof raw.name !== "string") return null;
  const color = typeof raw.color === "string" ? raw.color : "#1d2a4d";
  const colorDark =
    typeof raw.colorDark === "string" ? raw.colorDark : "#151f3a";
  return {
    id: raw.id,
    name: raw.name,
    levelNumber:
      typeof raw.levelNumber === "number"
        ? raw.levelNumber
        : typeof raw.order === "number"
          ? raw.order
          : 1,
    color,
    colorDark,
    description: typeof raw.description === "string" ? raw.description : undefined,
    requirements: toRequirements(raw.requirements),
  };
}

const TRACK_CATEGORIES: SkillTrackCategory[] = [
  "smart_saver",
  "career_launch",
  "digital_productivity",
  "wellness_fitness",
];

function toModules(value: unknown): SkillModule[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const modules = value
    .filter((m): m is Record<string, unknown> => !!m && typeof m === "object")
    .map((m) => {
      if (typeof m.id !== "string" || typeof m.title !== "string") return null;
      const trackCategory =
        typeof m.trackCategory === "string" &&
        (TRACK_CATEGORIES as string[]).includes(m.trackCategory)
          ? (m.trackCategory as SkillTrackCategory)
          : "smart_saver";
      return {
        id: m.id,
        trackCategory,
        title: m.title,
        description: typeof m.description === "string" ? m.description : "",
        order: typeof m.order === "number" ? m.order : 1,
        durationMinutes:
          typeof m.durationMinutes === "number" ? m.durationMinutes : 0,
        deliverableDescription:
          typeof m.deliverableDescription === "string"
            ? m.deliverableDescription
            : "",
      };
    })
    .filter((m): m is SkillModule => m !== null)
    .sort((a, b) => a.order - b.order);
  return modules.length > 0 ? modules : undefined;
}

function toDetail(value: unknown): SkillDetail | undefined {
  if (!value || typeof value !== "object") return undefined;
  const raw = value as Record<string, unknown>;
  const str = (v: unknown) => (typeof v === "string" && v ? v : undefined);
  const list = (v: unknown) =>
    Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : undefined;
  const pathways =
    raw.pathways && typeof raw.pathways === "object"
      ? {
          sproutGraduate: str((raw.pathways as Record<string, unknown>).sproutGraduate),
          directEntrant: str((raw.pathways as Record<string, unknown>).directEntrant),
        }
      : undefined;
  const projects = Array.isArray(raw.projects)
    ? raw.projects
        .filter(
          (p): p is SkillProject =>
            !!p &&
            typeof p === "object" &&
            typeof (p as SkillProject).title === "string" &&
            typeof (p as SkillProject).tier === "string",
        )
        .map((p) => ({
          title: p.title,
          tier: p.tier,
          fee: typeof p.fee === "string" ? p.fee : undefined,
        }))
    : undefined;
  const launchFund =
    raw.launchFund && typeof raw.launchFund === "object"
      ? (() => {
          const lf = raw.launchFund as Record<string, unknown>;
          return {
            goalName: str(lf.goalName),
            targetAmount: typeof lf.targetAmount === "number" ? lf.targetAmount : undefined,
            autoRouting: str(lf.autoRouting),
            disbursementRule: str(lf.disbursementRule),
          };
        })()
      : undefined;
  const detail: SkillDetail = {
    tools: list(raw.tools),
    learningProvider: str(raw.learningProvider),
    learningUrl: str(raw.learningUrl),
    appFeatures: list(raw.appFeatures),
    pathways:
      pathways && (pathways.sproutGraduate || pathways.directEntrant) ? pathways : undefined,
    projects: projects && projects.length ? projects : undefined,
    unlockRule: str(raw.unlockRule),
    unlockAfter: str(raw.unlockAfter),
    launchFund,
  };
  return detail;
}

function toSkill(value: unknown): Skill | null {
  if (!value || typeof value !== "object") return null;
  const raw = value as RawSkill;
  if (
    typeof raw.id !== "string" ||
    typeof raw.name !== "string" ||
    typeof raw.description !== "string"
  )
    return null;
  const icon = typeof raw.icon === "string" ? raw.icon : "star-outline";
  const image = typeof raw.image === "string" ? raw.image : undefined;
  const levels = Array.isArray(raw.levels)
    ? raw.levels.map(toLevel).filter((l): l is SkillLevel => l !== null)
    : [];
  return {
    id: raw.id,
    name: raw.name,
    description: raw.description,
    icon,
    image,
    clubSlug: typeof raw.clubSlug === "string" ? raw.clubSlug : undefined,
    levelId: typeof raw.levelId === "string" ? raw.levelId : undefined,
    color: typeof raw.color === "string" ? raw.color : undefined,
    type: raw.type === "Compulsory" || raw.type === "Elective" ? raw.type : undefined,
    output: typeof raw.output === "string" ? raw.output : undefined,
    detail: toDetail(raw.detail),
    modules: toModules(raw.modules),
    requirements: raw.requirements ? toRequirements(raw.requirements) : undefined,
    levels,
  };
}

function buildSkills(raw: unknown): SkillsCatalog | null {
  const payload = (raw && typeof raw === "object" ? raw : {}) as SkillsPayload;
  const clubSlug =
    typeof payload.clubSlug === "string" ? payload.clubSlug : "";
  const clubName =
    typeof payload.clubName === "string" ? payload.clubName : "";
  const clubColor =
    typeof payload.clubColor === "string" ? payload.clubColor : "#1d2a4d";
  const clubColorDark =
    typeof payload.clubColorDark === "string"
      ? payload.clubColorDark
      : "#151f3a";

  if (!clubSlug || !clubName) return null;

  const rawSkills = Array.isArray(payload.skills)
    ? (payload.skills as unknown[])
    : [];
  const skills = rawSkills
    .map(toSkill)
    .filter((s): s is Skill => s !== null);

  // Level definitions: prefer the payload's club-wide list, else derive from skills.
  const payloadLevels = Array.isArray(payload.levels)
    ? (payload.levels as unknown[]).map(toLevel).filter((l): l is SkillLevel => l !== null)
    : [];
  const levelMap = new Map<string, SkillLevel>();
  for (const l of payloadLevels) if (!levelMap.has(l.id)) levelMap.set(l.id, l);
  for (const skill of skills) {
    for (const l of skill.levels) {
      if (!levelMap.has(l.id)) levelMap.set(l.id, l);
    }
  }
  const levels = [...levelMap.values()].sort((a, b) => a.levelNumber - b.levelNumber);
  const levelById: Record<string, SkillLevel> = {};
  for (const l of levels) levelById[l.id] = l;

  return {
    clubSlug,
    clubName,
    clubColor,
    clubColorDark,
    skills,
    levels,
    levelById,
    skillsByLevel: (levelId: SkillLevelId) =>
      skills.filter((s) => s.levelId === levelId),
    getSkill: (id: string) => skills.find((s) => s.id === id),
    count: skills.length,
  };
}

let requestCache = new Map<string, Promise<SkillsCatalog>>();

function fromBundled(fallback: {
  clubSlug: string;
  clubName: string;
  clubColor: string;
  clubColorDark: string;
  skills: Skill[];
}): SkillsCatalog {
  const levelMap = new Map<string, SkillLevel>();
  for (const skill of fallback.skills) {
    for (const l of skill.levels) {
      if (!levelMap.has(l.id)) levelMap.set(l.id, l);
    }
  }
  const levels = [...levelMap.values()].sort((a, b) => a.levelNumber - b.levelNumber);
  const levelById: Record<string, SkillLevel> = {};
  for (const l of levels) levelById[l.id] = l;
  return {
    clubSlug: fallback.clubSlug,
    clubName: fallback.clubName,
    clubColor: fallback.clubColor,
    clubColorDark: fallback.clubColorDark,
    skills: fallback.skills,
    levels,
    levelById,
    skillsByLevel: (levelId: SkillLevelId) =>
      fallback.skills.filter((s) => s.levelId === levelId),
    getSkill: (id: string) => fallback.skills.find((s) => s.id === id),
    count: fallback.skills.length,
  };
}

export function fetchSkillsCatalog(clubSlug: string): Promise<SkillsCatalog> {
  const cacheKey = `skills:${clubSlug}`;
  const cached = requestCache.get(cacheKey);
  if (cached) return cached;

  const promise = fetch(`${API_BASE}/api/skills?club=${encodeURIComponent(clubSlug)}`, {
    headers: { Accept: "application/json" },
  })
    .then(async (res) => {
      if (!res.ok) throw new Error(`skills api ${res.status}`);
      const raw = await res.json();
      const catalog = buildSkills(raw);
      if (!catalog) throw new Error("unexpected skills payload");
      return catalog;
    })
    .catch((err: unknown) => {
      requestCache.delete(cacheKey);
      throw err;
    });

  requestCache.set(cacheKey, promise);
  return promise;
}

export type SkillsCatalogState = {
  data: SkillsCatalog | null;
  loading: boolean;
  error: string | null;
};

const LOADING: SkillsCatalogState = { data: null, loading: true, error: null };

/**
 * The skills framework for a screen, with loading and error spelled out.
 * Falls back to bundled data from `src/constants/skills.ts` when the API fails.
 */
export function useSkillsCatalog(clubSlug: string): SkillsCatalogState {
  const [state, setState] = useState<SkillsCatalogState>(() => LOADING);

  useEffect(() => {
    let cancelled = false;

    if (!clubSlug) {
      // Deferred a tick — setState straight in an effect body is disallowed.
      Promise.resolve().then(() => {
        if (!cancelled) setState({ data: null, loading: false, error: null });
      });
      return () => {
        cancelled = true;
      };
    }

    import("@/constants/skills").then(({ getClubSkills }) => {
      // Bundled copy is only a fallback — the API is the source of truth, so
      // every club fetches even when no local copy exists (Sprout, for one).
      const fallback = getClubSkills(clubSlug);

      fetchSkillsCatalog(clubSlug)
        .then((data) => {
          if (cancelled) return;
          setState({ data, loading: false, error: null });
        })
        .catch(() => {
          if (cancelled) return;
          if (fallback) {
            setState({ data: fromBundled(fallback), loading: false, error: null });
          } else {
            setState({
              data: null,
              loading: false,
              error: FALLBACK_ERROR,
            });
          }
        });
    });

    return () => {
      cancelled = true;
    };
  }, [clubSlug]);

  return state;
}

/**
 * Several clubs' skills at once (home rail, cross-club shelves). One shared
 * request per club per session, bundled data used per club when the API fails.
 * `loading` stays true until every club has settled, so screens can tell an
 * empty list apart from one that is still in flight.
 */
export type ClubsSkillsState = {
  catalogs: SkillsCatalog[];
  loading: boolean;
  error: string | null;
};

export function useClubsSkills(slugs: string[]): ClubsSkillsState {
  const key = slugs.join(",");
  const [state, setState] = useState<ClubsSkillsState>({
    catalogs: [],
    loading: true,
    error: null,
  });

  useEffect(() => {
    let cancelled = false;
    const list = key ? key.split(",") : [];

    // Deferred a tick — setState straight in an effect body is disallowed.
    Promise.resolve().then(() => {
      if (cancelled) return;
      setState(
        list.length === 0
          ? { catalogs: [], loading: false, error: null }
          : (prev) => ({ catalogs: prev.catalogs, loading: true, error: null }),
      );
    });

    if (list.length > 0) {
      Promise.all(
        list.map((slug) =>
          fetchSkillsCatalog(slug)
            .then((catalog): SkillsCatalog | null => catalog)
            .catch(async () => {
              const { getClubSkills } = await import("@/constants/skills");
              const fb = getClubSkills(slug);
              return fb ? fromBundled(fb) : null;
            }),
        ),
      ).then((res) => {
        if (cancelled) return;
        const catalogs = res.filter(
          (c): c is SkillsCatalog => c !== null && c.skills.length > 0,
        );
        setState({
          catalogs,
          loading: false,
          error: catalogs.length === 0 ? FALLBACK_ERROR : null,
        });
      });
    }

    return () => {
      cancelled = true;
    };
  }, [key]);

  return state;
}
