import { useMemo, useState } from "react";
import {
  Modal,
  ScrollView,
  SectionList,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { useSQLiteContext } from "expo-sqlite";
import { getBooks, getChapters, type BookInfo } from "@/lib/bible-queries";
import { useBibleTheme, type BibleTheme } from "@/lib/bible-theme";

type Props = {
  visible: boolean;
  version: string;
  bookNumber?: number | null;
  bookName?: string | null;
  chapter: number;
  onClose: () => void;
  onSelectBook: (book: BookInfo) => void;
  onSelectChapter: (chapter: number) => void;
};

type Tab = "books" | "chapters";

const OT_BOOKS = Array.from({ length: 39 }, (_, i) => i + 1);
const NT_BOOKS = Array.from({ length: 27 }, (_, i) => i + 40);

export default function BookChapterSheet({
  visible,
  version,
  bookNumber,
  bookName,
  chapter,
  onClose,
  onSelectBook,
  onSelectChapter,
}: Props) {
  const db = useSQLiteContext();
  const theme = useBibleTheme();
  const [tab, setTab] = useState<Tab>(bookNumber ? "chapters" : "books");
  const [query, setQuery] = useState("");

  // Re-anchoring the sheet each time it opens (render-phase adjustment).
  const [wasVisible, setWasVisible] = useState(visible);
  if (visible !== wasVisible) {
    setWasVisible(visible);
    if (visible) {
      setTab(bookNumber ? "chapters" : "books");
      setQuery("");
    }
  }

  const books = useMemo(() => getBooks(db, version), [db, version]);

  const sections = useMemo(() => {
    const q = query.trim().toLowerCase();
    const match = (b: BookInfo) => !q || b.book_name.toLowerCase().includes(q);
    const ot = books.filter((b) => OT_BOOKS.includes(b.book) && match(b));
    const nt = books.filter((b) => NT_BOOKS.includes(b.book) && match(b));
    const out = [];
    if (ot.length) out.push({ title: "Old Testament", data: ot });
    if (nt.length) out.push({ title: "New Testament", data: nt });
    return out;
  }, [books, query]);

  const chapters = useMemo(
    () => (bookNumber ? getChapters(db, version, bookNumber) : []),
    [db, version, bookNumber],
  );

  const s = createStyles(theme);

  return (
    <Modal
      visible={visible}
      transparent
      animationType="slide"
      onRequestClose={onClose}
    >
      <TouchableOpacity style={s.overlay} activeOpacity={1} onPress={onClose}>
        <TouchableOpacity activeOpacity={1} style={s.sheet} onPress={() => {}}>
          <View style={s.grabber} />
          <View style={s.titleRow}>
            <Text style={s.title}>Go to</Text>
            <TouchableOpacity
              onPress={onClose}
              style={s.closeBtn}
              accessibilityRole="button"
              accessibilityLabel="Close"
            >
              <Ionicons name="close" size={20} color={theme.textMuted} />
            </TouchableOpacity>
          </View>

          <View style={s.tabs}>
            <TouchableOpacity
              style={[s.tab, tab === "books" && s.tabActive]}
              onPress={() => setTab("books")}
              accessibilityRole="tab"
              accessibilityLabel="Browse books"
            >
              <Text style={[s.tabText, tab === "books" && s.tabTextActive]}>
                Books
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={[s.tab, tab === "chapters" && s.tabActive]}
              onPress={() => bookNumber && setTab("chapters")}
              accessibilityRole="tab"
              accessibilityLabel="Browse chapters"
            >
              <Text style={[s.tabText, tab === "chapters" && s.tabTextActive]}>
                Chapters
              </Text>
            </TouchableOpacity>
          </View>

          {tab === "books" ? (
            <>
              <View style={s.searchRow}>
                <Ionicons name="search" size={16} color={theme.textMuted} />
                <TextInput
                  style={s.searchInput}
                  value={query}
                  onChangeText={setQuery}
                  placeholder="Search books"
                  placeholderTextColor={theme.textMuted}
                  autoCapitalize="words"
                  returnKeyType="search"
                />
                {query.length > 0 ? (
                  <TouchableOpacity onPress={() => setQuery("")}>
                    <Ionicons
                      name="close-circle"
                      size={16}
                      color={theme.textMuted}
                    />
                  </TouchableOpacity>
                ) : null}
              </View>
              <SectionList
                sections={sections}
                keyExtractor={(item) => String(item.book)}
                stickySectionHeadersEnabled={false}
                renderSectionHeader={({ section }) => (
                  <Text style={s.sectionTitle}>{section.title}</Text>
                )}
                renderItem={({ item }) => {
                  const active = item.book === bookNumber;
                  return (
                    <TouchableOpacity
                      style={[s.bookRow, active && s.bookRowActive]}
                      activeOpacity={0.6}
                      onPress={() => {
                        onSelectBook(item);
                        setTab("chapters");
                      }}
                      accessibilityRole="button"
                      accessibilityLabel={`Open ${item.book_name}`}
                    >
                      <Text
                        style={[s.bookName, active && s.bookNameActive]}
                        numberOfLines={1}
                      >
                        {item.book_name}
                      </Text>
                      <Text style={s.bookCount}>{item.chapter_count} ch</Text>
                    </TouchableOpacity>
                  );
                }}
                contentContainerStyle={s.listContent}
                ListEmptyComponent={
                  <Text style={s.empty}>No books match “{query}”</Text>
                }
              />
            </>
          ) : (
            <ScrollView contentContainerStyle={s.chapterPane}>
              <Text style={s.chapterHead}>{bookName ?? ""}</Text>
              <Text style={s.chapterSub}>Choose a chapter</Text>
              <View style={s.grid}>
                {chapters.map((c) => {
                  const active = c.chapter === chapter;
                  return (
                    <TouchableOpacity
                      key={c.chapter}
                      style={[s.cell, active && s.cellActive]}
                      onPress={() => onSelectChapter(c.chapter)}
                      accessibilityRole="button"
                      accessibilityLabel={`Chapter ${c.chapter}`}
                    >
                      <Text
                        style={[s.cellText, active && s.cellTextActive]}
                        numberOfLines={1}
                        adjustsFontSizeToFit
                        minimumFontScale={0.75}
                      >
                        {c.chapter}
                      </Text>
                    </TouchableOpacity>
                  );
                })}
              </View>
            </ScrollView>
          )}
        </TouchableOpacity>
      </TouchableOpacity>
    </Modal>
  );
}

