const fmtDate = (value?: string | null) => {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-ZA", { day: "numeric", month: "short", year: "numeric" });
};

function ApplySheet({
  office,
  visible,
  onClose,
  onApplied,
}: {
  office: VolunteerOffice;
  visible: boolean;
  onClose: () => void;
  onApplied: () => void;
}) {
  return (
    <Modal visible={visible} animationType="slide" onRequestClose={onClose}>
      {/* Keyed remount so every open starts with fresh fields (no reset effect). */}
      {visible ? (
        <ApplyForm office={office} onClose={onClose} onApplied={onApplied} />
      ) : null}
    </Modal>
  );
}

function ApplyForm({
  office,
  onClose,
  onApplied,
}: {
  office: VolunteerOffice;
  onClose: () => void;
  onApplied: () => void;
}) {
  const questions = office.applicationQuestions?.length ? office.applicationQuestions : [];
  const [motivation, setMotivation] = useState("");
  const [answers, setAnswers] = useState<Record<string, string>>(() => {
    const seed: Record<string, string> = {};
    for (const q of questions) seed[q] = "";
    return seed;
  });
  const [busy, setBusy] = useState(false);

  const submit = async () => {
    if (questions.length) {
      for (const q of questions) {
        if (!(answers[q] || "").trim()) {
          Alert.alert("Missing answer", `Please answer: ${q}`);
          return;
        }
      }
      setBusy(true);
      try {
        await officesApi.apply(office._id, {
          answers: questions.map((q) => ({ question: q, answer: answers[q].trim() })),
        });
        onClose();
        onApplied();
      } catch (e: any) {
        Alert.alert("Could not apply", e?.message || "Please try again.");
      }
      setBusy(false);
      return;
    }
    if (motivation.trim().length < 20) {
      Alert.alert("A bit more detail", "Write at least 20 characters on why you'd like this office.");
      return;
    }
    setBusy(true);
    try {
      await officesApi.apply(office._id, { motivation: motivation.trim() });
      onClose();
      onApplied();
    } catch (e: any) {
      Alert.alert("Could not apply", e?.message || "Please try again.");
    }
    setBusy(false);
  };

  return (
    <SafeAreaView style={s.fullModal} edges={["top", "bottom"]}>
      <View style={s.fullHead}>
        <View style={{ flex: 1 }}>
          <Text style={s.sheetTitle}>Apply for this office</Text>
          <Text style={s.sheetSub} numberOfLines={1}>
            {office.title}
          </Text>
        </View>
        <TouchableOpacity onPress={onClose} style={s.sheetClose}>
          <Ionicons name="close" size={18} color={colors.muted} />
        </TouchableOpacity>
      </View>

      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === "ios" ? "padding" : "height"}
      >
        <ScrollView
          contentContainerStyle={s.fullScroll}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        >
          {questions.length ? (
            questions.map((q) => (
              <View key={q}>
                <Text style={s.fieldLabel}>{q}</Text>
                <TextInput
                  style={[s.input, s.textarea]}
                  value={answers[q] || ""}
                  onChangeText={(t) => setAnswers((prev) => ({ ...prev, [q]: t }))}
                  multiline
                  placeholder="Your answer"
                  placeholderTextColor={colors.muted}
                />
              </View>
            ))
          ) : (
            <>
              <Text style={s.fieldLabel}>Why do you want it?</Text>
              <TextInput
                style={[s.input, s.textarea]}
                value={motivation}
                onChangeText={setMotivation}
                multiline
                placeholder="A short note on your interest and availability (20+ characters)."
                placeholderTextColor={colors.muted}
              />
              <Text style={s.counter}>{motivation.trim().length}/20</Text>
            </>
          )}

          <PrimaryButton
            label="Send application"
            icon="arrow-forward"
            onPress={submit}
            loading={busy}
            disabled={busy}
          />
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const toLines = (value: string): string[] =>
  value
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);

function EditOfficeSheet({
  office,
  visible,
  onClose,
  onSaved,
}: {
  office: VolunteerOffice;
  visible: boolean;
  onClose: () => void;
  onSaved: () => void;
}) {
  return (
    <Modal visible={visible} animationType="slide" onRequestClose={onClose}>
      {/* Keyed remount so every open starts with fresh fields (no reset effect). */}
      {visible ? (
        <EditOfficeForm office={office} onClose={onClose} onSaved={onSaved} />
      ) : null}
    </Modal>
  );
}

function EditOfficeForm({
  office,
  onClose,
  onSaved,
}: {
  office: VolunteerOffice;
  onClose: () => void;
  onSaved: () => void;
}) {
  const [title, setTitle] = useState(office.title);
  const [description, setDescription] = useState(office.description);
  const [area, setArea] = useState(office.area ?? "");
  const [responsibilities, setResponsibilities] = useState(
    (office.responsibilities ?? []).join("\n"),
  );
  const [qualifications, setQualifications] = useState(
    (office.qualifications ?? []).join("\n"),
  );
  const [questions, setQuestions] = useState(
    (office.applicationQuestions ?? []).join("\n"),
  );
  const [busy, setBusy] = useState(false);

  const save = async () => {
    if (!title.trim()) {
      Alert.alert("Title required", "Give the office a short title.");
      return;
    }
    setBusy(true);
    try {
      const resp = toLines(responsibilities);
      const quals = toLines(qualifications);
      const qs = toLines(questions);
      await officesApi.update(office._id, {
        title: title.trim(),
        description: description.trim(),
        area: area.trim() || null,
        responsibilities: resp.length ? resp : null,
        qualifications: quals.length ? quals : null,
        applicationQuestions: qs.length ? qs : null,
      });
      onClose();
      onSaved();
    } catch (e: any) {
      Alert.alert("Could not save", e?.message || "Please try again.");
    }
    setBusy(false);
  };

  return (
    <SafeAreaView style={s.fullModal} edges={["top", "bottom"]}>
      <View style={s.fullHead}>
        <View style={{ flex: 1 }}>
          <Text style={s.sheetTitle}>Edit office</Text>
          <Text style={s.sheetSub} numberOfLines={1}>
            {office.title}
          </Text>
        </View>
        <TouchableOpacity onPress={onClose} style={s.sheetClose}>
          <Ionicons name="close" size={18} color={colors.muted} />
        </TouchableOpacity>
      </View>

      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === "ios" ? "padding" : "height"}
      >
        <ScrollView
          contentContainerStyle={s.fullScroll}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        >
          <Text style={s.fieldLabel}>Title</Text>
          <TextInput
            style={s.input}
            value={title}
            onChangeText={setTitle}
            placeholder="Office title"
            placeholderTextColor={colors.muted}
          />
          <Text style={s.fieldLabel}>Description</Text>
          <TextInput
            style={[s.input, s.textarea]}
            value={description}
            onChangeText={setDescription}
            multiline
            placeholder="What this office is about"
            placeholderTextColor={colors.muted}
          />
          <Text style={s.fieldLabel}>Area (optional)</Text>
          <TextInput
            style={s.input}
            value={area}
            onChangeText={setArea}
            placeholder="e.g. Operations"
            placeholderTextColor={colors.muted}
          />
          <Text style={s.fieldLabel}>Responsibilities (one per line)</Text>
          <TextInput
            style={[s.input, s.textarea]}
            value={responsibilities}
            onChangeText={setResponsibilities}
            multiline
            placeholder={"Run Sunday welcome desk\nPrepare the weekly report"}
            placeholderTextColor={colors.muted}
          />
          <Text style={s.fieldLabel}>Qualifications (one per line)</Text>
          <TextInput
            style={[s.input, s.textarea]}
            value={qualifications}
            onChangeText={setQualifications}
            multiline
            placeholder={"Friendly and reliable\nAvailable on Sundays"}
            placeholderTextColor={colors.muted}
          />
          <Text style={s.fieldLabel}>Application questions (one per line)</Text>
          <TextInput
            style={[s.input, s.textarea]}
            value={questions}
            onChangeText={setQuestions}
            multiline
            placeholder={"Why are you a good fit?\nWhat days are you free?"}
            placeholderTextColor={colors.muted}
          />
          <PrimaryButton
            label="Save changes"
            icon="checkmark"
            onPress={save}
            loading={busy}
            disabled={busy}
          />
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

export default function OfficeDetailScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const [office, setOffice] = useState<VolunteerOffice | null>(null);
  const [error, setError] = useState("");
  const [applyOpen, setApplyOpen] = useState(false);
  const [isAdmin, setIsAdmin] = useState(false);
  const [editOpen, setEditOpen] = useState(false);
  const insets = useSafeAreaInsets();

  const load = useCallback(async () => {
    if (!id) return;
    try {
      const res = await officesApi.get(id);
      setOffice(res.data);
      setError("");
    } catch (e: any) {
      setError(e?.message || "Could not reach the server.");
    }
  }, [id]);

  useEffect(() => {
    getSession().then((s) => setIsAdmin(s?.user?.role === "admin"));
  }, []);

  useEffect(() => {
    (async () => {
      await load();
    })();
  }, [load]);

  if (!office && !error) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <View style={s.bar}>
            <TouchableOpacity onPress={() => router.back()} style={s.iconBtn}>
              <Ionicons name="chevron-back" size={20} color={colors.forest} />
            </TouchableOpacity>
          </View>
          <View style={s.skeletonWrap}>
            {[0, 1, 2].map((i) => (
              <SkeletonPulse key={i} style={s.skeletonBlock} />
            ))}
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (error || !office) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <View style={s.bar}>
            <TouchableOpacity onPress={() => router.back()} style={s.iconBtn}>
              <Ionicons name="chevron-back" size={20} color={colors.forest} />
            </TouchableOpacity>
          </View>
          <EmptyState
            icon="warning-outline"
            color={colors.error}
            eyebrow="Something went wrong"
            title="Couldn't load this office"
            subtitle={error}
            actionLabel="Retry"
            onAction={load}
          />
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const status = OFFICE_STATUS_META[office.status];
  const app = office.myApplication;
  const appMeta = app ? OFFICE_APPLICATION_META[app.status] : null;
  const applied = !!app && app.status !== "rejected";
  const clubName = office.clubSlug
    ? CLUBS.find((c) => c.slug === office.clubSlug)?.name || office.clubSlug
    : null;

  const runAction = async (action: "fill" | "reopen" | "close") => {
    try {
      await officesApi.update(office._id, { action });
      await load();
    } catch (e: any) {
      Alert.alert("Could not update", e?.message || "Please try again.");
    }
  };

  const askAction = (action: "fill" | "reopen" | "close", danger = false) => {
    const labels = { fill: "Mark as filled", reopen: "Reopen office", close: "Close office" };
    Alert.alert(labels[action], office.title, [
      { text: "Cancel", style: "cancel" },
      {
        text: labels[action],
        style: danger ? "destructive" : "default",
        onPress: () => void runAction(action),
      },
    ]);
  };

  const confirmDelete = () => {
    Alert.alert("Delete office?", `"${office.title}" will be permanently removed.`, [
      { text: "Cancel", style: "cancel" },
      {
        text: "Delete",
        style: "destructive",
        onPress: async () => {
          try {
            await officesApi.remove(office._id);
            router.back();
          } catch (e: any) {
            Alert.alert("Could not delete", e?.message || "Please try again.");
          }
        },
      },
    ]);
  };

  return (
    <SafeAreaProvider>
      <SafeAreaView style={s.safe} edges={["top"]}>
        <View style={s.bar}>
          <TouchableOpacity
            onPress={() => router.back()}
            style={s.iconBtn}
            accessibilityLabel="Back"
          >
            <Ionicons name="chevron-back" size={20} color={colors.forest} />
          </TouchableOpacity>
          <Text style={s.barTitle} numberOfLines={1}>
            Office
          </Text>
          <View style={{ width: 40 }} />
        </View>

        <ScrollView contentContainerStyle={s.scroll} showsVerticalScrollIndicator={false}>
          <View style={s.headRow}>
            {office.area ? (
              <View style={s.areaChip}>
                <Ionicons name="briefcase-outline" size={12} color={colors.forest} />
                <Text style={s.areaChipText}>{office.area}</Text>
              </View>
            ) : null}
            <View style={[s.pill, { backgroundColor: status.bg }]}>
              <Text style={[s.pillText, { color: status.color }]}>{status.label}</Text>
            </View>
          </View>

          <Text style={s.title}>{office.title}</Text>
          <Text style={s.desc}>{office.description}</Text>

          {office.responsibilities?.length ? (
            <View style={s.bulletBlock}>
              <Text style={s.bulletHeading}>What you&rsquo;ll do</Text>
              {office.responsibilities.map((point) => (
                <View key={point} style={s.bulletRow}>
                  <Text style={s.bulletDot}>•</Text>
                  <Text style={s.bulletText}>{point}</Text>
                </View>
              ))}
            </View>
          ) : null}

          {office.qualifications?.length ? (
            <View style={s.bulletBlock}>
              <Text style={s.bulletHeading}>Qualifications</Text>
              {office.qualifications.map((point) => (
                <View key={point} style={s.bulletRow}>
                  <Text style={s.bulletDot}>•</Text>
                  <Text style={s.bulletText}>{point}</Text>
                </View>
              ))}
            </View>
          ) : null}

          {office.applicationQuestions?.length ? (
            <View style={s.bulletBlock}>
              <Text style={s.bulletHeading}>Application questions</Text>
              {office.applicationQuestions.map((q) => (
                <View key={q} style={s.bulletRow}>
                  <Text style={s.bulletDot}>•</Text>
                  <Text style={s.bulletText}>{q}</Text>
                </View>
              ))}
            </View>
          ) : null}

          <View style={s.metaCard}>
            {clubName ? (
              <View style={s.metaRow}>
                <Ionicons name="people-outline" size={15} color={colors.forest} />
                <Text style={s.metaText}>{clubName}</Text>
              </View>
            ) : null}
            <View style={s.metaRow}>
              <Ionicons name="person-circle-outline" size={15} color={colors.forest} />
              <Text style={s.metaText}>Posted by {office.postedByName}</Text>
            </View>
            <View style={s.metaRow}>
              <Ionicons name="calendar-outline" size={15} color={colors.forest} />
              <Text style={s.metaText}>Posted {fmtDate(office.createdAt)}</Text>
            </View>
          </View>

          {app && appMeta ? (
            <View style={[s.statusCard, { backgroundColor: appMeta.bg }]}>
              <Ionicons
                name={
                  app.status === "approved"
                    ? "checkmark-circle"
                    : app.status === "rejected"
                      ? "close-circle"
                      : "time"
                }
                size={18}
                color={appMeta.color}
              />
              <View style={{ flex: 1 }}>
                <Text style={[s.statusTitle, { color: appMeta.color }]}>
                  Application {appMeta.label.toLowerCase()}
                </Text>
                <Text style={s.statusSub}>Applied {fmtDate(app.createdAt)}</Text>
              </View>
            </View>
          ) : null}
        </ScrollView>

        {isAdmin ? (
          <View style={[s.footer, { paddingBottom: 16 + insets.bottom }]}>
            <View style={s.adminRow}>
              {office.status === "open" ? (
                <TouchableOpacity
                  style={s.adminAction}
                  activeOpacity={0.85}
                  onPress={() => askAction("fill")}
                >
                  <Ionicons name="checkmark-circle-outline" size={14} color={colors.forest} />
                  <Text style={s.adminActionText}>Mark filled</Text>
                </TouchableOpacity>
              ) : null}
              {office.status !== "open" ? (
                <TouchableOpacity
                  style={s.adminAction}
                  activeOpacity={0.85}
                  onPress={() => askAction("reopen")}
                >
                  <Ionicons name="refresh-outline" size={14} color={colors.forest} />
                  <Text style={s.adminActionText}>Reopen</Text>
                </TouchableOpacity>
              ) : null}
              {office.status !== "closed" ? (
                <TouchableOpacity
                  style={s.adminAction}
                  activeOpacity={0.85}
                  onPress={() => askAction("close", true)}
                >
                  <Ionicons name="close-circle-outline" size={14} color={colors.forest} />
                  <Text style={s.adminActionText}>Close</Text>
                </TouchableOpacity>
              ) : null}
              <TouchableOpacity
                style={[s.adminAction, s.adminActionDanger]}
                activeOpacity={0.85}
                onPress={confirmDelete}
              >
                <Ionicons name="trash-outline" size={14} color="#be123c" />
                <Text style={[s.adminActionText, { color: "#be123c" }]}>Delete</Text>
              </TouchableOpacity>
            </View>
            <PrimaryButton
              label="Edit office"
              icon="create-outline"
              onPress={() => setEditOpen(true)}
            />
          </View>
        ) : office.status === "open" && !applied ? (
          <View style={[s.footer, { paddingBottom: 16 + insets.bottom }]}>
            <PrimaryButton
              label="Apply for this office"
              icon="arrow-forward"
              onPress={() => setApplyOpen(true)}
            />
          </View>
        ) : null}
      </SafeAreaView>

      <ApplySheet
        office={office}
        visible={applyOpen}
        onClose={() => setApplyOpen(false)}
        onApplied={() => {
          setApplyOpen(false);
          load();
        }}
      />
      <EditOfficeSheet
        office={office}
        visible={editOpen}
        onClose={() => setEditOpen(false)}
        onSaved={load}
      />
    </SafeAreaProvider>
  );
}

