import { Circle, G, Line, Polyline, Svg, Text as SvgText } from "react-native-svg";
import { colors } from "@/constants/colors";

const GRID = "#EDF1F5";

function compact(value: number): string {
  if (value >= 1_000_000) return `${Math.round(value / 100_000) / 10}m`;
  if (value >= 1_000) return `${Math.round(value / 100) / 10}k`;
  return String(Math.round(value));
}

function axis(max: number): { top: number; step: number } {
  if (max <= 0) return { top: 4, step: 1 };
  const raw = max / 4;
  const magnitude = 10 ** Math.floor(Math.log10(raw));
  const step = ([1, 2, 2.5, 5, 10].find((m) => m * magnitude >= raw) ?? 10) * magnitude;
  return { top: Math.max(step, Math.ceil(max / step) * step), step };
}

export type GrowthSeries = {
  name: string;
  color: string;
  values: number[];
};

/** Cumulative growth lines, one per series, over a shared set of month labels. */
export default function GrowthChart({
  labels,
  series,
  width,
  height = 190,
}: {
  labels: string[];
  series: GrowthSeries[];
  width: number;
  height?: number;
}) {
  if (width <= 0 || labels.length === 0) return null;

  const PAD = { top: 12, right: 10, bottom: 26, left: 38 };
  const innerW = width - PAD.left - PAD.right;
  const innerH = height - PAD.top - PAD.bottom;
  const max = Math.max(0, ...series.flatMap((s) => s.values));
  const { top, step } = axis(max);
  const ticks: number[] = [];
  for (let value = 0; value <= top; value += step) ticks.push(value);

  const yFor = (value: number) => PAD.top + innerH * (1 - value / top);
  const xFor = (index: number) =>
    labels.length === 1
      ? PAD.left + innerW / 2
      : PAD.left + (index / (labels.length - 1)) * innerW;
  const showLabel = (index: number) =>
    labels.length <= 6 || index % 2 === 0 || index === labels.length - 1;

  return (
    <Svg
      width={width}
      height={height}
      accessibilityLabel={`Growth over ${labels.length} months`}
    >
      {ticks.map((tick) => (
        <G key={`grid-${tick}`}>
          <Line
            x1={PAD.left}
            x2={width - PAD.right}
            y1={yFor(tick)}
            y2={yFor(tick)}
            stroke={GRID}
            strokeWidth={1}
          />
          <SvgText
            x={PAD.left - 6}
            y={yFor(tick) + 3}
            fontSize={9}
            fill={colors.muted}
            textAnchor="end"
          >
            {compact(tick)}
          </SvgText>
        </G>
      ))}

      {labels.map((label, index) =>
        showLabel(index) ? (
          <SvgText
            key={`label-${index}`}
            x={xFor(index)}
            y={height - 7}
            fontSize={9}
            fill={colors.muted}
            textAnchor="middle"
          >
            {label}
          </SvgText>
        ) : null,
      )}

      {series.map((line) => (
        <G key={line.name}>
          <Polyline
            points={line.values.map((value, index) => `${xFor(index)},${yFor(value)}`).join(" ")}
            fill="none"
            stroke={line.color}
            strokeWidth={2.5}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          {line.values.map((value, index) => (
            <Circle
              key={`${line.name}-${index}`}
              cx={xFor(index)}
              cy={yFor(value)}
              r={2.5}
              fill={colors.white}
              stroke={line.color}
              strokeWidth={1.5}
            />
          ))}
        </G>
      ))}
    </Svg>
  );
}
