import { Image } from "expo-image";
import { LinearGradient } from "expo-linear-gradient";
import { memo, useEffect, useState, type ReactNode } from "react";
import { Animated, StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { colors } from "@/constants/colors";
import { getOptimizedImageUrl } from "@/services/cloudinary";
import { IS_WEB } from "@/services/config";

export type DiscoverCardType = "event" | "skill" | "group" | "team";

export const DISCOVER_TYPE_META: Record<
  DiscoverCardType,
  { label: string; icon: string; gradient: readonly [string, string] }
> = {
  event: {
    label: "EVENT",
    icon: "calendar-outline",
    gradient: ["#13c5dd", "#1d2a4d"],
  },
  skill: {
    label: "SKILL",
    icon: "hand-right-outline",
    gradient: ["#1d2a4d", "#0fa3c4"],
  },
  group: {
    label: "GROUP",
    icon: "people-outline",
    gradient: ["#13c5dd", "#0fa3c4"],
  },
  team: {
    label: "TEAM",
    icon: "shield-outline",
    gradient: ["#13c5dd", "#1d2a4d"],
  },
};

export type DiscoverCardMeta = { icon: string; text: string };

export type DiscoverCardBookmark = { section: string; itemId: string };

/** Pulsing pill used for live-group badges. */
export function LivePill({ children }: { children: ReactNode }) {
  const [opacity] = useState(() => new Animated.Value(1));
  useEffect(() => {
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(opacity, {
          toValue: 0.35,
          duration: 700,
          useNativeDriver: true,
        }),
        Animated.timing(opacity, {
          toValue: 1,
          duration: 700,
          useNativeDriver: true,
        }),
      ]),
    );
    loop.start();
    return () => loop.stop();
  }, [opacity]);
  return <Animated.View style={{ opacity }}>{children}</Animated.View>;
}

function DiscoverCard({
  type,
  title,
  meta,
  image,
  live,
  isSaved,
  bookmark,
  onToggleBookmark,
  onPress,
  width,
  accessibilityLabel,
  chipLabel,
  tileIcon,
  gradient,
}: {
  type: DiscoverCardType;
  title: string;
  meta: DiscoverCardMeta[];
  image?: string | null;
  live?: boolean;
  /** Bookmark key this card reports as saved, when bookmarks are supported. */
  isSaved?: boolean;
  bookmark?: DiscoverCardBookmark;
  onToggleBookmark?: () => void;
  onPress: () => void;
  /** Card width (e.g. rail cards). Omit for full-width layout. */
  width?: number;
  accessibilityLabel?: string;
  /** Override the type chip label (e.g. an age range for club classes). */
  chipLabel?: string;
  /** Override the icon-tile glyph (e.g. a club's icon). */
  tileIcon?: string;
  /** Override the no-image media gradient (e.g. a club's brand colors). */
  gradient?: readonly [string, string];
}) {
  const typeMeta = DISCOVER_TYPE_META[type];
  const isBookmarked = bookmark ? !!isSaved : false;
  // Team crests are square badges — grow the media to the image's aspect so
  // the whole badge stays visible instead of being cropped by the fixed height.
  const [mediaW, setMediaW] = useState(width ?? 0);
  const [aspect, setAspect] = useState<number | null>(null);
  const autoH =
    type === "team" && aspect != null && mediaW > 0 ? mediaW / aspect : null;

  return (
    <TouchableOpacity
      activeOpacity={0.9}
      onPress={onPress}
      style={[s.cardWrap, IS_WEB && s.cardWrapFlat, width ? { width } : null]}
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel}
    >
      <View style={[s.card, IS_WEB && s.cardFlat]}>
        {/* Media section */}
        <View
          style={[s.cardMedia, autoH != null ? { height: autoH } : null]}
          onLayout={(e) => {
            const w = e.nativeEvent.layout.width;
            if (w > 0 && w !== mediaW) setMediaW(w);
          }}
        >
          {image ? (
            <Image
              source={{ uri: getOptimizedImageUrl(image, 720) }}
              style={s.cardMediaImg}
              contentFit="cover"
              transition={400}
              onLoad={(e) => {
                const { width: iw, height: ih } = e.source;
                if (iw > 0 && ih > 0) setAspect(iw / ih);
              }}
            />
          ) : (
            <LinearGradient
              colors={gradient ?? typeMeta.gradient}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={s.cardMediaImg}
            />
          )}
          <View style={s.mediaTopRow}>
            <View style={s.typeChip}>
              <Text style={s.typeChipText}>{chipLabel ?? typeMeta.label}</Text>
            </View>
            <View style={s.mediaTopRight}>
              {live && (
                <LivePill>
                  <View style={s.liveBadge}>
                    <View style={s.liveDot} />
                    <Text style={s.liveText}>LIVE</Text>
                  </View>
                </LivePill>
              )}
              {bookmark && onToggleBookmark ? (
                <TouchableOpacity
                  onPress={(e) => {
                    e.stopPropagation();
                    onToggleBookmark();
                  }}
                  hitSlop={{ top: 6, bottom: 6, left: 6, right: 6 }}
                  style={[s.bookmarkBtn, isBookmarked && s.bookmarkBtnOn]}
                  accessibilityLabel={isBookmarked ? "Remove bookmark" : "Bookmark"}
                >
                  <Ionicons
                    name={isBookmarked ? "bookmark" : "bookmark-outline"}
                    size={14}
                    color={isBookmarked ? colors.goldDark : colors.forestDark}
                  />
                </TouchableOpacity>
              ) : null}
            </View>
          </View>
        </View>

        {/* Details section */}
        <View style={s.cardDetails}>
          <View style={s.detailTitleRow}>
            <LinearGradient
              colors={gradient ?? typeMeta.gradient}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={s.iconTile}
            >
              <Ionicons name={(tileIcon ?? typeMeta.icon) as any} size={16} color={colors.white} />
            </LinearGradient>
            <Text style={s.cardTitle} numberOfLines={2}>
              {title}
            </Text>
          </View>
          <View style={s.metaBlock}>
            {meta.map((m, i) => (
              <View key={i} style={s.metaRow}>
                <Ionicons name={m.icon as any} size={12} color={colors.goldDark} />
                <Text style={s.metaText} numberOfLines={1}>
                  {m.text}
                </Text>
              </View>
            ))}
          </View>
        </View>
      </View>
    </TouchableOpacity>
  );
}

