type MeetingDraft = {
  title: string;
  date: string;
  time: string;
  location: string;
  meetingLink: string;
  agenda: AgendaItem[];
};

function todayIso(): string {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${now.getFullYear()}-${month}-${day}`;
}

function isoToDate(value: string | null): string {
  const date = value ? new Date(value) : new Date();
  if (Number.isNaN(date.getTime())) return todayIso();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${date.getFullYear()}-${month}-${day}`;
}

function isoToTime(value: string | null): string {
  const date = value ? new Date(value) : null;
  if (!date || Number.isNaN(date.getTime())) return "09:00";
  const hours = String(date.getHours()).padStart(2, "0");
  const minutes = String(date.getMinutes()).padStart(2, "0");
  return `${hours}:${minutes}`;
}

function combine(date: string, time: string): string | null {
  const parsed = new Date(`${date.trim()}T${(time || "09:00").trim()}:00`);
  return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString();
}

function pad(value: number): string {
  return String(value).padStart(2, "0");
}

function draftMoment(draft: MeetingDraft): Date {
  const [year, month, day] = draft.date.split("-").map(Number);
  const [hours, minutes] = (draft.time || "09:00").split(":").map(Number);
  const parsed = new Date(year, (month || 1) - 1, day || 1, hours || 0, minutes || 0);
  return Number.isNaN(parsed.getTime()) ? new Date() : parsed;
}

function dateLabel(draft: MeetingDraft): string {
  return draftMoment(draft).toLocaleDateString("en-ZA", {
    weekday: "short",
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

function timeLabel(draft: MeetingDraft): string {
  const moment = draftMoment(draft);
  return `${pad(moment.getHours())}:${pad(moment.getMinutes())}`;
}

function freshDraft(): MeetingDraft {
  return {
    title: "",
    date: todayIso(),
    time: "09:00",
    location: "Relate World HQ",
    meetingLink: "",
    agenda: [{ text: "", subs: [] }],
  };
}

function draftFromMeeting(meeting: BoardMeeting): MeetingDraft {
  return {
    title: meeting.title,
    date: isoToDate(meeting.scheduledDate),
    time: isoToTime(meeting.scheduledDate),
    location: meeting.location || "Relate World HQ",
    meetingLink: meeting.meetingLink || "",
    agenda: meeting.agenda.length ? meeting.agenda : [{ text: "", subs: [] }],
  };
}

export default function MeetingSchedulerForm({
  meeting,
  onSaved,
  onCancelEdit,
}: {
  meeting?: BoardMeeting | null;
  onSaved: (meeting: BoardMeeting) => void;
  onCancelEdit?: () => void;
}) {
  const editing = !!meeting;
  const [draft, setDraft, clearDraft] = usePersistentFormState<MeetingDraft>(
    `board-meeting-draft:${meeting?._id ?? "new"}`,
    meeting ? draftFromMeeting(meeting) : freshDraft(),
  );
  const [saving, setSaving] = useState(false);
  const [picker, setPicker] = useState<"date" | "time" | null>(null);

  const patch = (next: Partial<MeetingDraft>) => {
    setDraft((current) => ({ ...current, ...next }));
  };

  const hasContent =
    !!draft.title.trim() ||
    !!draft.meetingLink?.trim() ||
    draft.agenda.some((item) => item.text.trim() || item.subs.some((sub) => sub.trim()));

  const submit = async () => {
    if (!draft.title.trim()) {
      Alert.alert("Missing title", "Give the meeting a clear title.");
      return;
    }
    const scheduledDate = combine(draft.date, draft.time);
    if (!scheduledDate) {
      Alert.alert("Check the date", "Choose a date and time for the meeting.");
      return;
    }
    const meetingLink = (draft.meetingLink || "").trim();
    if (meetingLink && !/^https?:\/\//i.test(meetingLink)) {
      Alert.alert(
        "Check the meeting link",
        "Paste the full link, starting with https:// (for example https://zoom.us/j/123).",
      );
      return;
    }

    const agenda = draft.agenda
      .map((item) => ({
        text: item.text.trim(),
        subs: item.subs.map((sub) => sub.trim()).filter(Boolean),
      }))
      .filter((item) => item.text);

    setSaving(true);
    try {
      if (meeting) {
        const res = await boardApi.updateMeeting(meeting._id, {
          title: draft.title.trim(),
          scheduledDate,
          location: draft.location.trim(),
          meetingLink,
          agenda,
        });
        await clearDraft();
        Alert.alert(
          "Meeting updated",
          "Every board member has been notified of the change by app, push and email.",
        );
        onSaved(res.data);
      } else {
        const res = await boardApi.createMeeting({
          title: draft.title.trim(),
          scheduledDate,
          location: draft.location.trim(),
          meetingLink,
          agenda,
        });
        setDraft((current) => ({
          ...current,
          title: "",
          agenda: [{ text: "", subs: [] }],
        }));
        Alert.alert(
          "Meeting scheduled",
          "Every board member has been notified by app, push and email.",
        );
        onSaved(res.data);
      }
    } catch (e: any) {
      Alert.alert(
        editing ? "Could not update" : "Could not schedule",
        e?.message || "Please try again.",
      );
    } finally {
      setSaving(false);
    }
  };

  return (
    <View style={[s.card, editing && styles.editingCard]}>
      <View style={s.cardHead}>
        <Ionicons
          name={editing ? "create-outline" : "calendar-outline"}
          size={16}
          color={colors.goldDark}
        />
        <Text style={s.cardTitle}>
          {editing ? "Edit board meeting" : "Schedule a board meeting"}
        </Text>
        {editing && onCancelEdit ? (
          <TouchableOpacity onPress={onCancelEdit} activeOpacity={0.8}>
            <Text style={styles.cancelLink}>Cancel</Text>
          </TouchableOpacity>
        ) : null}
      </View>
      <Text style={s.cardSub}>
        {editing
          ? "Changes are emailed to the board so nobody works from an old agenda."
          : "Board members are the admin team — everyone is invited and told when the details change."}
      </Text>

      <Text style={s.fieldLabel}>Meeting title</Text>
      <TextInput
        style={s.input}
        placeholder="Q4 Seasonal Board Sync & Budget Audit"
        placeholderTextColor={colors.muted}
        value={draft.title}
        onChangeText={(title) => patch({ title })}
        maxLength={160}
      />

      <View style={s.twoCol}>
        <View style={{ flex: 1 }}>
          <Text style={s.fieldLabel}>Date</Text>
          <TouchableOpacity
            style={styles.pickerBtn}
            onPress={() => setPicker(picker === "date" ? null : "date")}
            activeOpacity={0.8}
            accessibilityLabel="Choose the meeting date"
          >
            <Ionicons name="calendar-outline" size={16} color={colors.goldDark} />
            <Text style={styles.pickerText} numberOfLines={1}>
              {dateLabel(draft)}
            </Text>
          </TouchableOpacity>
        </View>
        <View style={{ width: 118 }}>
          <Text style={s.fieldLabel}>Time</Text>
          <TouchableOpacity
            style={styles.pickerBtn}
            onPress={() => setPicker(picker === "time" ? null : "time")}
            activeOpacity={0.8}
            accessibilityLabel="Choose the meeting time"
          >
            <Ionicons name="time-outline" size={16} color={colors.goldDark} />
            <Text style={styles.pickerText}>{timeLabel(draft)}</Text>
          </TouchableOpacity>
        </View>
      </View>

      {picker === "date" ? (
        <View style={styles.pickerPanel}>
          <InlineCalendar
            value={draftMoment(draft)}
            onSelect={(date) => {
              patch({
                date: `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`,
              });
              setPicker(null);
            }}
          />
        </View>
      ) : null}

      {picker === "time" ? (
        <View style={styles.pickerPanel}>
          <InlineTimePicker
            value={draftMoment(draft)}
            onSelect={(moment) => {
              patch({ time: `${pad(moment.getHours())}:${pad(moment.getMinutes())}` });
              setPicker(null);
            }}
          />
        </View>
      ) : null}

      <Text style={s.fieldLabel}>Location</Text>
      <TextInput
        style={s.input}
        placeholder="Relate World HQ / Virtual"
        placeholderTextColor={colors.muted}
        value={draft.location}
        onChangeText={(location) => patch({ location })}
        maxLength={160}
      />

      <Text style={s.fieldLabel}>Online meeting link (optional)</Text>
      <TextInput
        style={s.input}
        placeholder="https://zoom.us/j/123456789"
        placeholderTextColor={colors.muted}
        value={draft.meetingLink || ""}
        onChangeText={(meetingLink) => patch({ meetingLink })}
        autoCapitalize="none"
        autoCorrect={false}
        keyboardType="url"
        maxLength={600}
      />
      <Text style={s.hint}>
        Zoom, Google Meet, Teams or any join link. The board taps it to open the meeting.
      </Text>

      <AgendaEditor
        value={draft.agenda}
        onChange={(agenda) => patch({ agenda })}
      />

      {hasContent ? (
        <View style={styles.savedRow}>
          <Ionicons name="checkmark-circle-outline" size={12} color={colors.goldDark} />
          <Text style={styles.savedText}>
            Draft saved automatically — you can leave the app and come back.
          </Text>
        </View>
      ) : null}

      <TouchableOpacity
        style={[s.primaryBtn, saving && s.busy]}
        onPress={submit}
        disabled={saving}
        activeOpacity={0.9}
      >
        <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
        {saving ? (
          <ActivityIndicator color={colors.white} />
        ) : (
          <>
            <Ionicons
              name={editing ? "save-outline" : "send-outline"}
              size={17}
              color={colors.white}
            />
            <Text style={s.primaryText}>
              {editing ? "Save changes & notify board" : "Schedule & notify board"}
            </Text>
          </>
        )}
      </TouchableOpacity>
    </View>
  );
}

