export default function NotificationsMenuModal({
  visible,
  onClose,
}: {
  visible: boolean;
  onClose: () => void;
}) {
  const [isAdmin, setIsAdmin] = useState(false);
  const [notifUnread, setNotifUnread] = useState(() => getNotifUnread());

  useEffect(() => subscribeNotifUnread(setNotifUnread), []);

  useEffect(() => {
    if (!visible) return;
    let alive = true;
    getSession().then((s) => {
      if (alive) setIsAdmin(s?.user?.role === "admin");
    });
    return () => {
      alive = false;
    };
  }, [visible]);

  const sections: MenuSection[] = [
    { title: "Requests", rows: REQUESTS_ROWS },
    { title: "Community", rows: COMMUNITY_ROWS },
    { title: "Achievements", rows: ACHIEVEMENT_ROWS },
    { title: "Serve & Earn", rows: SERVICES_ROWS },
    { title: "Volunteer", rows: VOLUNTEER_ROWS },
    ...(isAdmin ? [{ title: "Admin", rows: ADMIN_ROWS }] : []),
  ];

  const go = (route: string) => {
    onClose();
    // Defer so the modal is fully dismissed before navigating.
    setTimeout(() => {
      if (IS_WEB && route === "/appraisals") {
        window.location.assign(`${WEB_BASE_PATH}/appraisals`);
        return;
      }
      router.push(route as any);
    }, 120);
  };

  return (
    <Modal
      visible={visible}
      transparent
      animationType="fade"
      statusBarTranslucent
      onRequestClose={onClose}
    >
      <TouchableOpacity
        style={styles.backdrop}
        activeOpacity={1}
        onPress={onClose}
        accessibilityLabel="Close menu"
      >
        <TouchableOpacity style={styles.card} activeOpacity={1}>
          <View style={styles.header}>
            <View style={styles.headerIcon}>
              <Ionicons
                name="notifications-outline"
                size={18}
                color={colors.gold}
              />
            </View>
            <View style={styles.headerText}>
              <Text style={styles.headerTitle}>Notifications</Text>
              <Text style={styles.headerSub}>Jump back in</Text>
            </View>
            <TouchableOpacity
              onPress={onClose}
              style={styles.closeBtn}
              activeOpacity={0.8}
              accessibilityLabel="Close"
            >
              <Ionicons name="close" size={18} color={colors.muted} />
            </TouchableOpacity>
          </View>

          <ScrollView
            style={styles.scroll}
            contentContainerStyle={styles.scrollContent}
            showsVerticalScrollIndicator={false}
          >
            <TouchableOpacity
              style={[styles.row, styles.allRow]}
              activeOpacity={0.8}
              onPress={() => go("/notifications-center")}
              accessibilityRole="button"
              accessibilityLabel="All notifications"
            >
              <View style={styles.rowIconWrap}>
                <Ionicons name="albums-outline" size={18} color={colors.gold} />
              </View>
              <Text style={[styles.rowLabel, styles.allRowLabel]}>
                All notifications
              </Text>
              {notifUnread > 0 ? (
                <View style={styles.countBadge}>
                  <Text style={styles.countBadgeText}>
                    {notifUnread > 9 ? "9+" : notifUnread}
                  </Text>
                </View>
              ) : null}
              <Ionicons name="chevron-forward" size={16} color={colors.muted} />
            </TouchableOpacity>

            {sections.map((section) => (
              <View key={section.title} style={styles.section}>
                <Text style={styles.sectionTitle}>{section.title}</Text>
                <View style={styles.sectionCard}>
                  {section.rows.map((row) => (
                    <TouchableOpacity
                      key={row.key}
                      style={styles.row}
                      activeOpacity={0.8}
                      onPress={() => go(row.route)}
                      accessibilityRole="button"
                      accessibilityLabel={row.label}
                    >
                      <View style={styles.rowIconWrap}>
                        <Ionicons
                          name={row.icon}
                          size={18}
                          color={colors.gold}
                        />
                      </View>
                      <Text style={styles.rowLabel}>{row.label}</Text>
                      <Ionicons
                        name="chevron-forward"
                        size={16}
                        color={colors.muted}
                      />
                    </TouchableOpacity>
                  ))}
                </View>
              </View>
            ))}
          </ScrollView>
        </TouchableOpacity>
      </TouchableOpacity>
    </Modal>
  );
}

