import {
  SHORT_TTL,
  cachedFetch,
  type CachedFetchOptions,
} from "@/services/cache";
import type { BankingDetails } from "@/services/sponsorships";
import type { CartLine } from "@/services/cart";

/**
 * Store orders — checkout, receipts and progress tracking.
 *
 * Statuses mirror `backend/lib/orders.ts`: the backend owns the transitions
 * (admins move orders forward in the web console) and this module only reads
 * them, so the mobile timeline and the admin queue can never disagree.
 */

export type OrderStatus =
  | "received"
  | "payment_received"
  | "shipped"
  | "delivered"
  | "cancelled";

/** The happy-path steps the progress bar walks through. */
export const ORDER_PROGRESS: OrderStatus[] = [
  "received",
  "payment_received",
  "shipped",
  "delivered",
];

export const ORDER_STATUS_LABEL: Record<OrderStatus, string> = {
  received: "Order received",
  payment_received: "Payment received",
  shipped: "Order shipped",
  delivered: "Order delivered",
  cancelled: "Cancelled",
};

export const ORDER_STATUS_SUB: Record<OrderStatus, string> = {
  received: "Waiting for payment",
  payment_received: "Being processed",
  shipped: "On its way to you",
  delivered: "Delivered",
  cancelled: "Order cancelled",
};

export type OrderItem = {
  itemId: string;
  name: string;
  price: number;
  qty: number;
  size?: string | null;
  image?: string;
};

export type OrderStatusEntry = {
  status: OrderStatus;
  at: string;
  note?: string;
};

export type Order = {
  _id: string;
  orderNumber: string;
  customerName: string;
  phone: string;
  email: string;
  note: string;
  items: OrderItem[];
  subtotal: number;
  total: number;
  currency: string;
  status: OrderStatus;
  statusHistory: OrderStatusEntry[];
  /** Estimated delivery date (`YYYY-MM-DD`), set by an admin. */
  eta: string | null;
  createdAt: string | null;
  updatedAt: string | null;
};

export type OrderCustomer = {
  name: string;
  phone: string;
  email?: string;
  note?: string;
};

export type PlacedOrder = { order: Order; banking: BankingDetails | null };

function orderFetch<T>(path: string, options: CachedFetchOptions = {}): Promise<T> {
  return cachedFetch<T>(path, options, ["/api/orders"]);
}

export const ordersApi = {
  /** Place an order — signed in. Returns the receipt + banking details. */
  place: (lines: CartLine[], customer: OrderCustomer) =>
    orderFetch<{ data: PlacedOrder }>("/api/orders", {
      method: "POST",
      cacheTtl: 0,
      body: JSON.stringify({
        items: lines.map((l) => ({
          itemId: l.itemId,
          qty: l.qty,
          size: l.size,
        })),
        customer,
      }),
    }),

  /** The signed-in buyer's orders, newest first. */
  mine: () => orderFetch<{ data: Order[] }>("/api/orders", { cacheTtl: SHORT_TTL }),

  /** One order by id or order number (`RW-2026-0001`). */
  get: (id: string) =>
    orderFetch<{ data: Order }>(`/api/orders/${encodeURIComponent(id)}`, {
      cacheTtl: SHORT_TTL,
    }),
};

/** Index of the furthest step reached, for the progress bar. */
export function progressIndex(order: Order): number {
  if (order.status === "cancelled") return -1;
  const at = ORDER_PROGRESS.indexOf(order.status);
  return at === -1 ? 0 : at;
}

/** Friendly "14 Oct 2026" for ETAs and history stamps. */
export function formatOrderDate(value?: string | null): string {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString(undefined, {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

/** The latest history entry for a status (used to show when it happened). */
export function historyAt(order: Order, status: OrderStatus): string | null {
  const entry = [...order.statusHistory].reverse().find((h) => h.status === status);
  return entry?.at ?? null;
}
