import { getOptimizedImageUrl } from "@/services/cloudinary";

type FixtureDate = {
  day: number;
  month: string;
  weekday: string;
  time: string;
};

function parseFixture(dateStr: string, time: string): FixtureDate {
  const d = new Date(`${dateStr}T00:00:00`);
  if (isNaN(d.getTime())) return { day: 0, month: dateStr, weekday: "", time };
  return {
    day: d.getDate(),
    month: d.toLocaleDateString("en-GB", { month: "short" }).toUpperCase(),
    weekday: d.toLocaleDateString("en-GB", { weekday: "short" }),
    time,
  };
}

function goBack(teamName: string) {
  if (router.canDismiss?.()) router.dismiss();
  else
    router.replace({ pathname: "/sports" as any, params: { sport: teamName } });
}

export default function TeamScreen() {
  const { teamId } = useLocalSearchParams<{ teamId?: string }>();
  const insets = useSafeAreaInsets();
  const { data: catalog, loading, error } = useSportsCatalog();
  const { find: findClub } = useClubs();
  const [payload, setPayload] = useState<RosterPayload | null>(null);
  const [roster, setRoster] = useState<SquadRoster | null>(null);
  const [rosterReady, setRosterReady] = useState(false);
  const { check } = useMyRegistration();
  const [already, setAlready] = useState<MyRegistration | null>(null);

  useEffect(() => {
    let active = true;
    fetchRoster(teamId ?? "")
      .then((res) => {
        if (active) setPayload(res);
      })
      .catch(() => {
        if (active) setPayload(null);
      });
    return () => {
      active = false;
    };
  }, [teamId]);

  const team = teamId && catalog ? catalog.getTeam(teamId) : undefined;
  // Every "Join / Register" CTA runs through here: an existing squad spot
  // opens the status sheet instead of skipping to the registration form.
  const openRegister = async (position?: string) => {
    if (!team) return;
    const mine = await check();
    if (mine) {
      setAlready(mine);
      return;
    }
    router.push({
      pathname: "/sports/[teamId]/register" as any,
      params: position ? { teamId: team.id, position } : { teamId: team.id },
    });
  };

  // Team sheet — registrations overlaid on the catalogue's squad (awaited,
  // because the position slots live in GET /api/sports/teams). Every setState
  // runs after an await, so the effect body itself never writes state.
  useEffect(() => {
    let active = true;
    const squad = team && catalog ? catalog.getSquad(team.id) : undefined;
    (async () => {
      await Promise.resolve();
      if (!active) return;
      if (!team || !squad) {
        setRoster(null);
        setRosterReady(true);
        return;
      }
      setRosterReady(false);
      try {
        const built = await buildRoster(
          squad,
          payload?.registrations ?? [],
          team.sport,
        );
        if (!active) return;
        setRoster(built);
        setRosterReady(true);
      } catch {
        if (!active) return;
        setRoster(null);
        setRosterReady(true);
      }
    })();
    return () => {
      active = false;
    };
  }, [catalog, team, payload]);

  if (loading) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={s.missingWrap}>
            <ActivityIndicator size="large" color={colors.goldDark} />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (error || !catalog) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={s.missingWrap}>
            <Ionicons
              name="alert-circle-outline"
              size={40}
              color={colors.gold}
            />
            <Text style={s.missingTitle}>Teams unavailable</Text>
            <Text style={[s.sectionSub, { textAlign: "center" }]}>
              {error ?? ""}
            </Text>
            <TouchableOpacity style={s.missingBtn} onPress={() => goBack("")}>
              <Text style={s.missingBtnText}>Back to sports</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (!team) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={s.missingWrap}>
            <Ionicons
              name="alert-circle-outline"
              size={40}
              color={colors.gold}
            />
            <Text style={s.missingTitle}>Team not found</Text>
            <TouchableOpacity style={s.missingBtn} onPress={() => goBack("")}>
              <Text style={s.missingBtnText}>Back to sports</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const theme = SPORT_THEME[team.sport];
  const club = findClub(team.clubSlug);
  const squad = catalog.getSquad(team.id);
  const director = catalog.director;
  const next = squad?.fixtures[0];
  const coach = squad?.coach ?? { name: "Head Coach", role: "Head Coach" };
  const coachName = coach.name || "Head Coach";
  const clubColors: [string, string] = club
    ? [club.color, club.colorDark]
    : (theme.colors as [string, string]);
  // "21–33 yrs" → "21–33" for the header's age line.
  const ageLabel = club?.ageRange.replace(/\s*yrs$/i, "").trim();
  const nextFixture = next ? parseFixture(next.date, next.time) : null;
  // Single clubs-screen hero slide (no carousel) — the team poster with the
  // guarded register CTA and squad meta carried over from the old chips.
  const heroSlide: HeroSlide = {
    key: team.id,
    image: teamHeroPhoto(team),
    gradient: [colors.forestDark, theme.colors[1], theme.colors[0]],
    title: team.name,
    meta: [
      {
        label: "Registered",
        value: `${roster?.registered ?? 0}/${squad?.players.length ?? 0}`,
      },
      { label: "Coach", value: coachName },
      {
        label: "Next",
        value: nextFixture
          ? `${nextFixture.day} ${nextFixture.month}`
          : "Not scheduled",
      },
    ],
    cta: { label: "Join this team", onPress: () => void openRegister() },
  };

  const openPlayer = (name: string) =>
    router.push({
      pathname: "/sports/[teamId]/[player]" as any,
      params: { teamId: team.id, player: playerSlug(name) },
    });

  const openSlot = (position: string, registrantName?: string) => {
    if (registrantName) openPlayer(registrantName);
    else void openRegister(position);
  };

  return (
    <SafeAreaProvider>
      <SafeAreaView style={s.safe} edges={["top"]}>
        <StatusBar style="dark" />
        <ScrollView
          contentContainerStyle={[
            s.content,
            { paddingBottom: 40 + insets.bottom + 70 },
          ]}
          showsVerticalScrollIndicator={false}
        >
          {/* Back + clubs-style header: sport / team name / age + tagline */}
          <View style={s.topBar}>
            <TouchableOpacity
              style={s.backBtn}
              onPress={() => goBack(team.sport)}
              activeOpacity={0.85}
              accessibilityLabel="Back to sports"
            >
              <Ionicons name="chevron-back" size={20} color={colors.forest} />
            </TouchableOpacity>
          </View>
          <View style={s.landingHeader}>
            <Text style={s.headerEyebrow}>{team.sport.toUpperCase()}</Text>
            <Text style={s.landingTitle}>{team.name}</Text>
            <Text style={s.headerSubtitle}>
              {ageLabel ? `Ages ${ageLabel} · ` : ""}
              {team.tagline}
            </Text>
          </View>

          {/* Hero — clubs-screen style, one slide and no carousel */}
          <View style={s.heroWrap}>
            <LandingHeroSlide slide={heroSlide} />
          </View>

          {/* Squad */}
          <View style={s.sectionHead}>
            <View style={s.sectionHeadText}>
              <Text style={s.sectionEyebrow}>
                {club?.name ?? "Relate"} · Squad
              </Text>
              <Text style={s.sectionTitle}>The {team.initials} squad</Text>
              <Text style={s.sectionSub}>
                {(roster?.registered ?? 0) === 0
                  ? `Open to registration — the first ${squad?.players.length ?? 0} players to register make up the team sheet.`
                  : squad?.coach.name
                    ? `${roster?.registered} of ${squad?.players.length} spots filled, coached by ${coach.name}.`
                    : `${roster?.registered} of ${squad?.players.length} spots filled · Head Coach to be announced.`}
              </Text>
            </View>
          </View>
          <View style={s.slotGrid}>
            {!rosterReady ? (
              <View style={s.slotState}>
                <ActivityIndicator size="small" color={colors.goldDark} />
              </View>
            ) : roster && roster.slots.length > 0 ? (
              roster.slots.map((slot, i) => {
              const registrant = slot.registrant;
              const name = registrant?.name ?? slot.placeholder.name;
              return (
                <TouchableOpacity
                  key={`${slot.position}-${i}`}
                  style={s.slotCard}
                  activeOpacity={0.9}
                  onPress={() => openSlot(slot.position, registrant?.name)}
                  accessibilityRole="button"
                  accessibilityLabel={
                    registrant
                      ? `Open ${name}`
                      : `Claim the ${slot.position} spot`
                  }
                >
                  <View style={s.slotAvatarWrap}>
                    {registrant?.photoUrl ? (
                      <ExpoImage
                        source={{ uri: getOptimizedImageUrl(registrant.photoUrl, 160) }}
                        style={s.slotAvatar}
                        contentFit="cover"
                        transition={250}
                      />
                    ) : (
                      <LinearGradient
                        colors={clubColors}
                        start={{ x: 0, y: 0 }}
                        end={{ x: 1, y: 1 }}
                        style={s.slotAvatar}
                      >
                        <Text style={s.slotBadge}>{slot.badge}</Text>
                      </LinearGradient>
                    )}
                    <View style={s.slotNumber}>
                      <Text style={s.slotNumberText}>{slot.number}</Text>
                    </View>
                  </View>
                  <Text style={s.slotName} numberOfLines={2}>
                    {name}
                  </Text>
                  <Text style={s.slotPos} numberOfLines={2}>
                    {slot.position}
                  </Text>
                  <Text style={[s.slotStatus, !registrant && s.slotStatusOpen]}>
                    {registrant ? "Registered" : "Claim this spot"}
                  </Text>
                </TouchableOpacity>
              );
            })
            ) : (
              <View style={s.slotState}>
                <Text style={[s.sectionSub, { textAlign: "center" }]}>
                  No team sheet yet — register to claim the first spot.
                </Text>
              </View>
            )}
          </View>

          {/* Reserves */}
          {roster && roster.reserves.length > 0 ? (
            <View style={s.reserveCard}>
              <Text style={s.reserveEyebrow}>Cover</Text>
              <Text style={s.reserveTitle}>Reserves</Text>
              <Text style={s.reserveSub}>
                Registered inside the {team.sport} position limit but outside
                the starting sheet — first up when a spot opens.
              </Text>
              <View style={s.chipWrap}>
                {roster.reserves.map((r) => (
                  <TouchableOpacity
                    key={r.id}
                    style={s.personChip}
                    activeOpacity={0.8}
                    onPress={() => openPlayer(r.name)}
                    accessibilityRole="button"
                    accessibilityLabel={`Open ${r.name}'s profile`}
                  >
                    {r.photoUrl ? (
                      <ExpoImage
                        source={{ uri: getOptimizedImageUrl(r.photoUrl, 160) }}
                        style={s.personAvatar}
                        contentFit="cover"
                        transition={200}
                      />
                    ) : (
                      <View style={[s.personAvatar, s.personAvatarFallback]}>
                        <Text style={s.personAvatarText}>{r.positionCode}</Text>
                      </View>
                    )}
                    <Text style={s.personName}>{r.name}</Text>
                    <Text style={s.personCode}>{r.positionCode}</Text>
                  </TouchableOpacity>
                ))}
              </View>
            </View>
          ) : null}

          {/* Waitlist */}
          {roster && roster.waitlist.length > 0 ? (
            <View style={s.waitCard}>
              <Text style={s.reserveEyebrow}>Queue</Text>
              <Text style={s.reserveTitle}>Waiting list</Text>
              <Text style={s.reserveSub}>
                Registered after their positions filled — next in line if anyone
                drops out.
              </Text>
              <View style={s.chipWrap}>
                {roster.waitlist.map((r) => (
                  <TouchableOpacity
                    key={r.id}
                    style={[s.personChip, s.personChipWait]}
                    activeOpacity={0.8}
                    onPress={() => openPlayer(r.name)}
                    accessibilityRole="button"
                    accessibilityLabel={`Open ${r.name}'s profile`}
                  >
                    {r.photoUrl ? (
                      <ExpoImage
                        source={{ uri: getOptimizedImageUrl(r.photoUrl, 160) }}
                        style={s.personAvatar}
                        contentFit="cover"
                        transition={200}
                      />
                    ) : (
                      <View style={[s.personAvatar, s.personAvatarFallback]}>
                        <Text style={s.personAvatarText}>{r.positionCode}</Text>
                      </View>
                    )}
                    <Text style={s.personName}>{r.name}</Text>
                    <Text style={s.personCode}>{r.positionCode}</Text>
                  </TouchableOpacity>
                ))}
              </View>
            </View>
          ) : null}

          {/* Registration callout */}
          <View style={s.callout}>
            <View style={s.calloutBody}>
              <Text style={s.calloutTitle}>
                Registration is open — claim your position.
              </Text>
              <Text style={s.calloutSub}>
                Photo, height, dominant foot and hand, position. First come,
                first picked; every position takes up to {catalog.maxPerPosition}.
              </Text>
            </View>
            <TouchableOpacity
              style={[s.calloutBtn, { backgroundColor: clubColors[1] }]}
              activeOpacity={0.9}
              onPress={() => openRegister()}
              accessibilityRole="button"
              accessibilityLabel="Register as a player"
            >
              <Text style={s.calloutBtnText}>Register as a player</Text>
              <Ionicons name="arrow-forward" size={15} color={colors.white} />
            </TouchableOpacity>
          </View>

          {/* Head Coach */}
          <View style={[s.sectionHead, s.sectionGap]}>
            <View style={s.sectionHeadText}>
              <Text style={s.sectionEyebrow}>Head Coach</Text>
              <Text style={s.sectionTitle}>Who runs the team</Text>
            </View>
          </View>
          <View style={s.staffList}>
            <View style={s.staffCard}>
              <LinearGradient
                colors={clubColors}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={s.staffAvatar}
              >
                <Text style={s.staffInitials}>
                  {coachName
                    .split(" ")
                    .map((n: string) => n[0])
                    .join("")
                    .slice(0, 2)}
                </Text>
              </LinearGradient>
              <View style={s.staffBody}>
                <Text style={s.staffName}>{coachName}</Text>
                <Text style={s.staffRole}>
                  {coach.name
                    ? `${coach.role || "Head Coach"} · ${team.name}`
                    : `Leads ${team.name}`}
                </Text>
              </View>
            </View>
            {director.name ? (
              <View style={s.staffCard}>
                <LinearGradient
                  colors={[colors.gold, colors.goldDark]}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 1 }}
                  style={s.staffAvatar}
                >
                  <Text style={s.staffInitials}>
                    {director.name
                      .split(" ")
                      .map((n: string) => n[0])
                      .join("")
                      .slice(0, 2)}
                  </Text>
                </LinearGradient>
                <View style={s.staffBody}>
                  <Text style={s.staffName}>{director.name}</Text>
                  <Text style={s.staffRole}>{director.role}</Text>
                </View>
              </View>
            ) : null}
          </View>

          {/* Fixtures */}
          {(squad?.fixtures ?? []).length > 0 ? (
            <>
              <View style={[s.sectionHead, s.sectionGap]}>
                <View style={s.sectionHeadText}>
                  <Text style={s.sectionEyebrow}>Upcoming</Text>
                  <Text style={s.sectionTitle}>Fixtures</Text>
                </View>
              </View>
              <View style={s.fixtureList}>
                {(squad?.fixtures ?? []).map((fx, i) => {
                  const d = parseFixture(fx.date, fx.time);
                  return (
                    <View key={fx.date + i} style={s.fixtureRow}>
                      <View style={s.fixtureDate}>
                        <Text style={s.fixtureDay}>{d.day || "—"}</Text>
                        <Text style={s.fixtureMonth}>{d.month}</Text>
                      </View>
                      <View style={s.fixtureBody}>
                        <View style={s.fixtureTop}>
                          <Text style={s.fixtureOpponent}>
                            vs {fx.opponent}
                          </Text>
                          <View
                            style={[
                              s.fixtureHomeChip,
                              { backgroundColor: `${theme.accent}1A` },
                            ]}
                          >
                            <Text
                              style={[
                                s.fixtureHomeText,
                                { color: theme.accent },
                              ]}
                            >
                              {fx.home ? "HOME" : "AWAY"}
                            </Text>
                          </View>
                        </View>
                        <Text style={s.fixtureComp} numberOfLines={1}>
                          {fx.competition}
                        </Text>
                        <View style={s.fixtureMeta}>
                          <Ionicons
                            name="location-outline"
                            size={12}
                            color={colors.muted}
                          />
                          <Text style={s.fixtureMetaText} numberOfLines={1}>
                            {fx.venue}
                          </Text>
                        </View>
                      </View>
                      <View style={s.fixtureTimeWrap}>
                        <Text style={s.fixtureTime}>{d.time}</Text>
                        <Text style={s.fixtureWeekday}>{d.weekday}</Text>
                      </View>
                    </View>
                  );
                })}
              </View>
            </>
          ) : (
            <>
              <View style={[s.sectionHead, s.sectionGap]}>
                <View style={s.sectionHeadText}>
                  <Text style={s.sectionEyebrow}>Upcoming</Text>
                  <Text style={s.sectionTitle}>Fixtures</Text>
                </View>
              </View>
              <View style={s.fixtureEmpty}>
                <View style={s.fixtureEmptyIcon}>
                  <Ionicons
                    name="calendar-outline"
                    size={24}
                    color={colors.goldDark}
                  />
                </View>
                <Text style={s.fixtureEmptyTitle}>
                  No fixtures scheduled
                </Text>
                <Text style={s.fixtureEmptyText}>
                  Fixtures will be published here once the league confirms the
                  match calendar.
                </Text>
              </View>
            </>
          )}

          {/* Register + club link */}
          <View style={s.bottomCard}>
            <View style={s.bottomIcon}>
              <MaterialCommunityIcons
                name={theme.icon as any}
                size={24}
                color={theme.accent}
              />
            </View>
            <Text style={s.bottomTitle}>Come play for {team.name}</Text>
            <Text style={s.bottomText}>
              Register and we&rsquo;ll take you straight to the team&rsquo;s
              WhatsApp group. Training runs weekly and match days are every
              weekend.
            </Text>
            <TouchableOpacity
              style={[s.bottomBtn, { backgroundColor: clubColors[1] }]}
              activeOpacity={0.9}
              onPress={() => openRegister()}
            >
              <Ionicons name="football" size={17} color={colors.white} />
              <Text style={s.bottomBtnText}>Register to join</Text>
            </TouchableOpacity>
            {club ? (
              <TouchableOpacity
                style={s.clubLink}
                activeOpacity={0.8}
                onPress={() =>
                  router.push({
                    pathname: "/clubs/[slug]",
                    params: { slug: club.slug },
                  })
                }
              >
                <Text style={s.clubLinkText}>
                  Part of {club.name} · open the club page
                </Text>
                <Ionicons
                  name="chevron-forward"
                  size={14}
                  color={colors.goldDark}
                />
              </TouchableOpacity>
            ) : null}
          </View>
        </ScrollView>
      </SafeAreaView>
      <AlreadyOnTeamModal
        registration={already}
        currentTeamId={team?.id}
        onClose={() => setAlready(null)}
      />
    </SafeAreaProvider>
  );
}

