import * as BackgroundFetch from "expo-background-fetch";
import * as TaskManager from "expo-task-manager";
import { maybeReschedulePrayerNotifications } from "./prayer-schedule";
import { IS_WEB } from "./config";

const TASK_NAME = "prayer-notifications-reschedule";

// Extends the multi-day prayer notification window in the background: runs at
// most every 15 minutes, but only actually reschedules when something
// significant changed (location, timezone, preferences) or the window is
// about to expire — see prayer-schedule.ts.
if (!TaskManager.isTaskDefined(TASK_NAME)) {
  TaskManager.defineTask(TASK_NAME, async () => {
    try {
      const result = await maybeReschedulePrayerNotifications();
      return result.action === "scheduled"
        ? BackgroundFetch.BackgroundFetchResult.NewData
        : BackgroundFetch.BackgroundFetchResult.NoData;
    } catch {
      return BackgroundFetch.BackgroundFetchResult.Failed;
    }
  });
}

export async function registerBackgroundReschedule(): Promise<void> {
  if (IS_WEB) return;
  const alreadyRegistered = await TaskManager.isTaskRegisteredAsync(TASK_NAME);
  if (alreadyRegistered) return;
  await BackgroundFetch.registerTaskAsync(TASK_NAME, {
    minimumInterval: 15 * 60,
    stopOnTerminate: false,
    startOnBoot: true,
  });
}

export async function unregisterBackgroundReschedule(): Promise<void> {
  if (IS_WEB) return;
  try {
    await BackgroundFetch.unregisterTaskAsync(TASK_NAME);
  } catch {}
}
