export const DEFAULT_PHONE_PREFIX = "+27 ";
export const SA_COUNTRY_CODE = "27";

export function toInternationalDigits(phone?: string): string {
  if (!phone) return "";
  const digits = phone.replace(/\D/g, "");
  if (!digits) return "";
  if (digits.startsWith("0027")) return digits.slice(2);
  if (digits.startsWith("00")) return digits.slice(2);
  if (digits.startsWith("27")) return digits;
  if (digits.startsWith("0")) return `27${digits.slice(1)}`;
  return `27${digits}`;
}

export function waLink(phone?: string): string | null {
  if (!phone) return null;
  const digits = toInternationalDigits(phone);
  if (!digits || digits.length < 9) return null;
  return `https://wa.me/${digits}`;
}

export function telLink(phone?: string): string | null {
  if (!phone) return null;
  const digits = toInternationalDigits(phone);
  if (!digits || digits.length < 9) return null;
  return `tel:+${digits}`;
}

export function hasValidPhone(phone?: string): boolean {
  if (!phone) return false;
  const digits = phone.replace(/\D/g, "");
  return digits.length >= 9;
}
