/**
 * Smart Saver targets — blueprint §5.
 *
 * Mirrors web_app/lib/savings.ts so the Expo app shows the same weekly target
 * for every age.
 */
export type SavingsTarget = {
  age: number;
  weekly: number;
  annual: number;
  cumulative: number;
};

export const SAVINGS_TARGETS: SavingsTarget[] = [
  { age: 6, weekly: 5, annual: 250, cumulative: 250 },
  { age: 7, weekly: 8, annual: 400, cumulative: 650 },
  { age: 8, weekly: 12, annual: 600, cumulative: 1250 },
  { age: 9, weekly: 16, annual: 800, cumulative: 2050 },
  { age: 10, weekly: 20, annual: 1000, cumulative: 3050 },
  { age: 11, weekly: 25, annual: 1250, cumulative: 4300 },
  { age: 12, weekly: 30, annual: 1500, cumulative: 5800 },
  { age: 13, weekly: 35, annual: 1750, cumulative: 7550 },
  { age: 14, weekly: 40, annual: 2000, cumulative: 9550 },
  { age: 15, weekly: 48, annual: 2400, cumulative: 11950 },
  { age: 16, weekly: 55, annual: 2750, cumulative: 14700 },
];

export function savingsForAge(age: number): SavingsTarget | null {
  const n = Math.trunc(Number(age));
  return SAVINGS_TARGETS.find((t) => t.age === n) ?? null;
}

/** Yearly Smart Saver target for each Sprout tier. */
export type ClubSavingsTarget = {
  slug: string;
  name: string;
  ageRange: string;
  annual: number;
};

export const CLUB_SAVINGS_TARGETS: ClubSavingsTarget[] = [
  { slug: "sprout-kids", name: "Sprout Kids", ageRange: "6 – 8 yrs", annual: 250 },
  { slug: "sprout-tweens", name: "Sprout Tweens", ageRange: "9 – 12 yrs", annual: 450 },
  { slug: "sprout-teens", name: "Sprout Teens", ageRange: "13 – 16 yrs", annual: 1000 },
];

/**
 * Target for a Sprout club page. The parent "sprout" page shows the range
 * across all three tiers; each age-class page shows its own yearly target.
 */
export function sproutTargetForClub(slug: string) {
  if (slug === "sprout") {
    const amounts = CLUB_SAVINGS_TARGETS.map((t) => t.annual);
    return {
      name: "Sprout",
      ageRange: "6 – 16 yrs",
      annualMin: Math.min(...amounts),
      annualMax: Math.max(...amounts),
    };
  }
  const target = CLUB_SAVINGS_TARGETS.find((t) => t.slug === slug);
  return target
    ? { ...target, annualMin: target.annual, annualMax: target.annual }
    : null;
}

export const SMART_SAVER_SPLIT = { vault: 0.6, wallet: 0.4 } as const;

export function splitContribution(amount: number) {
  const cents = Math.round(Math.max(0, Number(amount) || 0) * 100);
  const vaultCents = Math.round(cents * SMART_SAVER_SPLIT.vault);
  return {
    vault: vaultCents / 100,
    wallet: (cents - vaultCents) / 100,
  };
}

/** Target range for a club's age band, e.g. "9 – 12 yrs". */
export function savingsForRange(range: string) {
  const nums = (range.match(/[0-9]+/g) ?? []).map(Number);
  if (!nums.length) return null;
  const min = nums[0];
  const max = nums[1] ?? nums[0];
  const rows = SAVINGS_TARGETS.filter((t) => t.age >= min && t.age <= max);
  if (!rows.length) return null;
  const last = rows[rows.length - 1];
  return {
    weeklyMin: rows[0].weekly,
    weeklyMax: last.weekly,
    annualMin: rows[0].annual,
    annualMax: last.annual,
    cumulative: last.cumulative,
  };
}
