import { Image } from "expo-image";
import { LinearGradient } from "expo-linear-gradient";
import { memo } from "react";
import { StyleSheet, useWindowDimensions, View } from "react-native";
import type { Publication } from "@/data/publications";
import { getOptimizedImageUrl } from "@/services/cloudinary";

/**
 * Full-bleed publication hero image (60% of screen height) with a soft top
 * scrim so a floating back button stays legible. The masthead, issue line and
 * title are rendered in the reader below the image, not over it.
 */
function MagazineCover({ publication }: { publication: Publication }) {
  const { height } = useWindowDimensions();

  return (
    <View style={[styles.root, { height: Math.round(height * 0.6) }]}>
      <Image
        source={{ uri: getOptimizedImageUrl(publication.cover, 720) }}
        style={styles.fill}
        contentFit="cover"
        transition={400}
      />
      <LinearGradient
        colors={["rgba(10,18,40,0.45)", "transparent"]}
        style={styles.fill}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  root: {
    width: "100%",
    backgroundColor: "#dfe9f3",
    overflow: "hidden",
  },
  fill: {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
  },
});

export default memo(MagazineCover);