const money = (value: number) => `R ${Math.round(value || 0).toLocaleString("en-US")}`;

// Fixed split of the current balance — what is actually in the coffers.
const ALLOCATION = [
  { key: "relief", label: "Relief", pct: 55, color: colors.gold },
  { key: "reserve", label: "Reserve", pct: 30, color: colors.forestSoft },
  { key: "administration", label: "Administration", pct: 15, color: colors.amber },
] as const;

function allocationAmounts(balance: number) {
  const base = Math.max(0, balance);
  const relief = Math.round((base * 55) / 100);
  const reserve = Math.round((base * 30) / 100);
  // Administration takes the remainder so the three shares always add up.
  return ALLOCATION.map((slice) => ({
    ...slice,
    amount:
      slice.key === "relief" ? relief : slice.key === "reserve" ? reserve : base - relief - reserve,
  }));
}

function SectionHead({
  icon,
  title,
}: {
  icon: React.ComponentProps<typeof Ionicons>["name"];
  title: string;
}) {
  return (
    <View style={styles.cardHead}>
      <Ionicons name={icon} size={16} color={colors.goldDark} />
      <Text style={styles.cardTitle}>{title}</Text>
    </View>
  );
}

function Legend({ color, label }: { color: string; label: string }) {
  return (
    <View style={styles.legendItem}>
      <View style={[styles.legendDot, { backgroundColor: color }]} />
      <Text style={styles.legendText}>{label}</Text>
    </View>
  );
}

function Stat({
  label,
  value,
  tone,
}: {
  label: string;
  value: string;
  tone?: "positive" | "negative";
}) {
  return (
    <View style={styles.stat}>
      <Text style={styles.statLabel}>{label}</Text>
      <Text
        style={[
          styles.statValue,
          tone === "positive" && { color: colors.goldDark },
          tone === "negative" && { color: colors.error },
        ]}
        numberOfLines={1}
        adjustsFontSizeToFit
      >
        {value}
      </Text>
    </View>
  );
}

export default function PerformanceScreen() {
  const insets = useSafeAreaInsets();
  const [data, setData] = useState<PerformanceSummary | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [chartWidth, setChartWidth] = useState(0);
  const [selectedMonth, setSelectedMonth] = useState<number | null>(null);

  const load = useCallback(async (force = false) => {
    try {
      setError(null);
      const res = await performanceApi.get({ forceRefresh: force });
      setData(res.data);
    } catch (e: any) {
      setError(e?.message || "Failed to load organisation performance.");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    const task = InteractionManager.runAfterInteractions(() => {
      void load();
    });
    return () => task.cancel();
  }, [load]);

  useEffect(() => {
    const sub = BackHandler.addEventListener("hardwareBackPress", () => {
      router.back();
      return true;
    });
    return () => sub.remove();
  }, []);

  const onRefresh = () => {
    setRefreshing(true);
    load(true);
  };

  const mixTotal = data?.incomeMix.reduce((sum, row) => sum + row.value, 0) ?? 0;
  const allocation = allocationAmounts(data?.balance ?? 0);
  const selected =
    data?.months.find((month) => month.month === selectedMonth) ?? null;
  const impact = data?.latestImpact;
  const hasImpact =
    !!impact &&
    (impact.families > 0 ||
      impact.mealsServed > 0 ||
      impact.children > 0 ||
      impact.placements > 0 ||
      impact.events > 0);

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.header}>
          <TouchableOpacity
            onPress={() => router.back()}
            style={styles.headerBtn}
            accessibilityLabel="Close performance"
          >
            <Ionicons name="close" size={22} color={colors.darkGreen} />
          </TouchableOpacity>
          <Text style={styles.headerTitle}>Performance</Text>
          <View style={{ width: 36 }} />
        </View>

        {loading ? (
          <View style={styles.skeletonWrap}>
            <SkeletonPulse style={{ height: 190, borderRadius: 18 }} />
            <SkeletonPulse style={{ height: 230, borderRadius: 16 }} />
            <SkeletonPulse style={{ height: 210, borderRadius: 16 }} />
          </View>
        ) : error ? (
          <EmptyState
            icon="warning-outline"
            color={colors.error}
            eyebrow="Something went wrong"
            title="Couldn't load performance"
            subtitle={error}
            actionLabel="Retry"
            onAction={() => {
              setLoading(true);
              load(true);
            }}
          />
        ) : !data || (data.reportCount === 0 && !data.appraisals) ? (
          <EmptyState
            icon="stats-chart-outline"
            color={colors.gold}
            eyebrow="Nothing published yet"
            title="No financial reports yet"
            subtitle="Once a monthly report is published, the organisation's income, spending and coffer progress appear here."
          />
        ) : (
          <ScrollView
            contentContainerStyle={[styles.list, { paddingBottom: 32 + insets.bottom }]}
            showsVerticalScrollIndicator={false}
            refreshControl={
              <RefreshControl
                refreshing={refreshing}
                onRefresh={onRefresh}
                tintColor={colors.goldDark}
                colors={[colors.goldDark]}
              />
            }
          >
            {data.reportCount > 0 ? (
              <>
            <View style={styles.hero}>
              <View style={styles.heroTop}>
                <Text style={styles.heroEyebrow}>
                  ORGANISATION HEALTH · {data.year}
                </Text>
                <View style={styles.seasonPill}>
                  <Text style={styles.seasonText}>{data.season.name}</Text>
                </View>
              </View>

              <Text style={styles.heroScore}>{data.coffer.progressPct}%</Text>
              <Text style={styles.heroCaption}>
                of the {money(data.coffer.target)} annual coffer target
              </Text>

              <View style={styles.progressTrack}>
                <View
                  style={[
                    styles.progressFill,
                    { width: `${Math.min(100, data.coffer.progressPct)}%` },
                  ]}
                />
              </View>
              <View style={styles.progressRow}>
                <Text style={styles.progressText}>
                  {money(data.coffer.raised)} raised
                </Text>
                <Text style={styles.progressText}>
                  {money(data.coffer.remaining)} to go
                </Text>
              </View>

              <View style={styles.heroDivider} />

              <View style={styles.heroStats}>
                <Stat label="INCOME" value={money(data.totals.income)} />
                <Stat label="SPEND" value={money(data.totals.expenses)} />
                <Stat
                  label="BALANCE"
                  value={money(data.balance)}
                  tone={data.balance >= 0 ? "positive" : "negative"}
                />
              </View>
            </View>

            <View style={styles.card}>
              <SectionHead icon="wallet-outline" title="Income allocation" />
              <Text style={styles.cardSub}>
                55% Relief · 30% Reserve · 15% Administration
              </Text>
              <View style={styles.allocBar}>
                {allocation.map((slice) => (
                  <View
                    key={slice.key}
                    style={{ flex: slice.pct, backgroundColor: slice.color }}
                  />
                ))}
              </View>
              {allocation.map((slice) => (
                <View key={slice.key} style={styles.allocRow}>
                  <View style={[styles.legendDot, { backgroundColor: slice.color }]} />
                  <Text style={styles.allocLabel}>{slice.label}</Text>
                  <Text style={styles.allocPct}>{slice.pct}%</Text>
                  <Text style={styles.allocValue}>{money(slice.amount)}</Text>
                </View>
              ))}
              <Text style={styles.cardNote}>
                Split of the current balance — what is in the coffers today.
              </Text>
            </View>

            {data.app ? (
              <View style={styles.card}>
                <SectionHead icon="download-outline" title="App downloads" />
                <View style={[styles.heroStats, styles.appStats]}>
                  <Stat
                    label="TOTAL"
                    value={data.app.downloads.toLocaleString("en-US")}
                  />
                  <Stat
                    label={
                      data.app.latestVersion
                        ? `V${data.app.latestVersion}`
                        : "LATEST"
                    }
                    value={data.app.latestDownloads.toLocaleString("en-US")}
                  />
                  <Stat label="RELEASES" value={String(data.app.releases)} />
                </View>
                <Text style={styles.cardNote}>
                  APK downloads from GitHub releases.
                </Text>
              </View>
            ) : null}

            <View style={styles.card}>
              <SectionHead icon="bar-chart-outline" title="Income vs expenditure" />
              <Text style={styles.cardSub}>
                {data.months.length} reported month
                {data.months.length === 1 ? "" : "s"} in {data.year}
              </Text>
              <View style={styles.legendRow}>
                <Legend color={CHART_INCOME} label="Income" />
                <Legend color={CHART_EXPENSE} label="Expenditure" />
              </View>
              <View
                style={styles.chart}
                onLayout={(event) =>
                  setChartWidth(Math.round(event.nativeEvent.layout.width))
                }
              >
                {chartWidth > 0 && (
                  <IncomeExpenseBars
                    months={data.months}
                    width={chartWidth}
                    selectedMonth={selectedMonth}
                    onSelectMonth={(month) =>
                      setSelectedMonth((prev) => (prev === month ? null : month))
                    }
                  />
                )}
              </View>

              {selected ? (
                <View style={styles.chartDetail}>
                  <View style={styles.chartDetailHead}>
                    <Text style={styles.chartDetailTitle}>
                      {selected.period} · as filed
                    </Text>
                    <TouchableOpacity
                      onPress={() => setSelectedMonth(null)}
                      hitSlop={8}
                      accessibilityLabel="Clear selected month"
                    >
                      <Ionicons name="close" size={14} color={colors.muted} />
                    </TouchableOpacity>
                  </View>
                  <View style={styles.heroStats}>
                    <Stat label="INCOME" value={money(selected.income)} />
                    <Stat label="SPEND" value={money(selected.expenses)} />
                    <Stat
                      label="NET"
                      value={money(selected.net)}
                      tone={selected.net >= 0 ? "positive" : "negative"}
                    />
                  </View>
                </View>
              ) : (
                <Text style={styles.chartHint}>
                  Tap a bar for that month’s exact figures.
                </Text>
              )}
            </View>

            <View style={styles.card}>
              <SectionHead icon="pie-chart-outline" title="Income mix" />
              <Text style={styles.cardSub}>
                Every income line as filed in the reports
              </Text>
              <View style={styles.pieRow}>
                <IncomeMixPie rows={data.incomeMix} />
                <View style={styles.pieLegend}>
                  {data.incomeMix.map((row, index) => (
                    <View key={row.key} style={styles.pieLegendRow}>
                      <View
                        style={[
                          styles.legendDot,
                          {
                            backgroundColor:
                              MIX_COLORS[index % MIX_COLORS.length],
                          },
                        ]}
                      />
                      <View style={{ flex: 1 }}>
                        <Text style={styles.pieLabel}>{row.label}</Text>
                        <Text style={styles.pieValue}>
                          {money(row.value)} ·{" "}
                          {mixTotal > 0
                            ? Math.round((row.value / mixTotal) * 100)
                            : 0}
                          %
                        </Text>
                      </View>
                    </View>
                  ))}
                </View>
              </View>
            </View>

            {hasImpact && impact ? (
              <View style={styles.card}>
                <SectionHead icon="heart-outline" title="Latest report impact" />
                <View style={styles.impactRow}>
                  <ImpactCell value={impact.families} label="Families" />
                  <ImpactCell value={impact.mealsServed} label="Meals" />
                  <ImpactCell value={impact.children} label="Children" />
                  <ImpactCell value={impact.placements} label="Placements" />
                  <ImpactCell value={impact.events} label="Events" />
                </View>
                {!!data.latestReport && (
                  <Text style={styles.cardNote}>
                    Latest report: {data.latestReport.period}
                  </Text>
                )}
              </View>
            ) : null}
              </>
            ) : null}

            <View style={styles.card}>
              <SectionHead icon="business-outline" title="Department performance" />
              {data.appraisals && data.appraisals.departments.length > 0 ? (
                <>
                  <Text style={styles.cardSub}>
                    Approved for {data.appraisals.season.name}{" "}
                    {data.appraisals.season.year}
                  </Text>
                  <View style={styles.scoreList}>
                    {data.appraisals.departments.map((row) => (
                      <TouchableOpacity
                        key={row.id}
                        style={styles.scoreRow}
                        activeOpacity={0.85}
                        onPress={() =>
                          router.push({
                            pathname: "/appraisal/[id]",
                            params: { id: row.id },
                          } as any)
                        }
                      >
                        <View style={{ flex: 1 }}>
                          <Text style={styles.scoreName}>{row.department}</Text>
                          <Text style={styles.scoreSub} numberOfLines={1}>
                            {row.lead ? `${row.lead} · ` : ""}
                            {row.revenueTarget > 0
                              ? `${money(row.collected)} of ${money(row.revenueTarget)} coffer`
                              : "Season score"}
                          </Text>
                        </View>
                        <View style={styles.scoreValueWrap}>
                          <Text style={styles.scoreValue}>
                            {Math.round(row.score)}%
                          </Text>
                          {row.band ? (
                            <Text style={styles.scoreBand}>{row.band}</Text>
                          ) : null}
                        </View>
                        <Ionicons
                          name="chevron-forward"
                          size={15}
                          color={colors.muted}
                        />
                      </TouchableOpacity>
                    ))}
                  </View>
                </>
              ) : (
                <View style={styles.placeholder}>
                  <Ionicons
                    name="hourglass-outline"
                    size={22}
                    color={colors.muted}
                  />
                  <Text style={styles.placeholderTitle}>
                    No department appraisals yet
                  </Text>
                  <Text style={styles.placeholderBody}>
                    Department scores arrive after the {data.season.name}{" "}
                    appraisal at the end of {data.season.ends}.
                  </Text>
                </View>
              )}
            </View>

            <View style={styles.card}>
              <SectionHead icon="people-outline" title="Individual performance" />
              {data.appraisals && data.appraisals.individuals.length > 0 ? (
                <>
                  <Text style={styles.cardSub}>
                    Approved for {data.appraisals.season.name}{" "}
                    {data.appraisals.season.year}
                  </Text>
                  <View style={styles.scoreList}>
                    {data.appraisals.individuals.map((row) => (
                      <TouchableOpacity
                        key={row.id}
                        style={styles.scoreRow}
                        activeOpacity={0.85}
                        onPress={() =>
                          router.push({
                            pathname: "/appraisal/[id]",
                            params: { id: row.id },
                          } as any)
                        }
                      >
                        <View style={{ flex: 1 }}>
                          <Text style={styles.scoreName}>{row.name}</Text>
                          <Text style={styles.scoreSub} numberOfLines={1}>
                            {row.department || "Individual appraisal"}
                          </Text>
                        </View>
                        <View style={styles.scoreValueWrap}>
                          <Text style={styles.scoreValue}>
                            {Math.round(row.score)}%
                          </Text>
                          {row.band ? (
                            <Text style={styles.scoreBand}>{row.band}</Text>
                          ) : null}
                        </View>
                        <Ionicons
                          name="chevron-forward"
                          size={15}
                          color={colors.muted}
                        />
                      </TouchableOpacity>
                    ))}
                  </View>
                </>
              ) : (
                <View style={styles.placeholder}>
                  <Ionicons
                    name="person-circle-outline"
                    size={22}
                    color={colors.muted}
                  />
                  <Text style={styles.placeholderTitle}>
                    No member appraisals yet
                  </Text>
                  <Text style={styles.placeholderBody}>
                    Members’ seasonal percentages appear here once the{" "}
                    {data.season.name} {data.season.year} appraisal forms are
                    submitted and approved.
                  </Text>
                </View>
              )}
            </View>

            <Text style={styles.footer}>
              {data.reportCount > 0
                ? `Built from ${data.reportCount} published financial report${
                    data.reportCount === 1 ? "" : "s"
                  }${data.latestReport ? ` · latest: ${data.latestReport.period}` : ""}`
                : `Built from approved ${data.appraisals?.season.name ?? ""} appraisals`}
            </Text>
          </ScrollView>
        )}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

