const fmtDate = (value?: string) => {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-ZA", { day: "numeric", month: "short" });
};

type Tab = "open" | "mine";

function ApplyModal({
  office,
  visible,
  onClose,
  onApplied,
}: {
  office: VolunteerOffice | null;
  visible: boolean;
  onClose: () => void;
  onApplied: () => void;
}) {
  return (
    <Modal visible={visible} animationType="slide" onRequestClose={onClose}>
      {/* Keyed remount so every open starts with fresh fields (no reset effect). */}
      {visible && office ? (
        <ApplyForm office={office} onClose={onClose} onApplied={onApplied} />
      ) : null}
    </Modal>
  );
}

function ApplyForm({
  office,
  onClose,
  onApplied,
}: {
  office: VolunteerOffice;
  onClose: () => void;
  onApplied: () => void;
}) {
  const questions = office.applicationQuestions?.length ? office.applicationQuestions : [];
  const [motivation, setMotivation] = useState("");
  const [answers, setAnswers] = useState<Record<string, string>>(() => {
    const seed: Record<string, string> = {};
    for (const q of questions) seed[q] = "";
    return seed;
  });
  const [busy, setBusy] = useState(false);

  const submit = async () => {
    if (questions.length) {
      for (const q of questions) {
        if (!(answers[q] || "").trim()) {
          Alert.alert("Missing answer", `Please answer: ${q}`);
          return;
        }
      }
      setBusy(true);
      try {
        await officesApi.apply(office._id, {
          answers: questions.map((q) => ({ question: q, answer: answers[q].trim() })),
        });
        onClose();
        onApplied();
      } catch (e: any) {
        Alert.alert("Could not apply", e?.message || "Please try again.");
      }
      setBusy(false);
      return;
    }
    if (motivation.trim().length < 20) {
      Alert.alert(
        "A bit more detail",
        "Write at least 20 characters on why you'd like this office.",
      );
      return;
    }
    setBusy(true);
    try {
      await officesApi.apply(office._id, { motivation: motivation.trim() });
      setMotivation("");
      onClose();
      onApplied();
    } catch (e: any) {
      Alert.alert("Could not apply", e?.message || "Please try again.");
    }
    setBusy(false);
  };

  return (
    <SafeAreaView style={styles.fullModal} edges={["top", "bottom"]}>
      <View style={styles.fullHead}>
        <View style={{ flex: 1 }}>
          <Text style={styles.sheetTitle}>Apply for this office</Text>
          <Text style={styles.sheetSub} numberOfLines={1}>
            {office.title}
          </Text>
        </View>
        <TouchableOpacity onPress={onClose} style={styles.sheetClose}>
          <Ionicons name="close" size={18} color={colors.muted} />
        </TouchableOpacity>
      </View>

      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === "ios" ? "padding" : "height"}
      >
        <ScrollView
          contentContainerStyle={styles.fullScroll}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        >
          {questions.length ? (
            questions.map((q) => (
              <View key={q}>
                <Text style={styles.fieldLabel}>{q}</Text>
                <TextInput
                  style={[styles.input, styles.textarea]}
                  value={answers[q] || ""}
                  onChangeText={(t) => setAnswers((prev) => ({ ...prev, [q]: t }))}
                  multiline
                  placeholder="Your answer"
                  placeholderTextColor={colors.muted}
                />
              </View>
            ))
          ) : (
            <>
              <Text style={styles.fieldLabel}>Why do you want it?</Text>
              <TextInput
                style={[styles.input, styles.textarea]}
                value={motivation}
                onChangeText={setMotivation}
                multiline
                placeholder="A short note on your interest and availability (20+ characters)."
                placeholderTextColor={colors.muted}
              />
              <Text style={styles.counter}>{motivation.trim().length}/20</Text>
            </>
          )}

          <TouchableOpacity
            style={[styles.primaryBtn, busy && styles.btnDisabled]}
            onPress={submit}
            disabled={busy}
            activeOpacity={0.9}
          >
            {busy ? (
              <ActivityIndicator color={colors.forestDark} />
            ) : (
              <>
                <Text style={styles.primaryBtnText}>Send application</Text>
                <Ionicons name="arrow-forward" size={16} color={colors.forestDark} />
              </>
            )}
          </TouchableOpacity>
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

export default function OfficesScreen() {
  const { tab: tabParam } = useLocalSearchParams<{ tab?: string }>();
  const [isAdmin, setIsAdmin] = useState(false);
  const [tab, setTab] = useState<Tab>(() =>
    typeof tabParam === "string" && tabParam === "mine" ? "mine" : "open",
  );
  const [offices, setOffices] = useState<VolunteerOffice[] | null>(null);
  const [applications, setApplications] = useState<OfficeApplication[] | null>(null);
  const [error, setError] = useState("");
  const [refreshing, setRefreshing] = useState(false);
  const [applyTarget, setApplyTarget] = useState<VolunteerOffice | null>(null);

  const load = useCallback(async () => {
    try {
      const [officesRes, appsRes] = await Promise.all([
        officesApi.list(),
        tab === "mine" ? officesApi.mine() : Promise.resolve(null),
      ]);
      setOffices(officesRes.data);
      if (appsRes) setApplications(appsRes.data);
      setError("");
    } catch (e: any) {
      setError(e?.message || "Could not reach the server.");
    }
  }, [tab]);

  useEffect(() => {
    getSession().then((s) => setIsAdmin(s?.user?.role === "admin"));
  }, []);

  useEffect(() => {
    (async () => {
      await load();
    })();
  }, [load]);

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    await load();
    setRefreshing(false);
  }, [load]);

  const visibleOffices = useMemo(() => {
    if (!offices) return [];
    return offices.filter((o) => o.status !== "closed");
  }, [offices]);

  const renderOffice = ({ item }: { item: VolunteerOffice }) => {
    const status = OFFICE_STATUS_META[item.status];
    const app = item.myApplication;
    const appMeta = app ? OFFICE_APPLICATION_META[app.status] : null;
    const applied = !!app && app.status !== "rejected";
    return (
      <TouchableOpacity
        style={styles.card}
        activeOpacity={0.85}
        onPress={() => router.push(`/offices/${item._id}`)}
      >
        <View style={styles.cardTop}>
          {item.area ? (
            <View style={styles.areaChip}>
              <Ionicons name="briefcase-outline" size={12} color={colors.forest} />
              <Text style={styles.areaChipText}>{item.area}</Text>
            </View>
          ) : (
            <View style={{ flex: 1 }} />
          )}
          <View style={[styles.pill, { backgroundColor: status.bg }]}>
            <Text style={[styles.pillText, { color: status.color }]}>{status.label}</Text>
          </View>
        </View>

        <Text style={styles.cardTitle}>{item.title}</Text>
        <Text style={styles.cardDesc} numberOfLines={3}>
          {item.description}
        </Text>

        {item.responsibilities?.length ? (
          <View style={styles.bulletBlock}>
            <Text style={styles.bulletHeading}>What you&rsquo;ll do</Text>
            {item.responsibilities.map((point) => (
              <View key={point} style={styles.bulletRow}>
                <Text style={styles.bulletDot}>•</Text>
                <Text style={styles.bulletText}>{point}</Text>
              </View>
            ))}
          </View>
        ) : null}
        {item.qualifications?.length ? (
          <View style={styles.bulletBlock}>
            <Text style={styles.bulletHeading}>Qualifications</Text>
            {item.qualifications.map((point) => (
              <View key={point} style={styles.bulletRow}>
                <Text style={styles.bulletDot}>•</Text>
                <Text style={styles.bulletText}>{point}</Text>
              </View>
            ))}
          </View>
        ) : null}

        <View style={styles.cardFoot}>
          {item.clubSlug ? (
            <View style={styles.clubChip}>
              <Ionicons name="people" size={11} color={colors.forest} />
              <Text style={styles.clubChipText}>
                {CLUBS.find((c) => c.slug === item.clubSlug)?.name || item.clubSlug}
              </Text>
            </View>
          ) : null}
          <Text style={styles.cardMeta}>Posted {fmtDate(item.createdAt)}</Text>
          <View style={{ flex: 1 }} />

          {appMeta ? (
            <View style={[styles.pill, { backgroundColor: appMeta.bg }]}>
              <Text style={[styles.pillText, { color: appMeta.color }]}>
                {appMeta.label}
              </Text>
            </View>
          ) : item.status === "open" && !applied ? (
            <PrimaryButton
              label="Apply"
              icon="arrow-forward"
              size="sm"
              onPress={() => setApplyTarget(item)}
              style={styles.applyBtnCompact}
            />
          ) : null}
        </View>
      </TouchableOpacity>
    );
  };

  const renderApplication = ({ item }: { item: OfficeApplication }) => {
    const meta = OFFICE_APPLICATION_META[item.status];
    return (
      <View style={styles.card}>
        <View style={styles.cardTop}>
          <Text numberOfLines={1} style={[styles.cardTitle, styles.appTitle]}>
            {item.office?.title || item.officeTitle}
          </Text>
          <View style={[styles.pill, { backgroundColor: meta.bg }]}>
            <Text style={[styles.pillText, { color: meta.color }]}>{meta.label}</Text>
          </View>
        </View>
        <Text style={styles.appMotivation} numberOfLines={3}>
          {item.motivation}
        </Text>
        <Text style={styles.cardMeta}>Applied {fmtDate(item.createdAt)}</Text>
        {item.reviewNote ? (
          <Text style={styles.reviewNote}>Admin: {item.reviewNote}</Text>
        ) : null}
      </View>
    );
  };

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.bar}>
          <TouchableOpacity
            onPress={() => router.back()}
            style={styles.iconBtn}
            accessibilityLabel="Back"
          >
            <Ionicons name="chevron-back" size={20} color={colors.forest} />
          </TouchableOpacity>
          <View style={{ flex: 1 }}>
            <Text style={styles.pageEyebrow}>VOLUNTEER OFFICES</Text>
            <Text style={styles.pageTitle}>Step into a role</Text>
          </View>
          {isAdmin ? (
            <TouchableOpacity
              onPress={() => router.push("/offices-admin")}
              style={styles.addBtn}
              accessibilityLabel="Manage offices"
            >
              <Ionicons name="settings-outline" size={18} color={colors.forest} />
            </TouchableOpacity>
          ) : null}
        </View>

        <View>
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.tabsRow}
          >
            {(
              [
                { key: "open", label: "Open offices" },
                { key: "mine", label: "My applications" },
              ] as { key: Tab; label: string }[]
            ).map((t) => {
              const active = tab === t.key;
              return (
                <TouchableOpacity
                  key={t.key}
                  style={[styles.tab, active && styles.tabActive]}
                  activeOpacity={0.8}
                  onPress={() => setTab(t.key)}
                >
                  {active && (
                    <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                  )}
                  <Text style={[styles.tabText, active && styles.tabTextActive]}>
                    {t.label}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </ScrollView>
        </View>

        {tab === "open" && offices === null && !error ? (
          <View style={styles.skeletonWrap}>
            {[0, 1, 2, 3].map((i) => (
              <SkeletonPulse key={i} style={styles.skeletonCard} />
            ))}
          </View>
        ) : tab === "mine" && applications === null && !error ? (
          <View style={styles.skeletonWrap}>
            {[0, 1, 2].map((i) => (
              <SkeletonPulse key={i} style={styles.skeletonCard} />
            ))}
          </View>
        ) : error ? (
          <EmptyState
            icon="warning-outline"
            color={colors.error}
            eyebrow="Something went wrong"
            title="Couldn't load offices"
            subtitle={error}
            actionLabel="Retry"
            onAction={load}
          />
        ) : tab === "open" ? (
          <FlatList
            data={visibleOffices}
            keyExtractor={(item) => item._id}
            contentContainerStyle={styles.list}
            refreshControl={
              <RefreshControl
                refreshing={refreshing}
                onRefresh={onRefresh}
                tintColor={colors.forest}
              />
            }
            renderItem={renderOffice}
            ListEmptyComponent={
              <EmptyState
                icon="briefcase-outline"
                eyebrow="Nothing open"
                title="No open offices right now"
                subtitle="When admins post volunteer offices they show up here."
                compact
              />
            }
          />
        ) : (
          <FlatList
            data={applications || []}
            keyExtractor={(item) => item._id}
            contentContainerStyle={styles.list}
            refreshControl={
              <RefreshControl
                refreshing={refreshing}
                onRefresh={onRefresh}
                tintColor={colors.forest}
              />
            }
            renderItem={renderApplication}
            ListEmptyComponent={
              <EmptyState
                icon="document-text-outline"
                eyebrow="No applications"
                title="You haven't applied yet"
                subtitle="Apply for an open office and track it here."
                actionLabel="Browse open offices"
                onAction={() => setTab("open")}
                compact
              />
            }
          />
        )}

        <ApplyModal
          office={applyTarget}
          visible={!!applyTarget}
          onClose={() => setApplyTarget(null)}
          onApplied={load}
        />
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

