import { API_BASE } from "./config";
import { getRequestHeaders, getSessionToken, updateSessionUser } from "./auth";
import { uploadProfileImage as cloudinaryUpload, type UploadImageSource } from "./cloudinary";

/**
 * Upload a profile picture to Cloudinary, persist the returned secure URL
 * on the backend user record, and refresh the local session.
 */
export async function uploadProfileImage(source: UploadImageSource): Promise<string> {
  const token = await getSessionToken();
  if (!token) {
    throw new Error("Not signed in");
  }

  const url = await cloudinaryUpload(source);

  const res = await fetch(`${API_BASE}/api/profile/image`, {
    method: "POST",
    headers: await getRequestHeaders({ "Content-Type": "application/json" }),
    body: JSON.stringify({ url }),
  });

  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new Error(body.error || `Upload failed: ${res.status}`);
  }

  const data = await res.json();
  const savedUrl = data?.url || url;
  await updateSessionUser({ image: savedUrl });
  return savedUrl;
}
