import { Ionicons } from "@expo/vector-icons";
import { router, useFocusEffect, useLocalSearchParams } from "expo-router";
import { useCallback, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  Linking,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import {
  SafeAreaProvider,
  SafeAreaView,
  useSafeAreaInsets,
} from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import BoardHeader from "@/components/board/BoardHeader";
import { boardStyles as s } from "@/components/board/styles";
import {
  boardApi,
  type BoardMinutes,
  type TaskStatus,
} from "@/services/board-governance";

const TASK_TONE: Record<TaskStatus, { bg: string; color: string; label: string }> = {
  PENDING: { bg: "#fef3c7", color: "#b45309", label: "Pending" },
  IN_PROGRESS: { bg: "#d4eef5", color: "#1d2a4d", label: "In progress" },
  DONE: { bg: "#d1fae5", color: "#047857", label: "Done" },
};

function nextStatus(status: TaskStatus): TaskStatus {
  if (status === "PENDING") return "IN_PROGRESS";
  if (status === "IN_PROGRESS") return "DONE";
  return "PENDING";
}

function formatDate(value: string | null): string {
  if (!value) return "Date to be confirmed";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleDateString("en-ZA", {
    weekday: "short",
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

export default function BoardMinutesDetailScreen() {
  const insets = useSafeAreaInsets();
  const params = useLocalSearchParams<{ id?: string | string[] }>();
  const id = Array.isArray(params.id) ? params.id[0] : params.id || "";
  const [minutes, setMinutes] = useState<BoardMinutes | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [busyTask, setBusyTask] = useState("");
  const [deleting, setDeleting] = useState(false);

  const load = useCallback(async () => {
    if (!id) {
      setError("These minutes could not be found.");
      setLoading(false);
      return;
    }
    try {
      setError("");
      const res = await boardApi.getMinutes(id);
      setMinutes(res.data);
    } catch (e: any) {
      setError(e?.message || "Failed to load the minutes.");
    } finally {
      setLoading(false);
    }
  }, [id]);

  // Corrections saved on the edit screen should show as soon as we return.
  useFocusEffect(
    useCallback(() => {
      void load();
    }, [load]),
  );

  const openDocument = (url: string) => {
    Linking.openURL(url).catch(() =>
      Alert.alert("Could not open", "Copy the document link and open it in a browser."),
    );
  };

  const cycleTask = async (taskId: string, current: TaskStatus) => {
    if (!minutes || busyTask) return;
    const status = nextStatus(current);
    setBusyTask(taskId);
    try {
      const res = await boardApi.updateTask(minutes._id, taskId, status);
      setMinutes((entry) =>
        entry
          ? {
              ...entry,
              actionItems: entry.actionItems.map((item) =>
                item.taskId === taskId ? { ...item, status } : item,
              ),
              counts: res.data.counts,
            }
          : entry,
      );
    } catch (e: any) {
      Alert.alert("Could not update", e?.message || "Please try again.");
    } finally {
      setBusyTask("");
    }
  };

  const remove = async () => {
    if (!minutes) return;
    setDeleting(true);
    try {
      await boardApi.deleteMinutes(minutes._id);
      router.back();
    } catch (e: any) {
      Alert.alert("Could not delete", e?.message || "Please try again.");
    } finally {
      setDeleting(false);
    }
  };

  const confirmDelete = () => {
    if (!minutes) return;
    Alert.alert(
      "Delete these minutes?",
      `${minutes.meetingTitle} minutes and their action items will be removed, and the board will be told. This cannot be undone.`,
      [
        { text: "Keep them", style: "cancel" },
        { text: "Delete", style: "destructive", onPress: () => void remove() },
      ],
    );
  };

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <BoardHeader title="Minutes" />
        {loading ? (
          <View style={s.center}>
            <ActivityIndicator color={colors.goldDark} size="large" />
          </View>
        ) : error || !minutes ? (
          <View style={{ paddingHorizontal: 16 }}>
            <View style={s.emptyBox}>
              <Ionicons name="warning-outline" size={24} color={colors.error} />
              <Text style={s.emptyTitle}>Couldn’t load the minutes</Text>
              <Text style={s.emptyBody}>{error || "These minutes are no longer available."}</Text>
              <TouchableOpacity onPress={() => void load()} activeOpacity={0.85}>
                <Text style={[s.docLinkText, { marginTop: 6 }]}>Retry</Text>
              </TouchableOpacity>
            </View>
          </View>
        ) : (
          <ScrollView
            contentContainerStyle={[
              styles.content,
              { paddingBottom: 40 + insets.bottom },
            ]}
            showsVerticalScrollIndicator={false}
          >
            <View style={styles.head}>
              <Text style={styles.title}>{minutes.meetingTitle}</Text>
              <View style={styles.metaRow}>
                <Ionicons name="calendar-clear-outline" size={15} color={colors.goldDark} />
                <Text style={styles.metaText}>{formatDate(minutes.meetingDate)}</Text>
              </View>
              <View style={styles.metaRow}>
                <Ionicons name="person-outline" size={15} color={colors.goldDark} />
                <Text style={styles.metaText}>
                  Published by {minutes.publishedByName} · {formatDate(minutes.publishedAt)}
                </Text>
              </View>
              <View
                style={[
                  s.badge,
                  {
                    alignSelf: "flex-start",
                    marginTop: 4,
                    backgroundColor: minutes.within48h ? "#d1fae5" : "#ffe4e6",
                  },
                ]}
              >
                <Text
                  style={[
                    s.badgeText,
                    { color: minutes.within48h ? "#047857" : "#be123c" },
                  ]}
                >
                  {minutes.within48h
                    ? "Logged within 48 hours"
                    : `Late log · ${minutes.hoursAfterMeeting ?? "?"}h after the meeting`}
                </Text>
              </View>
            </View>

            <View style={styles.body}>
              {minutes.sections.length > 0 ? (
                minutes.sections.map((section, index) => (
                  <View key={`section-${index}`} style={styles.section}>
                    <Text style={styles.sectionTitle}>
                      {section.title || `Section ${index + 1}`}
                    </Text>
                    {section.points.map((point, pointIndex) => (
                      <View key={`section-${index}-point-${pointIndex}`} style={styles.pointRow}>
                        <Text style={styles.bullet}>•</Text>
                        <Text style={styles.pointText}>{point}</Text>
                      </View>
                    ))}
                  </View>
                ))
              ) : (
                <Text style={styles.summaryText}>{minutes.summary}</Text>
              )}
            </View>

            {minutes.minutesDocumentUrl ? (
              <TouchableOpacity
                style={styles.docBtn}
                onPress={() => openDocument(minutes.minutesDocumentUrl)}
                activeOpacity={0.85}
                accessibilityLabel="Open the signed minutes"
              >
                <View style={styles.docIcon}>
                  <Ionicons name="document-text-outline" size={20} color={colors.goldDark} />
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={styles.docTitle}>Signed minutes</Text>
                  <Text style={styles.docBody}>Open the document on file</Text>
                </View>
                <Ionicons name="open-outline" size={18} color={colors.goldDark} />
              </TouchableOpacity>
            ) : null}

            <View style={styles.tasksBlock}>
              <Text style={styles.blockTitle}>
                Action items · {minutes.counts.done}/{minutes.counts.total} done
              </Text>
              {minutes.actionItems.length === 0 ? (
                <Text style={styles.emptyText}>No action items were raised.</Text>
              ) : (
                <>
                  <Text style={styles.blockHint}>
                    Tap an action to move it to the next stage.
                  </Text>
                  <View style={styles.taskList}>
                    {minutes.actionItems.map((task) => {
                      const tone = TASK_TONE[task.status];
                      return (
                        <TouchableOpacity
                          key={task.taskId}
                          style={styles.taskRow}
                          activeOpacity={0.85}
                          onPress={() => void cycleTask(task.taskId, task.status)}
                          accessibilityLabel={`${task.taskDescription}. Tap to move to ${nextStatus(task.status).toLowerCase().replace("_", " ")}.`}
                        >
                          <Ionicons
                            name={
                              task.status === "DONE"
                                ? "checkmark-circle"
                                : task.status === "IN_PROGRESS"
                                  ? "time-outline"
                                  : "ellipse-outline"
                            }
                            size={20}
                            color={tone.color}
                          />
                          <View style={{ flex: 1 }}>
                            <Text style={styles.taskText}>
                              {task.taskDescription}
                            </Text>
                            <Text style={styles.taskMeta}>
                              {task.assigneeName}
                              {task.dueDate ? ` · due ${formatDate(task.dueDate)}` : ""}
                            </Text>
                          </View>
                          {busyTask === task.taskId ? (
                            <ActivityIndicator size="small" color={tone.color} />
                          ) : (
                            <View style={[s.statusPill, { backgroundColor: tone.bg }]}>
                              <Text style={[s.statusText, { color: tone.color }]}>
                                {tone.label}
                              </Text>
                            </View>
                          )}
                        </TouchableOpacity>
                      );
                    })}
                  </View>
                </>
              )}
            </View>

            <View style={styles.actions}>
              <TouchableOpacity
                style={[s.secondaryBtn, { flex: 1 }]}
                onPress={() =>
                  router.push({
                    pathname: "/admin/board-governance/upload-minutes",
                    params: { minutesId: minutes._id },
                  } as any)
                }
                activeOpacity={0.85}
              >
                <Ionicons name="create-outline" size={17} color={colors.goldDark} />
                <Text style={s.secondaryText}>Edit minutes</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[styles.deleteBtn, deleting && s.busy]}
                onPress={confirmDelete}
                disabled={deleting}
                activeOpacity={0.85}
              >
                {deleting ? (
                  <ActivityIndicator size="small" color="#be123c" />
                ) : (
                  <>
                    <Ionicons name="trash-outline" size={17} color="#be123c" />
                    <Text style={styles.deleteText}>Delete</Text>
                  </>
                )}
              </TouchableOpacity>
            </View>
          </ScrollView>
        )}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

