import { cachedFetch } from "./cache";

export type ClubMember = {
  /** Same id chat rows carry as sender_id, so bubbles can resolve avatars. */
  id: string;
  firstName: string;
  image: string | null;
  joinedAt: string | null;
};

export type ClubMembers = {
  count: number;
  members: ClubMember[];
};

/** Club chat helpers — the roster behind the chat's member list and settings. */
export const clubChatApi = {
  members: (slug: string) =>
    cachedFetch<ClubMembers>(
      `/api/clubs/${encodeURIComponent(slug)}/members`,
      { cacheTtl: 60_000 },
    ),
};

/** Club chat notification settings for the signed-in member. */
export const clubChatSettingsApi = {
  muted: () =>
    cachedFetch<{ muted: string[] }>("/api/clubs/chat/mute", {
      cacheTtl: 60_000,
    }),
  setMuted: (slug: string, muted: boolean) =>
    cachedFetch<{ slug: string; muted: boolean }>(
      "/api/clubs/chat/mute",
      { method: "POST", body: JSON.stringify({ slug, muted }), cacheTtl: 0 },
      ["/api/clubs/chat/mute"],
    ),
};

export type ClubChatNotifyRecord = {
  id: string;
  club_slug: string;
  sender_id: string;
  sender_name: string;
  body: string;
  image_url: string | null;
  /** Install that sent the message; its own push subscription is skipped. */
  device_id?: string;
};

/**
 * Asks the backend to push a new message to the other members of that club
 * (the sender's session authorises it). The Supabase database webhook targets
 * the same route; the backend claims the message id, so only one of the two
 * sends the push.
 */
export const clubChatNotifyApi = {
  send: (record: ClubChatNotifyRecord) =>
    cachedFetch<{ ok: boolean }>("/api/clubs/chat/notify", {
      method: "POST",
      body: JSON.stringify({ record }),
      cacheTtl: 0,
    }),
};
