import { SQLiteProvider, type SQLiteDatabase } from "expo-sqlite";

const DATABASE_VERSION = 7;

export type HighlightRow = {
  id: number;
  user_id: string;
  version_id: number;
  book: string;
  chapter: number;
  verse: number;
  color: string;
  created_at: string;
};

export type BookmarkRow = {
  id: number;
  user_id: string;
  book: string;
  chapter: number;
  verse: number;
  note: string;
  created_at: string;
};

export type ReadingProgressRow = {
  user_id: string;
  book: string;
  chapter: number;
  updated_at: string;
};

export type SunriseCacheRow = {
  id: number;
  lat: number;
  lng: number;
  sunrise: string;
  sunset: string;
  solar_noon: string;
  date: string;
};

export type PrayerScheduleRow = {
  date: string;
  dawn: string;
  sunrise: string;
  noon: string;
  afternoon: string;
  sunset: string;
  evening: string;
};

export type PrayerPreferencesRow = {
  id: number;
  disabled_prayers: string;
  custom_prayers: string;
  sounds: string;
  advance_minutes: number;
};

export type PrayerRequestRow = {
  id: number;
  user_id: string;
  day_key: string;
  text: string;
  done: number;
  created_at: string;
  name: string;
  topic: string;
};

export type SyncQueueRow = {
  id: number;
  table_name: string;
  record_id: string;
  action: string;
  payload_json: string;
  created_at: string;
  synced: number;
};

export async function migrateDb(db: SQLiteDatabase) {
  // Wait out cross-connection write locks instead of throwing; every launch.
  await db.execAsync("PRAGMA busy_timeout = 3000;");

  const versionRow = await db.getFirstAsync<{
    user_version: number;
  }>("PRAGMA user_version");
  let currentDbVersion = versionRow?.user_version ?? 0;

  if (currentDbVersion >= DATABASE_VERSION) {
    return;
  }

  if (currentDbVersion === 0) {
    await db.execAsync(`
      PRAGMA journal_mode = WAL;
      PRAGMA foreign_keys = ON;

      CREATE TABLE IF NOT EXISTS highlights (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT NOT NULL,
        version_id INTEGER NOT NULL,
        book TEXT NOT NULL,
        chapter INTEGER NOT NULL,
        verse INTEGER NOT NULL,
        color TEXT NOT NULL DEFAULT '#FFD700',
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );
      CREATE INDEX IF NOT EXISTS idx_highlights_user ON highlights(user_id, book, chapter);
      CREATE INDEX IF NOT EXISTS idx_highlights_verse ON highlights(user_id, version_id, book, chapter, verse);

      CREATE TABLE IF NOT EXISTS bookmarks (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT NOT NULL,
        book TEXT NOT NULL,
        chapter INTEGER NOT NULL,
        verse INTEGER NOT NULL DEFAULT 0,
        note TEXT NOT NULL DEFAULT '',
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );
      CREATE INDEX IF NOT EXISTS idx_bookmarks_user ON bookmarks(user_id, book, chapter);

      CREATE TABLE IF NOT EXISTS reading_progress (
        user_id TEXT NOT NULL,
        book TEXT NOT NULL,
        chapter INTEGER NOT NULL,
        updated_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (user_id)
      );

      CREATE TABLE IF NOT EXISTS sunrise_cache (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        lat REAL NOT NULL,
        lng REAL NOT NULL,
        sunrise TEXT NOT NULL,
        sunset TEXT NOT NULL,
        solar_noon TEXT NOT NULL,
        date TEXT NOT NULL
      );
      CREATE INDEX IF NOT EXISTS idx_sunrise_date ON sunrise_cache(date);
      CREATE INDEX IF NOT EXISTS idx_sunrise_location ON sunrise_cache(lat, lng, date);

      CREATE TABLE IF NOT EXISTS prayer_schedule (
        date TEXT PRIMARY KEY,
        dawn TEXT NOT NULL,
        sunrise TEXT NOT NULL,
        noon TEXT NOT NULL,
        afternoon TEXT NOT NULL,
        sunset TEXT NOT NULL,
        evening TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS prayer_preferences (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        disabled_prayers TEXT NOT NULL DEFAULT '[]',
        custom_prayers TEXT NOT NULL DEFAULT '[]',
        sounds TEXT NOT NULL DEFAULT '{}',
        advance_minutes INTEGER NOT NULL DEFAULT 10
      );

      CREATE TABLE IF NOT EXISTS prayer_requests (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT NOT NULL DEFAULT 'local',
        day_key TEXT NOT NULL DEFAULT '',
        text TEXT NOT NULL DEFAULT '',
        done INTEGER NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        name TEXT NOT NULL DEFAULT '',
        topic TEXT NOT NULL DEFAULT ''
      );
      CREATE INDEX IF NOT EXISTS idx_prayer_requests_day ON prayer_requests(user_id, day_key);

      CREATE TABLE IF NOT EXISTS sync_queue (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        table_name TEXT NOT NULL,
        record_id TEXT NOT NULL,
        action TEXT NOT NULL,
        payload_json TEXT NOT NULL,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        synced INTEGER NOT NULL DEFAULT 0
      );
      CREATE INDEX IF NOT EXISTS idx_sync_queue_pending ON sync_queue(synced, created_at);
    `);

    currentDbVersion = 1;
  }

  if (currentDbVersion === 1) {
    await db.execAsync(`
      CREATE TABLE IF NOT EXISTS settings (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL DEFAULT ''
      );
    `);
    currentDbVersion = 2;
  }

  if (currentDbVersion === 2) {
    await db.execAsync(`
      CREATE TABLE IF NOT EXISTS discover_snapshot (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        cards_json TEXT NOT NULL DEFAULT '[]',
        version TEXT NOT NULL DEFAULT '0',
        fetched_at TEXT NOT NULL DEFAULT (datetime('now'))
      );
    `);
    currentDbVersion = 3;
  }

  if (currentDbVersion === 3) {
    await db.execAsync(`
      CREATE TABLE IF NOT EXISTS votd_cache (
        day_key TEXT PRIMARY KEY,
        day_of_year INTEGER NOT NULL,
        version_id INTEGER NOT NULL,
        passage_id TEXT NOT NULL DEFAULT '',
        reference TEXT NOT NULL DEFAULT '',
        text TEXT NOT NULL DEFAULT '',
        fetched_at TEXT NOT NULL DEFAULT (datetime('now'))
      );
    `);
    currentDbVersion = 4;
  }

  if (currentDbVersion === 4) {
    await db.execAsync(`
      DROP TABLE IF EXISTS prayer_streaks;
      DROP TABLE IF EXISTS reading_streaks;
    `);
    currentDbVersion = 5;
  }

  if (currentDbVersion < 7) {
    await db.execAsync(`
      DROP TABLE IF EXISTS reading_plan_progress;
    `);
    currentDbVersion = 7;
  }

  // prayer_requests gained name/topic after v7. The focus data layer repairs
  // that schema on first use (see utils/streaks.ts), so there is deliberately
  // no startup migration here — a locked or odd DB must never block launch.

  await db.execAsync(`PRAGMA user_version = ${DATABASE_VERSION}`);
}

export function DatabaseProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <SQLiteProvider
      databaseName="relate.db"
      onInit={migrateDb}
    >
      {children}
    </SQLiteProvider>
  );
}
