import { cachedFetch, SHORT_TTL, type CachedFetchOptions } from "./cache";

export type SponsorshipStatus = "pending" | "approved" | "rejected";

export type Sponsorship = {
  _id: string;
  sponsorId: string;
  name: string;
  email: string | null;
  phone: string | null;
  amount: number;
  popUrl: string | null;
  status: SponsorshipStatus;
  createdAt: string;
};

export type MySponsorships = {
  sponsorId: string | null;
  sponsorships: Sponsorship[];
};

export type SponsorshipSummary = {
  est: string;
  downloads: number;
  families: number;
  sponsorships: number;
  sponsorshipTotal: number;
  sponsorshipPaid: number;
  eventIncome: number;
  fundsRaised: number;
};

export type BankingDetails = {
  bankName: string;
  accountHolder: string;
  accountNumber: string;
  branchCode: string;
  accountType: string;
  reference: string;
  instructions: string;
};

export const EMPTY_BANKING: BankingDetails = {
  bankName: "",
  accountHolder: "",
  accountNumber: "",
  branchCode: "",
  accountType: "",
  reference: "",
  instructions: "",
};

/** Renders banking details as a readable, labelled block. */
export function formatBankingDetails(b: BankingDetails): string {
  const rows: [string, string][] = [
    ["Bank", b.bankName],
    ["Account holder", b.accountHolder],
    ["Account number", b.accountNumber],
    ["Branch code", b.branchCode],
    ["Account type", b.accountType],
    ["Reference", b.reference],
  ];
  const lines: string[] = [];
  for (const [key, value] of rows) {
    if (value && value.trim()) lines.push(`${key}: ${value.trim()}`);
  }
  if (b.instructions && b.instructions.trim()) lines.push(b.instructions.trim());
  return lines.join("\n");
}

/** School Kit reach stored on a published report — impact only. */
export type SchoolKitImpact = {
  learners: number;
  books: number;
  pencils: number;
  pens: number;
};

export type KitItemKey = "book" | "pencil" | "pen";

/** Admin-only monthly School Kit statement returned by the prefill endpoint. */
export type SchoolKitStatement = {
  period: string | null;
  opening: Record<KitItemKey, number>;
  received: Record<KitItemKey, number>;
  issued: Record<KitItemKey, number>;
  closing: Record<KitItemKey, number>;
  spend: number;
  learners: number;
  impact: SchoolKitImpact;
};

export type FinancialReportInput = {
  period: string;
  preparedBy: string;
  income: {
    balanceBroughtDown: number;
    foundersFund: number;
    events: number;
    donations: number;
    books: number;
    other: number;
    otherDescription: string;
  };
  expenses: {
    meals: number;
    groceries: number;
    tuition: number;
    transport: number;
    employment: number;
    materials: number;
    other: number;
    otherDescription: string;
    amountsFromRecords: number;
  };
  impact: {
    families: number;
    mealsServed: number;
    children: number;
    placements: number;
    events: number;
  };
  otherActivities: string;
  notes: string;
  customFields: { title: string; content: string }[];
  schoolKit?: SchoolKitImpact;
};

/** One published financial report as shown in the "Financials" list. */
export type FinancialReportSummary = {
  _id: string;
  period: string;
  preparedBy: string;
  createdAt: string;
  income: number;
  /** Income without the balance brought down. Absent on older API responses. */
  raised?: number;
  balanceBroughtDown?: number;
  expenses: number;
  net: number;
};

/** Full detail of a published financial report (the report viewer). */
export type FinancialReport = {
  _id: string;
  period: string;
  preparedBy: string;
  createdAt: string;
  /** `sponsorships` is the retired key; reports filed before the rename still carry it. */
  income: FinancialReportInput["income"] & { sponsorships?: number };
  expenses: FinancialReportInput["expenses"];
  impact: FinancialReportInput["impact"];
  otherActivities: string;
  notes: string;
  customFields: { title: string; content: string }[];
  schoolKit?: SchoolKitImpact;
};

/** Founders’ Fund amount, falling back to the retired `sponsorships` key. */
export function foundersFundOf(income: {
  foundersFund?: number;
  sponsorships?: number;
}): number {
  return income.foundersFund ?? income.sponsorships ?? 0;
}

/** Totals (income / expenses / net) for a compiled report. */
export function reportTotals(r: Pick<FinancialReport, "income" | "expenses">) {
  const income =
    r.income.balanceBroughtDown +
    foundersFundOf(r.income) +
    r.income.events +
    r.income.donations +
    r.income.books +
    r.income.other;
  const expenses =
    r.expenses.meals +
    r.expenses.groceries +
    r.expenses.tuition +
    r.expenses.transport +
    r.expenses.employment +
    r.expenses.materials +
    r.expenses.other +
    r.expenses.amountsFromRecords;
  return { income, expenses, net: income - expenses };
}

async function apiFetch<T>(path: string, options: CachedFetchOptions = {}): Promise<T> {
  return cachedFetch<T>(path, options, ["/api/sponsorships"]);
}

export const sponsorApi = {
  /** Record a sponsorship pledge (login required; uses the session Cookie). */
  submit: (input: {
    name: string;
    email?: string;
    phone?: string;
    amount: number;
    popUrl?: string | null;
  }) =>
    apiFetch<{ data: Sponsorship }>("/api/sponsorships", {
      method: "POST",
      body: JSON.stringify(input),
    }),

  /** Public aggregates for the sponsor modal (approved pledges only). */
  summary: () =>
    apiFetch<SponsorshipSummary>("/api/sponsorships/summary", {
      cacheTtl: SHORT_TTL,
    }),

  /** The signed-in user's sponsor ID + their transactions. */
  me: () =>
    apiFetch<{ data: MySponsorships }>("/api/sponsorships/me", {
      cacheTtl: SHORT_TTL,
    }),

  /**
   * Idempotent — returns the user's existing sponsor ID or creates one if
   * they don't have one yet. Called by SponsorModal on first open so the
   * ID can be prefilled. Safe to call repeatedly; it never replaces an
   * existing ID.
   */
  ensureId: () =>
    apiFetch<{ sponsorId: string }>("/api/sponsorships/ensure-id", {
      method: "POST",
      cacheTtl: 0,
    }),

  /** Admin-only: list sponsorships, newest first (optionally by status). */
  list: (status?: SponsorshipStatus) =>
    apiFetch<{ data: Sponsorship[] }>(
      status ? `/api/sponsorships?status=${status}` : "/api/sponsorships",
      { cacheTtl: 0 },
    ),

  /** Admin-only: review a pending pledge. */
  review: (id: string, action: "approve" | "reject") =>
    apiFetch<{ data: Sponsorship }>(`/api/sponsorships/${id}`, {
      method: "PATCH",
      body: JSON.stringify({ action }),
    }),

  /** Public: banking details shown to sponsors. */
  banking: () =>
    apiFetch<{ data: { banking: BankingDetails } }>("/api/sponsorships/banking", {
      cacheTtl: SHORT_TTL,
    }),

  /** Admin-only: update the banking details sponsors are shown. */
  saveBanking: (banking: BankingDetails) =>
    apiFetch<{ data: { banking: BankingDetails } }>("/api/sponsorships/banking", {
      method: "POST",
      body: JSON.stringify(banking),
    }),

  /** Admin-only: save a manually compiled financial report. */
  saveFinancialReport: (input: FinancialReportInput) =>
    cachedFetch<{ data: { _id: string; period: string } }>(
      "/api/financial-report",
      { method: "POST", body: JSON.stringify(input) },
      ["/api/financial-reports", "/api/financial-report", "/api/performance"],
    ),
};

/** User-facing reads of published financial reports. */
const reportFetch = <T>(path: string, options: CachedFetchOptions = {}): Promise<T> =>
  cachedFetch<T>(path, options, [
    "/api/financial-reports",
    "/api/financial-report",
    "/api/performance",
  ]);

export const financialApi = {
  /** Every published report, newest first, with headline totals. */
  list: () =>
    reportFetch<{ data: FinancialReportSummary[] }>("/api/financial-reports", {
      cacheTtl: SHORT_TTL,
    }),

  /** Full detail of one report for the viewer screen. */
  get: (id: string) =>
    reportFetch<{ data: FinancialReport }>(`/api/financial-reports/${id}`, {
      cacheTtl: 0,
    }),

  /** Admin-only: edit a published report in place. */
  update: (id: string, input: FinancialReportInput) =>
    reportFetch<{ data: { _id: string; period: string } }>(
      `/api/financial-reports/${id}`,
      {
        method: "PATCH",
        body: JSON.stringify(input),
      },
    ),

  /** Admin-only: remove a report filed by mistake. */
  remove: (id: string) =>
    reportFetch<{ data: { _id: string } }>(`/api/financial-reports/${id}`, {
      method: "DELETE",
    }),
};

/** Aggregated data for pre-filling the financial report form. */
export const financialReportDataApi = {
  get: (period: string) =>
    apiFetch<{ data: { foundersFund: number; amountsUsed: number; balanceBroughtDown: number; period: string; schoolKit: SchoolKitStatement | null } }>(
      `/api/financial-report-data?period=${encodeURIComponent(period)}`,
      { cacheTtl: 0 },
    ),
};
