import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import {
  SPORT_THEME,
  teamCrest,
  type RelateTeam,
} from "@/services/sports-catalog";
import { Image as ExpoImage } from "expo-image";
import { LinearGradient } from "expo-linear-gradient";
import { memo, useState } from "react";
import { StyleSheet, Text } from "react-native";
import { getOptimizedImageUrl } from "@/services/cloudinary";

/**
 * A team's crest badge — the hosted logo on a white circle, falling back to
 * the sport's brand gradient with the team's initials when there's no logo
 * or the image fails to load.
 */
function TeamCrest({
  team,
  size,
}: {
  team: RelateTeam;
  /** Diameter in dp. */
  size: number;
}) {
  const uri = teamCrest(team);
  const [failed, setFailed] = useState(false);
  const circle = {
    width: size,
    height: size,
    borderRadius: size / 2,
  };

  if (uri && !failed) {
    return (
      <ExpoImage
        source={{ uri: getOptimizedImageUrl(uri, 160) }}
        style={[circle, { backgroundColor: colors.white }]}
        contentFit="cover"
        transition={200}
        onError={() => setFailed(true)}
        accessibilityLabel={`${team.name} crest`}
      />
    );
  }

  const theme = SPORT_THEME[team.sport];
  return (
    <LinearGradient colors={[theme.colors[0], theme.colors[1]]} style={circle}>
      <Text style={[s.initials, { fontSize: Math.round(size * 0.26) }]}>
        {team.initials}
      </Text>
    </LinearGradient>
  );
}

const s = StyleSheet.create({
  initials: {
    fontFamily: fonts.sansBold,
    fontWeight: "700",
    color: colors.white,
    textAlign: "center",
  },
});

export default memo(TeamCrest);
