import { authClient, STORAGE_PREFIX } from "./auth-client";
import { appStorage } from "./app-storage";
import { API_BASE, IS_WEB, WEB_BASE_PATH } from "./config";

export type User = {
  id: string;
  name: string;
  email: string;
  image: string | null;
  role: string;
};

export type Session = {
  user: User;
};

/** appStorage key that the @better-auth/expo client caches session data under. */
const SESSION_DATA_KEY = `${STORAGE_PREFIX}_session_data`;

function toUser(u: any): User {
  return {
    id: u.id,
    name: u.name ?? "",
    email: u.email ?? "",
    image: u.image ?? null,
    role: u.role ?? "user",
  };
}

function normalizeHeaders(headers?: HeadersInit): Record<string, string> {
  if (!headers) return {};
  if (typeof Headers !== "undefined" && headers instanceof Headers) {
    const result: Record<string, string> = {};
    headers.forEach((value, key) => {
      result[key] = value;
    });
    return result;
  }
  if (Array.isArray(headers)) {
    const result: Record<string, string> = {};
    for (const [key, value] of headers) result[key] = value;
    return result;
  }
  return { ...(headers as Record<string, string>) };
}

export async function getRequestHeaders(
  headers?: HeadersInit,
): Promise<Record<string, string>> {
  const normalized = normalizeHeaders(headers);
  if (IS_WEB) return normalized;
  const token = await getSessionToken();
  return {
    Origin: API_BASE,
    ...(token ? { Cookie: token } : {}),
    ...normalized,
  };
}

function resolveOAuthCallbackPath(callbackPath: string): string {
  if (!IS_WEB || callbackPath.startsWith(WEB_BASE_PATH)) return callbackPath;
  const path = callbackPath
    .split("/")
    .filter((segment) => segment && !(segment.startsWith("(") && segment.endsWith(")")))
    .join("/");
  return path ? `${WEB_BASE_PATH}/${path}` : `${WEB_BASE_PATH}/`;
}

async function readCachedSession(): Promise<Session | null> {
  try {
    const raw = await appStorage.getItemAsync(SESSION_DATA_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed?.user?.id) return null;
    return { user: toUser(parsed.user) };
  } catch {
    return null;
  }
}

async function persistSessionCache(user: any, session: any = null) {
  try {
    const raw = await appStorage.getItemAsync(SESSION_DATA_KEY);
    const prev = raw ? JSON.parse(raw) : {};
    await appStorage.setItemAsync(
      SESSION_DATA_KEY,
      JSON.stringify({ ...prev, user, session: session ?? prev.session ?? null }),
    );
  } catch {}
}

export async function signUp(name: string, email: string, password: string): Promise<Session> {
  const { data, error } = await authClient.signUp.email({ name, email, password });
  if (error) throw new Error(error.message || "Sign up failed");
  await persistSessionCache(data?.user, (data as any)?.session);
  return { user: toUser(data?.user) };
}

export async function signIn(email: string, password: string): Promise<Session> {
  const { data, error } = await authClient.signIn.email({ email, password });
  if (error) throw new Error(error.message || "Sign in failed");
  await persistSessionCache(data?.user, (data as any)?.session);
  return { user: toUser(data?.user) };
}

/** Opens the Google OAuth flow in the system browser and completes it via deep link. */
export async function signInWithGoogle(callbackPath = "/"): Promise<Session> {
  const { error } = await authClient.signIn.social({
    provider: "google",
    callbackURL: resolveOAuthCallbackPath(callbackPath),
  });
  if (error) throw new Error(error.message || "Google sign-in failed");
  const session = await getSession();
  if (!session) {
    throw new Error("Could not retrieve your session after Google sign-in. Please try again.");
  }
  return session;
}

/** Opens the GitHub OAuth flow in the system browser and completes it via deep link. */
export async function signInWithGitHub(callbackPath = "/"): Promise<Session> {
  const { error } = await authClient.signIn.social({
    provider: "github",
    callbackURL: resolveOAuthCallbackPath(callbackPath),
  });
  if (error) throw new Error(error.message || "GitHub sign-in failed");
  const session = await getSession();
  if (!session) {
    throw new Error("Could not retrieve your session after GitHub sign-in. Please try again.");
  }
  return session;
}

export async function signOut(): Promise<void> {
  try {
    await authClient.signOut();
  } catch {}
  await appStorage.deleteItemAsync(SESSION_DATA_KEY);
}

export async function deleteAccount(): Promise<void> {
  const response = await authClient.$fetch("/api/account", {
    method: "DELETE",
    headers: { Accept: "application/json" },
  });
  if (response.error) {
    throw new Error(response.error.message || "Could not delete your account.");
  }
  await signOut();
}

let sessionRefreshPromise: Promise<Session | null> | null = null;
let lastSessionRefreshAt = 0;
const SESSION_REFRESH_MS = 300_000;

async function fetchRemoteSession(): Promise<Session | null> {
  try {
    const { data, error } = await authClient.getSession();
    if (error) return null;
    if (!data?.user) {
      await appStorage.deleteItemAsync(SESSION_DATA_KEY);
      return null;
    }
    await persistSessionCache(data.user, (data as any)?.session ?? null);
    return { user: toUser(data.user) };
  } catch {
    return null;
  }
}

export async function refreshSession(force = false): Promise<Session | null> {
  if (!force && Date.now() - lastSessionRefreshAt < SESSION_REFRESH_MS) {
    return readCachedSession();
  }
  if (sessionRefreshPromise) return sessionRefreshPromise;
  lastSessionRefreshAt = Date.now();
  sessionRefreshPromise = fetchRemoteSession().finally(() => {
    sessionRefreshPromise = null;
  });
  return sessionRefreshPromise;
}

export async function getSession(): Promise<Session | null> {
  const cached = await readCachedSession();
  if (cached) return cached;
  return refreshSession(true);
}

/**
 * The signed-in user's id from local storage only — never hits the network.
 * For checking whether a per-user cache still belongs to the current account.
 */
export async function getCachedUserId(): Promise<string | null> {
  return (await readCachedSession())?.user?.id ?? null;
}

/**
 * Returns the auth identity used for request authentication and cache scoping.
 */
export async function getSessionToken(): Promise<string | null> {
  if (IS_WEB) return (await readCachedSession())?.user.id ?? null;
  const cookie = authClient.getCookie();
  return cookie || null;
}

export async function updateSessionUser(patch: Partial<User>): Promise<User> {
  const current = (await readCachedSession())?.user;
  const merged = { ...(current as User), ...patch };
  try {
    const raw = await appStorage.getItemAsync(SESSION_DATA_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      parsed.user = { ...parsed.user, ...patch };
      await appStorage.setItemAsync(SESSION_DATA_KEY, JSON.stringify(parsed));
    } else {
      await persistSessionCache(merged);
    }
  } catch {}
  return merged;
}
