import { PrayerName } from "@/services/notifications";

export type SoundOption = {
  id: string;
  label: string;
  file: string;
};

export const AVAILABLE_SOUNDS: SoundOption[] = [
  { id: "dawn", label: "Dawn", file: "dawn" },
  { id: "sunrise", label: "Sunrise", file: "sunrise" },
  { id: "noon", label: "Noon", file: "noon" },
  { id: "afternoon", label: "Afternoon", file: "afternoon" },
  { id: "sunset", label: "Sunset", file: "sunset" },
  { id: "evening", label: "Evening", file: "evening" },
];

export type PrayerSounds = Record<PrayerName, string>;

export const DEFAULT_SOUNDS: PrayerSounds = {
  dawn: "dawn",
  sunrise: "sunrise",
  noon: "noon",
  afternoon: "afternoon",
  sunset: "sunset",
  evening: "evening",
};

export function getSoundFile(id: string): string {
  return AVAILABLE_SOUNDS.find((s) => s.id === id)?.file || id;
}
