import { Ionicons } from "@expo/vector-icons";
import { router, useFocusEffect } from "expo-router";
import { useCallback, useState } from "react";
import {
  ActivityIndicator,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { boardApi, type BoardMinutesSummary } from "@/services/board-governance";
import { boardStyles as s } from "./styles";

function formatDate(value: string | null): string {
  if (!value) return "Date to be confirmed";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleDateString("en-ZA", {
    weekday: "short",
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

function monthLabel(value: string | null): string {
  if (!value) return "Undated";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "Undated";
  return date.toLocaleDateString("en-ZA", { month: "long", year: "numeric" });
}

type Group = { key: string; label: string; items: BoardMinutesSummary[] };

function groupByMonth(items: BoardMinutesSummary[]): Group[] {
  const groups: Group[] = [];
  for (const item of items) {
    const stamp = item.meetingDate || item.publishedAt;
    const label = monthLabel(stamp);
    const last = groups[groups.length - 1];
    if (last && last.label === label) last.items.push(item);
    else groups.push({ key: `${label}-${groups.length}`, label, items: [item] });
  }
  return groups;
}

/** Simple card archive: titles and dates only; the detail screen carries the record. */
export default function MinutesList({ bottomInset = 0 }: { bottomInset?: number }) {
  const [items, setItems] = useState<BoardMinutesSummary[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    try {
      setError("");
      const res = await boardApi.listMinutesCards();
      setItems(res.data || []);
    } catch (e: any) {
      setError(e?.message || "Failed to load minutes.");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  // Reloads on every focus so edits or deletes made in the detail screen show.
  useFocusEffect(
    useCallback(() => {
      void load();
    }, [load]),
  );

  const onRefresh = () => {
    setRefreshing(true);
    void load();
  };

  const groups = groupByMonth(items);

  return (
    <ScrollView
      contentContainerStyle={{
        paddingHorizontal: 16,
        paddingBottom: 40 + bottomInset,
        gap: 16,
      }}
      showsVerticalScrollIndicator={false}
      refreshControl={
        <RefreshControl
          refreshing={refreshing}
          onRefresh={onRefresh}
          tintColor={colors.goldDark}
          colors={[colors.goldDark]}
        />
      }
    >
      {loading ? (
        <View style={s.center}>
          <ActivityIndicator color={colors.goldDark} size="large" />
        </View>
      ) : error ? (
        <View style={s.emptyBox}>
          <Ionicons name="warning-outline" size={24} color={colors.error} />
          <Text style={s.emptyTitle}>Couldn’t load the minutes</Text>
          <Text style={s.emptyBody}>{error}</Text>
          <TouchableOpacity onPress={() => void load()} activeOpacity={0.85}>
            <Text style={[s.docLinkText, { marginTop: 6 }]}>Retry</Text>
          </TouchableOpacity>
        </View>
      ) : items.length === 0 ? (
        <View style={s.emptyBox}>
          <Ionicons name="documents-outline" size={24} color={colors.muted} />
          <Text style={s.emptyTitle}>No minutes yet</Text>
          <Text style={s.emptyBody}>
            Minutes you publish will appear here, newest first, grouped by month.
          </Text>
        </View>
      ) : (
        groups.map((group) => (
          <View key={group.key} style={styles.group}>
            <Text style={styles.groupLabel}>{group.label}</Text>
            {group.items.map((minutes) => (
              <TouchableOpacity
                key={minutes._id}
                style={styles.card}
                activeOpacity={0.85}
                onPress={() =>
                  router.push(
                    `/admin/board-governance/minutes/${minutes._id}` as any,
                  )
                }
                accessibilityLabel={`Open minutes for ${minutes.meetingTitle}`}
              >
                <View style={styles.cardIcon}>
                  <Ionicons name="document-text-outline" size={20} color={colors.goldDark} />
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={styles.cardTitle}>{minutes.meetingTitle}</Text>
                  <Text style={styles.cardDate}>{formatDate(minutes.meetingDate)}</Text>
                  <Text style={styles.cardMeta}>
                    Published {formatDate(minutes.publishedAt)} · {minutes.publishedByName}
                  </Text>
                </View>
                <Ionicons name="chevron-forward" size={19} color={colors.muted} />
              </TouchableOpacity>
            ))}
          </View>
        ))
      )}
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  group: { gap: 8 },
  groupLabel: {
    fontSize: 13,
    letterSpacing: 1,
    textTransform: "uppercase",
    color: colors.muted,
    fontFamily: fonts.sansBold,
  },
  card: {
    flexDirection: "row",
    alignItems: "center",
    gap: 12,
    padding: 16,
    borderRadius: 18,
    borderWidth: 0.5,
    borderColor: colors.lightGreen,
    backgroundColor: colors.white,
  },
  cardIcon: {
    width: 42,
    height: 42,
    borderRadius: 14,
    backgroundColor: `${colors.gold}1f`,
    alignItems: "center",
    justifyContent: "center",
  },
  cardTitle: {
    fontSize: 17,
    lineHeight: 23,
    color: colors.darkGreen,
    fontFamily: fonts.sansBold,
  },
  cardDate: {
    marginTop: 3,
    fontSize: 14,
    lineHeight: 20,
    color: colors.ink,
    fontFamily: fonts.sansMedium,
  },
  cardMeta: {
    marginTop: 2,
    fontSize: 12.5,
    lineHeight: 18,
    color: colors.muted,
    fontFamily: fonts.sans,
  },
});
