import { appStorage } from "./app-storage";
import { syncNotificationPreferences } from "./notification-settings";
import {
  DEFAULT_VERSION_ID,
  YOUVERSION_VERSIONS,
} from "@/constants/bible_versions_youversion";

const VOTD_VERSION_KEY = "bible_votd_version_id";
const VOTD_ENABLED_KEY = "bible_votd_enabled";

export const VOTD_VERSION_IDS = YOUVERSION_VERSIONS.map((v) => v.id);

export async function getVotdVersionId(): Promise<number> {
  try {
    const raw = await appStorage.getItemAsync(VOTD_VERSION_KEY);
    if (raw) {
      const id = parseInt(raw, 10);
      if (VOTD_VERSION_IDS.includes(id)) return id;
    }
  } catch {}
  return DEFAULT_VERSION_ID;
}

export async function setVotdVersionId(id: number): Promise<void> {
  await appStorage.setItemAsync(VOTD_VERSION_KEY, String(id));
}

// Home "Verse of the Day" card visibility. Defaults on; the Settings → General
// toggle persists it so Home can hide the card when the user turns it off.
export async function getVotdEnabled(): Promise<boolean> {
  try {
    const raw = await appStorage.getItemAsync(VOTD_ENABLED_KEY);
    if (raw !== null) return raw !== "false";
  } catch {}
  return true;
}

export async function setVotdEnabled(enabled: boolean): Promise<void> {
  await appStorage.setItemAsync(VOTD_ENABLED_KEY, enabled ? "true" : "false");
  await syncNotificationPreferences({ votdEnabled: enabled });
}
