import { Image } from "expo-image";
import { LinearGradient } from "expo-linear-gradient";
import { Ionicons } from "@expo/vector-icons";
import { useRouter } from "expo-router";
import { useEffect, useMemo, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  Pressable,
  StyleSheet,
  Text,
  View,
  useWindowDimensions,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { useClubs } from "@/services/clubs";
import { setTabBarHidden } from "@/services/unread";
import { signInWithGitHub, signInWithGoogle } from "@/services/auth";
import { getOptimizedImageUrl } from "@/services/cloudinary";
import GoogleIcon from "@/components/GoogleIcon";

/**
 * Landing shown over the home tab while prayer times and streaks load — the
 * mobile view of the web home hero: full-bleed crossfading photos, eyebrow →
 * display title → tagline → description → stats → CTA → carousel dots.
 *
 * Deliberately carries none of the web chrome: no navbar, no logo, no avatar
 * or profile. The tab bar stays hidden while it's up; the landing only leaves
 * when "Get Started" is tapped (it never auto-dismisses).
 */

type Slide = {
  key: string;
  eyebrow?: string;
  title: string;
  tagline: string;
  /** Age range the club covers (e.g. "6–16 yrs") — club slides only. */
  age?: string;
  description: string;
  image: string;
};

type Countdown = { hours: number; minutes: number; seconds: number };

const AUTOPLAY_MS = 6000;
const TRANSITION_MS = 700;

const pad = (n: number) => String(n).padStart(2, "0");

// Seconds render as unicode superscripts, exactly like the web hero.
const SUP_DIGITS = "⁰¹²³⁴⁵⁶⁷⁸⁹";
const supSeconds = (n: number) =>
  String(n)
    .padStart(2, "0")
    .replace(/\d/g, (d) => SUP_DIGITS[Number(d)]);

const brandImage =
  "https://images.unsplash.com/photo-1503454537195-1dcabb73ffb9?w=1600&q=80";
const charityImage =
  "https://images.unsplash.com/photo-1488521787991-ed7bbaae773c?w=1600&q=80";

const textShadow = {
  textShadowColor: "rgba(10,14,24,0.95)",
  textShadowOffset: { width: 0, height: 2 },
  textShadowRadius: 18,
};

export default function HomeLandingLoader({
  signedIn = false,
  authReady = false,
  onGetStarted,
  onSignIn,
  onAuthStart,
  onAuthSuccess,
  onContinueAsGuest,
  prayerTitle,
  remaining,
}: {
  /** True once a session is present — signed-in users get the Get Started CTA. */
  signedIn?: boolean;
  /** False until the session check has resolved, so the CTA never flashes wrong. */
  authReady?: boolean;
  onGetStarted: () => void;
  onSignIn?: () => void;
  /** Called before the OAuth sheet opens so the welcome is not shown again. */
  onAuthStart?: () => void;
  /** Called once OAuth completes, so the welcome closes without a remount. */
  onAuthSuccess?: () => void;
  onContinueAsGuest?: () => void;
  /** Title of the next prayer (e.g. "Fajr") once the times are known. */
  prayerTitle?: string;
  remaining?: Countdown;
}) {
  const router = useRouter();
  const [oauthBusy, setOauthBusy] = useState<"google" | "github" | null>(null);

  const handleGoogle = async () => {
    setOauthBusy("google");
    onAuthStart?.();
    try {
      await signInWithGoogle("/(tabs)");
      onAuthSuccess?.();
      router.replace("/(tabs)");
    } catch (err: any) {
      Alert.alert(
        "Google Sign In Failed",
        err?.message || "Unable to sign in with Google.",
      );
    } finally {
      setOauthBusy(null);
    }
  };

  const handleGitHub = async () => {
    setOauthBusy("github");
    onAuthStart?.();
    try {
      await signInWithGitHub("/(tabs)");
      onAuthSuccess?.();
      router.replace("/(tabs)");
    } catch (err: any) {
      Alert.alert(
        "GitHub Sign In Failed",
        err?.message || "Unable to sign in with GitHub.",
      );
    } finally {
      setOauthBusy(null);
    }
  };
  const insets = useSafeAreaInsets();
  const { width } = useWindowDimensions();
  const { clubs } = useClubs();
  const [index, setIndex] = useState(0);

  useEffect(() => {
    setTabBarHidden(true);
    return () => setTabBarHidden(false);
  }, []);

  const countdown =
    remaining != null
      ? remaining.hours > 0
        ? `${remaining.hours}h ${pad(remaining.minutes)}m ${supSeconds(remaining.seconds)}`
        : `${pad(remaining.minutes)}m ${supSeconds(remaining.seconds)}`
      : "";

  // Brand → prayer → charity, then every club with a hero photo — the same
  // set the web hero runs, minus the reading-guide slides.
  const slides = useMemo<Slide[]>(() => {
    const base: Slide[] = [
      {
        key: "brand",
        eyebrow: "Relate World",
        title: "Grow",
        tagline: "in every area of life",
        description:
          "Our vision is to help you be self-reliant and sustainable. Share your gifts, connect with your community, deepen your faith — every club and program is measured against that single outcome.",
        image: brandImage,
      },
      {
        key: "prayer",
        eyebrow: prayerTitle ? `${prayerTitle} Prayer` : undefined,
        title: countdown || "Pray with us",
        tagline: "six moments, every day",
        description:
          "A live countdown to the next prayer moment. Dawn, sunrise, noon, afternoon, sunset and evening — a simple daily rhythm, with a verse for each.",
        image: brandImage,
      },
      {
        key: "charity",
        title: "Care",
        tagline: "share it — we can help",
        description:
          "Charity comes first. We stand with orphans, widows and child-headed families — food relief, school fees, uniforms, childcare and counselling — so help today builds independence, not dependence.",
        image: charityImage,
      },
    ];
    const clubSlides: Slide[] = clubs
      .filter((club) => !!club.heroImage)
      .map((club) => ({
        key: club.slug,
        title: club.name,
        tagline: club.tagline,
        age: club.ageRange,
        description: club.description,
        image: club.heroImage as string,
      }));
    return [...base, ...clubSlides];
  }, [prayerTitle, countdown, clubs]);

  const active = slides.length > 0 ? Math.min(index, slides.length - 1) : 0;
  const slide = slides[active];

  useEffect(() => {
    if (slides.length < 2) return;
    const timer = setInterval(() => {
      setIndex((i) => (i + 1) % slides.length);
    }, AUTOPLAY_MS);
    return () => clearInterval(timer);
  }, [slides.length]);

  // One persistent Image drives every swap: expo-image cross-dissolves the
  // source natively and keeps the outgoing bitmap visible until the next one
  // is decoded, so the container background never flashes through.
  const source = useMemo(
    () => ({ uri: getOptimizedImageUrl(slide?.image ?? brandImage, 1200) }),
    [slide?.image],
  );

  return (
    <View style={styles.container}>
      <StatusBar style="light" />

      {/* Full-bleed photo; source changes cross-dissolve in place */}
      <Image
        source={source}
        style={StyleSheet.absoluteFill}
        contentFit="cover"
        transition={TRANSITION_MS}
        accessibilityIgnoresInvertColors
      />

      {/* Keeps the auth buttons off bright image patches. */}
      <LinearGradient
        pointerEvents="none"
        colors={[
          "rgba(3,16,11,0)",
          "rgba(3,16,11,0.45)",
          "#03100B",
          "#03100B",
        ]}
        locations={[0, 0.32, 0.68, 1]}
        style={styles.fade}
      />

      <View
        style={[
          styles.content,
          { paddingTop: insets.top + 24, paddingBottom: insets.bottom + 24 },
        ]}
      >
        <View style={styles.copy}>
          {slide?.eyebrow ? (
            <Text style={styles.eyebrow}>{slide.eyebrow.toUpperCase()}</Text>
          ) : null}

          <Text
            style={[
              styles.title,
              { fontSize: Math.min(Math.max(width * 0.16, 42), 64) },
            ]}
            numberOfLines={2}
            adjustsFontSizeToFit
          >
            {slide?.title ?? "Relate World"}
          </Text>

          <Text style={styles.tagline}>{slide?.tagline}</Text>
          {slide?.age ? (
            <Text style={styles.age} accessibilityRole="text">
              {slide.age}
            </Text>
          ) : null}
          <Text style={styles.description} numberOfLines={5}>
            {slide?.description}
          </Text>

          {/* Stats bar — the web hero's meta row */}
          <View style={styles.meta}>
            <View style={styles.metaItem}>
              <Text style={styles.metaLabel}>Clubs</Text>
              <Text style={styles.metaValue}>{clubs.length || 7}</Text>
            </View>
            <View style={styles.metaItem}>
              <Text style={styles.metaLabel}>Programs</Text>
              <Text style={styles.metaValue}>60+</Text>
            </View>
            <View style={styles.metaItem}>
              <Text style={styles.metaLabel}>Free</Text>
              <Text style={styles.metaValue}>100%</Text>
            </View>
          </View>

          {authReady ? (
            signedIn || !onSignIn ? (
              <Pressable
                onPress={onGetStarted}
                accessibilityRole="button"
                accessibilityLabel="Get Started"
                style={({ pressed }) => [
                  styles.cta,
                  pressed && styles.ctaPressed,
                ]}
              >
                <Text style={styles.ctaText}>Get Started</Text>
              </Pressable>
            ) : (
              <View style={styles.authActions}>
                <Pressable
                  onPress={handleGoogle}
                  disabled={oauthBusy !== null}
                  accessibilityRole="button"
                  accessibilityLabel="Continue with Google"
                  accessibilityState={{ disabled: oauthBusy !== null, busy: oauthBusy === "google" }}
                  style={({ pressed }) => [
                    styles.cta,
                    styles.authPrimary,
                    oauthBusy !== null && styles.ctaPressed,
                    pressed && oauthBusy === null && styles.ctaPressed,
                  ]}
                >
                  {oauthBusy === "google" ? (
                    <ActivityIndicator color={colors.forest} size="small" />
                  ) : (
                    <GoogleIcon size={20} />
                  )}
                  <Text style={styles.ctaText}>Continue with Google</Text>
                </Pressable>
                <Pressable
                  onPress={handleGitHub}
                  disabled={oauthBusy !== null}
                  accessibilityRole="button"
                  accessibilityLabel="Continue with GitHub"
                  accessibilityState={{ disabled: oauthBusy !== null, busy: oauthBusy === "github" }}
                  style={({ pressed }) => [
                    styles.authGhost,
                    pressed && oauthBusy === null && styles.ctaPressed,
                  ]}
                >
                  {oauthBusy === "github" ? (
                    <ActivityIndicator color={colors.white} size="small" />
                  ) : (
                    <Ionicons name="logo-github" size={18} color={colors.white} />
                  )}
                  <Text style={styles.authGhostText}>Continue with GitHub</Text>
                </Pressable>
                <View style={styles.authOr}>
                  <View style={styles.authOrLine} />
                  <Text style={styles.authOrText}>or</Text>
                  <View style={styles.authOrLine} />
                </View>
                <Pressable
                  onPress={onSignIn}
                  accessibilityRole="button"
                  accessibilityLabel="Sign in"
                  style={({ pressed }) => [
                    styles.authOutline,
                    pressed && styles.ctaPressed,
                  ]}
                >
                  <Ionicons
                    name="mail-outline"
                    size={17}
                    color={colors.forestDark}
                  />
                  <Text style={styles.authOutlineText}>Sign in</Text>
                </Pressable>
                {onContinueAsGuest ? (
                  <Pressable
                    onPress={onContinueAsGuest}
                    accessibilityRole="button"
                    accessibilityLabel="Continue without an account"
                    hitSlop={8}
                    style={({ pressed }) => pressed && styles.ctaPressed}
                  >
                    <Text style={styles.guestLink}>
                      Continue without an account
                    </Text>
                  </Pressable>
                ) : null}
              </View>
            )
          ) : (
            <Pressable
              disabled
              accessibilityRole="button"
              accessibilityLabel="Getting things ready"
              accessibilityState={{ disabled: true, busy: true }}
              style={[styles.cta, styles.ctaLoading]}
            >
              <ActivityIndicator color={colors.forest} size="small" />
              <Text style={styles.ctaText}>Getting things ready…</Text>
            </Pressable>
          )}

        </View>
      </View>
    </View>
  );
}

