import { API_BASE } from "@/services/config";
import type { Publication } from "@/data/publications/types";

const asPub = (p: unknown) => p as Publication;
const isPub = (p: unknown): p is Publication =>
  typeof p === "object" &&
  p !== null &&
  typeof (p as Publication).id === "string" &&
  ((p as Publication).kind === "magazine" ||
    (p as Publication).kind === "bulletin");

/**
 * Live publications from GET /api/publications. Throws on network/server
 * errors so callers can surface an error state; returns [] only when the
 * backend has no published content.
 */
export async function fetchPublications(): Promise<Publication[]> {
  const res = await fetch(`${API_BASE}/api/publications`, {
    headers: { Accept: "application/json" },
  });
  if (!res.ok) throw new Error("Failed to fetch publications");
  const data: unknown = await res.json();
  return Array.isArray(data) ? data.filter(isPub).map(asPub) : [];
}

/** Fetch one publication by its stable id (or the slug/route param). */
export async function fetchPublication(
  id: string | undefined,
): Promise<Publication | undefined> {
  if (!id) return undefined;
  const res = await fetch(
    `${API_BASE}/api/publications/${encodeURIComponent(id)}`,
    { headers: { Accept: "application/json" } },
  );
  if (!res.ok) throw new Error("Failed to fetch publication");
  const data: unknown = await res.json();
  return isPub(data) ? asPub(data) : undefined;
}

export type TodayReadingTarget = {
  slug: string;
  week: number;
  day: number;
  date: string;
};

/**
 * The day to deep-link for a club's guided reading (today, else next, else
 * first). Backed by GET /api/reading-today so the home shortcut doesn't need
 * every guide's weeks. Returns null when the club has no guide yet.
 */
export async function fetchTodayReading(
  tag: string,
  date: string,
): Promise<TodayReadingTarget | null> {
  const params = new URLSearchParams({ tag, date });
  const res = await fetch(`${API_BASE}/api/reading-today?${params.toString()}`, {
    headers: { Accept: "application/json" },
  });
  if (!res.ok) throw new Error("Failed to fetch today's reading");
  const data: unknown = await res.json();
  if (data && typeof data === "object" && (data as { found?: boolean }).found) {
    return data as TodayReadingTarget;
  }
  return null;
}