import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { router, useLocalSearchParams } from "expo-router";
import { StatusBar } from "expo-status-bar";
import {
  ActivityIndicator,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  useWindowDimensions,
  View,
} from "react-native";
import { SafeAreaProvider, SafeAreaView } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { useSkillsCatalog } from "@/services/skills-catalog";
import { getClub } from "@/constants/clubs";
import SkillCard from "@/components/skills/SkillCard";
import { GradientBox } from "@/constants/gradients";

/** Skills directory for a club — all skills for that club. */
export default function ClubSkillsScreen() {
  const { club: clubParam } = useLocalSearchParams<{ club?: string }>();
  const clubSlug = clubParam || "surge";
  const { data, loading, error } = useSkillsCatalog(clubSlug);
  const { width } = useWindowDimensions();

  const gutter = 20;
  // One skill card per row — full content width inside the padded grid.
  const cardW = width - gutter * 2;

  if (loading) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={s.stateWrap}>
            <ActivityIndicator size="large" color={colors.goldDark} />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (error || !data) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={s.stateWrap}>
            <Ionicons
              name="alert-circle-outline"
              size={40}
              color={colors.gold}
            />
            <Text style={s.stateTitle}>Skills unavailable</Text>
            <Text style={s.stateText}>{error ?? ""}</Text>
            <TouchableOpacity
              style={s.stateBtn}
              activeOpacity={0.85}
              onPress={() => router.back()}
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Text style={s.stateBtnText}>Go back</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const club = getClub(data.clubSlug);
  const gradient = [
    data.clubColor || club?.color || "#1d2a4d",
    data.clubColorDark || club?.colorDark || "#151f3a",
  ] as const;

  // Group by level when the catalog carries level ids; otherwise one flat grid.
  const grouped = data.skills.some((skill) => skill.levelId);
  const sections = grouped
    ? (() => {
        const byLevel = new Map<string, typeof data.skills>();
        for (const skill of data.skills) {
          if (!skill.levelId) continue;
          byLevel.set(skill.levelId, [...(byLevel.get(skill.levelId) ?? []), skill]);
        }
        const known = new Set<string>();
        const built = data.levels
          .map((level) => {
            known.add(level.id);
            return { level, skills: byLevel.get(level.id) ?? [] };
          })
          .filter((section) => section.skills.length > 0);
        // Skills pointing at an unknown level — keep them visible.
        const leftovers = data.skills.filter(
          (skill) => !skill.levelId || !known.has(skill.levelId),
        );
        if (leftovers.length > 0 && built.length > 0) {
          built[0] = { ...built[0], skills: [...leftovers, ...built[0].skills] };
        }
        return built;
      })()
    : [];

  return (
    <SafeAreaProvider>
      <SafeAreaView style={s.safe} edges={["top"]}>
        <StatusBar style="dark" />
        <ScrollView
          contentContainerStyle={s.content}
          showsVerticalScrollIndicator={false}
        >
          <LinearGradient
            colors={gradient}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={s.hero}
          >
            <TouchableOpacity
              style={s.heroBack}
              activeOpacity={0.85}
              onPress={() => router.back()}
              accessibilityLabel="Go back"
            >
              <Ionicons name="chevron-back" size={20} color={colors.white} />
            </TouchableOpacity>

            <Text style={s.heroEyebrow}>{data.clubName.toUpperCase()}</Text>
            <Text style={s.heroTitle}>Skills &amp; growth</Text>
            <Text style={s.heroTagline}>
              {data.count} skills across {data.clubName} — each with levels you
              can work toward and prove.
            </Text>

            <View style={s.heroMeta}>
              <View style={s.heroMetaItem}>
                <Text style={s.heroMetaValue}>{data.count}</Text>
                <Text style={s.heroMetaLabel}>Skills</Text>
              </View>
              {club && (
                <View style={s.heroMetaItem}>
                  <Text style={s.heroMetaValue}>{club.ageRange}</Text>
                  <Text style={s.heroMetaLabel}>Ages</Text>
                </View>
              )}
            </View>
          </LinearGradient>

          {grouped && sections.length > 0 ? (
            sections.map(({ level, skills }) => (
              <View key={level.id} style={s.section}>
                <View style={s.sectionHead}>
                  <View
                    style={[s.sectionDot, { backgroundColor: level.color }]}
                  />
                  <Text style={s.sectionTitle}>{level.name}</Text>
                </View>
                {level.description ? (
                  <Text style={s.sectionDesc}>{level.description}</Text>
                ) : null}
                <View style={s.grid}>
                  {skills.map((skill) => (
                    <SkillCard
                      key={skill.id}
                      skill={skill}
                      club={data}
                      width={cardW}
                      onPress={() =>
                        router.push(`/skills/${data.clubSlug}/${skill.id}`)
                      }
                      accessibilityLabel={`${skill.name} skill`}
                    />
                  ))}
                </View>
              </View>
            ))
          ) : (
            <View style={s.grid}>
              {data.skills.map((skill) => (
                <SkillCard
                  key={skill.id}
                  skill={skill}
                  club={data}
                  width={cardW}
                  onPress={() =>
                    router.push(`/skills/${data.clubSlug}/${skill.id}`)
                  }
                  accessibilityLabel={`${skill.name} skill`}
                />
              ))}
            </View>
          )}
        </ScrollView>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

