import { Ionicons } from "@expo/vector-icons";
import { Image } from "expo-image";
import { StatusBar } from "expo-status-bar";
import { useRouter } from "expo-router";
import { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator,
  FlatList,
  RefreshControl,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaProvider, SafeAreaView } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { getSession } from "@/services/auth";
import {
  ORDER_STATUS_LABEL,
  ORDER_STATUS_SUB,
  formatOrderDate,
  ordersApi,
  type Order,
} from "@/services/orders";
import { formatPrice } from "@/services/store";
import { getOptimizedImageUrl } from "@/services/cloudinary";
import { GradientBox } from "@/constants/gradients";

/** Status pill colour — mirrors the admin queue so the two never disagree. */
const STATUS_TINT: Record<Order["status"], { bg: string; fg: string }> = {
  received: { bg: "rgba(103,227,245,0.85)", fg: colors.goldDark },
  payment_received: { bg: "rgba(59,130,246,0.14)", fg: colors.info },
  shipped: { bg: "rgba(245,158,11,0.16)", fg: "#b45309" },
  delivered: { bg: "rgba(16,185,129,0.16)", fg: "#047857" },
  cancelled: { bg: "rgba(239,68,68,0.14)", fg: colors.error },
};

/**
 * Order history — every order this buyer has placed, newest first, each one
 * linking into the receipt/progress screen.
 */
export default function OrdersScreen() {
  const router = useRouter();
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const res = await ordersApi.mine();
      setOrders(res.data);
      setError(null);
    } catch (err: any) {
      setError(String(err?.message || "We couldn't load your orders."));
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  // Signed-in only — the backend 401s otherwise, so redirect up front.
  useEffect(() => {
    let cancelled = false;
    getSession()
      .then((session) => {
        if (cancelled) return;
        if (!session?.user) {
          router.replace({ pathname: "/login", params: { next: "/orders" } });
          return;
        }
        load();
      })
      .catch(() => {
        if (!cancelled) {
          router.replace({ pathname: "/login", params: { next: "/orders" } });
        }
      });
    return () => {
      cancelled = true;
    };
  }, [load, router]);

  const retry = () => {
    setLoading(true);
    load();
  };

  if (loading) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={styles.bar}>
            <TouchableOpacity
              style={styles.iconBtn}
              onPress={() => router.back()}
              accessibilityRole="button"
              accessibilityLabel="Back"
            >
              <Ionicons name="chevron-back" size={22} color={colors.forest} />
            </TouchableOpacity>
            <Text style={styles.barTitle}>My orders</Text>
            <View style={styles.iconBtn} />
          </View>
          <View style={styles.loading}>
            <ActivityIndicator color={colors.forest} size="large" />
            <Text style={styles.loadingText}>Loading your orders…</Text>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <StatusBar style="dark" />

        <View style={styles.bar}>
          <TouchableOpacity
            style={styles.iconBtn}
            onPress={() => router.back()}
            accessibilityRole="button"
            accessibilityLabel="Back"
          >
            <Ionicons name="chevron-back" size={22} color={colors.forest} />
          </TouchableOpacity>
          <View style={{ flex: 1 }}>
            <Text style={styles.barTitle}>My orders</Text>
            <Text style={styles.barSub}>
              {orders.length === 0
                ? "No orders yet"
                : `${orders.length} order${orders.length === 1 ? "" : "s"}`}
            </Text>
          </View>
          <View style={styles.iconBtn} />
        </View>

        <FlatList
          data={orders}
          keyExtractor={(o) => o._id}
          showsVerticalScrollIndicator={false}
          contentContainerStyle={styles.content}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={() => {
                setRefreshing(true);
                load();
              }}
              tintColor={colors.forest}
            />
          }
          ListHeaderComponent={
            error ? (
              <TouchableOpacity style={styles.errorBox} onPress={retry}>
                <Ionicons name="cloud-offline-outline" size={16} color={colors.error} />
                <Text style={styles.errorText}>{error}</Text>
                <Text style={styles.retry}>Tap to retry</Text>
              </TouchableOpacity>
            ) : null
          }
          ListEmptyComponent={
            !error ? (
              <View style={styles.empty}>
                <View style={styles.emptyIcon}>
                  <Ionicons name="receipt-outline" size={30} color={colors.forest} />
                </View>
                <Text style={styles.emptyTitle}>No orders yet</Text>
                <Text style={styles.emptyText}>
                  When you place an order it shows up here with its receipt,
                  payment details and delivery progress.
                </Text>
                <TouchableOpacity
                  style={styles.emptyBtn}
                  onPress={() => router.replace("/(tabs)/store")}
                  activeOpacity={0.9}
                >
                  <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                  <Text style={styles.emptyBtnText}>Browse the store</Text>
                </TouchableOpacity>
              </View>
            ) : null
          }
          renderItem={({ item }) => {
            const tint = STATUS_TINT[item.status];
            const qty = item.items.reduce((sum, it) => sum + it.qty, 0);
            return (
              <TouchableOpacity
                style={styles.orderCard}
                activeOpacity={0.9}
                onPress={() =>
                  router.push({ pathname: "/order/[id]" as any, params: { id: item._id } })
                }
                accessibilityRole="button"
                accessibilityLabel={`Order ${item.orderNumber}, ${ORDER_STATUS_LABEL[item.status]}`}
              >
                <View style={styles.orderHead}>
                  <View style={{ flex: 1 }}>
                    <Text style={styles.orderNo}>{item.orderNumber}</Text>
                    <Text style={styles.orderDate}>
                      {item.createdAt ? formatOrderDate(item.createdAt) : ""}
                      {qty ? ` · ${qty} item${qty === 1 ? "" : "s"}` : ""}
                    </Text>
                  </View>
                  <View style={[styles.statusPill, { backgroundColor: tint.bg }]}>
                    <Text style={[styles.statusText, { color: tint.fg }]}>
                      {ORDER_STATUS_LABEL[item.status]}
                    </Text>
                  </View>
                </View>

                <View style={styles.orderThumbs}>
                  {item.items.slice(0, 4).map((it, i) =>
                    it.image ? (
                      <Image
                        key={`${it.itemId}-${i}`}
                        source={{ uri: getOptimizedImageUrl(it.image, 720) }}
                        style={styles.thumb}
                        contentFit="cover"
                      />
                    ) : null,
                  )}
                  <View style={{ flex: 1 }} />
                  <View style={{ alignItems: "flex-end" }}>
                    <Text style={styles.orderTotal}>{formatPrice(item.total)}</Text>
                    <Text style={styles.orderEta}>
                      {item.status === "delivered"
                        ? "Delivered"
                        : item.status === "cancelled"
                          ? "Cancelled"
                          : item.eta
                            ? `Est. ${formatOrderDate(item.eta)}`
                            : ORDER_STATUS_SUB[item.status]}
                    </Text>
                  </View>
                </View>

                <View style={styles.orderFoot}>
                  <Text style={styles.viewReceipt}>View receipt</Text>
                  <Ionicons name="chevron-forward" size={14} color={colors.forest} />
                </View>
              </TouchableOpacity>
            );
          }}
        />
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

