function formatRegDate(value: string | Date | undefined): string {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

function eventStartMs(e: { date: string; time: string }): number {
  if (!e.date) return Number.MAX_SAFE_INTEGER;
  const day = new Date(`${String(e.date).slice(0, 10)}T00:00:00`);
  if (isNaN(day.getTime())) return Number.MAX_SAFE_INTEGER;
  const m = /^(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/i.exec(String(e.time).trim());
  let h = 12;
  let min = 0;
  if (m) {
    h = parseInt(m[1], 10);
    min = m[2] ? parseInt(m[2], 10) : 0;
    const ampm = m[3] ? m[3].toLowerCase() : null;
    if (ampm === "pm" && h < 12) h += 12;
    if (ampm === "am" && h === 12) h = 0;
  }
  day.setHours(h, min, 0, 0);
  return day.getTime();
}

/** Fallback "now" for call/session start, captured once at load to keep renders pure. */
const LOADED_AT_MS = Date.now();

/** Small counts spelled out so section titles read like the web copy ("three age groups"). */
const AGE_WORDS: Record<number, string> = {
  1: "one",
  2: "two",
  3: "three",
  4: "four",
  5: "five",
  6: "six",
  7: "seven",
  8: "eight",
  9: "nine",
  10: "ten",
  11: "eleven",
  12: "twelve",
};

type ClubEvent = Event & {
  /** Alias of _id required by the reused EventDetail/Registration modals. */
  id: string;
  feeAmount: number;
  feeSymbol: string;
  amountPaid: number;
  pendingAmount: number;
  totalDue: number;
  remaining: number;
};

/** Adds the id alias and payment defaults the reused event modals expect. */
function toClubEvent(e: Event): ClubEvent {
  return {
    ...e,
    id: e._id,
    feeAmount: e.feeAmount ?? 0,
    feeSymbol: e.feeSymbol ?? "",
    amountPaid: e.amountPaid ?? 0,
    pendingAmount: e.pendingAmount ?? 0,
    totalDue: e.totalDue ?? e.feeAmount ?? 0,
    remaining: e.remaining ?? e.totalDue ?? e.feeAmount ?? 0,
  };
}

function ClubScreen() {
  const { slug } = useLocalSearchParams<{ slug?: string }>();
  const club = getClub(slug);
  const classes = getClubClasses(club?.slug);
  const parent = club?.parentSlug ? getClub(club.parentSlug) : undefined;
  const insets = useSafeAreaInsets();

  // Sprout pages swap the program menu for the skills framework and events,
  // exactly as the web club page does.
  const isSprout =
    club?.slug === "sprout" || (club?.slug.startsWith("sprout-") ?? false);
  // Skills always come from the backend catalog (bundled copy is its fallback).
  const { data: skillsCatalog, loading: skillsLoading } = useSkillsCatalog(
    club?.slug ?? "",
  );
  const clubSkills = skillsCatalog?.skills ?? [];

  // The club's year calendar, authored in the admin and served by the backend.
  // When it exists it replaces the pillar list, exactly like the web page.
  const { calendar } = useProgramCalendar(club?.slug ?? "");
  const calendarEntries = calendar?.entries ?? [];
  const hasCalendar = calendarEntries.length > 0;

  // The hero fills about half the screen — the rest is content, as on the web.
  const { width: winW, height: winH } = useWindowDimensions();
  // One skill card per row, edge to edge inside the padded body.
  const skillCardW = winW - 40;
  const heroH = useRef(0);
  const sectionY = useRef(0);
  const scrollRef = useRef<ScrollView>(null);
  const eventLoadId = useRef(0);

  const onHeroLayout = (e: LayoutChangeEvent) => {
    heroH.current = e.nativeEvent.layout.height;
  };
  const onSectionLayout = (e: LayoutChangeEvent) => {
    sectionY.current = e.nativeEvent.layout.y;
  };

  const openProgram = (name: string) => {
    router.push({
      pathname: "/clubs/[slug]/program" as any,
      params: { slug: club?.slug || "", program: name },
    });
  };

  const [events, setEvents] = useState<EventCard[]>([]);
  const [groups, setGroups] = useState<PrayerGroup[]>([]);
  const [loading, setLoading] = useState(true);

  // Session / permissions
  const [session, setSession] =
    useState<Awaited<ReturnType<typeof getSession>>>(null);
  // The signed-in user's latest club membership (for member-aware CTAs).
  const [membership, setMembership] = useState<ClubMembership | null>(null);
  // Sprout umbrella ↔ age-class aware: a Sprout Kids member is a member of
  // the Sprout parent page too (and vice versa for legacy "sprout" rows).
  const isMember = membershipCoversClub(membership, club?.slug ?? "");
  const memberEffectiveSlug = isMember ? effectiveClubSlug(membership) : "";
  // On the Sprout parent page the chip names the age class ("Sprout Tweens");
  // everywhere else it shows the Membership ID, as before.
  const memberChipLabel = !isMember
    ? ""
    : memberEffectiveSlug !== club?.slug
      ? (getClub(memberEffectiveSlug)?.name ?? membership?.reference ?? "")
      : (membership?.reference ?? "");
  // Members already hold a membership, so their hero action opens the club
  // chat instead of asking them to register again.
  const joinCtaLabel = isMember
    ? "Open club chat"
    : `Join ${club?.name ?? ""}`.trim();
  const userRole = session?.user?.role || "user";
  const isAdmin = userRole === "admin";
  const canManageGroups = isAdmin;

  // Modals
  const [regEvent, setRegEvent] = useState<ClubEvent | null>(null);
  const [detailEvent, setDetailEvent] = useState<ClubEvent | null>(null);
  const [editEvent, setEditEvent] = useState<ClubEvent | null>(null);
  // Card taps fetch the full event before a modal opens; this drives the
  // spinner so the tap always has visible feedback.
  const [openingEventId, setOpeningEventId] = useState<string | null>(null);
  const [showEventForm, setShowEventForm] = useState(false);
  const [showGroupForm, setShowGroupForm] = useState(false);
  const [showRegistration, setShowRegistration] = useState(false);
  // Which club's registration form the modal opens — the member's actual
  // Sprout class (Sprout Tweens etc.), not necessarily the page's club.
  const [regClubSlug, setRegClubSlug] = useState<string | null>(null);
  const [regPrefill, setRegPrefill] = useState<
    Record<string, string> | undefined
  >();
  const [sessionLoadingId, setSessionLoadingId] = useState<string | null>(null);
  const [participants, setParticipants] = useState<ClubRegistration[]>([]);

  const load = useCallback(async () => {
    if (!slug) return;
    const loadId = ++eventLoadId.current;
    const requestedSlug =
      (typeof slug === "string" ? slug : slug[0] ?? "")
        .trim()
        .toLowerCase();
    setEvents([]);
    try {
      const s = await getSession();
      setSession(s);
      if (s?.user) {
        try {
          const m = await clubJoinApi.me();
          setMembership(m?.data ?? null);
        } catch {
          setMembership(null);
        }
      } else {
        setMembership(null);
      }
      const [ev, gr] = await Promise.all([
        communityApi.getEventCards(requestedSlug),
        communityApi.getClubGroups(requestedSlug),
      ]);
      if (loadId !== eventLoadId.current) return;
      // The cards only render a title, a date badge and a place, so the list
      // asks for card fields. Tapping one fetches the full event.
      setEvents(
        ((ev.data || []) as EventCard[]).filter((e) =>
          typeof e.clubSlug === "string"
            ? e.clubSlug.trim().toLowerCase() === requestedSlug
            : false,
        ),
      );
      setGroups(gr.data || []);
    } catch {
      if (loadId !== eventLoadId.current) return;
      setEvents([]);
      setGroups([]);
    } finally {
      if (loadId === eventLoadId.current) setLoading(false);
    }
  }, [slug]);

  useEffect(() => {
    if (!canManageGroups || !slug) return;
    let active = true;
    communityApi
      .listClubRegistrations(slug)
      .then((res) => {
        if (active) setParticipants(res.data || []);
      })
      .catch(() => {
        if (active) setParticipants([]);
      });
    return () => {
      active = false;
    };
  }, [canManageGroups, slug]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load]),
  );

  if (!club) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <View style={styles.notFound}>
            <Ionicons
              name="alert-circle-outline"
              size={40}
              color={colors.muted}
            />
            <Text style={styles.notFoundText}>Club not found</Text>
            <TouchableOpacity
              style={styles.backBtn}
              onPress={() => {
                if (router.canDismiss?.()) router.dismiss();
                else router.replace("/(tabs)/community");
              }}
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Ionicons name="chevron-back" size={18} color={colors.white} />
              <Text style={styles.backBtnText}>All clubs</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const upcomingEvents = [...events].sort(
    (a, b) => eventStartMs(a) - eventStartMs(b),
  );

  // The registration modal opens the member's own club — e.g. Sprout Tweens
  // when they tapped through from the Sprout parent page.
  const regClub = getClub(regClubSlug ?? "") ?? club;

  const visibleParticipants = canManageGroups ? participants : [];

  const requireAuth = () => {
    Alert.alert("Sign in required", "Sign in to join groups and events.", [
      { text: "Cancel", style: "cancel" },
      { text: "Sign in", onPress: () => router.push("/login") },
    ]);
  };

  const openCall = (activeSession: GroupSession, groupName: string) => {
    if (IS_WEB) return;
    if (!activeSession?.roomUrl) {
      Alert.alert("Session unavailable", "This session has no room yet.");
      return;
    }
    router.push({
      pathname: "/call" as any,
      params: {
        roomUrl: activeSession.roomUrl,
        token: activeSession.token || "",
        userName: activeSession.startedByName || "Group member",
        type: activeSession.type,
        groupName,
        isOwner: activeSession.isOwner ? "1" : "0",
        accessCode: activeSession.accessCode || "",
        groupId: activeSession.sessionId?.split("-")[0] || "",
        startedAt: activeSession.startedAt
          ? String(new Date(activeSession.startedAt).getTime())
          : String(LOADED_AT_MS),
        durationMs: activeSession.durationMs
          ? String(activeSession.durationMs)
          : String(45 * 60 * 1000),
      },
    });
  };

  const startGroupCall = async (group: PrayerGroup) => {
    if (sessionLoadingId) return;
    if (!session?.user) return requireAuth();
    if (!canManageGroups) {
      Alert.alert(
        "Admins only",
        "Only admins can start group calls now. Ask a Relate admin to start one.",
      );
      return;
    }
    setSessionLoadingId(group._id);
    try {
      const res = await communityApi.startGroupSession(group._id, "audio");
      if (res?.data) {
        setGroups((gs) =>
          gs.map((g) =>
            g._id === group._id
              ? { ...g, live: true, activeSession: res.data }
              : g,
          ),
        );
        openCall(res.data, group.name);
      }
    } catch (err: any) {
      Alert.alert("Could not start call", err?.message || "Please try again.");
    } finally {
      setSessionLoadingId(null);
    }
  };

  const joinGroupCall = async (group: PrayerGroup, accessCode?: string) => {
    if (sessionLoadingId) return;
    if (!session?.user) return requireAuth();
    setSessionLoadingId(group._id);
    try {
      const res = await communityApi.joinGroupSession(group._id, accessCode);
      if (res?.data) {
        setGroups((gs) =>
          gs.map((g) =>
            g._id === group._id
              ? { ...g, live: true, activeSession: res.data }
              : g,
          ),
        );
        openCall(res.data, group.name);
      }
    } catch (err: any) {
      Alert.alert(
        "Could not join",
        err?.message || "The session may have ended.",
      );
    } finally {
      setSessionLoadingId(null);
    }
  };

  const endGroupCall = async (group: PrayerGroup) => {
    if (sessionLoadingId) return;
    setSessionLoadingId(group._id);
    try {
      await communityApi.endGroupSession(group._id);
      setGroups((gs) =>
        gs.map((g) =>
          g._id === group._id ? { ...g, live: false, activeSession: null } : g,
        ),
      );
    } catch {
      Alert.alert("Error", "Failed to end the session. Please try again.");
    } finally {
      setSessionLoadingId(null);
    }
  };

  const toggleGroupMembership = async (group: PrayerGroup) => {
    if (!session?.user) return requireAuth();
    try {
      const res = await communityApi.joinGroup(group._id);
      if (res?.data) {
        setGroups((gs) =>
          gs.map((g) =>
            g._id === group._id
              ? {
                  ...g,
                  hasJoined: res.data.hasJoined,
                  members: res.data.members,
                }
              : g,
          ),
        );
      }
    } catch {
      Alert.alert("Error", "Failed to update membership. Please try again.");
    }
  };

  const openEventDetail = async (card: EventCard) => {
    if (openingEventId) return;
    setOpeningEventId(card._id);
    try {
      const res = await communityApi.getEvent(card._id);
      setDetailEvent(toClubEvent(res.data));
    } catch (err: any) {
      Alert.alert(
        "Error",
        err?.message || "Couldn't open the event. Please try again.",
      );
    } finally {
      setOpeningEventId(null);
    }
  };

  const handleRsvp = async (
    eventId: string,
    details?: any,
  ): Promise<boolean> => {
    try {
      const res = await communityApi.rsvpEvent(eventId, details);
      if (res?.data) {
        // The cards don't show RSVP state, so only the open detail modal needs
        // the new attendance — otherwise its Join button stays stale.
        setDetailEvent((prev) =>
          prev && prev._id === eventId
            ? {
                ...prev,
                attending: res.data.attending,
                hasRsvpd: res.data.hasRsvpd,
              }
            : prev,
        );
        return true;
      }
      return false;
    } catch (err: any) {
      Alert.alert("Error", err?.message || "Failed to RSVP. Please try again.");
      return false;
    }
  };

  const deleteEvent = (event: ClubEvent) => {
    Alert.alert("Delete event", `Delete "${event.title}"?`, [
      { text: "Cancel", style: "cancel" },
      {
        text: "Delete",
        style: "destructive",
        onPress: async () => {
          try {
            await communityApi.deleteEvent(event._id);
            setEvents((evs) => evs.filter((e) => e._id !== event._id));
          } catch {
            Alert.alert("Error", "Failed to delete the event.");
          }
        },
      },
    ]);
  };

  const getInvolved = async () => {
    const s = await getSession();
    if (!s?.user) {
      router.push({
        pathname: "/login",
        params: { next: `/clubs/${club.slug}` },
      });
      return;
    }
    // Members go straight to the club's registration form; everyone else
    // starts the full join flow and earns a Membership ID first.
    try {
      const me = await clubJoinApi.me();
      if (me?.data && membershipCoversClub(me.data, club.slug)) {
        const theirClub = effectiveClubSlug(me.data);
        try {
          const reg = await communityApi.getMyClubRegistration(theirClub);
          setRegPrefill(reg.data?.answers);
        } catch {
          setRegPrefill(undefined);
        }
        setRegClubSlug(theirClub);
        setShowRegistration(true);
        return;
      }
    } catch {
      // membership check unavailable — the join screen re-checks on its own
    }
    router.push({ pathname: "/join", params: { slug: club.slug } });
  };

  // The weekly flagship — web's gradient card with the join action, sitting
  // above whatever follows: the pillar list, or the year calendar.
  const flagshipCard =
    club.programs[0] && !isSprout ? (
      <View
        style={[styles.flagship, { backgroundColor: club.colorDark }]}
      >
        <LinearGradient
          colors={[club.colorDark, colors.forestDark]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={StyleSheet.absoluteFill}
        />
        <View
          style={[styles.flagshipGlow, { backgroundColor: club.color }]}
        />
        <Text style={[styles.flagshipEyebrow, { color: club.color }]}>
          The weekly flagship
        </Text>
        <Text style={styles.flagshipTitle}>{club.programs[0].name}</Text>
        <Text style={styles.flagshipBlurb}>{club.programs[0].blurb}</Text>
        <TouchableOpacity
          style={styles.flagshipBtn}
          activeOpacity={0.9}
          onPress={getInvolved}
          accessibilityRole="button"
          accessibilityLabel={joinCtaLabel}
        >
          <Text style={styles.flagshipBtnText}>{joinCtaLabel}</Text>
        </TouchableOpacity>
      </View>
    ) : null;

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <StatusBar style="dark" />
        <ScrollView
          ref={scrollRef}
          contentContainerStyle={[
            styles.content,
            { paddingBottom: 40 + insets.bottom + 70 },
          ]}
          showsVerticalScrollIndicator={false}
        >
          <LinearGradient
            colors={[colors.forestDark, club.colorDark, club.color]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={[styles.hero, { minHeight: Math.round(winH * 0.5) }]}
            onLayout={onHeroLayout}
          >
            {club.heroImage ? (
              <Image
                source={{ uri: getOptimizedImageUrl(club.heroImage, 1200) }}
                style={StyleSheet.absoluteFill}
                contentFit="cover"
                transition={250}
              />
            ) : null}

            <View style={styles.heroTopRow}>
              <TouchableOpacity
                style={styles.heroBack}
                activeOpacity={0.85}
                onPress={() => {
                  if (router.canDismiss?.()) router.dismiss();
                  else router.replace("/(tabs)/community");
                }}
                accessibilityRole="button"
                accessibilityLabel="Back to clubs"
              >
                <Ionicons name="chevron-back" size={20} color={colors.white} />
              </TouchableOpacity>
            </View>

            <View style={styles.heroCenter}>
              {isMember ? (
                <View style={styles.memberChip}>
                  <Ionicons
                    name="checkmark-circle"
                    size={13}
                    color={colors.forestDark}
                  />
                  <Text style={styles.memberChipText}>
                    Member
                    {memberChipLabel ? ` · ${memberChipLabel}` : ""}
                  </Text>
                </View>
              ) : null}
              <Text style={styles.heroTitle}>{club.name}</Text>
              <Text
                style={[
                  styles.heroTagline,
                  {
                    color:
                      club.heroImage ||
                      [
                        "prime",
                        "surge",
                        "spark",
                        "anchor",
                        "pulse",
                        "sprout",
                      ].includes(club.slug)
                        ? colors.white
                        : club.color,
                  },
                ]}
              >
                {club.tagline}
              </Text>

              <View style={styles.heroActions}>
                <TouchableOpacity
                  style={styles.heroJoin}
                  activeOpacity={0.9}
                  onPress={
                    isMember
                      ? () => router.push("/club-chat" as any)
                      : getInvolved
                  }
                  accessibilityRole="button"
                  accessibilityLabel={joinCtaLabel}
                >
                  <Text style={styles.heroJoinText}>{joinCtaLabel}</Text>
                  <Ionicons
                    name="arrow-forward"
                    size={16}
                    color={colors.forestDark}
                  />
                </TouchableOpacity>
              </View>

              <View style={styles.heroDivider} />

              <View style={styles.heroMetaBar}>
                <View style={[styles.heroMetaItem, styles.heroMetaAgeItem]}>
                  <Text style={styles.heroMetaAgeLabel}>Age</Text>
                  <Text style={styles.heroMetaAgeValue}>{club.ageRange}</Text>
                </View>
                {[
                  { label: "Group", value: club.group },
                  ...(isSprout
                    ? [{ label: "Skills", value: String(clubSkills.length) }]
                    : club.programs.length > 0
                      ? [
                          {
                            label: "Programs",
                            value: String(club.programs.length),
                          },
                        ]
                      : []),
                ].map((m) => (
                  <View key={m.label} style={styles.heroMetaItem}>
                    <Text style={styles.heroMetaLabel}>{m.label}</Text>
                    <Text style={styles.heroMetaValue}>{m.value}</Text>
                  </View>
                ))}
              </View>

              {parent ? (
                <TouchableOpacity
                  style={styles.heroParent}
                  activeOpacity={0.8}
                  onPress={() => router.push(`/clubs/${parent.slug}`)}
                  accessibilityRole="link"
                  accessibilityLabel={`Part of ${parent.name}`}
                >
                  <Text style={styles.heroParentLabel}>Part of</Text>
                  <Text style={styles.heroParentName}>{parent.name} ←</Text>
                </TouchableOpacity>
              ) : null}
            </View>
          </LinearGradient>

          <View style={styles.body}>
            {(() => {
              if (!club.slug.startsWith("sprout")) return null;
              const target = sproutTargetForClub(club.slug);
              if (!target) return null;
              return (
                <LinearGradient
                  colors={["#101218", "#24262e", "#0b0d11"]}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 1 }}
                  style={styles.savingsBanner}
                >
                  <View style={styles.savingsBannerGlow} />
                  <View style={styles.savingsBannerHead}>
                    <Text style={styles.savingsBannerEyebrow}>
                      SMART SAVER FUND
                    </Text>
                    <View style={styles.savingsBannerMc}>
                      <View style={styles.savingsBannerMcRed} />
                      <View style={styles.savingsBannerMcYellow} />
                    </View>
                  </View>

                  <View style={styles.savingsBannerMid}>
                    <LinearGradient
                      colors={["#efd27f", "#b98f2f"]}
                      start={{ x: 0, y: 0 }}
                      end={{ x: 1, y: 1 }}
                      style={styles.savingsBannerChip}
                    >
                      <View style={styles.savingsBannerChipLine} />
                    </LinearGradient>
                    <View style={styles.savingsBannerTag}>
                      <Text style={styles.savingsBannerTagText}>60 / 40</Text>
                    </View>
                  </View>

                  <Text style={styles.savingsBannerTitle}>
                    {target.annualMin === target.annualMax
                      ? `R${target.annualMin.toLocaleString("en-ZA")}`
                      : `R${target.annualMin.toLocaleString("en-ZA")}–R${target.annualMax.toLocaleString("en-ZA")}`}
                    <Text style={styles.savingsBannerUnit}> / year</Text>
                  </Text>
                  <Text style={styles.savingsBannerSub}>
                    The {target.name} savings target — 60% locked in Smart Saver, 40% in
                    your spendable wallet.
                  </Text>
                  <View style={styles.savingsBannerFoot}>
                    <TouchableOpacity
                      style={styles.savingsBannerBtn}
                      onPress={() => router.push("/savings" as any)}
                      activeOpacity={0.9}
                      accessibilityRole="button"
                      accessibilityLabel="Open the Smart Saver app"
                    >
                      <Text style={styles.savingsBannerBtnText}>Open Smart Saver</Text>
                      <Ionicons name="arrow-forward" size={15} color={colors.forestDark} />
                    </TouchableOpacity>
                    <Text style={styles.savingsBannerWordmark}>mastercard</Text>
                  </View>
                </LinearGradient>
              );
            })()}

            {/* ── Age groups (web: "Age groups" list on a parent club) ── */}
            {classes.length > 0 ? (
              <>
                <View style={styles.sectionHead}>
                  <View style={styles.sectionHeadText}>
                    <Text style={styles.sectionEyebrow}>Age groups</Text>
                    <Text style={styles.sectionTitle}>
                      {club.name} runs in{" "}
                      {AGE_WORDS[classes.length] ?? classes.length} age{" "}
                      {classes.length === 1 ? "group" : "groups"}
                    </Text>
                    <Text style={styles.sectionSub}>
                      Pick the band that fits your child — each has its own
                      leaders, rhythm and weekly program.
                    </Text>
                  </View>
                </View>
                <View style={styles.ageList}>
                  {classes.map((c) => {
                    // Which Sprout class this member actually belongs to.
                    const mine = isMember && memberEffectiveSlug === c.slug;
                    const compactAge = c.ageRange
                      .split(" yrs")[0]
                      .trim()
                      .replace(/\s*[–-]\s*/g, "–");
                    return (
                      <TouchableOpacity
                        key={c.slug}
                        style={[styles.ageRow, mine && styles.ageRowMine]}
                        activeOpacity={0.75}
                        onPress={() => router.push(`/clubs/${c.slug}`)}
                        accessibilityRole="button"
                        accessibilityLabel={`Open ${c.name}`}
                      >
                        <View
                          style={[
                            styles.ageBadge,
                            { backgroundColor: `${c.color}14` },
                          ]}
                        >
                          <Text
                            style={[styles.ageNumber, { color: c.color }]}
                            numberOfLines={1}
                          >
                            {compactAge}
                          </Text>
                          <Text style={[styles.ageUnit, { color: c.color }]}>
                            YRS
                          </Text>
                        </View>
                        <View style={styles.ageBody}>
                          <Text style={styles.ageName} numberOfLines={1}>
                            {c.name}
                          </Text>
                          <Text style={styles.ageTagline} numberOfLines={2}>
                            {c.tagline}
                          </Text>
                        </View>
                        {mine ? (
                          <View style={styles.ageYouBadge}>
                            <Ionicons
                              name="checkmark-circle"
                              size={12}
                              color={colors.white}
                            />
                            <Text style={styles.ageYouText}>Registered</Text>
                          </View>
                        ) : (
                          <View style={styles.ageChevron}>
                            <Ionicons
                              name="chevron-forward"
                              size={15}
                              color={colors.goldDark}
                            />
                          </View>
                        )}
                      </TouchableOpacity>
                    );
                  })}
                </View>
              </>
            ) : null}

            {/* ── Our teams (per-club sports rail) ── */}
            {teamsForClub(club.slug).length > 0 ? (
              <>
                <View style={[styles.sectionHead, styles.sectionGap]}>
                  <View style={styles.sectionHeadText}>
                    <Text style={styles.sectionEyebrow}>Our teams</Text>
                    <Text style={styles.sectionTitle}>
                      Play for {club.name}
                    </Text>
                    <Text style={styles.sectionSub}>
                      {teamsForClub(club.slug).length}{" "}
                      {teamsForClub(club.slug).length === 1 ? "team" : "teams"}{" "}
                      in the Relate sports league — training midweek, matches at
                      the weekend.
                    </Text>
                  </View>
                  <TouchableOpacity
                    onPress={() => router.push("/sports" as any)}
                    style={styles.sportViewAll}
                    activeOpacity={0.7}
                  >
                    <Text style={styles.sportViewAllText}>All teams</Text>
                    <Ionicons
                      name="chevron-forward"
                      size={14}
                      color={colors.goldDark}
                    />
                  </TouchableOpacity>
                </View>
                <ScrollView
                  horizontal
                  showsHorizontalScrollIndicator={false}
                  contentContainerStyle={styles.sportRail}
                >
                  {teamsForClub(club.slug).map((team) => {
                    return (
                      <TouchableOpacity
                        key={team.id}
                        style={styles.sportCard}
                        activeOpacity={0.88}
                        onPress={() =>
                          router.push({
                            pathname: "/sports/[teamId]" as any,
                            params: { teamId: team.id },
                          })
                        }
                        accessibilityLabel={`${team.name} — view team`}
                      >
                        <View style={styles.sportCardHead}>
                          <TeamCrest team={team} size={112} />
                        </View>
                      </TouchableOpacity>
                    );
                  })}
                </ScrollView>
              </>
            ) : null}

            {/* ── Events ── */}
            <View
              style={[styles.sectionHead, styles.sectionGap]}
              onLayout={isSprout ? onSectionLayout : undefined}
            >
              <View style={styles.sectionHeadText}>
                <Text style={styles.sectionEyebrow}>Events</Text>
                <Text style={styles.sectionTitle}>Upcoming Events</Text>
                <Text style={styles.sectionSub}>
                  One-off dates you can join — inside and outside the club.
                </Text>
              </View>
              {isAdmin ? (
                <TouchableOpacity
                  style={styles.addBtn}
                  activeOpacity={0.8}
                  onPress={() => setShowEventForm(true)}
                  accessibilityLabel="Create event"
                >
                  <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                  <Ionicons name="add" size={16} color={colors.white} />
                  <Text style={styles.addBtnText}>Create</Text>
                </TouchableOpacity>
              ) : null}
            </View>
            {loading ? (
              <View style={styles.cardList} accessibilityLabel="Loading events">
                {[0, 1].map((i) => (
                  <ClubEventCardSkeleton key={i} />
                ))}
              </View>
            ) : upcomingEvents.length > 0 ? (
              <View style={styles.cardList}>
                {upcomingEvents.map((e) => (
                  <ClubEventCard
                    key={e._id}
                    event={e}
                    onPress={() => openEventDetail(e)}
                  />
                ))}
              </View>
            ) : (
              <EmptyState
                compact
                icon="calendar-outline"
                color={club.color}
                eyebrow="Events"
                title="No events yet"
                subtitle={
                  isAdmin
                    ? "Be the first to add one — tap Create to host an event for the club."
                    : "Check back soon for upcoming dates."
                }
                actionLabel={isAdmin ? "Create event" : undefined}
                onAction={isAdmin ? () => setShowEventForm(true) : undefined}
              />
            )}

            {!club.parentSlug && classes.length === 0 ? (
              <>
                {/* ── Groups ── */}
                <View style={[styles.sectionHead, styles.sectionGap]}>
                  <View style={styles.sectionHeadText}>
                    <Text style={styles.sectionEyebrow}>Groups</Text>
                    <Text style={styles.sectionTitle}>Community Groups</Text>
                    <Text style={styles.sectionSub}>
                      Small circles inside {club.name} — chat, meet up and grow
                      together.
                    </Text>
                  </View>
                  {canManageGroups ? (
                    <TouchableOpacity
                      style={styles.addBtn}
                      activeOpacity={0.8}
                      onPress={() => setShowGroupForm(true)}
                      accessibilityLabel="Create group"
                    >
                      <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                      <Ionicons name="add" size={16} color={colors.white} />
                      <Text style={styles.addBtnText}>Create</Text>
                    </TouchableOpacity>
                  ) : null}
                </View>
                {loading ? (
                  <View
                    style={styles.cardList}
                    accessibilityLabel="Loading groups"
                  >
                    {[0, 1, 2].map((i) => (
                      <GroupCardSkeleton key={i} />
                    ))}
                  </View>
                ) : groups.length > 0 ? (
                  <View style={styles.cardList}>
                    {groups.map((g) => (
                      <View key={g._id} style={styles.groupCard}>
                        <View style={styles.groupCardTop}>
                          <View
                            style={[
                              styles.groupIcon,
                              { backgroundColor: `${club.color}22` },
                            ]}
                          >
                            {g.imageUrl ? (
                              <Image
                                source={{ uri: getOptimizedImageUrl(g.imageUrl, 720) }}
                                style={styles.groupIconImg}
                                contentFit="cover"
                                transition={250}
                              />
                            ) : (
                              <Ionicons
                                name="people-outline"
                                size={16}
                                color={club.colorDark}
                              />
                            )}
                          </View>
                          <View style={styles.groupBody}>
                            <Text style={styles.cardTitle}>{g.name}</Text>
                            <Text style={styles.cardSub} numberOfLines={1}>
                              {[
                                g.meetingTime,
                                g.members ? `${g.members} members` : null,
                              ]
                                .filter(Boolean)
                                .join(" · ") || "Join the conversation"}
                            </Text>
                          </View>
                          {!IS_WEB && g.live && g.activeSession ? (
                            <TouchableOpacity
                              style={styles.liveBtn}
                              onPress={() =>
                                g.isOwner
                                  ? openCall(g.activeSession!, g.name)
                                  : joinGroupCall(g)
                              }
                              activeOpacity={0.85}
                            >
                              <View style={styles.liveDot} />
                              <Text style={styles.liveBtnText}>LIVE</Text>
                            </TouchableOpacity>
                          ) : !IS_WEB && (g.isOwner || canManageGroups) ? (
                            <TouchableOpacity
                              style={styles.callBtn}
                              onPress={() => startGroupCall(g)}
                              disabled={sessionLoadingId === g._id}
                              activeOpacity={0.85}
                              accessibilityLabel="Start group call"
                            >
                              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                              {sessionLoadingId === g._id ? (
                                <ActivityIndicator
                                  size="small"
                                  color={colors.white}
                                />
                              ) : (
                                <Ionicons
                                  name="call"
                                  size={16}
                                  color={colors.white}
                                />
                              )}
                            </TouchableOpacity>
                          ) : (
                            <TouchableOpacity
                              style={styles.joinBtn}
                              onPress={() => toggleGroupMembership(g)}
                              activeOpacity={0.85}
                            >
                              <Text style={styles.joinBtnText}>
                                {g.hasJoined ? "LEAVE" : "JOIN"}
                              </Text>
                            </TouchableOpacity>
                          )}
                        </View>
                        {g.live && g.isOwner ? (
                          <View style={styles.groupHostRow}>
                            {g.activeSession?.accessCode ? (
                              <Text style={styles.groupCode} numberOfLines={1}>
                                Code {g.activeSession.accessCode}
                              </Text>
                            ) : null}
                            <View style={{ flex: 1 }} />
                            <TouchableOpacity
                              onPress={() => endGroupCall(g)}
                              style={styles.endBtn}
                              disabled={sessionLoadingId === g._id}
                            >
                              <Ionicons
                                name="stop-circle-outline"
                                size={14}
                                color={colors.white}
                              />
                              <Text style={styles.endBtnText}>End</Text>
                            </TouchableOpacity>
                          </View>
                        ) : null}
                      </View>
                    ))}
                  </View>
                ) : (
                  <EmptyState
                    compact
                    icon="people-outline"
                    color={club.color}
                    eyebrow="Groups"
                    title="No groups yet"
                    subtitle={
                      canManageGroups
                        ? "Start a small circle — prayer, skills, discussion or support."
                        : "Check back soon for new groups."
                    }
                    actionLabel={canManageGroups ? "Create group" : undefined}
                    onAction={
                      canManageGroups ? () => setShowGroupForm(true) : undefined
                    }
                  />
                )}
              </>
            ) : null}

            {/* ── Participants (admin roster) ── */}
            {visibleParticipants.length > 0 ? (
              <>
                <View style={[styles.sectionHead, styles.sectionGap]}>
                  <View style={styles.sectionHeadText}>
                    <Text style={styles.sectionEyebrow}>Roster</Text>
                    <Text style={styles.sectionTitle}>Participants</Text>
                    <Text style={styles.sectionSub}>
                      People signed up to {club.name} so far this month.
                    </Text>
                  </View>
                  <Text style={styles.participantCount}>
                    {visibleParticipants.length}
                  </Text>
                </View>
                <View style={styles.cardList}>
                  {visibleParticipants.map((p) => (
                    <View key={p._id} style={styles.participantRow}>
                      <View
                        style={[
                          styles.programIcon,
                          { backgroundColor: `${club.color}22` },
                        ]}
                      >
                        <Ionicons
                          name="person-outline"
                          size={16}
                          color={club.colorDark}
                        />
                      </View>
                      <View style={styles.programBody}>
                        <Text style={styles.programName}>{p.name}</Text>
                        <Text style={styles.participantMeta}>
                          {[
                            p.answers?.childName,
                            p.answers?.childAge,
                            p.answers?.activity,
                          ]
                            .filter(Boolean)
                            .join(" · ") ||
                            p.answers?.parentName ||
                            "Registered"}
                        </Text>
                      </View>
                      <Text style={styles.participantDate}>
                        {formatRegDate(p.createdAt)}
                      </Text>
                    </View>
                  ))}
                </View>
              </>
            ) : null}

            {/* ── Skills framework (backend catalog) ── */}
            {skillsLoading && !skillsCatalog ? (
              <View style={styles.skillsLoading}>
                <ActivityIndicator color={club.color} />
              </View>
            ) : clubSkills.length > 0 ? (
              <>
                <View style={[styles.sectionHead, styles.sectionGap]}>
                  <View style={styles.sectionHeadText}>
                    <Text style={styles.sectionEyebrow}>
                      Skills &amp; growth
                    </Text>
                    <Text style={styles.sectionTitle}>{club.name} Skills</Text>
                    <Text style={styles.sectionSub}>
                      {clubSkills.length} skills across {club.name} — build real
                      skills, track your progress, earn recognition.
                    </Text>
                  </View>
                </View>

                <View style={styles.skillsGrid}>
                  {clubSkills.slice(0, 6).map((skill) => (
                    <SkillCard
                      key={skill.id}
                      skill={skill}
                      club={skillsCatalog!}
                      width={skillCardW}
                      onPress={() =>
                        router.push(`/skills/${club.slug}/${skill.id}`)
                      }
                      accessibilityLabel={`${skill.name} — view skill`}
                    />
                  ))}
                </View>

                <TouchableOpacity
                  style={styles.honorAllLink}
                  activeOpacity={0.8}
                  onPress={() => router.push(`/skills/${club.slug}`)}
                  accessibilityRole="link"
                  accessibilityLabel={`See all ${club.name} skills`}
                >
                  <Text style={styles.honorAllLinkText}>All skills</Text>
                  <Ionicons
                    name="arrow-forward"
                    size={14}
                    color={colors.goldDark}
                  />
                </TouchableOpacity>
              </>
            ) : !hasCalendar && club.programs.length > 0 ? (
              <>
                {/* ── Programs & Activities ── */}
                <View
                  style={[styles.sectionHead, styles.sectionGap]}
                  onLayout={isSprout ? undefined : onSectionLayout}
                >
                  <View style={styles.sectionHeadText}>
                    <Text style={styles.sectionEyebrow}>What happens here</Text>
                    <Text style={styles.sectionTitle}>
                      Programs &amp; Activities
                    </Text>
                    <Text style={styles.sectionSub}>
                      {club.programs.length}{" "}
                      {club.programs.length === 1 ? "program" : "programs"} for{" "}
                      {club.group.toLowerCase()} — the weekly flagship first,
                      then everything grouped under Shift, Sanctuary and
                      Connect.
                    </Text>
                  </View>
                </View>

                {/* The weekly flagship — web's gradient card with the join action. */}
                {flagshipCard}

                {programsByPillar(club).map((group) => {
                  const items = group.programs.filter(
                    (p) => p !== club.programs[0],
                  );
                  if (items.length === 0) return null;
                  return (
                    <View key={group.pillar ?? "all"}>
                      <Text style={styles.moreLabel}>
                        {group.pillar
                          ? group.pillar +
                            (group.label ? ` · ${group.label}` : "")
                          : "More ways to be involved"}
                      </Text>
                      <View style={styles.moreList}>
                        {items.map((p) => (
                          <TouchableOpacity
                            key={p.name}
                            style={styles.moreRow}
                            activeOpacity={0.7}
                            onPress={() => openProgram(p.name)}
                            accessibilityRole="button"
                            accessibilityLabel={`${p.name} — view details`}
                          >
                            {p.image ? (
                              <Image
                                source={{ uri: getOptimizedImageUrl(p.image, 720) }}
                                style={styles.moreThumb}
                                contentFit="cover"
                                transition={200}
                              />
                            ) : (
                              <View
                                style={[
                                  styles.moreDot,
                                  { backgroundColor: club.color },
                                ]}
                              />
                            )}
                            <View style={styles.moreBody}>
                              <Text style={styles.moreName} numberOfLines={1}>
                                {p.name}
                              </Text>
                              <Text style={styles.moreBlurb} numberOfLines={2}>
                                {p.blurb}
                              </Text>
                            </View>
                          </TouchableOpacity>
                        ))}
                      </View>
                    </View>
                  );
                })}
              </>
            ) : null}

            {/* ── Mission & vision — web's two-up cards ── */}
            {club.mission || club.vision ? (
              <View style={[styles.missionGrid, styles.sectionGap]}>
                {club.mission ? (
                  <View style={styles.missionCard}>
                    <Text style={[styles.missionKicker, { color: club.color }]}>
                      MISSION
                    </Text>
                    <Text style={styles.missionText}>{club.mission}</Text>
                  </View>
                ) : null}
                {club.vision ? (
                  <View style={styles.missionCard}>
                    <Text style={[styles.missionKicker, { color: club.color }]}>
                      VISION
                    </Text>
                    <Text style={styles.missionText}>{club.vision}</Text>
                  </View>
                ) : null}
              </View>
            ) : null}

            {/* ── Program calendar — the year plan, authored in the admin ── */}
            {hasCalendar ? (
              <>
                <View
                  style={[styles.sectionHead, styles.sectionGap]}
                  onLayout={isSprout ? undefined : onSectionLayout}
                >
                  <View style={styles.sectionHeadText}>
                    <Text style={styles.sectionEyebrow}>What happens here</Text>
                    <Text style={styles.sectionTitle}>
                      Programs &amp; Activities
                    </Text>
                    <Text style={styles.sectionSub}>
                      Every date for {club.name} in {calendar?.year} — tap a
                      date to see what happens.
                    </Text>
                  </View>
                </View>

                {flagshipCard}

                <ProgramCalendar
                  entries={calendarEntries}
                  year={calendar?.year ?? 0}
                  clubColor={club.color}
                />
              </>
            ) : null}

          </View>
        </ScrollView>

        {/* Card tap is fetching the full event before the detail modal opens. */}
        {openingEventId ? (
          <View style={styles.eventFetchOverlay} pointerEvents="auto">
            <ActivityIndicator size="large" color={club.color} />
          </View>
        ) : null}

        {/* Event detail (RSVP, payments, admin edit/delete) — reused component */}
        {detailEvent ? (
          <EventDetailModal
            event={detailEvent}
            currentUserId={session?.user?.id || null}
            onClose={() => setDetailEvent(null)}
            joinLoading={false}
            onJoin={() => {
              if (!session?.user) return requireAuth();
              if (detailEvent.hasRsvpd) {
                handleRsvp(detailEvent._id);
              } else {
                setDetailEvent(null);
                setRegEvent(detailEvent);
              }
            }}
            onEdit={() => {
              setDetailEvent(null);
              setEditEvent(detailEvent);
              setShowEventForm(true);
            }}
            onDelete={() => {
              setDetailEvent(null);
              deleteEvent(detailEvent);
            }}
          />
        ) : null}

        {/* Registration modal (RSVP details) — reused component */}
        {regEvent ? (
          <EventRegistrationModal
            key={regEvent._id}
            event={regEvent}
            onClose={() => setRegEvent(null)}
            onSubmit={(details) => handleRsvp(regEvent._id, details)}
          />
        ) : null}

        {/* Admin event create/edit */}
        <ClubEventFormModal
          visible={showEventForm}
          club={club}
          editing={editEvent}
          onClose={() => {
            setShowEventForm(false);
            setEditEvent(null);
          }}
          onSaved={load}
        />

        {/* Admin group create */}
        <ClubGroupFormModal
          visible={showGroupForm}
          club={club}
          onClose={() => setShowGroupForm(false)}
          onSaved={load}
        />

        {/* Unique club registration form */}
        {showRegistration ? (
          <ClubRegistrationModal
            club={regClub}
            initialAnswers={regPrefill}
            onClose={() => setShowRegistration(false)}
          />
        ) : null}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

export default ClubScreen;

