import ModuleTracker from "@/components/skills/ModuleTracker";
import SkillProgressCard from "@/components/skills/SkillProgressCard";
import { getClub } from "@/constants/clubs";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { clubJoinApi, membershipCoversClub } from "@/services/club-join";
import { useSkillsCatalog } from "@/services/skills-catalog";
import { Ionicons } from "@expo/vector-icons";
import { Image } from "expo-image";
import { LinearGradient } from "expo-linear-gradient";
import { router, useLocalSearchParams } from "expo-router";
import { StatusBar } from "expo-status-bar";
import { useEffect, useState } from "react";
import {
  ActivityIndicator,
  Linking,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaProvider, SafeAreaView } from "react-native-safe-area-context";
import { getOptimizedImageUrl } from "@/services/cloudinary";
import { GradientBox } from "@/constants/gradients";

/** One skill: what it is, levels, and where it's earned. */
export default function SkillDetailScreen() {
  const { club: clubParam, skill: skillParam, id } = useLocalSearchParams<{
    club?: string;
    skill?: string;
    id?: string;
  }>();
  const clubSlug = clubParam || "surge";
  // Route segment is [skill]; `id` is kept for older links that carried ?id=.
  const skillId = String(skillParam || id || "");
  // Backend catalog is the source of truth (sprout skills live only there).
  const { data: catalog, loading } = useSkillsCatalog(clubSlug);
  const club = getClub(clubSlug);
  const whatsapp = club?.whatsappGroupLink;

  // Membership of this skill's club — drives the join card at the bottom
  // (null while we don't know yet, so members never see "Not a member?").
  const [isMember, setIsMember] = useState<boolean | null>(null);
  useEffect(() => {
    let active = true;
    clubJoinApi
      .me()
      .then((m) => {
        if (!active) return;
        setIsMember(membershipCoversClub(m?.data, clubSlug));
      })
      .catch(() => {
        if (active) setIsMember(false);
      });
    return () => {
      active = false;
    };
  }, [clubSlug]);

  if (loading) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={d.safe} edges={["top"]}>
          <View style={d.notFound}>
            <ActivityIndicator color={colors.forest} />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const skill = catalog?.getSkill(skillId);
  const clubName = catalog?.clubName || club?.name || "Skills";
  const clubColor = catalog?.clubColor || club?.color;
  const clubColorDark = catalog?.clubColorDark || club?.colorDark;
  if (!skill) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={d.safe} edges={["top"]}>
          <View style={d.notFound}>
            <Ionicons
              name="alert-circle-outline"
              size={40}
              color={colors.muted}
            />
            <Text style={d.notFoundText}>Skill not found</Text>
            <TouchableOpacity style={d.backBtn} onPress={() => router.back()}>
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Ionicons name="chevron-back" size={18} color={colors.white} />
              <Text style={d.backBtnText}>Go back</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const highestLevel = skill.levels[skill.levels.length - 1];
  const level1 = skill.levels[0];
  const detail = skill.detail;
  const requirementCount = (
    skill.requirements?.length
      ? skill.requirements
      : level1?.requirements ?? []
  ).reduce((sum, req) => sum + req.criteria.length, 0);
  const gradient = skill.image
    ? (["#0b0c0f", "#08090b"] as const)
    : ([
        level1?.color || clubColor || "#1d2a4d",
        level1?.colorDark || clubColorDark || "#151f3a",
      ] as const);

  const askLeader = () => {
    if (whatsapp) Linking.openURL(whatsapp).catch(() => {});
  };

  const openCourse = () => {
    if (detail?.learningUrl) Linking.openURL(detail.learningUrl).catch(() => {});
  };

  const chips = (items: string[]) => (
    <View style={d.chipRow}>
      {items.map((item) => (
        <View key={item} style={d.chip}>
          <Text style={d.chipText}>{item}</Text>
        </View>
      ))}
    </View>
  );

  return (
    <SafeAreaProvider>
      <SafeAreaView style={d.safe} edges={["top"]}>
        <StatusBar style="dark" />
        <ScrollView
          contentContainerStyle={d.content}
          showsVerticalScrollIndicator={false}
        >
          <LinearGradient
            colors={gradient}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={d.hero}
          >
            {skill.image ? (
              <Image
                source={{ uri: getOptimizedImageUrl(skill.image, 720) }}
                style={StyleSheet.absoluteFill}
                contentFit="cover"
                transition={200}
                accessibilityIgnoresInvertColors
              />
            ) : null}
            {skill.image ? (
              <LinearGradient
                colors={["rgba(8,9,11,0.5)", "rgba(8,9,11,0.45)"]}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={StyleSheet.absoluteFill}
              />
            ) : null}
            <View
              style={[
                d.heroGlow,
                { backgroundColor: level1?.color || clubColor || "#1d2a4d" },
              ]}
              pointerEvents="none"
            />

            {skill.type ? (
              <View
                style={[
                  d.typePill,
                  skill.type === "Compulsory" && d.typePillSolid,
                ]}
              >
                <Text
                  style={[
                    d.typePillText,
                    skill.type === "Compulsory" && d.typePillTextSolid,
                  ]}
                >
                  {skill.type}
                </Text>
              </View>
            ) : null}

            <Text style={d.heroTitle}>{skill.name}</Text>
            <Text style={d.heroDesc}>{skill.description}</Text>

            <View style={d.metaGrid}>
              {[
                { label: "Club", value: clubName || skill.id },
                ...(skill.type
                  ? [{ label: "Type", value: skill.type }]
                  : []),
                { label: "Requirements", value: String(requirementCount) },
                { label: "Levels", value: String(skill.levels.length) },
                {
                  label: "Highest",
                  value: highestLevel
                    ? `L${highestLevel.levelNumber}: ${highestLevel.name}`
                    : "—",
                },
              ].map((item) => (
                <View key={item.label} style={d.metaItem}>
                  <Text style={d.metaLabel}>{item.label}</Text>
                  <Text style={d.metaValue} numberOfLines={2}>
                    {item.value}
                  </Text>
                </View>
              ))}
            </View>

            <View style={d.heroActions}>
              <TouchableOpacity
                activeOpacity={0.9}
                style={d.heroPrimary}
                onPress={() => router.push(`/clubs/${clubSlug}` as any)}
                accessibilityRole="button"
                accessibilityLabel={`Back to ${clubName || "club"}`}
              >
                <Text style={d.heroPrimaryText}>
                  {clubName || "Club"}
                </Text>
                <Ionicons
                  name="arrow-forward"
                  size={15}
                  color={colors.forest}
                />
              </TouchableOpacity>
              <TouchableOpacity
                activeOpacity={0.9}
                style={d.heroSecondary}
                onPress={() => router.push(`/skills/${clubSlug}` as any)}
                accessibilityRole="button"
                accessibilityLabel={`All ${clubName || "club"} skills`}
              >
                <Text style={d.heroSecondaryText}>All skills</Text>
              </TouchableOpacity>
            </View>
          </LinearGradient>

          <View style={d.body}>
            <View style={d.card}>
              <Text style={[d.cardKicker, { color: level1?.colorDark || clubColorDark || "#1d2a4d" }]}>
                About this skill
              </Text>
              <Text style={d.cardTitle}>{skill.name}</Text>
              <Text style={d.cardText}>{skill.description}</Text>
              <View style={d.cardDivider}>
                <Text style={d.cardFocus}>
                  <Text style={d.strong}>{clubName || "Club"}</Text> —{" "}
                  {club?.ageRange || "All ages"}
                </Text>
              </View>
              <Text style={d.cardShape}>
                {skill.modules?.length
                  ? `${skill.modules.length} modules`
                  : `${skill.levels.length} levels`}{" "}
                · Icon: {skill.icon}
              </Text>
            </View>

            <View style={d.card}>
              <Text style={[d.cardKicker, { color: level1?.colorDark || clubColorDark || "#1d2a4d" }]}>
                Where it&rsquo;s earned
              </Text>
              <Text style={d.cardText}>
                Skills are worked on during {clubName || "club"} sessions and
                proven in front of a leader who signs each requirement off.
              </Text>
              <View style={d.linkRow}>
                <TouchableOpacity
                  activeOpacity={0.85}
                  style={d.linkBtn}
                  onPress={() => router.push(`/skills/${clubSlug}`)}
                >
                  <Text style={d.linkBtnText}>
                    {clubName || "Skills"} page →
                  </Text>
                </TouchableOpacity>
                {whatsapp ? (
                  <TouchableOpacity
                    activeOpacity={0.85}
                    style={d.linkBtn}
                    onPress={askLeader}
                  >
                    <Ionicons
                      name="logo-whatsapp"
                      size={14}
                      color={colors.goldDark}
                    />
                    <Text style={d.linkBtnText}>Ask a leader →</Text>
                  </TouchableOpacity>
                ) : null}
              </View>
            </View>

            {detail?.tools?.length ? (
              <View style={d.card}>
                <Text style={[d.cardKicker, { color: level1?.colorDark || clubColorDark || "#1d2a4d" }]}>
                  Tools
                </Text>
                {chips(detail.tools)}
              </View>
            ) : null}

            {detail?.appFeatures?.length ? (
              <View style={d.card}>
                <Text style={[d.cardKicker, { color: level1?.colorDark || clubColorDark || "#1d2a4d" }]}>
                  In the app
                </Text>
                {chips(detail.appFeatures)}
              </View>
            ) : null}

            {skill.output ? (
              <View style={d.outputCallout}>
                <Text style={d.outputKicker}>YOU WALK AWAY WITH</Text>
                <Text style={d.outputText}>{skill.output}</Text>
              </View>
            ) : null}

            {detail?.pathways &&
            (detail.pathways.sproutGraduate || detail.pathways.directEntrant) ? (
              <View style={d.card}>
                <Text style={[d.cardKicker, { color: level1?.colorDark || clubColorDark || "#1d2a4d" }]}>
                  Your pathway
                </Text>
                {detail.pathways.sproutGraduate ? (
                  <View style={d.pathwayRow}>
                    <Text style={d.pathwayLabel}>Sprout graduate</Text>
                    <Text style={d.pathwayValue}>
                      {detail.pathways.sproutGraduate}
                    </Text>
                  </View>
                ) : null}
                {detail.pathways.directEntrant ? (
                  <View style={d.pathwayRow}>
                    <Text style={d.pathwayLabel}>Direct entrant</Text>
                    <Text style={d.pathwayValue}>
                      {detail.pathways.directEntrant}
                    </Text>
                  </View>
                ) : null}
              </View>
            ) : null}

            {detail?.learningProvider ? (
              <View style={d.card}>
                <Text style={[d.cardKicker, { color: level1?.colorDark || clubColorDark || "#1d2a4d" }]}>
                  Learning tracker
                </Text>
                <Text style={d.cardText}>{detail.learningProvider}</Text>
                {detail.learningUrl ? (
                  <>
                    <TouchableOpacity
                      activeOpacity={0.85}
                      style={[d.linkBtn, d.learningLink]}
                      onPress={openCourse}
                      accessibilityRole="link"
                      accessibilityLabel="Start the free course"
                    >
                      <Text style={d.linkBtnText}>Start the free course ↗</Text>
                    </TouchableOpacity>
                    <Text style={d.learningBlurb}>
                      Learning comes from expert sites and videos — RelateWorld
                      mentors you through it and logs every milestone here.
                    </Text>
                  </>
                ) : null}
              </View>
            ) : null}

            {skill.modules?.length ? (
              <ModuleTracker
                skill={skill}
                clubSlug={clubSlug}
                kickerColor={level1?.colorDark || clubColorDark || "#1d2a4d"}
              />
            ) : null}

            {skill.levels
              .filter((level) => level.requirements.length > 0)
              .map((level) => (
              <View key={level.id} style={d.levelCard}>
                <View style={d.levelHead}>
                  <View
                    style={[
                      d.levelDot,
                      { backgroundColor: level.color || clubColor },
                    ]}
                  />
                  <View style={{ flex: 1 }}>
                    <Text style={d.levelName}>
                      Level {level.levelNumber}: {level.name}
                    </Text>
                    <Text style={d.levelMeta}>
                      {level.requirements.length} requirement
                      {level.requirements.length !== 1 ? "s" : ""}
                    </Text>
                  </View>
                </View>

                <SkillProgressCard
                  skill={skill}
                  level={level}
                  clubSlug={clubSlug}
                  whatsappGroupLink={whatsapp}
                />
              </View>
            ))}

            {isMember === true ? (
              <View style={d.joinCard}>
                <Text style={d.joinTitle}>
                  You&rsquo;re in {clubName}
                </Text>
                <Text style={d.joinText}>
                  Your progress here counts toward your club skills pathway —
                  keep ticking it off and your leader confirms each level.
                </Text>
                <TouchableOpacity
                  activeOpacity={0.9}
                  style={d.joinBtn}
                  onPress={() => router.push(`/clubs/${clubSlug}`)}
                  accessibilityRole="link"
                  accessibilityLabel={`Open ${clubName}`}
                >
                  <Text style={d.joinBtnText}>Open {clubName}</Text>
                </TouchableOpacity>
              </View>
            ) : isMember === false ? (
              <View style={d.joinCard}>
                <Text style={d.joinTitle}>Not a member yet?</Text>
                <Text style={d.joinText}>
                  Join {clubName || "the club"} and start earning skills this
                  term — free, and your leader walks with you through every
                  requirement.
                </Text>
                <TouchableOpacity
                  activeOpacity={0.9}
                  style={d.joinBtn}
                  onPress={() =>
                    router.push({
                      pathname: "/join",
                      params: { slug: clubSlug },
                    })
                  }
                  accessibilityRole="button"
                  accessibilityLabel={`Join ${clubName || "club"}`}
                >
                  <Text style={d.joinBtnText}>
                    Join {clubName || "club"}
                  </Text>
                </TouchableOpacity>
              </View>
            ) : null}
          </View>
        </ScrollView>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

