import { API_BASE } from "./config";
import { getRequestHeaders, getSessionToken } from "./auth";

const DEFAULT_TTL = 30_000;
export const SHORT_TTL = 5_000;

const store = new Map<string, { value: unknown; expires: number }>();
const pending = new Map<string, Promise<unknown>>();

function cacheKey(path: string, token: string | null): string {
  return `${token || "anon"}:${path}`;
}

function dayKey(): string {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function dayCacheKey(path: string, token: string | null): string {
  return `day:${dayKey()}:${token || "anon"}:${path}`;
}

export function readCache<T>(path: string, token: string | null): T | null {
  const key = cacheKey(path, token);
  const entry = store.get(key);
  if (!entry) return null;
  if (entry.expires < Date.now()) {
    store.delete(key);
    return null;
  }
  return entry.value as T;
}

export function writeCache(
  path: string,
  token: string | null,
  value: unknown,
  ttlMs: number = DEFAULT_TTL,
): void {
  store.set(cacheKey(path, token), { value, expires: Date.now() + ttlMs });
}

export function invalidateCache(prefix: string, token: string | null): void {
  const keyPrefix = cacheKey(prefix, token);
  for (const key of store.keys()) {
    if (key.startsWith(keyPrefix)) store.delete(key);
  }
}

export function readDayCache<T>(path: string, token: string | null): T | null {
  const key = dayCacheKey(path, token);
  const entry = store.get(key);
  if (!entry) return null;
  if (entry.expires < Date.now()) {
    store.delete(key);
    return null;
  }
  return entry.value as T;
}

export function writeDayCache(
  path: string,
  token: string | null,
  value: unknown,
): void {
  const endOfDay = new Date();
  endOfDay.setHours(23, 59, 59, 999);
  store.set(dayCacheKey(path, token), {
    value,
    expires: endOfDay.getTime(),
  });
}

export function invalidateDayCache(prefix: string, token: string | null): void {
  const keyPrefix = dayCacheKey(prefix, token);
  for (const key of store.keys()) {
    if (key.startsWith(keyPrefix)) store.delete(key);
  }
}

export type CachedFetchOptions = RequestInit & {
  cacheTtl?: number;
  forceRefresh?: boolean;
};

export class ApiError extends Error {
  status: number;

  constructor(status: number, message: string) {
    super(message);
    this.name = "ApiError";
    this.status = status;
  }
}

export async function cachedFetch<T>(
  path: string,
  options: CachedFetchOptions = {},
  invalidatePrefixes: string[] = [],
): Promise<T> {
  const { cacheTtl, forceRefresh, ...reqOptions } = options;
  const method = (reqOptions.method || "GET").toUpperCase();
  const token = await getSessionToken();
  const headers = await getRequestHeaders({
    "Content-Type": "application/json",
    ...((reqOptions.headers as Record<string, string>) || {}),
  });

  if (method === "GET") {
    const cached = readCache<T>(path, token);
    if (cached !== null && !forceRefresh) return cached;

    // Deduplicate concurrent calls to the same endpoint: if a request for
    // this exact path (and token) is already in flight, share its promise
    // instead of firing a second network request. This collapses the burst of
    // duplicate startup calls (e.g. sponsorships/me from focus + user effects)
    // into a single request.
    const reqKey = `${token || "anon"}:${method}:${path}`;
    const inFlight = pending.get(reqKey);
    if (inFlight) return inFlight as Promise<T>;
  }

  const run = async () => {
    try {
      const res = await fetch(`${API_BASE}${path}`, { ...reqOptions, headers });
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        throw new ApiError(res.status, body.error || `API error: ${res.status}`);
      }
      const json = await res.json();

      if (method === "GET") {
        writeCache(path, token, json, cacheTtl);
      } else if (invalidatePrefixes.length > 0) {
        for (const prefix of invalidatePrefixes) {
          invalidateCache(prefix, token);
        }
      }
      return json;
    } finally {
      if (method === "GET") {
        const reqKey = `${token || "anon"}:${method}:${path}`;
        pending.delete(reqKey);
      }
    }
  };

  if (method === "GET") {
    const reqKey = `${token || "anon"}:${method}:${path}`;
    const promise = run();
    pending.set(reqKey, promise);
    return promise;
  }
  return run();
}
