import { type SQLiteDatabase } from "expo-sqlite";

export type VerseRow = {
  id: number;
  version: string;
  book: number;
  book_name: string;
  chapter: number;
  verse: number;
  text: string;
};

export type BookInfo = {
  book: number;
  book_name: string;
  chapter_count: number;
  verse_count: number;
};

export type ChapterInfo = {
  chapter: number;
  verse_count: number;
};

export function cleanScriptureText(text: string): string {
  return text
    .replace(/<sync\b[^>]*\/?>/gi, "")
    .replace(/‹/g, "“")
    .replace(/›/g, "”");
}

export function getBooks(
  db: SQLiteDatabase,
  version: string,
): BookInfo[] {
  return db.getAllSync<BookInfo>(
    `SELECT
       book,
       book_name,
       MAX(chapter) as chapter_count,
       COUNT(*) as verse_count
     FROM verses
     WHERE version = ?
     GROUP BY book, book_name
     ORDER BY book`,
    [version],
  );
}

export function getChapters(
  db: SQLiteDatabase,
  version: string,
  book: number,
): ChapterInfo[] {
  return db.getAllSync<ChapterInfo>(
    `SELECT
       chapter,
       COUNT(*) as verse_count
     FROM verses
     WHERE version = ? AND book = ?
     GROUP BY chapter
     ORDER BY chapter`,
    [version, book],
  );
}

export function getVerses(
  db: SQLiteDatabase,
  version: string,
  book: number,
  chapter: number,
): VerseRow[] {
  return db
    .getAllSync<VerseRow>(
      `SELECT * FROM verses
       WHERE version = ? AND book = ? AND chapter = ?
       ORDER BY verse`,
      [version, book, chapter],
    )
    .map((row) => ({ ...row, text: cleanScriptureText(row.text) }));
}

export function searchVerses(
  db: SQLiteDatabase,
  query: string,
  version?: string,
): (VerseRow & { rank: number })[] {
  if (!query || query.trim().length === 0) return [];

  const ftsQuery = query
    .trim()
    .split(/\s+/)
    .map((w) => `"${w}"`)
    .join(" ");

  if (version) {
    return db
      .getAllSync<VerseRow & { rank: number }>(
        `SELECT v.*, fts.rank
         FROM verses_fts fts
         JOIN verses v ON v.id = fts.rowid
         WHERE verses_fts MATCH ? AND v.version = ?
         ORDER BY fts.rank
         LIMIT 100`,
        [ftsQuery, version],
      )
      .map((row) => ({ ...row, text: cleanScriptureText(row.text) }));
  }

  return db
    .getAllSync<VerseRow & { rank: number }>(
      `SELECT v.*, fts.rank
       FROM verses_fts fts
       JOIN verses v ON v.id = fts.rowid
       WHERE verses_fts MATCH ?
       ORDER BY fts.rank
       LIMIT 100`,
      [ftsQuery],
    )
    .map((row) => ({ ...row, text: cleanScriptureText(row.text) }));
}

export function getVerseCount(
  db: SQLiteDatabase,
  version: string,
  book: number,
  chapter: number,
): number {
  const row = db.getFirstSync<{ c: number }>(
    `SELECT COUNT(*) as c FROM verses
     WHERE version = ? AND book = ? AND chapter = ?`,
    [version, book, chapter],
  );
  return row?.c ?? 0;
}

export function getBookByName(
  db: SQLiteDatabase,
  version: string,
  bookName: string,
): BookInfo | null {
  return db.getFirstSync<BookInfo>(
    `SELECT
       book,
       book_name,
       MAX(chapter) as chapter_count,
       COUNT(*) as verse_count
     FROM verses
     WHERE version = ? AND book_name = ?
     GROUP BY book, book_name`,
    [version, bookName],
  );
}

export function getBookByNumber(
  db: SQLiteDatabase,
  version: string,
  bookNumber: number,
): BookInfo | null {
  return db.getFirstSync<BookInfo>(
    `SELECT
       book,
       book_name,
       MAX(chapter) as chapter_count,
       COUNT(*) as verse_count
     FROM verses
     WHERE version = ? AND book = ?
     GROUP BY book, book_name`,
    [version, bookNumber],
  );
}
