import { Ionicons } from "@expo/vector-icons";
import { Image } from "expo-image";
import { StatusBar } from "expo-status-bar";
import { useRouter } from "expo-router";
import { useEffect, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaProvider, SafeAreaView, useSafeAreaInsets } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { useCart } from "@/services/cart";
import { getSession } from "@/services/auth";
import { formatPrice } from "@/services/store";
import { getOptimizedImageUrl } from "@/services/cloudinary";
import { GradientBox } from "@/constants/gradients";

/**
 * The cart — quantity editing, a running subtotal and the single way into
 * checkout. The whole screen reads from the shared cart store, so items
 * added on the product page appear here instantly.
 */
export default function CartScreen() {
  const insets = useSafeAreaInsets();
  const router = useRouter();
  const { lines, subtotal, setQty, remove } = useCart();
  const [checkingAuth, setCheckingAuth] = useState(true);
  const [signedIn, setSignedIn] = useState(false);

  useEffect(() => {
    let cancelled = false;
    getSession()
      .then((session) => {
        if (cancelled) return;
        setSignedIn(!!session?.user);
        setCheckingAuth(false);
      })
      .catch(() => {
        if (!cancelled) setCheckingAuth(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const count = lines.reduce((sum, l) => sum + l.qty, 0);

  const goCheckout = () => {
    if (count === 0) return;
    if (!signedIn) {
      Alert.alert("Sign in to check out", "Orders are tied to your account.", [
        { text: "Not now", style: "cancel" },
        {
          text: "Sign in",
          onPress: () =>
            router.replace({ pathname: "/login", params: { next: "/checkout" } }),
        },
      ]);
      return;
    }
    router.push("/checkout" as any);
  };

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <StatusBar style="dark" />

        <View style={styles.bar}>
          <TouchableOpacity
            style={styles.iconBtn}
            onPress={() => router.back()}
            accessibilityRole="button"
            accessibilityLabel="Back"
          >
            <Ionicons name="chevron-back" size={22} color={colors.forest} />
          </TouchableOpacity>
          <View style={styles.barTitleWrap}>
            <Text style={styles.barTitle}>Your cart</Text>
            <Text style={styles.barSub}>
              {count === 0
                ? "Nothing here yet"
                : `${count} item${count === 1 ? "" : "s"}`}
            </Text>
          </View>
          <View style={styles.iconBtn} />
        </View>

        {lines.length === 0 ? (
          <View style={styles.empty}>
            <View style={styles.emptyIcon}>
              <Ionicons name="bag-outline" size={34} color={colors.forest} />
            </View>
            <Text style={styles.emptyTitle}>Your cart is empty</Text>
            <Text style={styles.emptyText}>
              Browse the Relate Store for merch, apparel and gifts for the
              community.
            </Text>
            <TouchableOpacity
              style={styles.emptyBtn}
              onPress={() => router.replace("/(tabs)/store")}
              activeOpacity={0.9}
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Text style={styles.emptyBtnText}>Start shopping</Text>
              <Ionicons name="arrow-forward" size={16} color={colors.white} />
            </TouchableOpacity>
          </View>
        ) : (
          <>
            <ScrollView
              showsVerticalScrollIndicator={false}
              contentContainerStyle={styles.scroll}
            >
              {lines.map((line) => {
                const key = `${line.itemId}:${line.size ?? ""}`;
                return (
                  <View key={key} style={styles.line}>
                    <TouchableOpacity
                      activeOpacity={0.85}
                      onPress={() => router.push(`/store/${line.itemId}` as any)}
                      accessibilityRole="button"
                      accessibilityLabel={`View ${line.name}`}
                    >
                      <Image
                        source={{ uri: getOptimizedImageUrl(line.image, 720) }}
                        style={styles.lineImg}
                        contentFit="cover"
                      />
                    </TouchableOpacity>

                    <View style={styles.lineBody}>
                      <View style={styles.lineTop}>
                        <View style={{ flex: 1 }}>
                          <Text style={styles.lineName} numberOfLines={2}>
                            {line.name}
                          </Text>
                          {!!line.size && (
                            <Text style={styles.lineMeta}>Size {line.size}</Text>
                          )}
                        </View>
                        <TouchableOpacity
                          onPress={() => remove(line.itemId, line.size)}
                          hitSlop={8}
                          accessibilityRole="button"
                          accessibilityLabel={`Remove ${line.name}`}
                        >
                          <Ionicons
                            name="trash-outline"
                            size={18}
                            color={colors.muted}
                          />
                        </TouchableOpacity>
                      </View>

                      <View style={styles.lineBottom}>
                        <Text style={styles.linePrice}>
                          {formatPrice(line.price * line.qty)}
                        </Text>
                        <View style={styles.stepper}>
                          <TouchableOpacity
                            style={styles.stepBtn}
                            onPress={() => setQty(line.itemId, line.size, line.qty - 1)}
                            accessibilityRole="button"
                            accessibilityLabel="Decrease quantity"
                          >
                            <Ionicons name="remove" size={16} color={colors.ink} />
                          </TouchableOpacity>
                          <Text style={styles.stepValue}>{line.qty}</Text>
                          <TouchableOpacity
                            style={styles.stepBtn}
                            onPress={() => setQty(line.itemId, line.size, line.qty + 1)}
                            accessibilityRole="button"
                            accessibilityLabel="Increase quantity"
                          >
                            <Ionicons name="add" size={16} color={colors.ink} />
                          </TouchableOpacity>
                        </View>
                      </View>
                    </View>
                  </View>
                );
              })}

              <TouchableOpacity
                style={styles.keepShopping}
                onPress={() => router.push("/(tabs)/store")}
                activeOpacity={0.8}
              >
                <Ionicons name="chevron-back" size={16} color={colors.forest} />
                <Text style={styles.keepShoppingText}>Keep shopping</Text>
              </TouchableOpacity>

              <View style={styles.summary}>
                <Text style={styles.summaryTitle}>Order summary</Text>
                <View style={styles.summaryRow}>
                  <Text style={styles.summaryLabel}>Subtotal</Text>
                  <Text style={styles.summaryValue}>{formatPrice(subtotal)}</Text>
                </View>
                <View style={styles.summaryRow}>
                  <Text style={styles.summaryLabel}>Delivery</Text>
                  <Text style={styles.summaryFree}>Arranged on payment</Text>
                </View>
                <View style={styles.summaryDivider} />
                <View style={styles.summaryRow}>
                  <Text style={styles.totalLabel}>Total</Text>
                  <Text style={styles.totalValue}>{formatPrice(subtotal)}</Text>
                </View>
                <Text style={styles.summaryNote}>
                  You’ll pay by EFT after checkout — our banking details appear
                  on your receipt with your order number.
                </Text>
              </View>
            </ScrollView>

            <View style={[styles.footer, { paddingBottom: Math.max(12, insets.bottom) }]}>
              <TouchableOpacity
                style={styles.checkoutBtn}
                onPress={goCheckout}
                activeOpacity={0.9}
                disabled={checkingAuth}
                accessibilityRole="button"
                accessibilityLabel="Proceed to checkout"
              >
                <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                {checkingAuth ? (
                  <ActivityIndicator color={colors.white} />
                ) : (
                  <>
                    <Text style={styles.checkoutText}>Checkout</Text>
                    <Text style={styles.checkoutTotal}>{formatPrice(subtotal)}</Text>
                  </>
                )}
              </TouchableOpacity>
            </View>
          </>
        )}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

