import { Ionicons } from "@expo/vector-icons";
import { Image } from "expo-image";
import { StatusBar } from "expo-status-bar";
import { useLocalSearchParams, useRouter } from "expo-router";
import { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaProvider, SafeAreaView } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import {
  ORDER_PROGRESS,
  ORDER_STATUS_LABEL,
  ORDER_STATUS_SUB,
  formatOrderDate,
  historyAt,
  ordersApi,
  progressIndex,
  type Order,
} from "@/services/orders";
import { sponsorApi, type BankingDetails } from "@/services/sponsorships";
import { formatPrice } from "@/services/store";
import { getOptimizedImageUrl } from "@/services/cloudinary";
import { GradientBox } from "@/constants/gradients";

/**
 * Order receipt + tracking.
 *
 * One screen answers everything a buyer asks after checkout: "did it go
 * through?", "what's the order number?", "where do I pay?" and "when does it
 * arrive?" — the same status history the admin console writes.
 */
export default function OrderScreen() {
  const router = useRouter();
  const { id } = useLocalSearchParams<{ id: string }>();

  const [order, setOrder] = useState<Order | null>(null);
  const [banking, setBanking] = useState<BankingDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const [orderRes] = await Promise.all([
        ordersApi.get(String(id ?? "")),
        sponsorApi
          .banking()
          .then((r) => setBanking(r.data.banking ?? null))
          .catch(() => null),
      ]);
      setOrder(orderRes.data);
      setError(null);
    } catch (err: any) {
      setError(
        String(err?.message || "We couldn't load that order — try again."),
      );
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [id]);

  useEffect(() => {
    (async () => {
      await load();
    })();
  }, [load]);

  if (loading) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={styles.bar}>
            <TouchableOpacity
              style={styles.iconBtn}
              onPress={() => router.back()}
              accessibilityRole="button"
              accessibilityLabel="Back"
            >
              <Ionicons name="chevron-back" size={22} color={colors.forest} />
            </TouchableOpacity>
            <View style={{ flex: 1 }} />
          </View>
          <View style={styles.loading}>
            <ActivityIndicator color={colors.forest} size="large" />
            <Text style={styles.loadingText}>Fetching your order…</Text>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (!order) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={styles.bar}>
            <TouchableOpacity
              style={styles.iconBtn}
              onPress={() => router.back()}
              accessibilityRole="button"
              accessibilityLabel="Back"
            >
              <Ionicons name="chevron-back" size={22} color={colors.forest} />
            </TouchableOpacity>
          </View>
          <View style={styles.empty}>
            <Ionicons name="alert-circle-outline" size={32} color={colors.muted} />
            <Text style={styles.emptyText}>{error || "Order not found."}</Text>
            <TouchableOpacity
              style={styles.emptyBtn}
              onPress={() => router.replace("/(tabs)/store")}
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Text style={styles.emptyBtnText}>Back to the store</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const cancelled = order.status === "cancelled";
  const step = progressIndex(order);
  const waitingPayment = order.status === "received";

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <StatusBar style="dark" />

        <View style={styles.bar}>
          <TouchableOpacity
            style={styles.iconBtn}
            onPress={() => router.back()}
            accessibilityRole="button"
            accessibilityLabel="Back"
          >
            <Ionicons name="chevron-back" size={22} color={colors.forest} />
          </TouchableOpacity>
          <View style={{ flex: 1 }}>
            <Text style={styles.barTitle}>{order.orderNumber}</Text>
            <Text style={styles.barSub}>
              {order.createdAt ? formatOrderDate(order.createdAt) : ""}
            </Text>
          </View>
          <TouchableOpacity
            style={styles.iconBtn}
            onPress={() => {
              setRefreshing(true);
              load();
            }}
            accessibilityRole="button"
            accessibilityLabel="Refresh order"
          >
            <Ionicons name="refresh" size={18} color={colors.forest} />
          </TouchableOpacity>
        </View>

        <ScrollView
          showsVerticalScrollIndicator={false}
          contentContainerStyle={styles.scroll}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={() => {
                setRefreshing(true);
                load();
              }}
              tintColor={colors.forest}
            />
          }
        >
          {/* Status hero */}
          <View
            style={[
              styles.hero,
              cancelled
                ? styles.heroCancelled
                : step >= 3
                  ? styles.heroDone
                  : styles.heroActive,
            ]}
          >
            <View style={styles.heroIcon}>
              <Ionicons
                name={
                  cancelled
                    ? "close"
                    : step >= 3
                      ? "checkmark"
                      : "cube-outline"
                }
                size={26}
                color={colors.white}
              />
            </View>
            <Text style={styles.heroLabel}>{ORDER_STATUS_LABEL[order.status]}</Text>
            <Text style={styles.heroSub}>{ORDER_STATUS_SUB[order.status]}</Text>

            {!cancelled && (
              <View style={styles.etaPill}>
                <Ionicons name="calendar-outline" size={13} color={colors.gold} />
                <Text style={styles.etaText}>
                  {order.eta
                    ? `Est. delivery ${formatOrderDate(order.eta)}`
                    : "Delivery date to be confirmed"}
                </Text>
              </View>
            )}
          </View>

          {/* Progress timeline */}
          {!cancelled ? (
            <View style={styles.card}>
              <Text style={styles.cardTitle}>Order progress</Text>
              {ORDER_PROGRESS.map((status, i) => {
                const done = i < step;
                const current = i === step;
                const at = historyAt(order, status);
                const last = i === ORDER_PROGRESS.length - 1;
                return (
                  <View key={status} style={styles.stepRow}>
                    <View style={styles.stepRail}>
                      <View
                        style={[
                          styles.stepDot,
                          done && styles.stepDotDone,
                          current && styles.stepDotCurrent,
                        ]}
                      >
                        {done ? (
                          <Ionicons name="checkmark" size={11} color={colors.white} />
                        ) : (
                          <Text
                            style={[
                              styles.stepNum,
                              current && styles.stepNumCurrent,
                            ]}
                          >
                            {i + 1}
                          </Text>
                        )}
                      </View>
                      {!last && (
                        <View
                          style={[
                            styles.stepLine,
                            done && styles.stepLineDone,
                          ]}
                        />
                      )}
                    </View>
                    <View style={styles.stepBody}>
                      <Text
                        style={[
                          styles.stepLabel,
                          (done || current) && styles.stepLabelActive,
                        ]}
                      >
                        {ORDER_STATUS_LABEL[status]}
                      </Text>
                      <Text style={styles.stepSub}>{ORDER_STATUS_SUB[status]}</Text>
                      {at ? (
                        <Text style={styles.stepWhen}>{formatOrderDate(at)}</Text>
                      ) : null}
                    </View>
                  </View>
                );
              })}
            </View>
          ) : (
            <View style={styles.card}>
              <Text style={styles.cardTitle}>What happened</Text>
              {order.statusHistory.length === 0 ? (
                <Text style={styles.muted}>No history recorded.</Text>
              ) : (
                [...order.statusHistory].reverse().map((h, i) => (
                  <View key={i} style={styles.historyRow}>
                    <Text style={styles.historyStatus}>
                      {ORDER_STATUS_LABEL[h.status] ?? h.status}
                    </Text>
                    <Text style={styles.historyWhen}>
                      {formatOrderDate(h.at)}
                      {h.note ? ` · ${h.note}` : ""}
                    </Text>
                  </View>
                ))
              )}
            </View>
          )}

          {/* Receipt */}
          <View style={styles.card}>
            <View style={styles.receiptHead}>
              <Text style={styles.cardTitle}>Receipt</Text>
              <Text style={styles.receiptNo}>{order.orderNumber}</Text>
            </View>
            {order.items.map((it, i) => (
              <View
                key={`${it.itemId}-${i}`}
                style={styles.itemRow}
              >
                {!!it.image && (
                  <Image
                    source={{ uri: getOptimizedImageUrl(it.image, 720) }}
                    style={styles.itemImg}
                    contentFit="cover"
                  />
                )}
                <View style={{ flex: 1 }}>
                  <Text style={styles.itemName} numberOfLines={2}>
                    {it.name}
                  </Text>
                  <Text style={styles.itemMeta}>
                    {it.size ? `Size ${it.size} · ` : ""}
                    {it.qty} × {formatPrice(it.price)}
                  </Text>
                </View>
                <Text style={styles.itemTotal}>
                  {formatPrice(it.price * it.qty)}
                </Text>
              </View>
            ))}
            <View style={styles.divider} />
            <View style={styles.totalRow}>
              <Text style={styles.totalLabel}>Total</Text>
              <Text style={styles.totalValue}>{formatPrice(order.total)}</Text>
            </View>
            <View style={styles.customerBox}>
              <Text style={styles.customerLine}>
                {order.customerName}
                {order.phone ? ` · ${order.phone}` : ""}
              </Text>
              {!!order.email && <Text style={styles.customerLine}>{order.email}</Text>}
              {!!order.note && (
                <Text style={styles.customerNote}>“{order.note}”</Text>
              )}
            </View>
          </View>

          {/* Banking details */}
          {banking ? (
            <View style={styles.card}>
              <View style={styles.bankHead}>
                <Ionicons name="wallet-outline" size={18} color={colors.forest} />
                <Text style={styles.cardTitle}>
                  {waitingPayment ? "Pay this to start your order" : "Banking details"}
                </Text>
              </View>
              {waitingPayment && (
                <View style={styles.payBanner}>
                  <Ionicons name="information-circle-outline" size={15} color={colors.forest} />
                  <Text style={styles.payBannerText}>
                    Use {order.orderNumber} as the payment reference, then send
                    us the proof of payment.
                  </Text>
                </View>
              )}
              <BankRow label="Bank" value={banking.bankName} />
              <BankRow label="Account holder" value={banking.accountHolder} />
              <BankRow label="Account number" value={banking.accountNumber} />
              <BankRow label="Branch code" value={banking.branchCode} />
              <BankRow label="Account type" value={banking.accountType} />
              <BankRow label="Reference" value={order.orderNumber} highlight />
              {!!banking.instructions && (
                <Text style={styles.instructions}>{banking.instructions}</Text>
              )}
            </View>
          ) : null}

          <View style={styles.actions}>
            <TouchableOpacity
              style={styles.secondaryBtn}
              onPress={() => router.replace("/orders" as any)}
              activeOpacity={0.85}
            >
              <Ionicons name="receipt-outline" size={16} color={colors.forest} />
              <Text style={styles.secondaryText}>All my orders</Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={styles.primaryBtn}
              onPress={() => router.replace("/(tabs)/store")}
              activeOpacity={0.85}
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Text style={styles.primaryText}>Keep shopping</Text>
            </TouchableOpacity>
          </View>
        </ScrollView>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

function BankRow({
  label,
  value,
  highlight,
}: {
  label: string;
  value: string;
  highlight?: boolean;
}) {
  if (!value) return null;
  return (
    <View style={styles.bankRow}>
      <Text style={styles.bankLabel}>{label}</Text>
      <Text style={[styles.bankValue, highlight && styles.bankValueHi]}>
        {value}
      </Text>
    </View>
  );
}

