import AsyncStorage from "@react-native-async-storage/async-storage";

/**
 * Android can kill a backgrounded app at any time (low memory, battery
 * savers or the "Don't keep activities" developer setting). When the user
 * comes back the JS app cold-starts on the landing screen, so whatever they
 * were writing is no longer on screen. Remember the last writing screen and
 * return there on the next cold start; the form drafts themselves are stored
 * separately by each form.
 */

const STORAGE_KEY = "app:resume-route";
const MAX_AGE_MS = 12 * 60 * 60 * 1000;

const EXCLUDED = [
  "/",
  "/login",
  "/signup",
  "/callback",
  "/details",
  "/terms",
  "/privacy",
  "/profile-modal",
];

type ResumePoint = { path: string; at: number };

function restorable(path: string): boolean {
  if (!path || !path.startsWith("/")) return false;
  return !EXCLUDED.some((entry) => path === entry || path.startsWith(`${entry}/`));
}

export async function rememberRoute(path: string): Promise<void> {
  try {
    if (!restorable(path)) {
      await AsyncStorage.removeItem(STORAGE_KEY);
      return;
    }
    const point: ResumePoint = { path, at: Date.now() };
    await AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(point));
  } catch {
    // A failed write only costs the resume shortcut.
  }
}

export async function takeRememberedRoute(): Promise<string | null> {
  try {
    const stored = await AsyncStorage.getItem(STORAGE_KEY);
    if (!stored) return null;
    const point = JSON.parse(stored) as ResumePoint;
    const fresh = Date.now() - (point?.at || 0) < MAX_AGE_MS;
    if (!fresh || typeof point?.path !== "string" || !restorable(point.path)) {
      await AsyncStorage.removeItem(STORAGE_KEY);
      return null;
    }
    return point.path;
  } catch {
    return null;
  }
}

export async function clearRememberedRoute(): Promise<void> {
  try {
    await AsyncStorage.removeItem(STORAGE_KEY);
  } catch {
    // Nothing to clear.
  }
}
