import { cachedFetch, SHORT_TTL, type CachedFetchOptions } from "./cache";

export type MobileBadges = {
  userUnread: number;
  adminUnread: number;
  unread: number;
};

export function fetchMobileBadges(
  options: CachedFetchOptions = {},
): Promise<{ data: MobileBadges }> {
  return cachedFetch<{ data: MobileBadges }>("/api/mobile/badges", {
    cacheTtl: SHORT_TTL,
    ...options,
  });
}
