import { Ionicons } from "@expo/vector-icons";
import { useEffect, useState } from "react";
import {
  Animated,
  Modal,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";

type Props = {
  visible: boolean;
  title: string;
  message?: string;
  actionLabel?: string;
  onClose: () => void;
};

/** Confirmation card with a spring-in tick, used when an operation commits. */
export default function SuccessModal({
  visible,
  title,
  message,
  actionLabel = "Done",
  onClose,
}: Props) {
  const [opacity] = useState(() => new Animated.Value(0));
  const [scale] = useState(() => new Animated.Value(0.85));
  const [ring] = useState(() => new Animated.Value(0));

  useEffect(() => {
    if (!visible) return;
    opacity.setValue(0);
    scale.setValue(0.85);
    ring.setValue(0);
    Animated.parallel([
      Animated.timing(opacity, {
        toValue: 1,
        duration: 180,
        useNativeDriver: true,
      }),
      Animated.spring(scale, {
        toValue: 1,
        friction: 7,
        tension: 90,
        useNativeDriver: true,
      }),
    ]).start(() => {
      Animated.timing(ring, {
        toValue: 1,
        duration: 520,
        useNativeDriver: true,
      }).start();
    });
  }, [visible, opacity, scale, ring]);

  return (
    <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}>
      <View style={styles.backdrop}>
        <Animated.View style={[styles.card, { opacity, transform: [{ scale }] }]}>
          <View style={styles.iconWrap}>
            <Animated.View
              style={[
                styles.ring,
                {
                  opacity: ring.interpolate({
                    inputRange: [0, 1],
                    outputRange: [0.45, 0],
                  }),
                  transform: [
                    {
                      scale: ring.interpolate({
                        inputRange: [0, 1],
                        outputRange: [1, 1.9],
                      }),
                    },
                  ],
                },
              ]}
            />
            <View style={styles.iconCircle}>
              <Ionicons name="checkmark" size={30} color={colors.forest} />
            </View>
          </View>
          <Text style={styles.title}>{title}</Text>
          {message ? <Text style={styles.message}>{message}</Text> : null}
          <TouchableOpacity
            style={styles.button}
            onPress={onClose}
            activeOpacity={0.85}
            accessibilityLabel={actionLabel}
          >
            <Text style={styles.buttonText}>{actionLabel}</Text>
          </TouchableOpacity>
        </Animated.View>
      </View>
    </Modal>
  );
}

const styles = StyleSheet.create({
  backdrop: {
    flex: 1,
    backgroundColor: "rgba(11,25,44,0.45)",
    alignItems: "center",
    justifyContent: "center",
    padding: 28,
  },
  card: {
    width: "100%",
    maxWidth: 340,
    borderRadius: 24,
    backgroundColor: colors.white,
    paddingHorizontal: 24,
    paddingTop: 26,
    paddingBottom: 20,
    alignItems: "center",
    ...colors.shadow.lg,
  },
  iconWrap: {
    width: 64,
    height: 64,
    alignItems: "center",
    justifyContent: "center",
  },
  ring: {
    position: "absolute",
    width: 64,
    height: 64,
    borderRadius: 32,
    borderWidth: 2,
    borderColor: colors.gold,
  },
  iconCircle: {
    width: 64,
    height: 64,
    borderRadius: 32,
    backgroundColor: `${colors.gold}26`,
    alignItems: "center",
    justifyContent: "center",
  },
  title: {
    marginTop: 14,
    fontSize: 19,
    color: colors.forest,
    fontFamily: fonts.sansBold,
    textAlign: "center",
  },
  message: {
    marginTop: 6,
    fontSize: 13.5,
    lineHeight: 20,
    color: colors.muted,
    fontFamily: fonts.sans,
    textAlign: "center",
  },
  button: {
    marginTop: 18,
    alignSelf: "stretch",
    borderRadius: 14,
    backgroundColor: colors.gold,
    paddingVertical: 13,
    alignItems: "center",
    justifyContent: "center",
  },
  buttonText: {
    fontSize: 14,
    color: colors.forest,
    fontFamily: fonts.sansBold,
  },
});