import {
  Modal,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { useBibleTheme, type BibleTheme } from "@/lib/bible-theme";
import {
  READER_FONTS,
  READER_LAYOUTS,
  type ReaderFontKey,
  type ReaderLayoutKey,
  type ReaderThemeKey,
} from "@/lib/reader-settings";

type Props = {
  visible: boolean;
  onClose: () => void;
  fontSize: number;
  onFontSizeChange: (size: number) => void;
  fontKey: ReaderFontKey;
  onFontFamilyChange: (key: ReaderFontKey) => void;
  fontWeight: string;
  onFontWeightChange: (family: string) => void;
  themePref: ReaderThemeKey;
  onThemeChange: (theme: ReaderThemeKey) => void;
  layout: ReaderLayoutKey;
  onLayoutChange: (layout: ReaderLayoutKey) => void;
};

const THEME_SWATCHES: {
  key: ReaderThemeKey;
  label: string;
  bg: string;
}[] = [
  { key: "system", label: "Auto", bg: "#E8ECF2" },
  { key: "light", label: "Light", bg: "#FFFFFF" },
  { key: "dark", label: "Dark", bg: "#16211B" },
  { key: "sepia", label: "Sepia", bg: "#F4ECD8" },
  { key: "paper", label: "Paper", bg: "#FBF7EF" },
];

const LAYOUT_ICONS: Record<string, keyof typeof Ionicons.glyphMap> = {
  verses: "list-outline",
  paragraph: "document-text-outline",
  poetry: "book-outline",
  focus: "eye-outline",
};

const MIN_SIZE = 14;
const MAX_SIZE = 28;
const SIZE_STEPS = MAX_SIZE - MIN_SIZE;

export default function DisplaySheet({
  visible,
  onClose,
  fontSize,
  onFontSizeChange,
  fontKey,
  onFontFamilyChange,
  fontWeight,
  onFontWeightChange,
  themePref,
  onThemeChange,
  layout,
  onLayoutChange,
}: Props) {
  const theme = useBibleTheme();
  const s = createStyles(theme);

  const activeFont =
    READER_FONTS.find((f) => f.key === fontKey) ?? READER_FONTS[0];
  const progress = (fontSize - MIN_SIZE) / SIZE_STEPS;

  return (
    <Modal
      visible={visible}
      transparent
      animationType="slide"
      onRequestClose={onClose}
    >
      <TouchableOpacity style={s.overlay} activeOpacity={1} onPress={onClose}>
        <TouchableOpacity activeOpacity={1} style={s.sheet} onPress={() => {}}>
          <View style={s.grabber} />
          <ScrollView
            style={s.sheetScroll}
            contentContainerStyle={s.sheetScrollContent}
            showsVerticalScrollIndicator={false}
          >
          <View style={s.titleRow}>
            <Text style={s.title}>Display</Text>
            <TouchableOpacity
              onPress={onClose}
              style={s.closeBtn}
              accessibilityRole="button"
              accessibilityLabel="Close display settings"
            >
              <Ionicons name="close" size={20} color={theme.textMuted} />
            </TouchableOpacity>
          </View>

          <Text style={s.section}>Text size</Text>
          <View style={s.sizeRow}>
            <TouchableOpacity
              style={s.sizeBtn}
              onPress={() => onFontSizeChange(Math.max(MIN_SIZE, fontSize - 1))}
              accessibilityRole="button"
              accessibilityLabel="Decrease text size"
            >
              <Text style={s.sizeBtnSmall}>A</Text>
            </TouchableOpacity>
            <View style={s.sizeTrack}>
              <View style={[s.sizeFill, { width: `${progress * 100}%` }]} />
            </View>
            <TouchableOpacity
              style={s.sizeBtn}
              onPress={() => onFontSizeChange(Math.min(MAX_SIZE, fontSize + 1))}
              accessibilityRole="button"
              accessibilityLabel="Increase text size"
            >
              <Text style={s.sizeBtnLarge}>A</Text>
            </TouchableOpacity>
          </View>
          <Text style={s.sizePreview}>
            {fontSize}pt — For God so loved the world
          </Text>

          <Text style={s.section}>Font style</Text>
          {READER_FONTS.map((f) => {
            const active = f.key === activeFont.key;
            return (
              <TouchableOpacity
                key={f.key}
                style={[s.option, active && s.optionActive]}
                onPress={() => onFontFamilyChange(f.key)}
                accessibilityRole="button"
                accessibilityLabel={`Use ${f.label} font`}
              >
                <Text style={[s.optionSample, { fontFamily: f.defaultWeight }]}>
                  {f.label}
                </Text>
                {active ? (
                  <Ionicons name="checkmark" size={18} color={theme.accent} />
                ) : null}
              </TouchableOpacity>
            );
          })}

          <Text style={s.section}>Weight</Text>
          <View style={s.chipRow}>
            {activeFont.weights.map((w) => {
              const active = w.family === fontWeight;
              return (
                <TouchableOpacity
                  key={w.family}
                  style={[s.chip, active && s.chipActive]}
                  onPress={() => onFontWeightChange(w.family)}
                  accessibilityRole="button"
                  accessibilityLabel={`Use ${w.label} weight`}
                >
                  <Text
                    style={[
                      s.chipText,
                      active && s.chipTextActive,
                      { fontFamily: w.family },
                    ]}
                  >
                    {w.label}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </View>

          <Text style={s.section}>Reading</Text>
          <View style={s.layoutRow}>
            {READER_LAYOUTS.map((l) => {
              const active = l.key === layout;
              return (
                <TouchableOpacity
                  key={l.key}
                  style={[s.layoutOption, active && s.layoutOptionActive]}
                  onPress={() => onLayoutChange(l.key)}
                  accessibilityRole="button"
                  accessibilityLabel={`${l.label} layout — ${l.description}`}
                >
                  <Ionicons
                    name={LAYOUT_ICONS[l.key] ?? "apps-outline"}
                    size={20}
                    color={active ? theme.accent : theme.textMuted}
                  />
                  <View style={s.layoutTextCol}>
                    <Text
                      style={[s.layoutLabel, active && s.layoutLabelActive]}
                    >
                      {l.label}
                    </Text>
                    <Text style={s.layoutDesc}>{l.description}</Text>
                  </View>
                  {active ? (
                    <Ionicons name="checkmark" size={18} color={theme.accent} />
                  ) : null}
                </TouchableOpacity>
              );
            })}
          </View>

          <Text style={s.section}>Background</Text>
          <View style={s.swatchRow}>
            {THEME_SWATCHES.map((t) => {
              const active = themePref === t.key;
              return (
                <TouchableOpacity
                  key={t.key}
                  style={s.swatchBtn}
                  onPress={() => onThemeChange(t.key)}
                  accessibilityRole="button"
                  accessibilityLabel={`Use ${t.label} background`}
                >
                  {t.key === "system" ? (
                    <View style={s.swatchSystem}>
                      <View style={s.swatchHalfLight} />
                      <View style={s.swatchHalfDark} />
                    </View>
                  ) : (
                    <View style={[s.swatch, { backgroundColor: t.bg }]} />
                  )}
                  <Text
                    style={[s.swatchLabel, active && s.swatchLabelActive]}
                  >
                    {t.label}
                  </Text>
                  {active ? <View style={s.swatchDot} /> : null}
                </TouchableOpacity>
              );
            })}
          </View>
          </ScrollView>
        </TouchableOpacity>
      </TouchableOpacity>
    </Modal>
  );
}

function createStyles(theme: BibleTheme) {
  return StyleSheet.create({
    overlay: {
      flex: 1,
      backgroundColor: "rgba(0,0,0,0.5)",
      justifyContent: "flex-end",
    },
    sheet: {
      backgroundColor: theme.cardBg,
      borderTopLeftRadius: 24,
      borderTopRightRadius: 24,
      paddingHorizontal: 20,
      paddingBottom: 36,
      paddingTop: 10,
      maxHeight: "78%",
    },
    grabber: {
      alignSelf: "center",
      width: 40,
      height: 4,
      borderRadius: 2,
      backgroundColor: theme.borderStrong,
      marginBottom: 10,
    },
    titleRow: {
      flexDirection: "row",
      alignItems: "center",
      justifyContent: "space-between",
      marginBottom: 4,
    },
    title: {
      fontWeight: "700",
      fontSize: 22,
      color: theme.text,
    },
    closeBtn: {
      padding: 6,
    },
    section: {
      fontWeight: "700",
      fontSize: 12,
      color: theme.textMuted,
      textTransform: "uppercase",
      letterSpacing: 1.2,
      marginTop: 18,
      marginBottom: 10,
    },
    sizeRow: {
      flexDirection: "row",
      alignItems: "center",
      gap: 14,
    },
    sizeBtn: {
      width: 44,
      height: 40,
      borderRadius: 12,
      backgroundColor: theme.inputBg,
      alignItems: "center",
      justifyContent: "center",
    },
    sizeBtnSmall: {
      fontWeight: "700",
      fontSize: 13,
      color: theme.text,
    },
    sizeBtnLarge: {
      fontWeight: "700",
      fontSize: 21,
      color: theme.text,
    },
    sizeTrack: {
      flex: 1,
      height: 6,
      borderRadius: 3,
      backgroundColor: theme.inputBg,
      overflow: "hidden",
    },
    sizeFill: {
      height: 6,
      borderRadius: 3,
      backgroundColor: theme.accent,
    },
    sizePreview: {
      fontFamily: "Eczar_500Medium",
      fontSize: 15,
      color: theme.textMuted,
      marginTop: 10,
    },
    option: {
      flexDirection: "row",
      alignItems: "center",
      justifyContent: "space-between",
      paddingVertical: 12,
      paddingHorizontal: 14,
      borderRadius: 12,
      marginBottom: 6,
      backgroundColor: theme.inputBg,
    },
    optionActive: {
      backgroundColor: theme.accentSoft,
    },
    optionSample: {
      fontSize: 17,
      color: theme.text,
    },
    chipRow: {
      flexDirection: "row",
      flexWrap: "wrap",
      gap: 8,
    },
    chip: {
      paddingHorizontal: 14,
      paddingVertical: 9,
      borderRadius: 999,
      backgroundColor: theme.inputBg,
      borderWidth: 1,
      borderColor: "transparent",
    },
    chipActive: {
      backgroundColor: theme.accentSoft,
      borderColor: theme.accent,
    },
    chipText: {
      fontWeight: "600",
      fontSize: 13,
      color: theme.textMuted,
    },
    chipTextActive: {
      color: theme.accent,
      fontWeight: "700",
    },
    sheetScroll: {
      flexGrow: 0,
    },
    sheetScrollContent: {
      paddingBottom: 8,
    },
    layoutRow: {
      gap: 8,
    },
    layoutOption: {
      flexDirection: "row",
      alignItems: "center",
      gap: 12,
      paddingVertical: 12,
      paddingHorizontal: 14,
      borderRadius: 12,
      marginBottom: 6,
      backgroundColor: theme.inputBg,
      borderWidth: 1,
      borderColor: "transparent",
    },
    layoutOptionActive: {
      backgroundColor: theme.accentSoft,
      borderColor: theme.accent,
    },
    layoutTextCol: {
      flex: 1,
    },
    layoutLabel: {
      fontWeight: "600",
      fontSize: 15,
      color: theme.text,
    },
    layoutLabelActive: {
      color: theme.accent,
      fontWeight: "700",
    },
    layoutDesc: {
      fontSize: 12,
      color: theme.textMuted,
      marginTop: 1,
    },
    swatchRow: {
      flexDirection: "row",
      flexWrap: "wrap",
      gap: 12,
    },
    swatchBtn: {
      alignItems: "center",
      gap: 5,
    },
    swatch: {
      width: 44,
      height: 44,
      borderRadius: 22,
      borderWidth: StyleSheet.hairlineWidth,
      borderColor: theme.borderStrong,
    },
    swatchSystem: {
      width: 44,
      height: 44,
      borderRadius: 22,
      overflow: "hidden",
      flexDirection: "row",
      borderWidth: StyleSheet.hairlineWidth,
      borderColor: theme.borderStrong,
    },
    swatchHalfLight: {
      flex: 1,
      backgroundColor: "#F5F7FA",
    },
    swatchHalfDark: {
      flex: 1,
      backgroundColor: "#1A2332",
    },
    swatchLabel: {
      fontSize: 11,
      fontWeight: "600",
      color: theme.textMuted,
    },
    swatchLabelActive: {
      color: theme.accent,
      fontWeight: "700",
    },
    swatchDot: {
      width: 5,
      height: 5,
      borderRadius: 3,
      backgroundColor: theme.accent,
    },
  });
}
