import { type SQLiteDatabase } from "expo-sqlite";
import { enqueue } from "@/lib/sync-queue";

export type HighlightInput = {
  user_id: string;
  version_id: number;
  book: string;
  chapter: number;
  verse: number;
  color: string;
};

export async function addHighlight(
  db: SQLiteDatabase,
  userId: string,
  highlight: HighlightInput,
) {
  const existing = await db.getFirstSync<{ id: number }>(
    `SELECT id FROM highlights
     WHERE user_id = ? AND version_id = ? AND book = ? AND chapter = ? AND verse = ?`,
    [userId, highlight.version_id, highlight.book, highlight.chapter, highlight.verse],
  );

  if (existing) {
    await db.runAsync(
      `UPDATE highlights SET color = ? WHERE id = ?`,
      [highlight.color, existing.id],
    );
    await enqueue(db, "highlights", String(existing.id), "update", {
      ...highlight,
      id: existing.id,
    });
    return existing.id;
  }

  const result = await db.runAsync(
    `INSERT INTO highlights (user_id, version_id, book, chapter, verse, color)
     VALUES (?, ?, ?, ?, ?, ?)`,
    [userId, highlight.version_id, highlight.book, highlight.chapter, highlight.verse, highlight.color],
  );
  const newId = result.lastInsertRowId;
  await enqueue(db, "highlights", String(newId), "insert", {
    ...highlight,
    id: newId,
  });
  return newId;
}

export async function removeHighlight(
  db: SQLiteDatabase,
  userId: string,
  versionId: number,
  book: string,
  chapter: number,
  verse: number,
) {
  const existing = await db.getFirstSync<{ id: number }>(
    `SELECT id FROM highlights
     WHERE user_id = ? AND version_id = ? AND book = ? AND chapter = ? AND verse = ?`,
    [userId, versionId, book, chapter, verse],
  );

  if (existing) {
    await db.runAsync(`DELETE FROM highlights WHERE id = ?`, [existing.id]);
    await enqueue(db, "highlights", String(existing.id), "delete", { id: existing.id });
  }
}

export async function getHighlightsForChapter(
  db: SQLiteDatabase,
  userId: string,
  versionId: number,
  book: string,
  chapter: number,
): Promise<Map<number, string>> {
  const rows = await db.getAllSync<{ verse: number; color: string }>(
    `SELECT verse, color FROM highlights
     WHERE user_id = ? AND version_id = ? AND book = ? AND chapter = ?`,
    [userId, versionId, book, chapter],
  );
  const map = new Map<number, string>();
  for (const r of rows) map.set(r.verse, r.color);
  return map;
}

export async function addBookmark(
  db: SQLiteDatabase,
  userId: string,
  book: string,
  chapter: number,
  verse: number,
  note: string = "",
) {
  const result = await db.runAsync(
    `INSERT INTO bookmarks (user_id, book, chapter, verse, note)
     VALUES (?, ?, ?, ?, ?)`,
    [userId, book, chapter, verse, note],
  );
  const newId = result.lastInsertRowId;
  await enqueue(db, "bookmarks", String(newId), "insert", {
    id: newId,
    user_id: userId,
    book,
    chapter,
    verse,
    note,
  });
  return newId;
}

export async function removeBookmark(
  db: SQLiteDatabase,
  bookmarkId: number,
) {
  await db.runAsync(`DELETE FROM bookmarks WHERE id = ?`, [bookmarkId]);
  await enqueue(db, "bookmarks", String(bookmarkId), "delete", { id: bookmarkId });
}

export async function getBookmarksForChapter(
  db: SQLiteDatabase,
  userId: string,
  book: string,
  chapter: number,
): Promise<{ id: number; verse: number; note: string }[]> {
  return db.getAllSync<{ id: number; verse: number; note: string }>(
    `SELECT id, verse, note FROM bookmarks
     WHERE user_id = ? AND book = ? AND chapter = ?`,
    [userId, book, chapter],
  );
}

export async function isBookmarked(
  db: SQLiteDatabase,
  userId: string,
  book: string,
  chapter: number,
  verse: number,
): Promise<boolean> {
  const row = await db.getFirstSync<{ id: number }>(
    `SELECT id FROM bookmarks
     WHERE user_id = ? AND book = ? AND chapter = ? AND verse = ?`,
    [userId, book, chapter, verse],
  );
  return !!row;
}

export type BookmarkRow = {
  id: number;
  book: string;
  chapter: number;
  verse: number;
  note: string;
  created_at: string;
};

export async function getAllBookmarks(
  db: SQLiteDatabase,
  userId: string,
): Promise<BookmarkRow[]> {
  return db.getAllSync<BookmarkRow>(
    `SELECT id, book, chapter, verse, note, created_at FROM bookmarks
     WHERE user_id = ?
     ORDER BY created_at DESC, id DESC`,
    [userId],
  );
}

export async function updateBookmarkNote(
  db: SQLiteDatabase,
  bookmarkId: number,
  note: string,
) {
  await db.runAsync(`UPDATE bookmarks SET note = ? WHERE id = ?`, [note, bookmarkId]);
  const row = await db.getFirstSync<{
    user_id: string;
    book: string;
    chapter: number;
    verse: number;
  }>(`SELECT user_id, book, chapter, verse FROM bookmarks WHERE id = ?`, [bookmarkId]);
  await enqueue(db, "bookmarks", String(bookmarkId), "update", {
    id: bookmarkId,
    ...(row ?? {}),
    note,
  });
}
