import { CLUBS } from "@/constants/clubs";
import { colors } from "@/constants/colors";
import { appStorage } from "@/services/app-storage";

const CLUB_THEME_SLUGS = [
  "sprout",
  "sprout-kids",
  "sprout-tweens",
  "sprout-teens",
  "surge",
  "pulse",
  "prime",
  "anchor",
  "spark",
  "synergy",
] as const;

export type ClubThemeKey = (typeof CLUB_THEME_SLUGS)[number];
export type ChatThemeKey = "club" | "relate" | "night" | ClubThemeKey;
export type ChatBackgroundKey =
  | "signal"
  | "grid"
  | "doodles"
  | "waves"
  | "speckle"
  | "plain";

export type ChatAppearance = {
  theme: ChatThemeKey;
  background: ChatBackgroundKey;
};

export type ChatPalette = {
  key: ChatThemeKey;
  accent: string;
  accentDeep: string;
  accentSoft: string;
  accentFaint: string;
  mineFrom: string;
  mineTo: string;
  mineText: string;
  background: string;
  pattern: string;
  surface: string;
  surfaceAlt: string;
  text: string;
  textMuted: string;
  border: string;
  headerBg: string;
  headerText: string;
  headerMuted: string;
  headerIconBg: string;
  headerIconText: string;
  composerBg: string;
  fieldBg: string;
  fieldText: string;
  placeholder: string;
  sendBg: string;
  sendText: string;
  sendDisabledBg: string;
  sendDisabledText: string;
  inlineIcon: string;
  reactionBg: string;
  reactionActiveBg: string;
  reactionActiveText: string;
  backdrop: string;
  cardBg: string;
  statusBar: "light" | "dark";
};

export type ChatThemeOption = {
  key: ChatThemeKey;
  label: string;
  description: string;
  swatch: string;
};

export type ChatBackgroundOption = {
  key: ChatBackgroundKey;
  label: string;
  description: string;
};

const THEME_KEY = "club_chat_theme";
const BACKGROUND_KEY = "club_chat_background";

export const DEFAULT_CHAT_APPEARANCE: ChatAppearance = {
  theme: "club",
  background: "signal",
};

function clubColor(slug: ClubThemeKey) {
  return CLUBS.find((club) => club.slug === slug)?.colorDark || colors.gold;
}

export const CHAT_THEME_OPTIONS: ChatThemeOption[] = [
  {
    key: "club",
    label: "My club",
    description: "Uses your club's colour",
    swatch: colors.gold,
  },
  ...CLUB_THEME_SLUGS.map((slug) => {
    const club = CLUBS.find((item) => item.slug === slug);
    return {
      key: slug,
      label: club?.name || slug,
      description: `${club?.name || slug} colour`,
      swatch: club?.colorDark || colors.gold,
    };
  }),
  {
    key: "relate",
    label: "Relate",
    description: "Navy and cyan",
    swatch: colors.gold,
  },
  {
    key: "night",
    label: "Night",
    description: "Low-light chat",
    swatch: "#07111E",
  },
];

export const CHAT_BACKGROUND_OPTIONS: ChatBackgroundOption[] = [
  {
    key: "signal",
    label: "Signal",
    description: "Faint club arcs",
  },
  {
    key: "grid",
    label: "Grid",
    description: "Quiet graph paper",
  },
  {
    key: "doodles",
    label: "Doodles",
    description: "Hand-drawn chat marks",
  },
  {
    key: "waves",
    label: "Waves",
    description: "Soft flowing curves",
  },
  {
    key: "speckle",
    label: "Speckle",
    description: "Scattered quiet dots",
  },
  {
    key: "plain",
    label: "Plain",
    description: "No pattern",
  },
];

function parseHex(color: string) {
  const value = color.trim().replace("#", "");
  const full =
    value.length === 3
      ? value
          .split("")
          .map((ch) => ch + ch)
          .join("")
      : value;
  if (!/^[0-9a-f]{6}$/i.test(full)) return null;
  return {
    r: parseInt(full.slice(0, 2), 16),
    g: parseInt(full.slice(2, 4), 16),
    b: parseInt(full.slice(4, 6), 16),
  };
}

function withAlpha(color: string, alpha: number) {
  const rgb = parseHex(color);
  if (!rgb) return color;
  return `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${alpha})`;
}

function mixHex(color: string, target: string, amount: number) {
  const from = parseHex(color);
  const to = parseHex(target);
  if (!from || !to) return color;
  const channel = (a: number, b: number) =>
    Math.round(a + (b - a) * amount)
      .toString(16)
      .padStart(2, "0");
  return `#${channel(from.r, to.r)}${channel(from.g, to.g)}${channel(from.b, to.b)}`;
}

function contrastText(color: string) {
  const rgb = parseHex(color);
  if (!rgb) return colors.white;
  const luminance = (0.299 * rgb.r + 0.587 * rgb.g + 0.114 * rgb.b) / 255;
  return luminance > 0.5 ? colors.ink : colors.white;
}

function isValidColor(color: string) {
  return /^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(color.trim());
}

function isThemeKey(value: string | null): value is ChatThemeKey {
  return CHAT_THEME_OPTIONS.some((option) => option.key === value);
}

function isBackgroundKey(value: string | null): value is ChatBackgroundKey {
  return CHAT_BACKGROUND_OPTIONS.some((option) => option.key === value);
}

function lightPalette(accent: string, background?: string): ChatPalette {
  const accentDeep = mixHex(accent, "#000000", 0.22);
  const onAccent = contrastText(accent);
  const bg = background || mixHex(accent, "#FFFFFF", 0.95);
  return {
    key: "club",
    accent,
    accentDeep,
    accentSoft: withAlpha(accent, 0.14),
    accentFaint: withAlpha(accent, 0.06),
    mineFrom: mixHex(accent, "#FFFFFF", 0.12),
    mineTo: accentDeep,
    mineText: onAccent,
    background: bg,
    pattern: withAlpha(accent, 0.12),
    surface: colors.white,
    surfaceAlt: mixHex(accent, "#FFFFFF", 0.975),
    text: colors.ink,
    textMuted: colors.muted,
    border: colors.border,
    headerBg: bg,
    headerText: colors.ink,
    headerMuted: colors.muted,
    headerIconBg: accent,
    headerIconText: onAccent,
    composerBg: colors.white,
    fieldBg: colors.bg,
    fieldText: colors.ink,
    placeholder: colors.gray[400],
    sendBg: accent,
    sendText: onAccent,
    sendDisabledBg: colors.gray[200],
    sendDisabledText: colors.gray[500],
    inlineIcon: accentDeep,
    reactionBg: colors.white,
    reactionActiveBg: withAlpha(accent, 0.14),
    reactionActiveText: accentDeep,
    backdrop: "rgba(11,25,44,0.48)",
    cardBg: colors.white,
    statusBar: "dark",
  };
}

export async function getChatAppearance(): Promise<ChatAppearance> {
  try {
    const [theme, background] = await Promise.all([
      appStorage.getItemAsync(THEME_KEY),
      appStorage.getItemAsync(BACKGROUND_KEY),
    ]);
    return {
      theme: isThemeKey(theme) ? theme : DEFAULT_CHAT_APPEARANCE.theme,
      background: isBackgroundKey(background)
        ? background
        : DEFAULT_CHAT_APPEARANCE.background,
    };
  } catch {
    return DEFAULT_CHAT_APPEARANCE;
  }
}

export async function setChatTheme(theme: ChatThemeKey): Promise<void> {
  await appStorage.setItemAsync(THEME_KEY, theme);
}

export async function setChatBackground(
  background: ChatBackgroundKey,
): Promise<void> {
  await appStorage.setItemAsync(BACKGROUND_KEY, background);
}

export function resolveChatPalette(
  theme: ChatThemeKey,
  clubColorValue: string,
): ChatPalette {
  if (theme === "night") {
    return {
      key: "night",
      accent: colors.gold,
      accentDeep: colors.goldDark,
      accentSoft: withAlpha(colors.gold, 0.16),
      accentFaint: withAlpha(colors.gold, 0.07),
      mineFrom: colors.gold,
      mineTo: colors.goldDark,
      mineText: "#07111E",
      background: "#07111E",
      pattern: withAlpha(colors.goldLight, 0.1),
      surface: "#13233B",
      surfaceAlt: "#0E1C2F",
      text: "#E8F2F7",
      textMuted: "#93A8BD",
      border: "#24344A",
      headerBg: "#07111E",
      headerText: colors.white,
      headerMuted: "rgba(232,242,247,0.68)",
      headerIconBg: colors.gold,
      headerIconText: "#07111E",
      composerBg: "#0B192C",
      fieldBg: "#13233B",
      fieldText: "#E8F2F7",
      placeholder: "#6F8499",
      sendBg: colors.gold,
      sendText: "#07111E",
      sendDisabledBg: "#24344A",
      sendDisabledText: "#6F8499",
      inlineIcon: colors.goldLight,
      reactionBg: "#13233B",
      reactionActiveBg: withAlpha(colors.gold, 0.2),
      reactionActiveText: colors.goldLight,
      backdrop: "rgba(0,0,0,0.64)",
      cardBg: "#13233B",
      statusBar: "light",
    };
  }

  if (theme === "relate") {
    return {
      ...lightPalette(colors.gold, "#F3F8FB"),
      key: "relate",
      mineTo: "#0284C7",
    };
  }

  if (theme === "club") {
    const accent = isValidColor(clubColorValue)
      ? clubColorValue
      : colors.gold;
    return lightPalette(accent);
  }

  return { ...lightPalette(clubColor(theme)), key: theme };
}
