/**
 * Cloudinary uploads + URL optimization for public media (avatars, event
 * banners, group covers, proofs-of-payment).
 *
 * Uploads are unsigned: the device posts the image straight to Cloudinary
 * with the public preset, so no API key or secret ever ships in the bundle.
 * The returned `secure_url` is what gets persisted through the backend —
 * Supabase/Postgres only ever holds the URL string, never the file. This
 * module replaces the Supabase Storage helpers that used to live in
 * `services/supabase.ts`.
 */

export const CLOUDINARY_CLOUD_NAME =
  process.env.EXPO_PUBLIC_CLOUDINARY_CLOUD_NAME || "";
export const CLOUDINARY_UPLOAD_PRESET =
  process.env.EXPO_PUBLIC_CLOUDINARY_UPLOAD_PRESET || "";

export const isCloudinaryConfigured = !!(
  CLOUDINARY_CLOUD_NAME && CLOUDINARY_UPLOAD_PRESET
);

/** A picked image. Matches the useful fields of an expo-image-picker asset. */
export interface UploadImageSource {
  uri: string;
  /** Base64-encoded image bytes (without the `data:` prefix). */
  base64?: string | null;
  /** MIME type of the image, e.g. `image/jpeg`. */
  mimeType?: string;
}

/** Resolve a valid image MIME type from the asset or the file extension. */
function resolveContentType(source: UploadImageSource): string {
  if (source.mimeType?.startsWith("image/")) return source.mimeType;
  const ext = source.uri.split(".").pop()?.split("?")[0]?.toLowerCase() || "jpg";
  switch (ext) {
    case "png":
      return "image/png";
    case "webp":
      return "image/webp";
    case "gif":
      return "image/gif";
    case "heic":
      return "image/heic";
    case "heif":
      return "image/heif";
    default:
      return "image/jpeg";
  }
}

/**
 * Upload a picked image straight to Cloudinary and return its secure URL.
 * Prefers the base64 payload (all pickers run with `base64: true`) because a
 * data URI needs no file-system read; falls back to the local file URI.
 * Throws on missing configuration or a Cloudinary rejection so callers
 * surface a real error instead of persisting a broken local link.
 */
export async function uploadToCloudinary(
  source: UploadImageSource,
  folder: string,
): Promise<string> {
  if (!isCloudinaryConfigured) {
    throw new Error(
      "Image uploads are not configured — set EXPO_PUBLIC_CLOUDINARY_CLOUD_NAME and EXPO_PUBLIC_CLOUDINARY_UPLOAD_PRESET.",
    );
  }

  const mime = resolveContentType(source);
  const body = new FormData();
  if (source.base64) {
    body.append("file", `data:${mime};base64,${source.base64}`);
  } else {
    const ext = mime.split("/")[1]?.replace("jpeg", "jpg") || "jpg";
    body.append("file", {
      uri: source.uri,
      name: `image.${ext}`,
      type: mime,
    } as any);
  }
  body.append("upload_preset", CLOUDINARY_UPLOAD_PRESET);
  body.append("folder", folder);

  const res = await fetch(
    `https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/image/upload`,
    { method: "POST", body },
  );
  const json = await res.json().catch(() => null);
  if (!res.ok || typeof json?.secure_url !== "string") {
    throw new Error(json?.error?.message || "Upload failed.");
  }
  return json.secure_url as string;
}

/**
 * Upload an image for a community event. The returned URL is stored on the
 * backend (see /api/community/events) so other users can view it.
 */
export function uploadEventImage(source: UploadImageSource): Promise<string> {
  return uploadToCloudinary(source, "relate/events");
}

/**
 * Upload an icon/cover image for a group. The returned URL is stored on the
 * group (see /api/community/groups) and also shown in the home "What's new"
 * rail (DiscoverRail) as the group card's cover.
 */
export function uploadGroupImage(source: UploadImageSource): Promise<string> {
  return uploadToCloudinary(source, "relate/groups");
}

/**
 * Upload a proof-of-payment image for an event registration. The returned URL
 * is stored on the registration (see /api/community/events/[id]/payments) and
 * viewed by the event owner/admin to verify payment.
 */
export function uploadEventPop(source: UploadImageSource): Promise<string> {
  return uploadToCloudinary(source, "relate/pops");
}

/**
 * Upload a proof-of-payment image for a sponsorship pledge. The returned URL
 * is stored on the sponsorship (see /api/sponsorships) and viewed by admins
 * in the financial report.
 */
export function uploadSponsorPop(source: UploadImageSource): Promise<string> {
  return uploadToCloudinary(source, "relate/pops");
}

/**
 * Upload a profile picture. The returned URL is persisted on the backend's
 * user record (see /api/profile/image) so it shows across devices.
 */
export function uploadProfileImage(source: UploadImageSource): Promise<string> {
  return uploadToCloudinary(source, "relate/avatars");
}

/** A merchandise cover or gallery image published by an admin. */
export function uploadStoreImage(source: UploadImageSource): Promise<string> {
  return uploadToCloudinary(source, "relate/store");
}

/** An image shared in a club chat message; the URL is stored in Supabase. */
export function uploadChatImage(source: UploadImageSource): Promise<string> {
  return uploadToCloudinary(source, "relate/club-chat");
}

/** A cover image for an officer or position training. */
export function uploadTrainingImage(source: UploadImageSource): Promise<string> {
  return uploadToCloudinary(source, "relate/trainings");
}

/**
 * Upload school proof (school ID / report card / enrollment letter / fee
 * invoice) for a school grant application. The returned URL is stored on the
 * application and viewed by admins during review.
 */
export function uploadSchoolProof(source: UploadImageSource): Promise<string> {
  return uploadToCloudinary(source, "relate/grants");
}

/**
 * Upload proof for a curriculum module deliverable (CV screenshot, budget
 * map, signed pledge photo, sleep log, …). The URL is stored on the module's
 * `module_progress` row via POST /api/skills/<skillId>/modules.
 */
export function uploadSkillDeliverable(source: UploadImageSource): Promise<string> {
  return uploadToCloudinary(source, "relate/deliverables");
}

const UPLOAD_MARK = "/image/upload/";

/**
 * Append `w_{width},f_auto,q_auto` to a Cloudinary URL so image views fetch
 * a screen-sized WebP/AVIF instead of the multi-megabyte original — the main
 * defence against out-of-memory crashes on 2 GB devices. Non-Cloudinary URLs
 * (Supabase, Unsplash, relateworld.org) and URLs that already carry a
 * transformation pass through untouched, so it is safe to wrap any source.
 */
export function getOptimizedImageUrl(url: string, width: number): string;
export function getOptimizedImageUrl(
  url: string | null | undefined,
  width: number,
): string | null | undefined;
export function getOptimizedImageUrl(
  url: string | null | undefined,
  width: number,
): string | null | undefined {
  if (!url || !url.includes(UPLOAD_MARK)) return url;
  const markerAt = url.indexOf(UPLOAD_MARK);
  const rest = url.slice(markerAt + UPLOAD_MARK.length);
  const firstSegment = rest.split("/")[0] ?? "";
  // A transform chain like "w_300,c_fill" has no dot and does have a
  // component separator — leave those alone so the helper stays idempotent.
  if (firstSegment && !firstSegment.includes(".") && firstSegment.includes("_")) {
    return url;
  }
  return url.replace(UPLOAD_MARK, `${UPLOAD_MARK}w_${width},f_auto,q_auto/`);
}
