import { cachedFetch, SHORT_TTL, type CachedFetchOptions } from "./cache";

/**
 * School Kit — stationery stock ledger and learner allocations for the
 * education team. Everything is derived from one movement ledger, so stock,
 * usage and renewals never disagree.
 */

export type KitItemKey = "book" | "pencil" | "pen";
export type KitMovementKind = "opening" | "restock" | "issue" | "adjustment";
export type DueState = "none" | "ok" | "due" | "overdue";

export type KitItemStock = {
  opening: number;
  received: number;
  issued: number;
  adjusted: number;
  stock: number;
};

export type KitMovement = {
  _id: string;
  kind: KitMovementKind;
  item: KitItemKey;
  qty: number;
  date: string;
  amount: number;
  unitCost: number | null;
  memberId: string | null;
  memberName: string | null;
  clubSlug: string | null;
  swapVerified: boolean;
  note: string;
};

export type LearnerKitItem = {
  qty: number;
  lastIssued: string | null;
  dueFrom: string | null;
  dueTo: string | null;
  state: DueState;
  renewedWith: boolean;
};

export type LearnerKit = {
  id: string;
  name: string;
  clubSlug: string;
  clubName: string;
  age: number | null;
  userId: string | null;
  items: Record<KitItemKey, LearnerKitItem>;
  nextDue: string | null;
  dueState: DueState;
  examCheckedAt: string | null;
};

export type KitMonth = {
  key: string;
  label: string;
  issued: Record<KitItemKey, number>;
  restocked: Record<KitItemKey, number>;
  spend: number;
};

export type KitOverview = {
  season: number;
  seasons: number[];
  asOf: string;
  items: Record<KitItemKey, KitItemStock>;
  totals: {
    learnersServed: number;
    dueSoon: number;
    overdue: number;
    spend: number;
  };
  months: KitMonth[];
  clubs: { clubSlug: string; clubName: string; issued: number }[];
  dueList: {
    memberId: string;
    name: string;
    clubSlug: string;
    item: KitItemKey;
    dueState: DueState;
    dueTo: string | null;
  }[];
};

export const KIT_ITEMS: Record<
  KitItemKey,
  { name: string; short: string; unit: string; weeks: string }
> = {
  book: {
    name: "32-page A4 exercise book",
    short: "Exercise books",
    unit: "books",
    weeks: "renew every 4–8 weeks",
  },
  pencil: {
    name: "HB pencil",
    short: "HB pencils",
    unit: "pencils",
    weeks: "renew every 3–4 weeks",
  },
  pen: {
    name: "Ballpoint pen",
    short: "Ballpoint pens",
    unit: "pens",
    weeks: "renew every 4–6 weeks",
  },
};

export const KIT_ITEM_KEYS: KitItemKey[] = ["book", "pencil", "pen"];

export const DUE_LABELS: Record<DueState, string> = {
  overdue: "Renewal overdue",
  due: "Due for renewal",
  ok: "Up to date",
  none: "Not issued yet",
};

function kitFetch<T>(path: string, options: CachedFetchOptions = {}): Promise<T> {
  return cachedFetch<T>(path, options, ["/api/admin/school-kit"]);
}

export const schoolKitApi = {
  overview: (season?: number) =>
    kitFetch<{ data: KitOverview }>(
      `/api/admin/school-kit/overview${season ? `?season=${season}` : ""}`,
      { cacheTtl: SHORT_TTL },
    ),

  learners: (query: string, season?: number) => {
    const params = new URLSearchParams();
    if (query.trim()) params.set("q", query.trim());
    if (season) params.set("season", String(season));
    const qs = params.toString();
    return kitFetch<{ data: LearnerKit[] }>(
      `/api/admin/school-kit/learners${qs ? `?${qs}` : ""}`,
      { cacheTtl: SHORT_TTL },
    );
  },

  learner: (id: string, season?: number) =>
    kitFetch<{ data: { learner: LearnerKit; history: KitMovement[] } }>(
      `/api/admin/school-kit/learners/${id}${season ? `?season=${season}` : ""}`,
      { cacheTtl: 0 },
    ),

  movements: (season?: number, limit = 80) => {
    const params = new URLSearchParams({ limit: String(limit) });
    if (season) params.set("season", String(season));
    return kitFetch<{ data: KitMovement[] }>(
      `/api/admin/school-kit/movements?${params.toString()}`,
      { cacheTtl: 0 },
    );
  },

  recordMovement: (input: {
    kind: Exclude<KitMovementKind, "issue">;
    item: KitItemKey;
    qty: number;
    amount?: number;
    date?: string;
    note?: string;
  }) =>
    kitFetch<{ success: boolean; data: { stock: Record<KitItemKey, KitItemStock>; movements: KitMovement[] } }>(
      "/api/admin/school-kit/movements",
      { method: "POST", body: JSON.stringify(input) },
    ),

  updateMovement: (
    id: string,
    input: {
      item: KitItemKey;
      qty: number;
      amount?: number;
      date?: string;
      note?: string;
    },
  ) =>
    kitFetch<{ success: boolean; data: { stock: Record<KitItemKey, KitItemStock>; movements: KitMovement[]; season: number } }>(
      `/api/admin/school-kit/movements/${id}`,
      { method: "PATCH", body: JSON.stringify(input) },
    ),

  removeMovement: (id: string) =>
    kitFetch<{ success: boolean; data: { stock: Record<KitItemKey, KitItemStock>; movements: KitMovement[]; season: number } }>(
      `/api/admin/school-kit/movements/${id}`,
      { method: "DELETE" },
    ),

  allocate: (input: {
    memberIds: string[];
    items: { item: KitItemKey; qty: number }[];
    swapVerified?: boolean;
    date?: string;
    note?: string;
  }) =>
    kitFetch<{ success: boolean; data: { issued: number; stock: Record<KitItemKey, KitItemStock> } }>(
      "/api/admin/school-kit/allocations",
      { method: "POST", body: JSON.stringify(input) },
    ),

  setExamCheck: (id: string, checked: boolean, season: number) =>
    kitFetch<{ success: boolean }>(
      `/api/admin/school-kit/learners/${id}/exam-check`,
      { method: "POST", body: JSON.stringify({ checked, season }) },
    ),
};