import { Ionicons } from "@expo/vector-icons";
import { Image } from "expo-image";
import * as ImagePicker from "expo-image-picker";
import { router } from "expo-router";
import { useEffect, useState } from "react";
import {
  ActivityIndicator,
  Pressable,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import type { Skill } from "@/constants/skills";
import { getSession, type Session } from "@/services/auth";
import { moduleProgressApi } from "@/services/skills-progress";
import type { ModuleProgress } from "@/services/skills-catalog";

type RowMap = Record<string, ModuleProgress | undefined>;

/**
 * The curriculum-module tracker shown on skill detail screens that carry
 * `skill.modules` (Pulse's four tracks and Prime's Smart Saver). Each module
 * can be marked complete and has a practical deliverable that members prove
 * by attaching a photo — saved to `module_progress` through
 * GET/POST /api/skills/<skillId>/modules.
 */
export default function ModuleTracker({
  skill,
  clubSlug,
  kickerColor,
}: {
  skill: Skill;
  clubSlug: string;
  kickerColor?: string;
}) {
  const modules = skill.modules ?? [];
  const [session, setSession] = useState<Session | null | undefined>(undefined);
  const [rows, setRows] = useState<RowMap>({});
  const [loadedFor, setLoadedFor] = useState<string | null>(null);
  const [savingId, setSavingId] = useState<string | null>(null);
  const [uploadingId, setUploadingId] = useState<string | null>(null);
  const [error, setError] = useState("");
  const user = session?.user ?? null;

  useEffect(() => {
    let cancelled = false;
    getSession()
      .then((s) => {
        if (!cancelled) setSession(s);
      })
      .catch(() => {
        if (!cancelled) setSession(null);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!user) return;
    let cancelled = false;
    moduleProgressApi
      .list(skill.id)
      .then((list) => {
        if (cancelled) return;
        const map: RowMap = {};
        for (const row of list) map[row.moduleId] = row;
        setRows(map);
        setLoadedFor(user.id);
      })
      .catch(() => {
        if (cancelled) return;
        setRows({});
        setLoadedFor(user.id);
      });
    return () => {
      cancelled = true;
    };
  }, [user, skill.id]);

  async function toggleComplete(mod: (typeof modules)[number]) {
    const prev = rows[mod.id];
    const nextCompleted = !(prev?.completed ?? false);
    setSavingId(mod.id);
    setError("");
    setRows((r) => ({
      ...r,
      [mod.id]: {
        ...prev,
        moduleId: mod.id,
        completed: nextCompleted,
        deliverableSubmitted: prev?.deliverableSubmitted ?? false,
        deliverableUrl: prev?.deliverableUrl ?? null,
      },
    }));
    try {
      const saved = await moduleProgressApi.save(skill.id, {
        moduleId: mod.id,
        completed: nextCompleted,
      });
      setRows((r) => ({ ...r, [mod.id]: saved }));
    } catch (err) {
      setRows((r) => {
        const next = { ...r };
        if (prev) next[mod.id] = prev;
        else delete next[mod.id];
        return next;
      });
      setError((err as Error).message);
    } finally {
      setSavingId(null);
    }
  }

  async function attachDeliverable(mod: (typeof modules)[number]) {
    setSavingId(mod.id);
    setError("");
    try {
      const perm = await ImagePicker.requestMediaLibraryPermissionsAsync();
      if (!perm.granted) {
        setError("Photo access is needed to attach your deliverable.");
        return;
      }
      setUploadingId(mod.id);
      const result = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ["images"],
        allowsEditing: true,
        quality: 0.7,
        base64: true,
      });
      if (result.canceled || !result.assets?.length) return;
      const asset = result.assets[0];
      const { uploadSkillDeliverable } = await import("@/services/cloudinary");
      const url = await uploadSkillDeliverable({
        uri: asset.uri,
        base64: asset.base64 ?? null,
        mimeType: asset.mimeType,
      });
      const saved = await moduleProgressApi.save(skill.id, {
        moduleId: mod.id,
        deliverableUrl: url,
        deliverableSubmitted: true,
      });
      setRows((r) => ({ ...r, [mod.id]: saved }));
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setUploadingId(null);
      setSavingId(null);
    }
  }

  const done = modules.filter((m) => rows[m.id]?.completed).length;
  const pct = modules.length ? Math.round((done / modules.length) * 100) : 0;
  const kicker = { color: kickerColor ?? colors.gray[400] };

  if (session === undefined || (user && loadedFor !== user.id)) {
    return (
      <View style={m.card}>
        <View style={m.loadingRow}>
          <ActivityIndicator size="small" color={colors.goldDark} />
          <Text style={m.loadingText}>Loading modules…</Text>
        </View>
      </View>
    );
  }

  if (!user) {
    return (
      <View style={m.card}>
        <Text style={[m.kicker, kicker]}>Modules</Text>
        <Text style={m.title}>
          {modules.length} modules — work through them at your own pace
        </Text>

        <View style={m.list}>
          {modules.map((mod) => (
            <View key={mod.id} style={m.modCard}>
              <View style={m.modHead}>
                <View style={m.orderBadge}>
                  <Text style={m.orderBadgeText}>{mod.order}</Text>
                </View>
                <Text style={m.modTitle}>{mod.title}</Text>
              </View>
              <Text style={m.modText}>{mod.description}</Text>
              <Text style={m.modDeliverable}>
                Deliverable: {mod.deliverableDescription}
              </Text>
            </View>
          ))}
        </View>

        <View style={m.signInCard}>
          <View style={m.signInIcon}>
            <Ionicons name="log-in-outline" size={18} color={colors.goldDark} />
          </View>
          <Text style={m.signInTitle}>Track your modules</Text>
          <Text style={m.signInText}>
            Sign in to mark modules complete, attach deliverables, and keep
            your progress with your account.
          </Text>
          <TouchableOpacity
            activeOpacity={0.9}
            style={m.signInBtn}
            onPress={() =>
              router.push({
                pathname: "/login",
                params: { next: `/skills/${clubSlug}/${skill.id}` },
              })
            }
            accessibilityRole="button"
            accessibilityLabel="Sign in to start tracking modules"
          >
            <Ionicons name="log-in-outline" size={15} color={colors.white} />
            <Text style={m.signInBtnText}>Sign in to start</Text>
          </TouchableOpacity>
        </View>
      </View>
    );
  }

  return (
    <View style={m.card}>
      <View style={m.headRow}>
        <View style={{ flex: 1 }}>
          <Text style={[m.kicker, kicker]}>Modules</Text>
          <Text style={m.title}>
            {done} of {modules.length} modules complete
          </Text>
        </View>
        <View
          style={[
            m.statusPill,
            {
              backgroundColor:
                done === modules.length && modules.length > 0
                  ? "rgba(16,185,129,0.14)"
                  : done > 0
                    ? "rgba(19,197,221,0.14)"
                    : colors.bgSoft,
            },
          ]}
        >
          <Text
            style={[
              m.statusPillText,
              {
                color:
                  done === modules.length && modules.length > 0
                    ? colors.emeraldDark
                    : done > 0
                      ? colors.goldDark
                      : colors.muted,
              },
            ]}
          >
            {done === modules.length && modules.length > 0
              ? "Complete"
              : done > 0
                ? "In progress"
                : "Not started"}
          </Text>
        </View>
      </View>

      <View style={m.progressBlock}>
        <View style={m.barTrack}>
          <View
            style={[
              m.barFill,
              {
                width: `${pct}%`,
                backgroundColor:
                  done === modules.length && modules.length > 0
                    ? colors.emerald
                    : colors.gold,
              },
            ]}
          />
        </View>
        <Text style={m.progressText}>
          <Text style={m.strong}>{pct}% complete</Text>
          {"  ·  "}tick each module off as you finish it
        </Text>
      </View>

      <View style={m.list}>
        {modules.map((mod) => {
          const row = rows[mod.id];
          const completed = row?.completed ?? false;
          const submitted = row?.deliverableSubmitted ?? false;
          const statusLabel = completed
            ? "Complete"
            : submitted
              ? "In progress"
              : "Not started";
          const busy = savingId === mod.id;
          return (
            <View
              key={mod.id}
              style={[m.modCard, completed && m.modCardDone]}
            >
              <View style={m.modHead}>
                <View style={m.orderBadge}>
                  <Text style={m.orderBadgeText}>{mod.order}</Text>
                </View>
                <Text style={m.modTitle}>{mod.title}</Text>
                <View
                  style={[
                    m.modPill,
                    {
                      backgroundColor: completed
                        ? "rgba(16,185,129,0.14)"
                        : submitted
                          ? "rgba(19,197,221,0.14)"
                          : colors.bgSoft,
                    },
                  ]}
                >
                  <Text
                    style={[
                      m.modPillText,
                      {
                        color: completed
                          ? colors.emeraldDark
                          : submitted
                            ? colors.goldDark
                            : colors.muted,
                      },
                    ]}
                  >
                    {statusLabel}
                  </Text>
                </View>
              </View>

              <Text style={m.modText}>{mod.description}</Text>

              <View style={m.modMeta}>
                <Ionicons
                  name="time-outline"
                  size={13}
                  color={colors.gray[400]}
                />
                <Text style={m.modMetaText}>≈ {mod.durationMinutes} min</Text>
              </View>

              <View style={m.deliverableBox}>
                <Text style={m.deliverableLabel}>PRACTICAL DELIVERABLE</Text>
                <Text style={m.deliverableText}>
                  {mod.deliverableDescription}
                </Text>

                {row?.deliverableUrl ? (
                  <View style={m.proofRow}>
                    <Image
                      source={{ uri: row.deliverableUrl }}
                      style={m.proofThumb}
                      contentFit="cover"
                    />
                    <View style={{ flex: 1 }}>
                      <Text style={m.proofOk}>Proof attached</Text>
                      <Text style={m.proofHint} numberOfLines={2}>
                        {row.deliverableUrl}
                      </Text>
                    </View>
                  </View>
                ) : null}

                <TouchableOpacity
                  activeOpacity={0.85}
                  style={[m.attachBtn, busy && { opacity: 0.6 }]}
                  disabled={busy}
                  onPress={() => void attachDeliverable(mod)}
                  accessibilityRole="button"
                  accessibilityLabel={`Attach deliverable for ${mod.title}`}
                >
                  {uploadingId === mod.id ? (
                    <ActivityIndicator size="small" color={colors.goldDark} />
                  ) : (
                    <Ionicons
                      name={row?.deliverableUrl ? "image-outline" : "camera-outline"}
                      size={15}
                      color={colors.goldDark}
                    />
                  )}
                  <Text style={m.attachBtnText}>
                    {row?.deliverableUrl
                      ? "Replace photo"
                      : uploadingId === mod.id
                        ? "Uploading…"
                        : "Attach photo proof"}
                  </Text>
                </TouchableOpacity>
              </View>

              <Pressable
                onPress={() => void toggleComplete(mod)}
                disabled={busy}
                style={m.toggleRow}
                accessibilityRole="checkbox"
                accessibilityState={{ checked: completed, disabled: busy }}
                accessibilityLabel={`Mark ${mod.title} complete`}
              >
                <Ionicons
                  name={completed ? "checkbox" : "square-outline"}
                  size={19}
                  color={completed ? colors.emerald : colors.gray[400]}
                />
                <Text
                  style={[
                    m.toggleText,
                    completed && m.toggleTextDone,
                  ]}
                >
                  {completed ? "Module complete" : "Mark module complete"}
                </Text>
                {busy ? (
                  <ActivityIndicator size="small" color={colors.muted} />
                ) : null}
              </Pressable>
            </View>
          );
        })}
      </View>

      {error ? (
        <View style={m.errorBox}>
          <Text style={m.errorText}>{error}</Text>
        </View>
      ) : null}

      {savingId ? (
        <View style={m.savedRow}>
          <ActivityIndicator size="small" color={colors.muted} />
          <Text style={m.savedText}>Saving…</Text>
        </View>
      ) : null}
    </View>
  );
}

