import * as Notifications from "expo-notifications";
import * as Device from "expo-device";
import { Platform } from "react-native";
import { appStorage } from "./app-storage";
import { IS_WEB } from "./config";
import { syncNotificationPreferences } from "./notification-settings";
import { enableWebPush, requestWebPushPermission, sendTestWebPush } from "./web-push";
import { getPrayerSounds } from "./prayer-sounds";
import { playPrayerSound } from "./inapp-sound";
import { AVAILABLE_SOUNDS, getSoundFile } from "@/constants/sounds";
import { verseForDate } from "@/constants/prayer-verses";

export type PrayerName = "dawn" | "sunrise" | "noon" | "afternoon" | "sunset" | "evening";

export type PrayerNotificationInfo = {
  name: PrayerName;
  title: string;
  date: Date;
};

const PRAYER_CHANNEL_IDS: Record<PrayerName, string> = {
  dawn: "prayer-dawn",
  sunrise: "prayer-sunrise",
  noon: "prayer-noon",
  afternoon: "prayer-afternoon",
  sunset: "prayer-sunset",
  evening: "prayer-evening",
};

// Fallback channel used for custom prayers and any name without a dedicated
// channel, so their notifications still get a custom sound instead of the
// device default.
const DEFAULT_CHANNEL_ID = "prayer-default";

// Channel for server pushes (new requests, replies, status changes, ...).
// HIGH importance so Android shows a heads-up banner + plays a sound. The
// backend sends `channelId: "requests"` in every Expo push payload.
export const GENERAL_CHANNEL_ID = "requests";

// Channel for the daily reading reminder (magazine/study-guide nudge). Shares
// the "requests" channel so a single HIGH-importance Android channel covers
// both server pushes and the daily reminder without extra setup.
export const READING_REMINDER_CHANNEL_ID = GENERAL_CHANNEL_ID;

// Tracks the id of the most recently scheduled daily reading reminder so it
// can be replaced without touching prayer notifications.
const READING_REMINDER_ID_KEY = "reading_reminder_id";

/**
 * Schedules (or replaces) the daily reading reminder at the chosen time. Uses
 * a repeating daily trigger — the OS delivers it every day at hour:minute even
 * when the app is closed. Call again to change the time; the previous reminder
 * is cancelled first so it never doubles up.
 */
export async function scheduleReadingReminderNotification(
  hour: number,
  minute: number,
): Promise<string | null> {
  if (IS_WEB) return null;
  try {
    const enabled = await getNotificationsEnabled();
    if (!enabled) return null;

    await cancelReadingReminderNotification();

    const channelId = READING_REMINDER_CHANNEL_ID;
    const id = await Notifications.scheduleNotificationAsync({
      content: {
        title: "Time to read today's magazine",
        body: "Your club reading is waiting — open today's study when you're ready.",
        ...(Platform.OS === "android" ? { channelId } : {}),
        data: { readReminder: true },
      },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.DAILY,
        hour,
        minute,
      },
    });
    await appStorage.setItemAsync(READING_REMINDER_ID_KEY, id);
    return id;
  } catch {
    return null;
  }
}

/** Cancels the scheduled daily reading reminder, leaving prayer alerts intact. */
export async function cancelReadingReminderNotification(): Promise<void> {
  if (IS_WEB) return;
  try {
    const id = await appStorage.getItemAsync(READING_REMINDER_ID_KEY);
    if (id) {
      await Notifications.cancelScheduledNotificationAsync(id);
      await appStorage.deleteItemAsync(READING_REMINDER_ID_KEY);
    }
  } catch {}
}

/** Cancels the reading reminder alongside prayer cancels (master toggle off). */
export async function cancelReadingReminderWithPrayers(): Promise<void> {
  await Promise.all([
    cancelAllPrayerNotifications(),
    cancelReadingReminderNotification(),
    cancelVerseReminderNotifications(),
  ]);
}

// ── Verse of the Day reminders ────────────────────────────────────────
// One short notification per day with that day's verse. A week is scheduled
// ahead (each day a one-shot with its own text) and re-scheduled on every app
// open, so the message always matches the calendar day without a repeating
// trigger showing stale text.
const VERSE_REMINDER_IDS_KEY = "verse_reminder_ids";
const VERSE_REMINDER_DAYS = 7;
const VERSE_REMINDER_HOUR = 7;
const VERSE_REMINDER_MINUTE = 0;

/** Cancels pending verse-of-the-day notifications (prayers and reading stay). */
export async function cancelVerseReminderNotifications(): Promise<void> {
  if (IS_WEB) return;
  try {
    const raw = await appStorage.getItemAsync(VERSE_REMINDER_IDS_KEY);
    if (raw) {
      const ids = JSON.parse(raw);
      if (Array.isArray(ids)) {
        for (const id of ids) {
          if (typeof id === "string") {
            await Notifications.cancelScheduledNotificationAsync(id).catch(
              () => {},
            );
          }
        }
      }
    }
  } catch {}
  try {
    await appStorage.deleteItemAsync(VERSE_REMINDER_IDS_KEY);
  } catch {}
}

/** Schedules (or replaces) the next week of daily verse notifications at 07:00. */
export async function scheduleVerseReminderNotifications(): Promise<void> {
  if (IS_WEB) return;
  try {
    const enabled = await getNotificationsEnabled();
    if (!enabled) return;

    await cancelVerseReminderNotifications();

    const now = new Date();
    const ids: string[] = [];
    for (let offset = 0; offset < VERSE_REMINDER_DAYS; offset++) {
      const day = new Date(now);
      day.setDate(day.getDate() + offset);
      day.setHours(VERSE_REMINDER_HOUR, VERSE_REMINDER_MINUTE, 0, 0);
      if (day.getTime() <= now.getTime()) continue;
      const verse = verseForDate("dawn", day);
      const id = await Notifications.scheduleNotificationAsync({
        content: {
          title: "Verse of the Day",
          body: `"${verse.verse}" — ${verse.ref}`,
          ...(Platform.OS === "android"
            ? { channelId: GENERAL_CHANNEL_ID }
            : {}),
          data: { votdReminder: true },
        },
        trigger: {
          type: Notifications.SchedulableTriggerInputTypes.DATE,
          date: day,
        },
      });
      ids.push(id);
    }
    if (ids.length) {
      await appStorage.setItemAsync(
        VERSE_REMINDER_IDS_KEY,
        JSON.stringify(ids),
      );
    }
  } catch {}
}

// Sound used when a prayer has no matching bundled sound (e.g. custom prayers).
const FALLBACK_SOUND_ID = "dawn";

// ── Prayer notification text ──────────────────────────────────────────
// Inspirational prompts shown at the actual prayer time.
export const PRAYER_PROMPTS: Record<PrayerName, string> = {
  dawn: "It is prayer time. A new day to seek His face",
  sunrise: "It is prayer time. His mercies are new this morning",
  noon: "It is prayer time. Pause and be still with Him",
  afternoon: "It is prayer time. He walks with you through this day",
  sunset: "It is prayer time. Give thanks for the day He gave",
  evening: "It is prayer time. Rest in His peace tonight",
};

// Unique advance-warning bodies (10-min heads-up, each prayer gets its own).
export const ADVANCE_PROMPTS: Record<PrayerName, string> = {
  dawn: "The world is quiet — meet with Him before the day begins.",
  sunrise: "Light is breaking — greet the One who made the sun.",
  noon: "The day is busy — pause now and be still with God.",
  afternoon: "You've come this far — let Him carry what's ahead.",
  sunset: "The day is ending — bring your thanks before the sun sets.",
  evening: "Lay it all down — rest is coming.",
};

const DEFAULT_ADVANCE_PROMPT = "A moment of prayer is near — prepare your heart.";

// Android exposes a channel's sound only as 'default' | 'custom' (never the
// filename), so the app tracks the sound it last configured per channel to
// avoid recreating channels on every schedule. Fresh app starts start empty
// and rebuild once; sound changes flow through updatePrayerChannel/setup.
const _configuredChannelSounds: Record<string, string> = {};

// Recreating a channel resets any per-channel settings the user changed in
// system settings (mute, importance). When a custom sound can't stick (build
// missing the raw file, OEM quirk), retrying on every schedule would thrash
// the channels all day — so failed attempts are bounded per app session.
// Explicit repair (Settings → Fix) resets the counter and tries again.
// NOTE: The limit was removed so channels always attempt to recreate with the
// correct custom sound. On some devices the first setup fails but a retry
// succeeds (e.g. race with channel deletion). Leaving the counter for
// diagnostics only.
const _channelSetupAttempts: Record<string, number> = {};

function channelIdForPrayer(prayer: string): string {
  return PRAYER_CHANNEL_IDS[prayer as PrayerName] || DEFAULT_CHANNEL_ID;
}

function resolveSoundFile(soundId: string): string {
  // Only bundled sounds can actually play — anything else (e.g. a custom
  // prayer key) would silently fall back to the device's default sound.
  const known = AVAILABLE_SOUNDS.some((s) => s.id === soundId);
  return getSoundFile(known ? soundId : FALLBACK_SOUND_ID);
}

async function getUserSoundFileName(name: string): Promise<string> {
  try {
    const sounds = await getPrayerSounds();
    const soundId = (sounds as Record<string, string>)[name] || name;
    const file = resolveSoundFile(soundId);
    if (Platform.OS === "android") return file;
    return `${file}.wav`;
  } catch {
    const file = resolveSoundFile(name);
    if (Platform.OS === "android") return file;
    return `${file}.wav`;
  }
}

const ENABLED_KEY = "notifications_enabled";
let _prayerData: PrayerNotificationInfo[] | null = null;
let _channelsInitialized = false;

export function setPrayerData(data: PrayerNotificationInfo[]) {
  _prayerData = data;
}

export function getPrayerData(): PrayerNotificationInfo[] | null {
  return _prayerData;
}

export async function getNotificationsEnabled(): Promise<boolean> {
  try {
    const val = await appStorage.getItemAsync(ENABLED_KEY);
    if (val === "false") return false;
    // On the PWA the stored flag is only meaningful if the browser has
    // actually granted notification permission; otherwise the switch would
    // show "on" with no push subscription behind it.
    if (IS_WEB) {
      return typeof Notification !== "undefined" && Notification.permission === "granted";
    }
    return true;
  } catch {
    return true;
  }
}

export async function setNotificationsEnabled(enabled: boolean) {
  await appStorage.setItemAsync(ENABLED_KEY, enabled ? "true" : "false");
  if (IS_WEB) await syncNotificationPreferences({ enabled });
}

export async function setupNotificationChannels() {
  if (IS_WEB || Platform.OS !== "android") return;
  let userSounds: Record<string, string> = {};
  try {
    userSounds = await getPrayerSounds();
  } catch {}

  // Recreate a channel only when its sound differs from what we last set.
  // Android channels can't change their sound after creation, so delete + set
  // is required — but it must not run on every schedule (that happens on every
  // tab focus, app resume, hourly refresh and pull-to-refresh).
  //
  // After creating, the channel is read back: Android reports a channel's
  // sound only as 'default' | 'custom', and a failed setup (missing raw
  // resource, OEM quirk) silently leaves it on the device default. We only
  // record the channel as configured once the custom sound actually stuck,
  // so a stale/default channel is retried on the next setup call instead of
  // being accepted silently.
  const ensureChannel = async (channelId: string, name: string, soundFile: string) => {
    if (_configuredChannelSounds[channelId] === soundFile) return;
    _channelSetupAttempts[channelId] = (_channelSetupAttempts[channelId] || 0) + 1;
    try {
      await Notifications.deleteNotificationChannelAsync(channelId);
    } catch {}
    // Use the return value of set() for verification — it reflects the
    // in-process channel (no OS propagation race). A separate get() call
    // may return stale state on Android's async channel manager.
    let ch: Notifications.NotificationChannel | null = null;
    try {
      ch = await Notifications.setNotificationChannelAsync(channelId, {
        name,
        importance: Notifications.AndroidImportance.HIGH,
        ...(soundFile === "default"
          ? {}
          : { sound: soundFile }),
        vibrationPattern: [0, 250, 100, 250],
        enableVibrate: true,
      });
    } catch {}
    if (soundFile === "default" || ch?.sound === "custom") {
      _configuredChannelSounds[channelId] = soundFile;
    } else {
      console.warn(
        `[notifications] Channel ${channelId} did not take custom sound ${soundFile} — will retry.`,
      );
    }
  };

  // One channel per standard prayer, each with its own chosen sound.
  for (const prayer of Object.keys(PRAYER_CHANNEL_IDS) as PrayerName[]) {
    const soundId = userSounds[prayer] || prayer;
    const soundFile = resolveSoundFile(soundId);
    await ensureChannel(
      PRAYER_CHANNEL_IDS[prayer],
      prayer.charAt(0).toUpperCase() + prayer.slice(1),
      soundFile,
    );
  }

  // Fallback channel for custom prayers / anything unmapped.
  await ensureChannel(DEFAULT_CHANNEL_ID, "Prayers", resolveSoundFile(FALLBACK_SOUND_ID));

  // Server pushes (requests, replies, status changes). HIGH importance gives
  // heads-up banners + sound; the backend routes every push here via
  // channelId, so these never fall into a silent default channel.
  await ensureChannel(GENERAL_CHANNEL_ID, "Requests & Replies", "default");

  // Verify the custom sounds actually made it into the build. When they
  // didn't (Expo Go, or a build predating the "sounds" config), Android
  // silently falls back to the device default — the #1 cause of "prayer
  // notifications play the default sound" reports.
  try {
    const status = await getChannelSoundStatus();
    const missing = (Object.keys(status) as PrayerName[]).filter(
      (p) => status[p] === "default",
    );
    if (missing.length) {
      console.warn(
        "[notifications] Custom prayer sounds not available in this build (" +
          missing.join(", ") +
          "). Install a development/production build created after adding the " +
          'expo-notifications "sounds" config — Expo Go and older builds play ' +
          "the default sound for background notifications.",
      );
    }
  } catch {}
}

export async function updatePrayerChannel(prayer: PrayerName) {
  if (IS_WEB || Platform.OS !== "android") return;
  // Force channel recreation when the user changes a sound setting.
  for (const key of Object.keys(_configuredChannelSounds)) {
    delete _configuredChannelSounds[key];
  }
  _channelsInitialized = false;
  await setupNotificationChannels();
  _channelsInitialized = true;
}

/**
 * Forces a full delete + recreate + verify round for every Android channel
 * and reports whether the custom sounds are now actually in use. Use this to
 * self-heal channels left over from an older install (in-place app updates
 * keep the old, default-sound channels until they are recreated).
 */
export async function repairNotificationChannels(): Promise<PrayerSoundStatus> {
  if (IS_WEB) {
    return Object.fromEntries(
      (Object.keys(PRAYER_CHANNEL_IDS) as PrayerName[]).map((prayer) => [prayer, "custom"]),
    ) as PrayerSoundStatus;
  }
  for (const key of Object.keys(_configuredChannelSounds)) {
    delete _configuredChannelSounds[key];
  }
  for (const key of Object.keys(_channelSetupAttempts)) {
    delete _channelSetupAttempts[key];
  }
  _channelsInitialized = false;
  await setupNotificationChannels();
  _channelsInitialized = true;
  return getChannelSoundStatus();
}

export type PrayerSoundStatus = Record<PrayerName, "custom" | "default">;

/**
 * Reads back the Android channels to check whether the bundled custom sounds
 * actually resolved to native raw resources. Reports 'default' when Android
 * fell back to the device default sound — i.e. the installed build has no
 * res/raw sounds (Expo Go, or a build predating the expo-notifications
 * "sounds" config). On iOS the per-notification content.sound always applies,
 * so every prayer reads as 'custom'.
 */
export async function getChannelSoundStatus(): Promise<PrayerSoundStatus> {
  if (IS_WEB) {
    return Object.fromEntries(
      (Object.keys(PRAYER_CHANNEL_IDS) as PrayerName[]).map((prayer) => [prayer, "custom"]),
    ) as PrayerSoundStatus;
  }
  const out = {} as PrayerSoundStatus;
  for (const prayer of Object.keys(PRAYER_CHANNEL_IDS) as PrayerName[]) {
    out[prayer] = "custom";
    if (Platform.OS !== "android") continue;
    try {
      const ch = await Notifications.getNotificationChannelAsync(
        PRAYER_CHANNEL_IDS[prayer],
      );
      out[prayer] = ch?.sound === "custom" ? "custom" : "default";
    } catch {
      // Keep the conservative 'default' reading on errors.
      out[prayer] = "default";
    }
  }
  return out;
}

export async function requestNotificationPermissions(): Promise<boolean> {
  if (IS_WEB) {
    const permission = await requestWebPushPermission();
    if (permission !== "granted") return false;
    return Boolean(await enableWebPush());
  }
  if (!Device.isDevice) {
    return true;
  }
  const { status: existingStatus } = await Notifications.getPermissionsAsync();
  let finalStatus = existingStatus;
  if (existingStatus !== "granted") {
    const { status } = await Notifications.requestPermissionsAsync();
    finalStatus = status;
  }
  return finalStatus === "granted";
}

export async function cancelAllPrayerNotifications() {
  if (IS_WEB) return;
  await Notifications.cancelAllScheduledNotificationsAsync();
}

async function schedulePrayerNotification(
  prayer: string,
  title: string,
  date: Date,
  advanceMinutes: number,
  userName: string,
): Promise<string[]> {
  const ids: string[] = [];
  const channelId = channelIdForPrayer(prayer);
  const sound = await getUserSoundFileName(prayer);
  const isCustomPrayer = !PRAYER_PROMPTS[prayer as PrayerName];
  const prayerKey = prayer as PrayerName;

  const nowMs = Date.now();

  // ── Advance warning notification ──
  // Only warn within the next 24h: the schedule window spans several days and
  // advance notices for every prayer in it would blow past iOS's cap of 64
  // pending local notifications.
  if (advanceMinutes > 0) {
    const advanceMs = date.getTime() - advanceMinutes * 60_000 - nowMs;
    if (advanceMs > 0 && advanceMs <= 24 * 60 * 60 * 1000) {
      const advanceDate = new Date(date.getTime() - advanceMinutes * 60_000);
      const body = isCustomPrayer
        ? DEFAULT_ADVANCE_PROMPT
        : ADVANCE_PROMPTS[prayerKey] || DEFAULT_ADVANCE_PROMPT;
      const advanceId = await Notifications.scheduleNotificationAsync({
        content: {
          title: `Prayer in ${advanceMinutes} min`,
          body,
          sound,
          ...(Platform.OS === "android" ? { channelId } : {}),
          data: { prayer, advance: true },
        },
        trigger: {
          type: Notifications.SchedulableTriggerInputTypes.DATE,
          date: advanceDate,
        },
      });
      ids.push(advanceId);
    }
  }

  // ── Actual prayer-time notification ──
  if (date.getTime() > nowMs) {
    const greeting = isCustomPrayer
      ? "It is prayer time."
      : PRAYER_PROMPTS[prayerKey] || "It is prayer time.";
    const body = userName ? `${greeting}` : greeting;

    const id = await Notifications.scheduleNotificationAsync({
      content: {
        title: userName ? `Hi ${userName}` : "Prayer Time",
        body,
        sound,
        ...(Platform.OS === "android" ? { channelId } : {}),
        data: { prayer },
      },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.DATE,
        date,
      },
    });
    ids.push(id);
  }

  return ids;
}

export async function scheduleAllPrayerNotifications(
  prayers: PrayerNotificationInfo[],
  advanceMinutes = 0,
  userName = "",
) {
  if (IS_WEB) return [];
  const enabled = await getNotificationsEnabled();
  if (!enabled) return [];

  // Only set up channels on first schedule. Subsequent calls reuse the
  // in-memory cache — channels don't need recreation unless the user
  // changes a sound setting (which calls updatePrayerChannel).
  if (!_channelsInitialized) {
    await setupNotificationChannels();
    _channelsInitialized = true;
  }
  await cancelAllPrayerNotifications();

  // Chronological order matters: iOS caps pending local notifications at 64
  // and rejects the extras, so the nearest prayers must be scheduled first —
  // an oversized custom-prayer list then only loses the farthest days.
  const ordered = [...prayers].sort(
    (a, b) => a.date.getTime() - b.date.getTime(),
  );

  const ids: string[] = [];
  for (const p of ordered) {
    try {
      const result = await schedulePrayerNotification(
        p.name,
        p.title,
        p.date,
        advanceMinutes,
        userName,
      );
      ids.push(...result);
    } catch {
      // Over the OS notification cap or a bad trigger — keep scheduling the
      // rest instead of aborting the whole window.
    }
  }
  return ids;
}

export async function testPrayerNotification(prayer: PrayerName): Promise<boolean> {
  if (IS_WEB) return sendTestWebPush();
  const date = new Date(Date.now() + 3000);
  const channelId = channelIdForPrayer(prayer);
  const sound = await getUserSoundFileName(prayer);

  if (Platform.OS === "android") {
    await setupNotificationChannels();
  }

  const prompt = PRAYER_PROMPTS[prayer] || "It is prayer time.";

  await Notifications.scheduleNotificationAsync({
    content: {
      title: "Hi there",
      body: prompt,
      sound,
      ...(Platform.OS === "android" ? { channelId } : {}),
      data: { prayer, test: true },
    },
    trigger: {
      type: Notifications.SchedulableTriggerInputTypes.DATE,
      date,
    },
  });
  return true;
}

export async function initializeNotifications() {
  if (IS_WEB) return;
  // Only set up channels on first init or when the app process restarts.
  // The in-memory cache (_configuredChannelSounds) persists across focus
  // events within the same process, so we skip the expensive delete+create
  // cycle when channels are already configured. This avoids ~24 native
  // bridge calls on every app resume.
  if (_channelsInitialized) {
    await requestNotificationPermissions();
    return;
  }
  await setupNotificationChannels();
  _channelsInitialized = true;
  await requestNotificationPermissions();
}

Notifications.setNotificationHandler({
  handleNotification: async (notification) => {
    const data = notification.request.content.data as Record<
      string,
      unknown
    > | null;
    const prayer = data?.prayer;

    // Prayer-time alerts play the user's chosen sound in-app (exactly like
    // the request-notification chime) so they never fall back to the device
    // default. The OS sound is suppressed here to avoid a double sound — the
    // backgrounded case is handled by the notification channel sound. Only
    // the six standard prayer names take this path, so unrelated push data
    // that happens to contain a "prayer" key is never mis-handled.
    if (
      typeof prayer === "string" &&
      (PRAYER_CHANNEL_IDS as Record<string, string>)[prayer] !== undefined
    ) {
      playPrayerSound(prayer as PrayerName);
      return {
        shouldShowBanner: true,
        shouldShowList: true,
        shouldPlaySound: false,
        shouldSetBadge: false,
      };
    }

    return {
      shouldShowBanner: true,
      shouldShowList: true,
      shouldPlaySound: true,
      shouldSetBadge: false,
    };
  },
});
