function timeAgo(iso?: string) {
  if (!iso) return "";
  try {
    const diff = Date.now() - new Date(iso).getTime();
    const mins = Math.floor(diff / 60000);
    if (mins < 1) return "Just now";
    if (mins < 60) return `${mins}m ago`;
    const hours = Math.floor(mins / 60);
    if (hours < 24) return `${hours}h ago`;
    const days = Math.floor(hours / 24);
    if (days < 7) return `${days}d ago`;
    return new Date(iso).toLocaleDateString("en-GB", {
      day: "numeric",
      month: "short",
    });
  } catch {
    return "";
  }
}

export default function NotificationsCenterScreen() {
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [unread, setUnread] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const onBackPress = () => {
      router.back();
      return true;
    };
    const sub = BackHandler.addEventListener("hardwareBackPress", onBackPress);
    return () => sub.remove();
  }, []);

  const [reload, setReload] = useState(0);
  // The All section stays null until asked for — opening the screen must only
  // cost the unread query.
  const [allItems, setAllItems] = useState<AppNotification[] | null>(null);
  const [allHasMore, setAllHasMore] = useState(false);
  const [loadingAll, setLoadingAll] = useState(false);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        if (!cancelled) setError(null);
        const res = await notifApi.list();
        if (cancelled) return;
        setNotifications(res.data || []);
        setUnread(res.unread || 0);
      } catch (e: any) {
        if (!cancelled) setError(e?.message || "Failed to load notifications.");
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [reload]);

  const loadAll = async (before?: string) => {
    if (loadingAll) return;
    setLoadingAll(true);
    try {
      const res = await notifApi.listAll({ before });
      const page = res.data || [];
      setAllItems((prev) => {
        if (!before || !prev) return page;
        const seen = new Set(prev.map((x) => x._id));
        return [...prev, ...page.filter((x) => !seen.has(x._id))];
      });
      setAllHasMore(Boolean(res.hasMore));
    } catch {
    } finally {
      setLoadingAll(false);
    }
  };

  const openNotification = (n: AppNotification) => {
    // Opening marks the item read, so drop it from Unread and clear its New
    // badge if the All section already holds it.
    setNotifications((prev) => prev.filter((x) => x._id !== n._id));
    setAllItems((prev) =>
      prev
        ? prev.map((x) => (x._id === n._id ? { ...x, read: true } : x))
        : prev,
    );
    if (!n.read) {
      setUnread((u) => Math.max(0, u - 1));
      notifApi
        .markRead(n._id)
        .then((r) => setNotifUnread(r.unread))
        .catch(() => {});
    }

    // Smart Saver notifications open the savings ledger.
    if (n.type === "smart_saver_credit" || n.type === "smart_saver_withdrawal") {
      router.back();
      router.push("/savings" as any);
      return;
    }
    // Financial report notifications open the published report.
    if (n.type === "financial_report") {
      const reportId = n.data?.reportId;
      router.back();
      if (reportId) {
        router.push({ pathname: "/financial-report-view", params: { reportId } });
      } else {
        router.push("/financials");
      }
      return;
    }
    // Sponsorship notifications: new pledges land with admins, approval /
    // rejection outcomes with the sponsor.
    if (
      n.type === "new_sponsorship" ||
      n.type === "sponsorship_approved" ||
      n.type === "sponsorship_rejected"
    ) {
      router.back();
      router.push(
        (n.type === "new_sponsorship" ? "/sponsorships-admin" : "/financials") as any,
      );
      return;
    }
    // Board governance notifications open the portal: minutes drop into the
    // archive, meeting and task notices into the board calendar.
    if (n.type.startsWith("board_")) {
      const toArchive =
        n.type === "board_minutes_published" ||
        n.type === "board_minutes_deleted" ||
        n.type.startsWith("board_action");
      router.back();
      router.push(
        (toArchive ? "/admin/board-governance/archive" : "/admin/board-governance") as any,
      );
      return;
    }
    // Training notifications open the session (created/updated) or the
    // calendar once it has been removed.
    if (n.type.startsWith("training_")) {
      const trainingId = n.data?.trainingId;
      router.back();
      if (n.type !== "training_deleted" && trainingId) {
        router.push({
          pathname: "/admin/trainings/[id]",
          params: { id: String(trainingId) },
        } as any);
      } else {
        router.push("/admin/trainings" as any);
      }
      return;
    }
    // Appraisal notifications open the form or the review screen.
    if (n.data?.appraisalId) {
      router.back();
      router.push({
        pathname: "/appraisal/[id]",
        params: { id: String(n.data.appraisalId) },
      } as any);
      return;
    }
    // Service & office notifications deep-link to the item (or the list).
    if (n.data?.section === "services" || n.data?.section === "offices") {
      const itemId = n.data?.itemId ? String(n.data.itemId) : null;
      router.back();
      if (itemId) {
        router.push({
          pathname: n.data.section === "services" ? "/services/[id]" : "/offices/[id]",
          params: { id: itemId },
        });
      } else {
        router.push(n.data.section === "services" ? "/services" : "/offices");
      }
      return;
    }
    // Onboarding & induction notifications open the admin form.
    if (n.type === "onboarding_induction" || n.data?.route === "/onboarding-induction") {
      const params: Record<string, string> = {};
      if (typeof n.data?.action === "string") params.action = n.data.action;
      if (typeof n.data?.submissionId === "string") {
        params.submissionId = n.data.submissionId;
      }
      if (typeof n.data?.status === "string") params.status = n.data.status;
      router.back();
      router.push({ pathname: "/onboarding-induction", params } as any);
      return;
    }
    // Help-request notifications deep-link straight into the request thread.
    if (n.data?.requestId && n.data.section !== "requests") {
      router.back();
      router.push({
        pathname: "/(tabs)/requests",
        params: { open: n.data.requestId },
      });
      return;
    }
    // Community engagement notifications (RSVP / payment / connect / apply /
    // join) open the community club landing.
    if (n.data?.tab) {
      router.back();
      router.push({ pathname: "/(tabs)/community" });
      return;
    }
    // Community prayer notifications open the Request Hub on the prayer segment.
    if (
      n.type === "prayer_request" ||
      n.type === "prayer_prayed" ||
      n.type === "request_comment"
    ) {
      router.back();
      router.push({
        pathname: "/(tabs)/requests",
        params: { segment: "prayer" },
      });
    }
  };

  // Unread is pinned on top; the All section below is the rest of the inbox
  // (already-shown unread rows are not repeated there).
  const sections: { title: string; data: AppNotification[] }[] = [];
  if (notifications.length) {
    sections.push({ title: "Unread", data: notifications });
  }
  if (allItems) {
    const shown = new Set(notifications.map((n) => n._id));
    const rest = allItems.filter((n) => !shown.has(n._id));
    if (rest.length) sections.push({ title: "All", data: rest });
  }

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.header}>
          <TouchableOpacity onPress={() => router.back()} style={styles.headerBtn}>
            <Ionicons name="close" size={22} color={colors.darkGreen} />
          </TouchableOpacity>
          <View style={styles.headerTitleWrap}>
            <Text style={styles.headerTitle}>Notifications</Text>
            {unread > 0 ? (
              <View style={styles.countBadge}>
                <Text style={styles.countBadgeText}>{unread > 9 ? "9+" : unread}</Text>
              </View>
            ) : null}
          </View>
          {unread > 0 ? (
            <TouchableOpacity
              onPress={() => {
                notifApi
                  .markAllRead()
                  .then(() => {
                    setNotifications([]);
                    setAllItems((prev) =>
                      prev ? prev.map((x) => ({ ...x, read: true })) : prev,
                    );
                    setUnread(0);
                    setNotifUnread(0);
                  })
                  .catch(() => {});
              }}
              style={styles.markAllBtn}
              accessibilityRole="button"
            >
              <Text style={styles.markAllText}>Mark all read</Text>
            </TouchableOpacity>
          ) : (
            <View style={{ width: 36 }} />
          )}
        </View>

        {loading ? (
          <SkeletonList count={6} render={NotificationSkeleton} />
        ) : error ? (
          <EmptyState
            icon="warning-outline"
            color={colors.error}
            eyebrow="Something went wrong"
            title="Couldn't load notifications"
            subtitle={error}
            actionLabel="Retry"
            onAction={() => setReload((r) => r + 1)}
          />
        ) : notifications.length === 0 && allItems === null ? (
          <EmptyState
            icon="notifications-off-outline"
            color={colors.info}
            eyebrow="All quiet"
            title="You're all caught up"
            subtitle="Unread updates about your requests and community will land here."
            actionLabel="Show all notifications"
            onAction={() => void loadAll()}
          />
        ) : notifications.length === 0 && allItems?.length === 0 ? (
          <EmptyState
            icon="notifications-off-outline"
            color={colors.info}
            eyebrow="All quiet"
            title="No notifications yet"
            subtitle="Updates about your requests and community will land here."
          />
        ) : (
          <SectionList
            sections={sections}
            keyExtractor={(item) => item._id}
            contentContainerStyle={styles.list}
            showsVerticalScrollIndicator={false}
            stickySectionHeadersEnabled={false}
            renderSectionHeader={({ section }) => (
              <View style={styles.sectionHeader}>
                <Text style={styles.sectionTitle}>{section.title}</Text>
                {section.title === "Unread" && unread > 0 ? (
                  <View style={styles.countBadge}>
                    <Text style={styles.countBadgeText}>
                      {unread > 9 ? "9+" : unread}
                    </Text>
                  </View>
                ) : null}
              </View>
            )}
            renderItem={({ item }) => {
              const meta = TYPE_ICONS[item.type] || TYPE_ICONS.help_reply;
              return (
                <TouchableOpacity
                  onPress={() => openNotification(item)}
                  activeOpacity={0.8}
                  style={[styles.card, !item.read && styles.cardUnread]}
                >
                  <View style={[styles.iconBox, { backgroundColor: meta.bg }]}>
                    <Ionicons name={meta.icon} size={18} color={meta.color} />
                  </View>
                  <View style={{ flex: 1 }}>
                    <View style={styles.titleRow}>
                      <Text style={styles.cardTitle} numberOfLines={1}>
                        {item.title}
                      </Text>
                      {!item.read ? (
                        <View style={styles.newBadge}>
                          <Text style={styles.newBadgeText}>New</Text>
                        </View>
                      ) : null}
                    </View>
                    <Text style={styles.cardBody} numberOfLines={2}>
                      {item.body}
                    </Text>
                  </View>
                  <Text style={styles.cardTime}>{timeAgo(item.createdAt)}</Text>
                </TouchableOpacity>
              );
            }}
            onEndReachedThreshold={0.4}
            onEndReached={() => {
              if (allItems === null || !allHasMore || loadingAll) return;
              const last = allItems[allItems.length - 1];
              if (last) void loadAll(last.createdAt);
            }}
            ListFooterComponent={
              loadingAll ? (
                <View style={styles.footer}>
                  <ActivityIndicator size="small" color="#13c5dd" />
                </View>
              ) : allItems === null ? (
                <TouchableOpacity
                  style={styles.loadAllBtn}
                  activeOpacity={0.8}
                  onPress={() => void loadAll()}
                  accessibilityRole="button"
                >
                  <Text style={styles.loadAllText}>Show all notifications</Text>
                  <Ionicons name="chevron-down" size={15} color="#13c5dd" />
                </TouchableOpacity>
              ) : null
            }
          />
        )}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

function NotificationSkeleton() {
  return (
    <View style={styles.card}>
      <SkeletonPulse style={{ width: 38, height: 38, borderRadius: 12 }} />
      <View style={{ flex: 1, gap: 6 }}>
        <SkeletonPulse style={{ width: "62%", height: 14 }} />
        <SkeletonPulse style={{ width: "88%", height: 12 }} />
      </View>
      <SkeletonPulse style={{ width: 40, height: 11 }} />
    </View>
  );
}

