import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { router, useLocalSearchParams } from "expo-router";
import { useCallback, useEffect, useMemo, useState } from "react";
import {
  ActivityIndicator,
  RefreshControl,
  ScrollView,
  Share,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaProvider, SafeAreaView } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import {
  CHART_EXPENSE,
  IncomeMixPie,
  MIX_COLORS,
} from "@/components/PerformanceCharts";
import { getSession } from "@/services/auth";
import {
  financialApi,
  foundersFundOf,
  reportTotals,
  type FinancialReport,
} from "@/services/sponsorships";
import type { IncomeMixRow } from "@/services/performance";

const fmtMoney = (n: number) => `R ${(n || 0).toLocaleString("en-US")}`;

const HERO_GRADIENT = ["#EAF9FE", "#D2ECF9"] as [string, string];

type IconName = React.ComponentProps<typeof Ionicons>["name"];

function LineRow({
  label,
  value,
  note,
  positive,
  money = true,
}: {
  label: string;
  value: number;
  note?: string;
  positive?: boolean;
  money?: boolean;
}) {
  return (
    <View style={styles.lineRow}>
      <View style={styles.lineBody}>
        <Text style={styles.lineLabel}>{label}</Text>
        {!!note && <Text style={styles.lineNote}>{note}</Text>}
      </View>
      <Text
        style={[
          styles.lineValue,
          positive != null && (positive ? styles.linePositive : styles.lineNegative),
        ]}
      >
        {money ? fmtMoney(value) : value.toLocaleString("en-US")}
      </Text>
    </View>
  );
}

function SectionHead({
  icon,
  title,
  meta,
}: {
  icon: IconName;
  title: string;
  meta?: string;
}) {
  return (
    <View style={styles.cardHead}>
      <View style={styles.cardIcon}>
        <Ionicons name={icon} size={15} color={colors.goldDark} />
      </View>
      <Text style={styles.cardTitle}>{title}</Text>
      {meta ? <Text style={styles.cardMeta}>{meta}</Text> : null}
    </View>
  );
}

function StatTile({
  label,
  value,
  tint,
}: {
  label: string;
  value: number;
  tint: string;
}) {
  return (
    <View style={styles.statTile}>
      <Text style={styles.statLabel}>{label}</Text>
      <Text style={[styles.statValue, { color: tint }]} numberOfLines={1} adjustsFontSizeToFit>
        {fmtMoney(value)}
      </Text>
    </View>
  );
}

/** Horizontal share-of-total bars — the expense breakdown at a glance. */
function ShareBars({ rows, total }: { rows: IncomeMixRow[]; total: number }) {
  if (rows.length === 0 || total <= 0) return null;
  return (
    <View style={styles.shareList}>
      {rows.map((row) => {
        const pct = Math.round((row.value / total) * 100);
        return (
          <View key={row.key} style={styles.shareRow}>
            <View style={styles.shareHead}>
              <Text style={styles.shareLabel} numberOfLines={1}>
                {row.label}
              </Text>
              <Text style={styles.shareValue}>{fmtMoney(row.value)}</Text>
            </View>
            <View style={styles.shareTrack}>
              <View
                style={[
                  styles.shareFill,
                  { width: `${Math.max(2, (row.value / total) * 100)}%` },
                ]}
              />
              <Text style={styles.sharePct}>{pct}%</Text>
            </View>
          </View>
        );
      })}
    </View>
  );
}

const fmtDate = (value?: string) => {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-ZA", { day: "numeric", month: "short", year: "numeric" });
};

export default function FinancialReportView() {
  const { reportId } = useLocalSearchParams<{ reportId?: string }>();
  const [loggedIn, setLoggedIn] = useState<boolean | null>(null);
  const [report, setReport] = useState<FinancialReport | null>(null);
  const [error, setError] = useState("");
  const [refreshing, setRefreshing] = useState(false);

  const load = useCallback(async () => {
    if (!reportId) {
      setError("No report selected.");
      return;
    }
    try {
      const res = await financialApi.get(reportId);
      setReport(res.data);
      setError("");
    } catch (e: any) {
      setError(e?.message || "Failed to load the financial report.");
    }
  }, [reportId]);

  useEffect(() => {
    (async () => {
      const session = await getSession();
      if (!session?.user) {
        setLoggedIn(false);
        return;
      }
      setLoggedIn(true);
      await load();
    })();
  }, [load]);

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    await load();
    setRefreshing(false);
  }, [load]);

  const handleShare = () => {
    if (!report) return;
    const t = reportTotals(report);
    const lines = [
      "RELATE — FINANCIAL REPORT",
      `Period: ${report.period}`,
      `Prepared by: ${report.preparedBy || "Relate Admin"}`,
      `Published: ${fmtDate(report.createdAt)}`,
      "",
      "INCOME",
      `  Balance brought down: ${fmtMoney(report.income.balanceBroughtDown)}`,
      `  Founders’ Fund: ${fmtMoney(foundersFundOf(report.income))}`,
      `  Events: ${fmtMoney(report.income.events)}`,
      `  Donations: ${fmtMoney(report.income.donations)}`,
      `  Book and resource sales: ${fmtMoney(report.income.books)}`,
      `  Other: ${fmtMoney(report.income.other)}${report.income.otherDescription ? ` (${report.income.otherDescription})` : ""}`,
      `  Total income: ${fmtMoney(t.income)}`,
      "",
      "EXPENSES",
      `  Meals: ${fmtMoney(report.expenses.meals)}`,
      `  Groceries: ${fmtMoney(report.expenses.groceries)}`,
      `  Tuition support: ${fmtMoney(report.expenses.tuition)}`,
      `  Transport and travel: ${fmtMoney(report.expenses.transport)}`,
      `  Skills and employment: ${fmtMoney(report.expenses.employment)}`,
      `  Materials and printing: ${fmtMoney(report.expenses.materials)}`,
      report.expenses.amountsFromRecords > 0 ? `  Amounts used from records: ${fmtMoney(report.expenses.amountsFromRecords)}` : null,
      `  Other: ${fmtMoney(report.expenses.other)}${report.expenses.otherDescription ? ` (${report.expenses.otherDescription})` : ""}`,
      `  Total expenses: ${fmtMoney(t.expenses)}`,
      "",
      `NET FUNDS: ${fmtMoney(t.net)}`,
      "",
      "IMPACT",
      `  Families supported: ${report.impact.families}`,
      `  Meals served: ${report.impact.mealsServed}`,
      `  Children supported: ${report.impact.children}`,
      `  Skills and employment placements: ${report.impact.placements}`,
      `  Events hosted: ${report.impact.events}`,
    ];
    if (report.otherActivities) lines.push("", "OTHER ACTIVITIES", report.otherActivities);
    if (report.notes) lines.push("", "NOTES", report.notes);
    if (report.customFields?.length) {
      lines.push("", "ADDITIONAL ITEMS");
      for (const f of report.customFields) {
        lines.push(`  ${f.title}: ${f.content}`);
      }
    }
    Share.share({ message: lines.filter((l) => l !== null).join("\n") }).catch(() => {});
  };

  const totals = report ? reportTotals(report) : null;
  const carried = report?.income.balanceBroughtDown ?? 0;
  const raised = totals ? totals.income - carried : 0;

  /** The carried balance is not income, so it never enters the mix. */
  const incomeRows = useMemo<IncomeMixRow[]>(() => {
    if (!report) return [];
    return [
      { key: "foundersFund", label: "Founders’ Fund", value: foundersFundOf(report.income) },
      { key: "events", label: "Events & fees", value: report.income.events },
      { key: "donations", label: "Donations", value: report.income.donations },
      { key: "books", label: "Books & resources", value: report.income.books },
      {
        key: "other",
        label: report.income.otherDescription || "Other income",
        value: report.income.other,
      },
    ]
      .filter((row) => row.value > 0)
      .sort((a, b) => b.value - a.value);
  }, [report]);

  const expenseRows = useMemo<IncomeMixRow[]>(() => {
    if (!report) return [];
    return [
      { key: "meals", label: "Meals", value: report.expenses.meals },
      { key: "groceries", label: "Groceries", value: report.expenses.groceries },
      { key: "tuition", label: "Tuition support", value: report.expenses.tuition },
      { key: "transport", label: "Transport & travel", value: report.expenses.transport },
      { key: "employment", label: "Skills & employment", value: report.expenses.employment },
      { key: "materials", label: "Materials & printing", value: report.expenses.materials },
      { key: "records", label: "Amounts from records", value: report.expenses.amountsFromRecords },
      {
        key: "other",
        label: report.expenses.otherDescription || "Other expenses",
        value: report.expenses.other,
      },
    ]
      .filter((row) => row.value > 0)
      .sort((a, b) => b.value - a.value);
  }, [report]);

  const impactTiles = report
    ? [
        { key: "families", icon: "home-outline" as IconName, label: "Families", value: report.impact.families },
        { key: "meals", icon: "restaurant-outline" as IconName, label: "Meals served", value: report.impact.mealsServed },
        { key: "children", icon: "happy-outline" as IconName, label: "Children", value: report.impact.children },
        { key: "placements", icon: "briefcase-outline" as IconName, label: "Placements", value: report.impact.placements },
        { key: "events", icon: "calendar-outline" as IconName, label: "Events hosted", value: report.impact.events },
      ]
    : [];

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.header}>
          <TouchableOpacity onPress={() => router.back()} style={styles.closeBtn}>
            <Ionicons name="close" size={20} color={colors.forest} />
          </TouchableOpacity>
          <Text style={styles.headerTitle}>Financial Report</Text>
          {report ? (
            <TouchableOpacity
              onPress={handleShare}
              style={styles.closeBtn}
              accessibilityLabel="Share report"
            >
              <Ionicons name="share-outline" size={19} color={colors.forest} />
            </TouchableOpacity>
          ) : (
            <View style={{ width: 36 }} />
          )}
        </View>

        {loggedIn === null || (loggedIn && !report && !error) ? (
          <View style={styles.center}>
            <ActivityIndicator color={colors.goldDark} size="large" />
          </View>
        ) : !loggedIn ? (
          <View style={styles.center}>
            <Ionicons name="person-circle-outline" size={40} color={colors.muted} />
            <Text style={styles.deniedTitle}>Sign in to view this report</Text>
            <Text style={styles.deniedText}>
              Financial reports are available to signed-in users.
            </Text>
            <TouchableOpacity
              style={styles.signInBtn}
              onPress={() => {
                router.replace({
                  pathname: "/login",
                  params: { next: `/financial-report-view?reportId=${reportId || ""}` },
                });
              }}
              activeOpacity={0.85}
            >
              <Text style={styles.signInBtnText}>Sign in</Text>
            </TouchableOpacity>
          </View>
        ) : !report ? (
          <View style={styles.center}>
            <Ionicons name="cloud-offline-outline" size={40} color={colors.muted} />
            <Text style={styles.deniedText}>{error}</Text>
            <TouchableOpacity style={styles.retryBtn} onPress={load} activeOpacity={0.85}>
              <Text style={styles.retryBtnText}>Try again</Text>
            </TouchableOpacity>
          </View>
        ) : (
          <ScrollView
            contentContainerStyle={styles.scroll}
            showsVerticalScrollIndicator={false}
            refreshControl={
              <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
            }
          >
            <LinearGradient
              colors={HERO_GRADIENT}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={styles.heroCard}
            >
              <View style={styles.heroTop}>
                <View style={styles.heroBadge}>
                  <Ionicons name="document-text" size={12} color={colors.goldDark} />
                  <Text style={styles.heroBadgeText}>FINANCIAL REPORT</Text>
                </View>
                <View
                  style={[
                    styles.netPill,
                    { backgroundColor: (totals?.net ?? 0) < 0 ? "#fee2e2" : "#d1fae5" },
                  ]}
                >
                  <Ionicons
                    name={(totals?.net ?? 0) < 0 ? "trending-down" : "trending-up"}
                    size={12}
                    color={(totals?.net ?? 0) < 0 ? "#be123c" : colors.emeraldDark}
                  />
                  <Text
                    style={[
                      styles.netPillText,
                      { color: (totals?.net ?? 0) < 0 ? "#be123c" : colors.emeraldDark },
                    ]}
                  >
                    {(totals?.net ?? 0) < 0 ? "Over spent" : "In surplus"}
                  </Text>
                </View>
              </View>

              <Text style={styles.heroTitle}>{report.period}</Text>
              <Text style={styles.heroSub}>
                Prepared by {report.preparedBy || "Relate Admin"} · Published{" "}
                {fmtDate(report.createdAt)}
              </Text>

              <View style={styles.balanceBlock}>
                <Text style={styles.balanceLabel}>Closing balance</Text>
                <Text
                  style={[
                    styles.balanceValue,
                    { color: (totals?.net ?? 0) < 0 ? "#be123c" : colors.forest },
                  ]}
                  numberOfLines={1}
                  adjustsFontSizeToFit
                >
                  {fmtMoney(totals?.net ?? 0)}
                </Text>
                <Text style={styles.balanceNote}>
                  {carried > 0
                    ? `${fmtMoney(carried)} carried in, ${fmtMoney(raised)} raised, ${fmtMoney(totals?.expenses ?? 0)} spent`
                    : `${fmtMoney(raised)} raised, ${fmtMoney(totals?.expenses ?? 0)} spent`}
                </Text>
              </View>
            </LinearGradient>

            {totals ? (
              <View style={styles.statRow}>
                <StatTile label="Raised" value={raised} tint={colors.goldDark} />
                <StatTile label="Spent" value={totals.expenses} tint={colors.forest} />
                <StatTile
                  label="Funds available"
                  value={totals.income}
                  tint={colors.info}
                />
              </View>
            ) : null}

            <View style={styles.card}>
              <SectionHead icon="trending-up" title="Income" meta={fmtMoney(raised)} />

              {incomeRows.length > 0 ? (
                <View style={styles.mixBlock}>
                  <IncomeMixPie rows={incomeRows} size={144} />
                  <View style={styles.mixLegend}>
                    {incomeRows.map((row, index) => (
                      <View key={row.key} style={styles.mixLegendRow}>
                        <View
                          style={[
                            styles.mixDot,
                            { backgroundColor: MIX_COLORS[index % MIX_COLORS.length] },
                          ]}
                        />
                        <Text style={styles.mixLabel} numberOfLines={1}>
                          {row.label}
                        </Text>
                        <Text style={styles.mixValue}>{fmtMoney(row.value)}</Text>
                      </View>
                    ))}
                  </View>
                </View>
              ) : (
                <Text style={styles.emptyNote}>No income was recorded for this period.</Text>
              )}

              {carried > 0 ? (
                <View style={styles.carriedBox}>
                  <Ionicons name="swap-vertical" size={15} color={colors.info} />
                  <View style={{ flex: 1 }}>
                    <Text style={styles.carriedTitle}>Balance brought down</Text>
                    <Text style={styles.carriedNote}>
                      Carried from the previous period — not new income.
                    </Text>
                  </View>
                  <Text style={styles.carriedValue}>{fmtMoney(carried)}</Text>
                </View>
              ) : null}

              <View style={styles.lineList}>
                <LineRow label="Founders’ Fund" value={foundersFundOf(report.income)} />
                <LineRow label="Event registrations and fees" value={report.income.events} />
                <LineRow label="Donations" value={report.income.donations} />
                <LineRow label="Book and resource sales" value={report.income.books} />
                {report.income.other > 0 || report.income.otherDescription ? (
                  <LineRow
                    label="Other income"
                    value={report.income.other}
                    note={report.income.otherDescription || undefined}
                  />
                ) : null}
              </View>
            </View>

            <View style={styles.card}>
              <SectionHead
                icon="trending-down"
                title="Expenses"
                meta={fmtMoney(totals?.expenses ?? 0)}
              />
              <ShareBars rows={expenseRows} total={totals?.expenses ?? 0} />
              {expenseRows.length === 0 ? (
                <Text style={styles.emptyNote}>Nothing was spent in this period.</Text>
              ) : null}
              <View style={styles.lineList}>
                <LineRow label="Meals" value={report.expenses.meals} />
                <LineRow label="Groceries" value={report.expenses.groceries} />
                <LineRow label="Tuition support" value={report.expenses.tuition} />
                <LineRow label="Transport and travel" value={report.expenses.transport} />
                <LineRow label="Skills and employment" value={report.expenses.employment} />
                <LineRow label="Materials and printing" value={report.expenses.materials} />
                {report.expenses.amountsFromRecords > 0 ? (
                  <LineRow label="Amounts used from records" value={report.expenses.amountsFromRecords} />
                ) : null}
                {report.expenses.other > 0 || report.expenses.otherDescription ? (
                  <LineRow
                    label="Other expenses"
                    value={report.expenses.other}
                    note={report.expenses.otherDescription || undefined}
                  />
                ) : null}
              </View>
            </View>

            <View style={styles.card}>
              <SectionHead icon="heart-outline" title="Impact" />
              <View style={styles.impactGrid}>
                {impactTiles.map((tile) => (
                  <View key={tile.key} style={styles.impactTile}>
                    <Ionicons name={tile.icon} size={17} color={colors.goldDark} />
                    <Text style={styles.impactValue}>
                      {tile.value.toLocaleString("en-US")}
                    </Text>
                    <Text style={styles.impactLabel} numberOfLines={1}>
                      {tile.label}
                    </Text>
                  </View>
                ))}
              </View>
            </View>

            {report.otherActivities ? (
              <View style={styles.card}>
                <SectionHead icon="finger-print-outline" title="Other activities" />
                <Text style={styles.notesText}>{report.otherActivities}</Text>
              </View>
            ) : null}

            {report.customFields?.length ? (
              <View style={styles.card}>
                <SectionHead icon="add-circle-outline" title="Additional items" />
                {report.customFields.map((cf, i) => (
                  <View key={i} style={styles.customPreviewRow}>
                    <Text style={styles.customPreviewTitle}>{cf.title}</Text>
                    <Text style={styles.customPreviewContent}>{cf.content}</Text>
                  </View>
                ))}
              </View>
            ) : null}

            {report.notes ? (
              <View style={styles.card}>
                <SectionHead icon="chatbox-ellipses-outline" title="Notes" />
                <Text style={styles.notesText}>{report.notes}</Text>
              </View>
            ) : null}

            <TouchableOpacity
              style={styles.backBtn}
              onPress={() => router.back()}
              activeOpacity={0.85}
            >
              <Ionicons name="chevron-back" size={16} color={colors.forest} />
              <Text style={styles.backBtnText}>Back to Financials</Text>
            </TouchableOpacity>
          </ScrollView>
        )}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

