import type { ImageSourcePropType } from "react-native";
import { WEB_ORIGIN } from "@/services/config";

/**
 * Curated background photos for the Verse of the Day card.
 * One is picked per calendar day (stable all day, rotates daily).
 *
 * The photos are served from the web origin (like team crests and sport
 * heroes) so they don't depend on OTA asset delivery; the bundled copies
 * are only placeholders for instant paint.
 */
const VOTD_BACKGROUNDS: ImageSourcePropType[] = [
  require("../../assets/images/votd_bg_images/dawid-zawila--G3rw6Y02D0-unsplash.webp"),
  require("../../assets/images/votd_bg_images/johannes-plenio-hvrpOmuMrAI-unsplash.webp"),
  require("../../assets/images/votd_bg_images/john-fowler-03Pv2Ikm5Hk-unsplash.webp"),
  require("../../assets/images/votd_bg_images/mark-basarab-1OtUkD_8svc-unsplash.webp"),
  require("../../assets/images/votd_bg_images/mohammad-alizade-4wzRuAb-KWs-unsplash.webp"),
  require("../../assets/images/votd_bg_images/ryan-schroeder-Gg7uKdHFb_c-unsplash.webp"),
  require("../../assets/images/votd_bg_images/tobias-keller-73F4pKoUkM0-unsplash.webp"),
  require("../../assets/images/votd_bg_images/urban-vintage-78A265wPiO4-unsplash.webp"),
  require("../../assets/images/votd_bg_images/v2osk-1Z2niiBPg5A-unsplash.webp"),
];

const VOTD_URLS = [
  "votd-1.webp",
  "votd-2.webp",
  "votd-3.webp",
  "votd-4.webp",
  "votd-5.webp",
  "votd-6.webp",
  "votd-7.webp",
  "votd-8.webp",
  "votd-9.webp",
];

export const VOTD_BACKGROUND_COUNT = VOTD_BACKGROUNDS.length;

function dayIndex(date: Date): number {
  const daySeed = date.getFullYear() * 372 + date.getMonth() * 31 + date.getDate();
  return daySeed % VOTD_BACKGROUND_COUNT;
}

/**
 * Returns the background for a given day — deterministic, so the same
 * image shows all day and changes each new day (local calendar day).
 */
export function votdBackgroundForDay(date: Date = new Date()): ImageSourcePropType {
  const file = VOTD_URLS[dayIndex(date)];
  return { uri: `${WEB_ORIGIN}/images/votd/${file}` };
}

/** Bundled copy of the same day's photo, shown while the hosted one loads. */
export function votdPlaceholderForDay(date: Date = new Date()): ImageSourcePropType {
  return VOTD_BACKGROUNDS[dayIndex(date)];
}
