import { Ionicons } from "@expo/vector-icons";
import {
  ActivityIndicator,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { type Club, useClubs } from "@/services/clubs";
import { colors } from "@/constants/colors";
import { GradientBox } from "@/constants/gradients";
import { fonts } from "@/constants/fonts";

/** Chip value meaning "no club filter at all", distinct from "" (Relate). */
export const ALL_CLUBS = "*";

type Props = {
  /** Currently selected club slug ("" = nothing selected). */
  value: string;
  onChange: (slug: string) => void;
  /** Optional label text shown above the chips. */
  label?: string;
  /** Limit the selectable clubs (e.g. top-level only). Defaults to all clubs. */
  clubs?: Club[];
  /** Show a leading "Relate" chip (selects value ""). */
  allowOrganization?: boolean;
  /** Show a leading "Everything" chip (selects ALL_CLUBS). */
  allowAll?: boolean;
};

/**
 * Horizontal row of club chips used when picking which club something belongs
 * to (events, groups, publications). Active chip fills with the club color.
 */
export default function ClubSelect({ value, onChange, label, clubs, allowOrganization, allowAll }: Props) {
  const { clubs: catalogClubs, loading, error } = useClubs();
  const items = clubs ?? catalogClubs;
  return (
    <View>
      {label ? <Text style={s.label}>{label}</Text> : null}
      {!clubs && loading ? (
        <View style={s.loading}>
          <ActivityIndicator size="small" color={colors.forest} />
        </View>
      ) : !clubs && error ? (
        <Text style={s.error}>{error}</Text>
      ) : (
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={s.row}
        >
          {allowAll ? (
            <TouchableOpacity
              style={[s.chip, value === ALL_CLUBS && { borderColor: "transparent" }]}
              activeOpacity={0.8}
              onPress={() => onChange(ALL_CLUBS)}
              accessibilityLabel="Everything"
              accessibilityState={{ selected: value === ALL_CLUBS }}
            >
              {value === ALL_CLUBS && (
                <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              )}
              <Ionicons
                name="apps-outline"
                size={13}
                color={value === ALL_CLUBS ? colors.white : colors.forest}
              />
              <Text style={[s.chipText, value === ALL_CLUBS && s.chipTextActive]}>Everything</Text>
            </TouchableOpacity>
          ) : null}
          {allowOrganization ? (
            <TouchableOpacity
              style={[s.chip, value === "" && { borderColor: "transparent" }]}
              activeOpacity={0.8}
              onPress={() => onChange("")}
              accessibilityLabel="Relate"
            >
              {value === "" && (
                <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              )}
              <Ionicons
                name="globe-outline"
                size={13}
                color={value === "" ? colors.white : colors.forest}
              />
              <Text style={[s.chipText, value === "" && s.chipTextActive]}>Relate</Text>
            </TouchableOpacity>
          ) : null}
          {items.map((club) => {
            const active = value === club.slug;
            return (
              <TouchableOpacity
                key={club.slug}
                style={[s.chip, active && { backgroundColor: club.color, borderColor: club.color }]}
                activeOpacity={0.8}
                onPress={() => onChange(club.slug)}
                accessibilityLabel={`Club ${club.name}`}
              >
                <Ionicons
                  name={club.icon as any}
                  size={13}
                  color={active ? colors.white : club.colorDark}
                />
                <Text style={[s.chipText, active && s.chipTextActive]}>{club.name}</Text>
              </TouchableOpacity>
            );
          })}
        </ScrollView>
      )}
    </View>
  );
}

const s = StyleSheet.create({
  label: {
    fontFamily: fonts.sansSemiBold,
    fontWeight: "600",
    fontSize: 13,
    color: colors.ink,
    marginBottom: 6,
  },
  loading: {
    paddingVertical: 10,
    alignItems: "center",
  },
  error: {
    fontFamily: fonts.sans,
    fontWeight: "400",
    fontSize: 12.5,
    color: colors.error,
    paddingVertical: 8,
  },
  row: {
    gap: 8,
    paddingVertical: 2,
  },
  chip: {
    flexDirection: "row",
    alignItems: "center",
    gap: 6,
    paddingHorizontal: 12,
    paddingVertical: 8,
    borderRadius: 999,
    overflow: "hidden",
    backgroundColor: colors.white,
    borderWidth: 1,
    borderColor: "#d9e8f1",
  },
  chipText: {
    fontFamily: fonts.sansBold,
    fontWeight: "700",
    fontSize: 12,
    color: colors.forestDark,
  },
  chipTextActive: {
    color: colors.white,
  },
});