/**
 * Shown when "Join a Club" opens without a specific club — pick one, then
 * the registration form loads for that club. Existing members see their
 * membership instead of the list.
 */
function ClubPicker({ onPick }: { onPick: (slug: string) => void }) {
  const router = useRouter();
  const [gate, setGate] = useState<"checking" | "member" | "clear">("checking");
  const [membership, setMembership] = useState<ClubMembership | null>(null);

  useEffect(() => {
    let cancelled = false;
    clubJoinApi
      .me()
      .then((json) => {
        if (cancelled) return;
        const m = json?.data ?? null;
        if (m && m.status !== "graduated") {
          setMembership(m);
          setGate("member");
        } else {
          setGate("clear");
        }
      })
      .catch(() => {
        // Guest (401) or request failed — show the list; the form gates sign-in.
        if (!cancelled) setGate("clear");
      });
    return () => {
      cancelled = true;
    };
  }, []);

  if (gate === "checking") {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={j.safe} edges={["top", "bottom"]}>
          <StatusBar style="dark" />
          <View style={j.center}>
            <ActivityIndicator size="small" color={colors.gold} />
            <Text style={j.centerText}>Checking your membership…</Text>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (gate === "member" && membership) {
    return <AlreadyMemberScreen membership={membership} />;
  }

  return (
    <SafeAreaProvider>
      <SafeAreaView style={j.pickerSafe} edges={["top", "bottom"]}>
        <StatusBar style="dark" />
        <View style={j.pickerBar}>
          <TouchableOpacity
            onPress={() => router.back()}
            style={j.pickerBack}
            accessibilityRole="button"
            accessibilityLabel="Back"
          >
            <Ionicons name="chevron-back" size={20} color={colors.forest} />
          </TouchableOpacity>
          <View style={{ flex: 1 }}>
            <Text style={j.pickerTitle}>Join a club</Text>
            <Text style={j.pickerSub}>Pick the club you&rsquo;d like to join.</Text>
          </View>
        </View>
        <ScrollView
          style={{ flex: 1 }}
          contentContainerStyle={j.pickerList}
          contentInsetAdjustmentBehavior="never"
          showsVerticalScrollIndicator={false}
        >
          {CLUBS.map((club) => (
            <TouchableOpacity
              key={club.slug}
              style={j.pickerRow}
              activeOpacity={0.85}
              onPress={() => onPick(club.slug)}
              accessibilityRole="button"
              accessibilityLabel={`Join ${club.name}`}
            >
              <View style={[j.pickerIcon, { backgroundColor: `${club.color}18` }]}>
                <Ionicons name={club.icon as any} size={20} color={club.color} />
              </View>
              <View style={{ flex: 1 }}>
                <View style={j.pickerNameRow}>
                  <Text style={j.pickerName}>{club.name}</Text>
                  <Text style={j.pickerAge}>{club.ageRange}</Text>
                </View>
                <Text style={j.pickerTag} numberOfLines={1}>
                  {club.tagline}
                </Text>
              </View>
              <Ionicons name="chevron-forward" size={16} color={colors.muted} />
            </TouchableOpacity>
          ))}
        </ScrollView>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

/**
 * Entry point: without a `slug` param (e.g. from the notifications menu's
 * "Join a Club") show the club picker; otherwise render the join form.
 */
export default function ClubJoinScreen() {
  const router = useRouter();
  const params = useLocalSearchParams<{ slug?: string }>();
  const slug = typeof params.slug === "string" ? params.slug : "";

  if (!slug) {
    return (
      <ClubPicker
        onPick={(s) => router.push({ pathname: "/join", params: { slug: s } })}
      />
    );
  }
  return <ClubJoinForm />;
}

