import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { router } from "expo-router";
import { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  BackHandler,
  InteractionManager,
  KeyboardAvoidingView,
  Platform,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import {
  SafeAreaProvider,
  SafeAreaView,
  useSafeAreaInsets,
} from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import EmptyState from "@/components/EmptyState";
import { SkeletonPulse } from "@/components/Skeleton";
import { getSession } from "@/services/auth";
import {
  appraisalApi,
  type AppraisalStatus,
  type AppraisalSummary,
  type AppraisalType,
  type AppraisalUser,
} from "@/services/appraisals";
import { GradientBox } from "@/constants/gradients";

const STATUS_TONE: Record<
  AppraisalStatus,
  { bg: string; color: string; icon: keyof typeof Ionicons.glyphMap }
> = {
  assigned: { bg: "#fef3c7", color: "#b45309", icon: "time-outline" },
  submitted: { bg: "#d4eef5", color: "#1d2a4d", icon: "eye-outline" },
  approved: { bg: "#d1fae5", color: "#047857", icon: "checkmark-circle-outline" },
  rejected: { bg: "#ffe4e6", color: "#be123c", icon: "arrow-undo-outline" },
};

const FILTERS: { key: AppraisalStatus | "all"; label: string }[] = [
  { key: "all", label: "All" },
  { key: "assigned", label: "Awaiting form" },
  { key: "submitted", label: "To review" },
  { key: "approved", label: "Approved" },
  { key: "rejected", label: "Sent back" },
];

function StatusPill({ status, label }: { status: AppraisalStatus; label: string }) {
  const tone = STATUS_TONE[status] ?? STATUS_TONE.assigned;
  return (
    <View style={[styles.pill, { backgroundColor: tone.bg }]}>
      <Text style={[styles.pillText, { color: tone.color }]}>{label}</Text>
    </View>
  );
}

function StatCard({
  label,
  value,
  color,
  active,
  onPress,
}: {
  label: string;
  value: string;
  color: string;
  active?: boolean;
  onPress?: () => void;
}) {
  return (
    <TouchableOpacity
      style={[styles.statCard, active && styles.statCardOn]}
      onPress={onPress}
      activeOpacity={0.85}
      accessibilityRole="button"
      accessibilityState={{ selected: !!active }}
    >
      <Text style={[styles.statValue, { color }]}>{value}</Text>
      <Text style={styles.statLabel}>{label}</Text>
    </TouchableOpacity>
  );
}

export default function AppraisalsScreen() {
  const insets = useSafeAreaInsets();
  const [isAdmin, setIsAdmin] = useState(false);
  const [items, setItems] = useState<AppraisalSummary[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [filter, setFilter] = useState<AppraisalStatus | "all">("all");

  const [type, setType] = useState<AppraisalType>("individual");
  const [search, setSearch] = useState("");
  const [users, setUsers] = useState<AppraisalUser[]>([]);
  const [searching, setSearching] = useState(false);
  const [selected, setSelected] = useState<AppraisalUser | null>(null);
  const [department, setDepartment] = useState("");
  const [assigning, setAssigning] = useState(false);

  const load = useCallback(async () => {
    try {
      setError(null);
      const res = await appraisalApi.list();
      setItems(res.data || []);
      setIsAdmin(!!res.isAdmin);
    } catch (e: any) {
      setError(e?.message || "Failed to load appraisals.");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    const task = InteractionManager.runAfterInteractions(() => {
      void load();
    });
    return () => task.cancel();
  }, [load]);

  useEffect(() => {
    getSession().then((s) => {
      if (s?.user?.role === "admin") setIsAdmin(true);
    });
  }, []);

  useEffect(() => {
    const sub = BackHandler.addEventListener("hardwareBackPress", () => {
      router.back();
      return true;
    });
    return () => sub.remove();
  }, []);

  useEffect(() => {
    const query = search.trim();
    if (query.length < 2) return;
    let alive = true;
    const timer = setTimeout(() => {
      setSearching(true);
      appraisalApi
        .searchUsers(query)
        .then((res) => {
          if (alive) setUsers(res.data || []);
        })
        .catch(() => {
          if (alive) setUsers([]);
        })
        .finally(() => {
          if (alive) setSearching(false);
        });
    }, 350);
    return () => {
      alive = false;
      clearTimeout(timer);
    };
  }, [search]);

  const onRefresh = () => {
    setRefreshing(true);
    load();
  };

  const allocate = async () => {
    if (!selected) {
      Alert.alert("Choose a member", "Search for the member who will complete this appraisal.");
      return;
    }
    if (type === "department" && !department.trim()) {
      Alert.alert("Name the department", "Enter the department or club this appraisal covers.");
      return;
    }
    setAssigning(true);
    const allocatedName =
      type === "department" ? department.trim() : selected.name;
    try {
      await appraisalApi.create({
        type,
        userId: selected.id,
        department: type === "department" ? department.trim() : undefined,
      });
      setSelected(null);
      setDepartment("");
      setSearch("");
      setUsers([]);
      await load();
      Alert.alert(
        "Appraisal allocated",
        `${allocatedName} will be notified to complete it.`,
      );
    } catch (e: any) {
      Alert.alert("Could not allocate", e?.message || "Please try again.");
    } finally {
      setAssigning(false);
    }
  };

  const visible = filter === "all" ? items : items.filter((item) => item.status === filter);
  const toReview = items.filter((item) => item.status === "submitted").length;
  const awaiting = items.filter((item) => item.status === "assigned").length;
  const approved = items.filter((item) => item.status === "approved").length;
  const latestApproved =
    items
      .filter((item) => item.status === "approved" && item.score != null)
      .sort((a, b) =>
        (b.reviewedAt || b.createdAt || "").localeCompare(a.reviewedAt || a.createdAt || ""),
      )[0] ?? null;

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.header}>
          <TouchableOpacity
            onPress={() => router.back()}
            style={styles.headerBtn}
            accessibilityLabel="Close appraisals"
          >
            <Ionicons name="close" size={22} color={colors.darkGreen} />
          </TouchableOpacity>
          <Text style={styles.headerTitle}>Appraisals</Text>
          <View style={{ width: 36 }} />
        </View>

        {loading ? (
          <View style={styles.skeletonWrap}>
            <SkeletonPulse style={{ height: 150, borderRadius: 22 }} />
            <SkeletonPulse style={{ height: 62, borderRadius: 16 }} />
            <SkeletonPulse style={{ height: 78, borderRadius: 16 }} />
          </View>
        ) : error ? (
          <EmptyState
            icon="warning-outline"
            color={colors.error}
            eyebrow="Something went wrong"
            title="Couldn’t load appraisals"
            subtitle={error}
            actionLabel="Retry"
            onAction={() => {
              setLoading(true);
              load();
            }}
          />
        ) : (
          <KeyboardAvoidingView
            behavior={Platform.OS === "ios" ? "padding" : "height"}
            style={styles.flex}
          >
            <ScrollView
              contentContainerStyle={[styles.list, { paddingBottom: 32 + insets.bottom }]}
              showsVerticalScrollIndicator={false}
              keyboardShouldPersistTaps="handled"
              keyboardDismissMode="none"
              refreshControl={
                <RefreshControl
                  refreshing={refreshing}
                  onRefresh={onRefresh}
                  tintColor={colors.goldDark}
                  colors={[colors.goldDark]}
                />
              }
            >
              <LinearGradient
                colors={["#FFE9D6", "#FFCBA4"]}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={styles.heroCard}
              >
                <View style={styles.heroHead}>
                  <Ionicons name="clipboard" size={16} color="#9A3412" />
                  <Text style={styles.heroEyebrow}>{"APPRAISALS"}</Text>
                </View>
                <Text style={styles.heroTitle}>
                  {isAdmin ? "Seasonal appraisals" : "Your appraisals"}
                </Text>
                <Text style={styles.heroSub}>
                  {isAdmin
                    ? "Allocate a form, review what comes back and approve the season score."
                    : "Complete the form when your admin allocates one. Approved scores appear on the organisation performance screen."}
                </Text>
                {!isAdmin && latestApproved ? (
                  <View style={styles.heroScoreRow}>
                    <View style={{ flex: 1 }}>
                      <Text style={styles.heroScoreLabel}>{"LATEST SCORE"}</Text>
                      <Text style={styles.heroScoreSeason}>
                        {latestApproved.season} {latestApproved.seasonYear}
                        {latestApproved.band ? ` · ${latestApproved.band}` : ""}
                      </Text>
                    </View>
                    <Text style={styles.heroScoreValue}>
                      {Math.round(latestApproved.score ?? 0)}%
                    </Text>
                  </View>
                ) : null}
              </LinearGradient>

              {isAdmin ? (
                <View style={styles.statsRow}>
                  <StatCard
                    label="Awaiting form"
                    value={String(awaiting)}
                    color="#b45309"
                    active={filter === "assigned"}
                    onPress={() => setFilter(filter === "assigned" ? "all" : "assigned")}
                  />
                  <StatCard
                    label="To review"
                    value={String(toReview)}
                    color="#0e7490"
                    active={filter === "submitted"}
                    onPress={() => setFilter(filter === "submitted" ? "all" : "submitted")}
                  />
                  <StatCard
                    label="Approved"
                    value={String(approved)}
                    color="#047857"
                    active={filter === "approved"}
                    onPress={() => setFilter(filter === "approved" ? "all" : "approved")}
                  />
                </View>
              ) : null}

              {isAdmin ? (
                <View style={styles.card}>
                  <View style={styles.cardHead}>
                    <Ionicons name="clipboard-outline" size={16} color={colors.goldDark} />
                    <Text style={styles.cardTitle}>Allocate an appraisal</Text>
                  </View>
                  <Text style={styles.cardSub}>
                    Choose a member and the kind of appraisal they must complete.
                  </Text>

                  <View style={styles.segment}>
                    {(["individual", "department"] as AppraisalType[]).map((option) => (
                      <TouchableOpacity
                        key={option}
                        style={[styles.segmentBtn, type === option && styles.segmentBtnOn]}
                        onPress={() => setType(option)}
                        activeOpacity={0.85}
                      >
                        <Text
                          style={[
                            styles.segmentText,
                            type === option && styles.segmentTextOn,
                          ]}
                        >
                          {option === "individual" ? "Individual" : "Department"}
                        </Text>
                      </TouchableOpacity>
                    ))}
                  </View>

                  {type === "department" ? (
                    <TextInput
                      style={styles.input}
                      placeholder="Department or club name"
                      placeholderTextColor={colors.muted}
                      value={department}
                      onChangeText={setDepartment}
                    />
                  ) : null}

                  <View style={styles.searchWrap}>
                    <Ionicons name="search-outline" size={16} color={colors.muted} />
                    <TextInput
                      style={styles.searchInput}
                      placeholder={
                        type === "department" ? "Search the department lead" : "Search a member"
                      }
                      placeholderTextColor={colors.muted}
                      value={search}
                      onChangeText={(text) => {
                        setSearch(text);
                        setSelected(null);
                      }}
                      autoCapitalize="none"
                    />
                    {searching ? (
                      <ActivityIndicator size="small" color={colors.goldDark} />
                    ) : null}
                  </View>

                  {search.trim().length >= 2 ? (
                    <View style={styles.results}>
                      {users.length === 0 && !searching ? (
                        <Text style={styles.resultEmpty}>No members match that search.</Text>
                      ) : (
                        users.slice(0, 6).map((user) => (
                          <TouchableOpacity
                            key={user.id}
                            style={[
                              styles.resultRow,
                              selected?.id === user.id && styles.resultRowOn,
                            ]}
                            onPress={() => setSelected(user)}
                            activeOpacity={0.85}
                          >
                            <View style={styles.avatar}>
                              <Text style={styles.avatarText}>
                                {user.name.charAt(0).toUpperCase()}
                              </Text>
                            </View>
                            <View style={{ flex: 1 }}>
                              <Text style={styles.resultName}>{user.name}</Text>
                              <Text style={styles.resultEmail} numberOfLines={1}>
                                {user.email || user.role}
                              </Text>
                            </View>
                            {selected?.id === user.id ? (
                              <Ionicons
                                name="checkmark-circle"
                                size={18}
                                color={colors.goldDark}
                              />
                            ) : null}
                          </TouchableOpacity>
                        ))
                      )}
                    </View>
                  ) : null}

                  {selected ? (
                    <Text style={styles.selectedNote}>
                      {type === "department"
                        ? `${department.trim() || "Department"} · ${selected.name}`
                        : selected.name}
                    </Text>
                  ) : null}

                  <TouchableOpacity
                    style={[styles.primaryBtn, assigning && styles.primaryBtnBusy]}
                    onPress={allocate}
                    disabled={assigning}
                    activeOpacity={0.9}
                  >
                    <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                    {assigning ? (
                      <ActivityIndicator color={colors.white} />
                    ) : (
                      <>
                        <Ionicons name="add-circle-outline" size={18} color={colors.white} />
                        <Text style={styles.primaryText}>Allocate appraisal</Text>
                      </>
                    )}
                  </TouchableOpacity>
                </View>
              ) : null}

              {isAdmin ? (
                <ScrollView
                  horizontal
                  showsHorizontalScrollIndicator={false}
                  contentContainerStyle={styles.filterRow}
                >
                  {FILTERS.map((option) => (
                    <TouchableOpacity
                      key={option.key}
                      style={[styles.filterChip, filter === option.key && styles.filterChipOn]}
                      onPress={() => setFilter(option.key)}
                      activeOpacity={0.85}
                    >
                      <Text
                        style={[
                          styles.filterText,
                          filter === option.key && styles.filterTextOn,
                        ]}
                      >
                        {option.label}
                      </Text>
                    </TouchableOpacity>
                  ))}
                </ScrollView>
              ) : null}

              {visible.length === 0 ? (
                <View style={styles.emptyCard}>
                  <Ionicons name="clipboard-outline" size={22} color={colors.muted} />
                  <Text style={styles.emptyTitle}>
                    {isAdmin ? "No appraisals here yet" : "No appraisal allocated to you"}
                  </Text>
                  <Text style={styles.emptyBody}>
                    {isAdmin
                      ? "Allocate one above and its progress will appear here."
                      : "Your admin will allocate the next seasonal appraisal."}
                  </Text>
                </View>
              ) : (
                visible.map((item) => {
                  const tone = STATUS_TONE[item.status] ?? STATUS_TONE.assigned;
                  return (
                    <TouchableOpacity
                      key={item._id}
                      style={styles.rowCard}
                      activeOpacity={0.85}
                      onPress={() =>
                        router.push({
                          pathname: "/appraisal/[id]",
                          params: { id: item._id },
                        } as any)
                      }
                    >
                      <View style={[styles.rowTile, { backgroundColor: tone.bg }]}>
                        <Ionicons name={tone.icon} size={19} color={tone.color} />
                      </View>
                      <View style={styles.rowBody}>
                        <View style={styles.rowTop}>
                          <Text style={styles.rowTitle} numberOfLines={1}>
                            {item.type === "department" ? item.department : item.subjectName}
                          </Text>
                          {item.score != null ? (
                            <Text style={[styles.rowScore, { color: tone.color }]}>
                              {Math.round(item.score)}%
                            </Text>
                          ) : null}
                        </View>
                        <Text style={styles.rowSub} numberOfLines={1}>
                          {item.type === "department"
                            ? `Department · lead ${item.subjectName}`
                            : "Individual"}
                          {" · "}
                          {item.season} {item.seasonYear}
                        </Text>
                        <View style={styles.rowBottom}>
                          <StatusPill status={item.status} label={item.statusLabel} />
                          <Text style={styles.rowCta}>
                            {item.status === "assigned" || item.status === "rejected"
                              ? "Complete"
                              : item.status === "submitted"
                                ? "Review"
                                : "View"}
                          </Text>
                        </View>
                      </View>
                      <Ionicons name="chevron-forward" size={15} color={colors.muted} />
                    </TouchableOpacity>
                  );
                })
              )}
            </ScrollView>
          </KeyboardAvoidingView>
        )}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

