import { Ionicons } from "@expo/vector-icons";
import { Image } from "expo-image";
import { StatusBar } from "expo-status-bar";
import { useLocalSearchParams, useRouter } from "expo-router";
import { useMemo, useState } from "react";
import {
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaProvider, SafeAreaView, useSafeAreaInsets } from "react-native-safe-area-context";
import { SkeletonPulse } from "@/components/Skeleton";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { addToCart, useCartCount } from "@/services/cart";
import {
  effectivePrice,
  formatPrice,
  useStoreProduct,
} from "@/services/store";
import { getOptimizedImageUrl } from "@/services/cloudinary";
import { GradientBox } from "@/constants/gradients";

/**
 * Product page — the gallery is the star: one large photo with a strip of
 * thumbnails underneath, and tapping a thumbnail swaps it straight into the
 * main frame (the same pattern every storefront uses).
 */
export default function ProductScreen() {
  const insets = useSafeAreaInsets();
  const router = useRouter();
  const { id } = useLocalSearchParams<{ id: string }>();
  const { product, loading, error } = useStoreProduct(id);
  const cartCount = useCartCount();

  const gallery = useMemo(() => {
    if (!product) return [] as string[];
    const shots = [product.image, ...product.images].filter(Boolean);
    return Array.from(new Set(shots));
  }, [product]);

  // Gallery and option state are derived from the loaded product instead of
  // being reset in an effect: switching products just clamps stale picks, so
  // there is no render that clears state it no longer owns.
  const [photoIndexRaw, setPhotoIndex] = useState(0);
  const [sizeSel, setSizeSel] = useState<string | null>(null);
  const [qtyRaw, setQty] = useState(1);
  const [added, setAdded] = useState(false);

  const photoIndex =
    gallery.length > 0 ? Math.min(photoIndexRaw, gallery.length - 1) : 0;
  const size = !product
    ? null
    : product.sizes.length === 0
      ? null
      : sizeSel && product.sizes.includes(sizeSel)
        ? sizeSel
        : product.sizes[0] ?? null;
  const qty = Math.min(20, Math.max(1, qtyRaw));

  if (loading) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={styles.bar}>
            <SkeletonPulse style={{ width: 42, height: 42, borderRadius: 21 }} />
            <SkeletonPulse style={{ flex: 1, height: 16, borderRadius: 6 }} />
            <SkeletonPulse style={{ width: 42, height: 42, borderRadius: 21 }} />
          </View>
          <SkeletonPulse style={styles.mainImg} />
          <View style={styles.thumbRow}>
            {[0, 1, 2].map((i) => (
              <SkeletonPulse
                key={i}
                style={{ width: 60, height: 60, borderRadius: 12 }}
              />
            ))}
          </View>
          <View style={styles.body}>
            <SkeletonPulse style={{ width: "45%", height: 12, borderRadius: 5 }} />
            <SkeletonPulse
              style={{ width: "80%", height: 22, borderRadius: 6, marginTop: 10 }}
            />
            <SkeletonPulse
              style={{ width: "100%", height: 13, borderRadius: 5, marginTop: 14 }}
            />
            <SkeletonPulse
              style={{ width: "85%", height: 13, borderRadius: 5, marginTop: 6 }}
            />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (!product) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={styles.bar}>
            <TouchableOpacity
              style={styles.iconBtn}
              onPress={() => router.back()}
              accessibilityRole="button"
              accessibilityLabel="Back"
            >
              <Ionicons name="chevron-back" size={22} color={colors.forest} />
            </TouchableOpacity>
          </View>
          <View style={styles.empty}>
            <Ionicons name="alert-circle-outline" size={30} color={colors.muted} />
            <Text style={styles.emptyText}>
              {error || "That product could not be found."}
            </Text>
            <TouchableOpacity
              style={styles.emptyBtn}
              onPress={() => router.replace("/(tabs)/store")}
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Text style={styles.emptyBtnText}>Back to the store</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const price = effectivePrice(product);
  const onSale = product.offerPrice != null && product.offerPrice < product.price;
  const requiresSize = product.sizes.length > 0;
  const canAdd = product.inStock && (!requiresSize || !!size);

  const handleAdd = (thenCheckout = false) => {
    if (!canAdd) return;
    addToCart(product, { qty, size });
    if (thenCheckout) {
      router.push("/checkout" as any);
      return;
    }
    setAdded(true);
    setTimeout(() => setAdded(false), 1500);
  };

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <StatusBar style="dark" />

        <View style={styles.bar}>
          <TouchableOpacity
            style={styles.iconBtn}
            onPress={() => router.back()}
            accessibilityRole="button"
            accessibilityLabel="Back"
          >
            <Ionicons name="chevron-back" size={22} color={colors.forest} />
          </TouchableOpacity>
          <Text style={styles.barTitle} numberOfLines={1}>
            {product.name}
          </Text>
          <TouchableOpacity
            style={styles.iconBtn}
            onPress={() => router.push("/cart" as any)}
            accessibilityRole="button"
            accessibilityLabel={`Cart, ${cartCount} items`}
          >
            <Ionicons name="bag-outline" size={20} color={colors.forest} />
            {cartCount > 0 ? (
              <View style={styles.cartBadge}>
                <Text style={styles.cartBadgeText}>{cartCount}</Text>
              </View>
            ) : null}
          </TouchableOpacity>
        </View>

        <ScrollView
          showsVerticalScrollIndicator={false}
          contentContainerStyle={styles.scroll}
        >
          {/* Main image */}
          <Pressable
            style={styles.mainImgWrap}
            onPress={() => {
              if (gallery.length < 2) return;
              setPhotoIndex((i) => (i + 1) % gallery.length);
            }}
            accessibilityRole="imagebutton"
            accessibilityLabel={
              gallery.length > 1 ? "Next photo" : product.name
            }
          >
            <Image
              source={{ uri: getOptimizedImageUrl(gallery[photoIndex] || product.image, 720) }}
              style={styles.mainImg}
              contentFit="cover"
              transition={250}
            />
            {gallery.length > 1 ? (
              <View style={styles.counter}>
                <Text style={styles.counterText}>
                  {photoIndex + 1} / {gallery.length}
                </Text>
              </View>
            ) : null}
          </Pressable>

          {/* Thumbnails — tap to promote to the main image */}
          {gallery.length > 1 ? (
            <ScrollView
              horizontal
              showsHorizontalScrollIndicator={false}
              contentContainerStyle={styles.thumbRow}
            >
              {gallery.map((uri, i) => {
                const active = i === photoIndex;
                return (
                  <TouchableOpacity
                    key={`${uri}-${i}`}
                    activeOpacity={0.85}
                    onPress={() => setPhotoIndex(i)}
                    style={[styles.thumb, active && styles.thumbActive]}
                    accessibilityRole="button"
                    accessibilityLabel={`Show photo ${i + 1}`}
                    accessibilityState={{ selected: active }}
                  >
                    <Image
                      source={getOptimizedImageUrl(uri, 720)}
                      style={styles.thumbImg}
                      contentFit="cover"
                    />
                  </TouchableOpacity>
                );
              })}
            </ScrollView>
          ) : null}

          <View style={styles.body}>
            <Text style={styles.category}>{product.category.toUpperCase()}</Text>
            <Text style={styles.name}>{product.name}</Text>

            <View style={styles.priceRow}>
              <Text style={styles.price}>{formatPrice(price)}</Text>
              {onSale ? (
                <Text style={styles.priceWas}>{formatPrice(product.price)}</Text>
              ) : null}
              {product.rating != null ? (
                <View style={styles.rating}>
                  <Ionicons name="star" size={13} color={colors.warning} />
                  <Text style={styles.ratingText}>{product.rating.toFixed(1)}</Text>
                </View>
              ) : null}
            </View>

            {!product.inStock ? (
              <View style={styles.stockOut}>
                <Ionicons name="close-circle-outline" size={15} color={colors.error} />
                <Text style={styles.stockOutText}>
                  Out of stock — this one is unavailable right now.
                </Text>
              </View>
            ) : null}

            {!!product.blurb && <Text style={styles.blurb}>{product.blurb}</Text>}

            {/* Sizes */}
            {requiresSize ? (
              <View style={styles.block}>
                <Text style={styles.blockTitle}>Select size</Text>
                <View style={styles.sizes}>
                  {product.sizes.map((s) => {
                    const active = size === s;
                    return (
                      <TouchableOpacity
                        key={s}
                        style={[styles.size, active && styles.sizeActive]}
                        activeOpacity={0.8}
                        onPress={() => setSizeSel(s)}
                        accessibilityRole="button"
                        accessibilityLabel={`Size ${s}`}
                        accessibilityState={{ selected: active }}
                      >
                        {active && (
                          <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                        )}
                        <Text
                          style={[styles.sizeText, active && styles.sizeTextActive]}
                        >
                          {s}
                        </Text>
                      </TouchableOpacity>
                    );
                  })}
                </View>
              </View>
            ) : null}

            {/* Quantity */}
            <View style={styles.block}>
              <Text style={styles.blockTitle}>Quantity</Text>
              <View style={styles.stepper}>
                <TouchableOpacity
                  style={styles.stepBtn}
                  onPress={() => setQty((q) => Math.max(1, q - 1))}
                  disabled={qty <= 1}
                  accessibilityRole="button"
                  accessibilityLabel="Decrease quantity"
                >
                  <Ionicons
                    name="remove"
                    size={18}
                    color={qty <= 1 ? colors.muted : colors.ink}
                  />
                </TouchableOpacity>
                <Text style={styles.stepValue}>{qty}</Text>
                <TouchableOpacity
                  style={styles.stepBtn}
                  onPress={() => setQty((q) => Math.min(20, q + 1))}
                  disabled={qty >= 20}
                  accessibilityRole="button"
                  accessibilityLabel="Increase quantity"
                >
                  <Ionicons
                    name="add"
                    size={18}
                    color={qty >= 20 ? colors.muted : colors.ink}
                  />
                </TouchableOpacity>
              </View>
            </View>

            {/* Details */}
            {product.details.length > 0 ? (
              <View style={styles.block}>
                <Text style={styles.blockTitle}>About this product</Text>
                {product.details.map((line, i) => (
                  <View key={i} style={styles.bulletRow}>
                    <View style={styles.bulletDot} />
                    <Text style={styles.bulletText}>{line}</Text>
                  </View>
                ))}
              </View>
            ) : null}

            <View style={styles.trustRow}>
              <Ionicons name="cube-outline" size={14} color={colors.muted} />
              <Text style={styles.trustText}>
                Packed by the Relate team · pay by EFT after checkout
              </Text>
            </View>
          </View>
        </ScrollView>

        {/* Sticky purchase bar */}
        <View style={[styles.buyBar, { paddingBottom: Math.max(12, insets.bottom) }]}>
          <TouchableOpacity
            style={[styles.secondaryBtn, !canAdd && styles.btnOff]}
            onPress={() => handleAdd(false)}
            disabled={!canAdd}
            activeOpacity={0.9}
            accessibilityRole="button"
            accessibilityLabel="Add to cart"
          >
            {added ? (
              <Ionicons name="checkmark" size={18} color={colors.forest} />
            ) : (
              <Text style={styles.secondaryText}>
                {added ? "Added" : "Add to cart"}
              </Text>
            )}
          </TouchableOpacity>
          <TouchableOpacity
            style={[styles.primaryBtn, !canAdd && styles.btnOff]}
            onPress={() => handleAdd(true)}
            disabled={!canAdd}
            activeOpacity={0.9}
            accessibilityRole="button"
            accessibilityLabel="Buy now"
          >
            <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
            <Text style={styles.primaryText}>Buy now</Text>
            <Ionicons name="arrow-forward" size={16} color={colors.white} />
          </TouchableOpacity>
        </View>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

