const fmtDateTime = (value?: string | null) => {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-ZA", {
    day: "numeric",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
};

const fmtDate = (value?: string | null) => {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-ZA", { day: "numeric", month: "short" });
};

function SubmitWorkModal({
  service,
  visible,
  onClose,
  onSubmitted,
}: {
  service: ClubService;
  visible: boolean;
  onClose: () => void;
  onSubmitted: () => void;
}) {
  const submissionDraftKey = `form-draft:service-submission:${service._id}`;
  const insets = useSafeAreaInsets();
  const [note, setNote] = usePersistentFormState(`${submissionDraftKey}:note`, "");
  const [githubLink, setGithubLink] = usePersistentFormState(`${submissionDraftKey}:githubLink`, "");
  const [imageUrls, setImageUrls] = useState<string[]>([]);
  const [imageLoading, setImageLoading] = useState(false);
  const [busy, setBusy] = useState(false);

  const needsGithub = service.type === "bug";
  const needsImage = service.type === "design";
  const canGithub = service.type === "bug" || service.type === "other";
  const canImage = service.type === "design" || service.type === "other";

  const reset = () => {
    setNote("");
    setGithubLink("");
    setImageUrls([]);
  };

  const pickImage = async () => {
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ["images"],
      allowsEditing: false,
      allowsMultipleSelection: true,
      quality: 0.8,
      base64: true,
    });
    if (!result.canceled && result.assets?.length > 0) {
      setImageLoading(true);
      try {
        const urls = await Promise.all(
          result.assets.map((asset) => uploadStoreImage(asset)),
        );
        setImageUrls((current) => [...current, ...urls]);
      } catch (err) {
        Alert.alert(
          "Upload Failed",
          err instanceof Error ? err.message : "Could not upload the image.",
        );
      }
      setImageLoading(false);
    }
  };

  const removeImage = (index: number) => {
    setImageUrls((current) => current.filter((_, i) => i !== index));
  };

  const submit = async () => {
    if (!note.trim()) {
      Alert.alert("Add a note", "Tell the admin what you delivered.");
      return;
    }
    if (needsGithub && !githubLink.trim()) {
      Alert.alert("GitHub link needed", "Bug fixes need a PR or commit link.");
      return;
    }
    if (needsGithub && !/^https?:\/\//i.test(githubLink.trim())) {
      Alert.alert("Check the link", "The GitHub link must start with http(s)://");
      return;
    }
    if (needsImage && imageUrls.length === 0) {
      Alert.alert("Image needed", "Design work needs the finished image.");
      return;
    }
    setBusy(true);
    try {
      await servicesApi.submit(service._id, {
        note: note.trim(),
        githubLink: githubLink.trim() ? githubLink.trim() : null,
        imageUrls,
      });
      await clearPersistentFormDraft(submissionDraftKey);
      reset();
      onClose();
      onSubmitted();
    } catch (e: any) {
      Alert.alert("Could not submit", e?.message || "Please try again.");
    }
    setBusy(false);
  };

  return (
    <Modal visible={visible} transparent animationType="slide" onRequestClose={onClose}>
      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : "height"}
        style={styles.sheetAvoider}
      >
        <View
          style={[
            styles.sheet,
            { paddingBottom: Math.max(insets.bottom, 16) + 8 },
          ]}
        >
          <View style={styles.sheetHead}>
            <Text style={styles.sheetTitle}>Submit your work</Text>
            <TouchableOpacity onPress={onClose} style={styles.sheetClose}>
              <Ionicons name="close" size={18} color={colors.muted} />
            </TouchableOpacity>
          </View>

          <ScrollView
            style={styles.sheetScroll}
            contentContainerStyle={styles.sheetBody}
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator={false}
          >
            <Text style={styles.fieldLabel}>What did you deliver?</Text>
            <TextInput
              style={[styles.input, styles.textarea]}
              value={note}
              onChangeText={setNote}
              multiline
              placeholder="Summary of the fix / design and anything the admin should check."
              placeholderTextColor={colors.muted}
            />

            {canGithub ? (
              <>
                <Text style={styles.fieldLabel}>
                  GitHub link {needsGithub ? "(required)" : "(optional)"}
                </Text>
                <TextInput
                  style={styles.input}
                  value={githubLink}
                  onChangeText={setGithubLink}
                  autoCapitalize="none"
                  keyboardType="url"
                  placeholder="https://github.com/…/pull/123"
                  placeholderTextColor={colors.muted}
                />
              </>
            ) : null}

            {canImage ? (
              <>
                <Text style={styles.fieldLabel}>
                  Work images {needsImage ? "(at least 1 required)" : "(optional)"}
                </Text>
                <TouchableOpacity
                  style={styles.imageAddBtn}
                  activeOpacity={0.85}
                  onPress={pickImage}
                  disabled={imageLoading}
                  accessibilityLabel="Add work images"
                >
                  {imageLoading ? (
                    <ActivityIndicator color={colors.forest} />
                  ) : (
                    <>
                      <Ionicons name="images-outline" size={20} color={colors.forest} />
                      <Text style={styles.imageAddText}>
                        {imageUrls.length
                          ? `Add more images (${imageUrls.length} added)`
                          : "Add images"}
                      </Text>
                    </>
                  )}
                </TouchableOpacity>
                {imageUrls.length > 0 ? (
                  <View style={styles.imageGrid}>
                    {imageUrls.map((url, index) => (
                      <View key={`${url}-${index}`} style={styles.imageTile}>
                        <Image
                          source={{ uri: getOptimizedImageUrl(url, 240) }}
                          style={styles.imageThumb}
                          contentFit="cover"
                        />
                        <TouchableOpacity
                          style={styles.imageRemove}
                          onPress={() => removeImage(index)}
                          hitSlop={8}
                          accessibilityLabel={`Remove image ${index + 1}`}
                        >
                          <Ionicons
                            name="close-circle"
                            size={22}
                            color={colors.forestDark}
                          />
                        </TouchableOpacity>
                      </View>
                    ))}
                  </View>
                ) : null}
              </>
            ) : null}
          </ScrollView>

          <TouchableOpacity
            style={[styles.primaryBtn, (busy || imageLoading) && styles.btnDisabled]}
            onPress={submit}
            disabled={busy || imageLoading}
            activeOpacity={0.9}
          >
            {busy ? (
              <ActivityIndicator color={colors.forestDark} />
            ) : (
              <>
                <Text style={styles.primaryBtnText}>Submit for review</Text>
                <Ionicons name="arrow-forward" size={16} color={colors.forestDark} />
              </>
            )}
          </TouchableOpacity>
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
}

export default function ServiceDetailScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const [service, setService] = useState<ClubService | null>(null);
  const [error, setError] = useState("");
  const [isAdmin, setIsAdmin] = useState(false);
  const [busy, setBusy] = useState(false);
  const [submitOpen, setSubmitOpen] = useState(false);
  const [adminNote, setAdminNote] = useState<string>("");

  const load = useCallback(async () => {
    if (!id) return;
    try {
      const res = await servicesApi.get(id);
      setService(res.data);
      setError("");
    } catch (e: any) {
      setError(e?.message || "Could not reach the server.");
    }
  }, [id]);

  useEffect(() => {
    (async () => {
      const s = await getSession();
      setIsAdmin(s?.user?.role === "admin");
      await load();
    })();
  }, [load]);

  const run = async (label: string, action: () => Promise<unknown>) => {
    setBusy(true);
    try {
      await action();
      await load();
    } catch (e: any) {
      Alert.alert(label + " failed", e?.message || "Please try again.");
    }
    setBusy(false);
  };

  const confirm = (title: string, body: string, label: string, action: () => Promise<unknown>) => {
    Alert.alert(title, body, [
      { text: "Cancel", style: "cancel" },
      { text: label, style: "destructive", onPress: () => run(title, action) },
    ]);
  };

  if (!service && !error) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <View style={styles.bar}>
            <TouchableOpacity onPress={() => router.back()} style={styles.iconBtn}>
              <Ionicons name="chevron-back" size={20} color={colors.forest} />
            </TouchableOpacity>
          </View>
          <View style={styles.skeletonWrap}>
            {[0, 1, 2].map((i) => (
              <SkeletonPulse key={i} style={styles.skeletonBlock} />
            ))}
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (error || !service) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <View style={styles.bar}>
            <TouchableOpacity onPress={() => router.back()} style={styles.iconBtn}>
              <Ionicons name="chevron-back" size={20} color={colors.forest} />
            </TouchableOpacity>
          </View>
          <EmptyState
            icon="warning-outline"
            color={colors.error}
            eyebrow="Something went wrong"
            title="Couldn't load this service"
            subtitle={error}
            actionLabel="Retry"
            onAction={load}
          />
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const type = SERVICE_TYPE_META[service.type];
  const status = SERVICE_STATUS_META[service.status];
  const mine = !!service.isClaimedByMe;
  const clubName = service.clubSlug
    ? CLUBS.find((c) => c.slug === service.clubSlug)?.name || service.clubSlug
    : null;

  const openGithub = () => {
    const url = service.submission?.githubLink;
    if (url) Linking.openURL(url).catch(() => {});
  };

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.bar}>
          <TouchableOpacity
            onPress={() => router.back()}
            style={styles.iconBtn}
            accessibilityLabel="Back"
          >
            <Ionicons name="chevron-back" size={20} color={colors.forest} />
          </TouchableOpacity>
          <View style={[styles.typeChip, { backgroundColor: `${type.color}16` }]}>
            <Ionicons name={type.icon} size={13} color={type.color} />
            <Text style={[styles.typeChipText, { color: type.color }]}>
              {type.label}
            </Text>
          </View>
          <View style={{ flex: 1 }} />
          <View style={[styles.pill, { backgroundColor: status.bg }]}>
            <Text style={[styles.pillText, { color: status.color }]}>{status.label}</Text>
          </View>
        </View>

        <ScrollView contentContainerStyle={styles.content} showsVerticalScrollIndicator={false}>
          <Text style={styles.title}>{service.title}</Text>

          <View style={styles.metaRow}>
            <Ionicons name="person-circle-outline" size={15} color={colors.muted} />
            <Text style={styles.metaText}>
              Posted by {service.posterName}
              {clubName ? ` · ${clubName}` : ""}
            </Text>
            <View style={{ flex: 1 }} />
            <Text style={styles.metaDate}>{fmtDate(service.createdAt)}</Text>
          </View>

          <View style={styles.descCard}>
            <Text style={styles.descText}>{service.description}</Text>
          </View>

          {service.dueDate &&
          service.status !== "approved" &&
          service.status !== "closed" ? (
            <View style={styles.infoRow}>
              <Ionicons name="calendar-outline" size={16} color={colors.forest} />
              <Text style={styles.infoText}>Due by {fmtDate(service.dueDate)}</Text>
            </View>
          ) : null}

          {service.acceptedByName && service.status !== "open" ? (
            <View style={styles.infoRow}>
              <Ionicons name="hand-left-outline" size={16} color={colors.forest} />
              <Text style={styles.infoText}>
                {mine ? "You are" : `${service.acceptedByName} is`} working on this
                {service.acceptedAt ? ` · since ${fmtDate(service.acceptedAt)}` : ""}
              </Text>
            </View>
          ) : null}

          {service.submission ? (
            <View style={styles.submissionCard}>
              <View style={styles.submissionHead}>
                <Ionicons name="checkmark-done" size={16} color={colors.success} />
                <Text style={styles.submissionTitle}>Submitted work</Text>
                <View style={{ flex: 1 }} />
                <Text style={styles.submissionDate}>
                  {fmtDateTime(service.submission.submittedAt)}
                </Text>
              </View>
              <Text style={styles.submissionNote}>{service.submission.note}</Text>

              {service.submission.githubLink ? (
                <TouchableOpacity
                  style={styles.linkBtn}
                  activeOpacity={0.85}
                  onPress={openGithub}
                >
                  <Ionicons name="logo-github" size={16} color={colors.forest} />
                  <Text style={styles.linkBtnText} numberOfLines={1}>
                    Open pull request
                  </Text>
                  <Ionicons name="open-outline" size={14} color={colors.muted} />
                </TouchableOpacity>
              ) : null}

              {(service.submission.imageUrls?.length
                ? service.submission.imageUrls
                : service.submission.imageUrl
                  ? [service.submission.imageUrl]
                  : []
              ).map((url, index) => (
                <View key={url} style={{ gap: 8, marginTop: 8 }}>
                  <Image
                    source={{ uri: getOptimizedImageUrl(url, 720) }}
                    style={styles.submissionImage}
                    contentFit="cover"
                  />
                  <TouchableOpacity
                    style={styles.linkBtn}
                    activeOpacity={0.85}
                    onPress={() => Linking.openURL(url)}
                  >
                    <Ionicons name="download-outline" size={16} color={colors.forest} />
                    <Text style={styles.linkBtnText}>Download proof image {index + 1}</Text>
                    <Ionicons name="open-outline" size={14} color={colors.muted} />
                  </TouchableOpacity>
                </View>
              ))}
            </View>
          ) : null}

          {service.review ? (
            <View
              style={[
                styles.reviewCard,
                {
                  backgroundColor: service.review.approved ? "#d1fae5" : "#fef3c7",
                  borderColor: service.review.approved ? "#6ee7b7" : "#fcd34d",
                },
              ]}
            >
              <Ionicons
                name={service.review.approved ? "shield-checkmark" : "refresh"}
                size={16}
                color={service.review.approved ? "#047857" : "#b45309"}
              />
              <View style={{ flex: 1 }}>
                <Text
                  style={[
                    styles.reviewTitle,
                    { color: service.review.approved ? "#047857" : "#b45309" },
                  ]}
                >
                  {service.review.approved
                    ? "Approved by the admin"
                    : "Sent back for changes"}
                </Text>
                {service.review.note ? (
                  <Text style={styles.reviewNote}>{service.review.note}</Text>
                ) : null}
              </View>
            </View>
          ) : null}

          {/* ── Actions ── */}
          <View style={styles.actions}>
            {!isAdmin && service.status === "open" ? (
              <TouchableOpacity
                style={[styles.primaryBtn, busy && styles.btnDisabled]}
                disabled={busy}
                activeOpacity={0.9}
                onPress={() =>
                  run("Accept", () => servicesApi.accept(service._id))
                }
              >
                <Ionicons name="hand-left" size={16} color={colors.forestDark} />
                <Text style={styles.primaryBtnText}>Accept this service</Text>
              </TouchableOpacity>
            ) : null}

            {!isAdmin && service.status === "accepted" && mine ? (
              <>
                <TouchableOpacity
                  style={[styles.primaryBtn, busy && styles.btnDisabled]}
                  disabled={busy}
                  activeOpacity={0.9}
                  onPress={() => setSubmitOpen(true)}
                >
                  <Ionicons name="cloud-upload" size={16} color={colors.forestDark} />
                  <Text style={styles.primaryBtnText}>Submit work</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={styles.ghostBtn}
                  disabled={busy}
                  activeOpacity={0.85}
                  onPress={() =>
                    confirm(
                      "Withdraw",
                      "Release this service so someone else can take it?",
                      "Withdraw",
                      () => servicesApi.withdraw(service._id),
                    )
                  }
                >
                  <Text style={styles.ghostBtnText}>Withdraw</Text>
                </TouchableOpacity>
              </>
            ) : null}

            {!isAdmin && service.status === "submitted" && mine ? (
              <View style={styles.waitRow}>
                <Ionicons name="time-outline" size={16} color={colors.muted} />
                <Text style={styles.waitText}>
                  Waiting for the admin to review your work.
                </Text>
              </View>
            ) : null}

            {!isAdmin && service.status === "accepted" && !mine ? (
              <View style={styles.waitRow}>
                <Ionicons name="lock-closed-outline" size={16} color={colors.muted} />
                <Text style={styles.waitText}>
                  Another member is working on this service.
                </Text>
              </View>
            ) : null}

            {isAdmin && service.status === "open" ? (
              <View style={styles.waitRow}>
                <Ionicons name="hourglass-outline" size={16} color={colors.muted} />
                <Text style={styles.waitText}>
                  Posted — waiting for a member to accept.
                </Text>
              </View>
            ) : null}

            {isAdmin && service.status === "submitted" ? (
              <>
                <Text style={styles.fieldLabel}>Note for the member</Text>
                <TextInput
                  value={adminNote}
                  onChangeText={setAdminNote}
                  placeholder="What looks good, or what needs changing…"
                  multiline
                  numberOfLines={2}
                  style={styles.input}
                />
                <TouchableOpacity
                  style={[styles.primaryBtn, busy && styles.btnDisabled]}
                  disabled={busy}
                  activeOpacity={0.9}
                  onPress={() =>
                    run("Approve", () =>
                      servicesApi.update(service._id, { action: "approve", note: adminNote || undefined }),
                    )
                  }
                >
                  <Ionicons name="checkmark-circle" size={16} color={colors.forestDark} />
                  <Text style={styles.primaryBtnText}>Approve work</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={styles.ghostBtn}
                  disabled={busy}
                  activeOpacity={0.85}
                  onPress={() =>
                    confirm(
                      "Send back",
                      "Return this service to the member for changes?",
                      "Send back",
                      () =>
                        servicesApi.update(service._id, { action: "reopen", note: adminNote || undefined }),
                    )
                  }
                >
                  <Text style={styles.ghostBtnText}>Send back for changes</Text>
                </TouchableOpacity>
                {service.submission?.githubLink ? (
                  <TouchableOpacity
                    style={styles.linkWide}
                    activeOpacity={0.85}
                    onPress={openGithub}
                  >
                    <Ionicons name="logo-github" size={16} color={colors.forest} />
                    <Text style={styles.linkWideText}>Open GitHub link</Text>
                    <Ionicons name="open-outline" size={14} color={colors.muted} />
                  </TouchableOpacity>
                ) : null}
              </>
            ) : null}

            {isAdmin && service.status === "approved" ? (
              <View style={styles.waitRow}>
                <Ionicons name="shield-checkmark" size={16} color={colors.success} />
                <Text style={styles.waitText}>This work has been approved.</Text>
              </View>
            ) : null}

            {isAdmin && service.status === "closed" ? (
              <TouchableOpacity
                style={styles.primaryBtn}
                activeOpacity={0.9}
                onPress={() =>
                  run("Reopen", () =>
                    servicesApi.update(service._id, { action: "reopen" }),
                  )
                }
              >
                <Ionicons name="refresh" size={16} color={colors.forestDark} />
                <Text style={styles.primaryBtnText}>Reopen</Text>
              </TouchableOpacity>
            ) : null}

            {isAdmin && service.status !== "closed" ? (
              <TouchableOpacity
                style={styles.ghostBtn}
                disabled={busy}
                activeOpacity={0.85}
                onPress={() =>
                  confirm(
                    "Close",
                    "Close this service? It moves out of the open list.",
                    "Close",
                    () => servicesApi.update(service._id, { action: "close" }),
                  )
                }
              >
                <Text style={styles.ghostBtnText}>Close service</Text>
              </TouchableOpacity>
            ) : null}
          </View>
        </ScrollView>

        <SubmitWorkModal
          service={service}
          visible={submitOpen}
          onClose={() => setSubmitOpen(false)}
          onSubmitted={load}
        />
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

