import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  BackHandler,
  Keyboard,
  LayoutChangeEvent,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaProvider, SafeAreaView } from "react-native-safe-area-context";
import { router } from "expo-router";
import { colors } from "@/constants/colors";
import { getSession } from "@/services/auth";
import {
  badgeStyles,
  chapters,
  navGroups,
  type ManualChapter,
  type ManualSection,
} from "@/data/relateManual";
import { GradientBox } from "@/constants/gradients";

type ManualMatch = {
  chapterId: string;
  chapterNumber: string;
  chapterTitle: string;
  sectionTitle: string;
  index: number;
  snippet: string;
};

function SectionBody({ section }: { section: ManualSection }) {
  const badge = section.badge ? badgeStyles[section.badge] : null;
  return (
    <View style={styles.secCard}>
      <View style={styles.secTitleRow}>
        <Text style={styles.secTitle}>{section.title}</Text>
        {badge ? (
          <View style={[styles.badgeChip, { backgroundColor: badge.bg }]}>
            <Text style={[styles.badgeText, { color: badge.text }]}>
              {section.badge}
            </Text>
          </View>
        ) : null}
      </View>

      {section.highlight && section.body ? (
        <View style={styles.highlightBox}>
          <Text style={styles.highlightMark}>“</Text>
          <Text style={styles.highlightBody}>{section.body}</Text>
        </View>
      ) : null}

      {!section.highlight && section.body ? (
        <Text style={styles.secBody}>{section.body}</Text>
      ) : null}

      {section.note ? (
        <View style={styles.noteBox}>
          <Ionicons name="information-circle" size={15} color={colors.goldDark} />
          <Text style={styles.noteText}>{section.note}</Text>
        </View>
      ) : null}

      {section.tags ? (
        <View style={styles.tagRow}>
          {section.tags.map((tag, ti) => (
            <View key={ti} style={styles.tagChip}>
              <Text style={styles.tagText}>{tag}</Text>
            </View>
          ))}
        </View>
      ) : null}

      {section.list ? (
        <View style={styles.listBlock}>
          {section.list.map((item, li) => (
            <View key={li} style={styles.listRow}>
              <Text style={styles.listBullet}>◆</Text>
              <Text style={styles.listItem}>{item}</Text>
            </View>
          ))}
        </View>
      ) : null}

      {section.stages ? (
        <View style={styles.stagesRow}>
          {section.stages.map((stage, si) => (
            <View key={si} style={styles.stageCard}>
              <Text style={styles.stageLabel}>{stage.label}</Text>
              <Text style={styles.stageName}>{stage.name}</Text>
              {stage.items.map((item, ii) => (
                <View key={ii} style={styles.stageItemRow}>
                  <Ionicons
                    name="checkmark-circle"
                    size={14}
                    color={colors.goldDark}
                  />
                  <Text style={styles.stageItem}>{item}</Text>
                </View>
              ))}
            </View>
          ))}
        </View>
      ) : null}
    </View>
  );
}


export default function RelateManualScreen() {
  const [checking, setChecking] = useState(true);
  const [authorized, setAuthorized] = useState(false);
  const [activeId, setActiveId] = useState(chapters[0].id);
  const [query, setQuery] = useState("");
  const [menuOpen, setMenuOpen] = useState(false);
  const [pendingJump, setPendingJump] = useState<{
    chapterId: string;
    index: number;
  } | null>(null);
  const scrollRef = useRef<ScrollView>(null);
  const sectionYs = useRef<Record<string, number>>({});

  useEffect(() => {
    (async () => {
      const session = await getSession();
      setAuthorized(!!session?.user);
      setChecking(false);
    })();
  }, []);

  useEffect(() => {
    const sub = BackHandler.addEventListener("hardwareBackPress", () => {
      if (menuOpen) {
        setMenuOpen(false);
        return true;
      }
      router.back();
      return true;
    });
    return () => sub.remove();
  }, [menuOpen]);

  useEffect(() => {
    if (!pendingJump) return;
    const { chapterId, index } = pendingJump;
    const timer = setTimeout(() => {
      const y = index < 0 ? 0 : sectionYs.current[`${chapterId}:${index}`];
      if (typeof y === "number") {
        scrollRef.current?.scrollTo({ y: Math.max(0, y - 8), animated: true });
      }
      setPendingJump(null);
    }, 120);
    return () => clearTimeout(timer);
  }, [pendingJump]);

  const q = query.trim().toLowerCase();
  const activeIdx = chapters.findIndex((c) => c.id === activeId);
  const chapter: ManualChapter = chapters[activeIdx];

  const matches = useMemo<ManualMatch[]>(() => {
    if (!q) return [];
    const out: ManualMatch[] = [];
    for (const c of chapters) {
      const chapterMatched =
        c.title.toLowerCase().includes(q) ||
        (c.content || "").toLowerCase().includes(q);
      if (chapterMatched) {
        out.push({
          chapterId: c.id,
          chapterNumber: c.number,
          chapterTitle: c.title,
          sectionTitle: c.title,
          index: -1,
          snippet: (c.content || "").slice(0, 120),
        });
      }
      c.sections.forEach((section, index) => {
        const texts = [
          section.title,
          section.body,
          section.note,
          ...(section.list || []),
          ...(section.tags || []),
          ...(section.stages || []).flatMap((s) => [s.name, ...s.items]),
        ].filter(Boolean) as string[];
        for (const text of texts) {
          const lower = text.toLowerCase();
          if (lower.includes(q)) {
            const at = lower.indexOf(q);
            const start = Math.max(0, at - 30);
            const snippet =
              text.length > 110
                ? "\u2026" + text.slice(start, start + 110) + "\u2026"
                : text;
            out.push({
              chapterId: c.id,
              chapterNumber: c.number,
              chapterTitle: c.title,
              sectionTitle: section.title,
              index,
              snippet,
            });
            break;
          }
        }
      });
    }
    return out;
  }, [q]);

  const jumpToSection = (chapterId: string, index: number) => {
    Keyboard.dismiss();
    setMenuOpen(false);
    setQuery("");
    setActiveId(chapterId);
    setPendingJump({ chapterId, index });
  };

  const selectChapter = (id: string) => {
    setMenuOpen(false);
    setActiveId(id);
    setPendingJump(null);
    scrollRef.current?.scrollTo({ y: 0, animated: false });
  };

  if (checking) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={[styles.safe, styles.centerBox]} edges={["top"]}>
          <Text style={styles.spinnerText}>Loading…</Text>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (!authorized) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={[styles.safe, styles.centerBox]} edges={["top"]}>
          <View style={styles.restrictedIcon}>
            <Ionicons name="lock-closed" size={26} color={colors.muted} />
          </View>
          <Text style={styles.restrictedTitle}>Sign in required</Text>
          <Text style={styles.restrictedBody}>
            Please sign in to view the Relate Manual.
          </Text>
          <TouchableOpacity
            style={styles.restrictedBtn}
            onPress={() => router.back()}
            activeOpacity={0.8}
          >
            <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
            <Text style={styles.restrictedBtnText}>Go back</Text>
          </TouchableOpacity>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.header}>
          <TouchableOpacity onPress={() => router.back()} style={styles.headerBtn}>
            <Ionicons name="close" size={22} color={colors.darkGreen} />
          </TouchableOpacity>
          <Text style={styles.headerTitle} numberOfLines={1}>
            Relate Manual
          </Text>
          <View style={styles.headerSpacer} />
        </View>

        <View style={styles.searchWrap}>
          <Ionicons name="search" size={16} color={colors.muted} />
          <TextInput
            style={styles.searchInput}
            value={query}
            onChangeText={(text) => {
              setQuery(text);
              if (text.trim()) setMenuOpen(false);
            }}
            placeholder="Search the manual…"
            placeholderTextColor={colors.muted}
            autoCapitalize="none"
            autoCorrect={false}
            returnKeyType="search"
          />
          {query.length > 0 ? (
            <TouchableOpacity
              onPress={() => setQuery("")}
              hitSlop={8}
              accessibilityLabel="Clear search"
            >
              <Ionicons name="close-circle" size={16} color={colors.muted} />
            </TouchableOpacity>
          ) : null}
        </View>

        {q.length === 0 ? (
          <TouchableOpacity
            style={[styles.chapterBar, menuOpen && styles.chapterBarOpen]}
            onPress={() => setMenuOpen((open) => !open)}
            activeOpacity={0.8}
            accessibilityRole="button"
            accessibilityLabel="Choose a chapter"
            accessibilityState={{ expanded: menuOpen }}
          >
            <View style={styles.chapterBarIcon}>
              <Text style={styles.chapterBarGlyph}>{chapter.icon}</Text>
            </View>
            <View style={{ flex: 1 }}>
              <Text style={styles.chapterBarKicker}>
                Chapter {chapter.number}
              </Text>
              <Text style={styles.chapterBarTitle} numberOfLines={1}>
                {chapter.title}
              </Text>
            </View>
            <View style={styles.chapterBarCaret}>
              <Ionicons
                name={menuOpen ? "chevron-up" : "chevron-down"}
                size={16}
                color={colors.darkGreen}
              />
            </View>
          </TouchableOpacity>
        ) : null}

        {menuOpen && q.length === 0 ? (
          <View style={styles.dropdown}>
            <ScrollView
              style={styles.dropdownScroll}
              showsVerticalScrollIndicator={false}
              nestedScrollEnabled
            >
              {navGroups.map((group) => {
                const groupChapters = chapters.filter((c) =>
                  group.ids.includes(c.id),
                );
                if (groupChapters.length === 0) return null;
                return (
                  <View key={group.title} style={styles.dropdownGroup}>
                    <Text style={styles.dropdownGroupLabel}>
                      {group.title.toUpperCase()}
                    </Text>
                    {groupChapters.map((c) => {
                      const active = activeId === c.id;
                      return (
                        <TouchableOpacity
                          key={c.id}
                          style={[
                            styles.dropdownRow,
                            active && styles.dropdownRowActive,
                          ]}
                          onPress={() => selectChapter(c.id)}
                          activeOpacity={0.8}
                          accessibilityRole="button"
                          accessibilityState={{ selected: active }}
                        >
                          <View
                            style={[
                              styles.dropdownIcon,
                              active && styles.dropdownIconActive,
                            ]}
                          >
                            <Text
                              style={[
                                styles.dropdownGlyph,
                                active && styles.dropdownGlyphActive,
                              ]}
                            >
                              {c.icon}
                            </Text>
                          </View>
                          <View style={styles.dropdownRowBody}>
                            <Text
                              style={[
                                styles.dropdownRowTitle,
                                active && styles.dropdownRowTitleActive,
                              ]}
                              numberOfLines={1}
                            >
                              {c.number} · {c.title}
                            </Text>
                            <Text
                              style={styles.dropdownRowTagline}
                              numberOfLines={1}
                            >
                              {c.tagline}
                            </Text>
                          </View>
                          {active ? (
                            <Ionicons
                              name="checkmark-circle"
                              size={18}
                              color={colors.goldDark}
                            />
                          ) : null}
                        </TouchableOpacity>
                      );
                    })}
                  </View>
                );
              })}
            </ScrollView>
          </View>
        ) : null}

        {q.length === 0 ? (
          <ScrollView
            ref={scrollRef}
            contentContainerStyle={styles.body}
            showsVerticalScrollIndicator={false}
            keyboardShouldPersistTaps="handled"
          >
            <View style={styles.chapterHeader}>
              <Text style={styles.chapterIcon}>{chapter.icon}</Text>
              <View style={{ flex: 1 }}>
                <Text style={styles.chapterKicker}>
                  Chapter {chapter.number}
                </Text>
                <Text style={styles.chapterTitle}>{chapter.title}</Text>
              </View>
            </View>

            {chapter.content ? (
              <LinearGradient
                colors={[colors.lightGreen, colors.white]}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={styles.introCard}
              >
                <Text style={styles.introText}>{chapter.content}</Text>
              </LinearGradient>
            ) : null}

            {chapter.sections.map((section, index) => (
              <View
                key={index}
                onLayout={(e: LayoutChangeEvent) => {
                  sectionYs.current[`${chapter.id}:${index}`] =
                    e.nativeEvent.layout.y;
                }}
              >
                <SectionBody section={section} />
              </View>
            ))}

            <Text style={styles.version}>
              Relate Manual · Version 1.1
            </Text>
          </ScrollView>
        ) : (
          <ScrollView
            contentContainerStyle={styles.body}
            showsVerticalScrollIndicator={false}
            keyboardShouldPersistTaps="handled"
          >
            <Text style={styles.resultsLabel}>
              {matches.length === 0
                ? "No results"
                : `${matches.length} result${matches.length === 1 ? "" : "s"}`}{" "}
              for {`\u201C${query.trim()}\u201D`}
            </Text>

            {matches.length === 0 ? (
              <View style={styles.noResultsBox}>
                <Ionicons name="search" size={28} color={colors.muted} />
                <Text style={styles.noResultsText}>
                  No matches found. Try a different word or phrase.
                </Text>
              </View>
            ) : (
              matches.map((m, i) => (
                <TouchableOpacity
                  key={i}
                  style={styles.resultRow}
                  onPress={() => jumpToSection(m.chapterId, m.index)}
                  activeOpacity={0.8}
                >
                  <View style={styles.resultIconWrap}>
                    <Ionicons
                      name="document-text-outline"
                      size={17}
                      color={colors.goldDark}
                    />
                  </View>
                  <View style={{ flex: 1 }}>
                    <Text style={styles.resultChapter} numberOfLines={1}>
                      Ch. {m.chapterNumber} · {m.chapterTitle}
                    </Text>
                    <Text style={styles.resultSection} numberOfLines={1}>
                      {m.sectionTitle}
                    </Text>
                    <Text style={styles.resultSnippet} numberOfLines={2}>
                      {m.snippet}
                    </Text>
                  </View>
                  <Ionicons name="chevron-forward" size={16} color={colors.muted} />
                </TouchableOpacity>
              ))
            )}
          </ScrollView>
        )}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

