import EmptyState from "@/components/EmptyState";
import AlreadyOnTeamModal from "@/components/AlreadyOnTeamModal";
import AutoCarousel from "@/components/AutoCarousel";
import LandingHeroSlide, {
  type HeroSlide,
} from "@/components/LandingHeroSlide";
import TeamCrest from "@/components/TeamCrest";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { useClubs } from "@/services/clubs";
import {
  useMyRegistration,
  type MyRegistration,
} from "@/services/sports";
import {
  SPORT_THEME,
  teamHeroPhoto,
  useSportsCatalog,
  type RelateSport,
} from "@/services/sports-catalog";
import { Ionicons, MaterialCommunityIcons } from "@expo/vector-icons";
import { useLocalSearchParams, useRouter } from "expo-router";
import { StatusBar } from "expo-status-bar";
import { useMemo, useState } from "react";
import {
  ActivityIndicator,
  Linking,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import {
  SafeAreaProvider,
  SafeAreaView,
  useSafeAreaInsets,
} from "react-native-safe-area-context";

const WHATSAPP = "27782677436";

function goBackHome(router: ReturnType<typeof useRouter>) {
  if (router.canDismiss?.()) router.dismiss();
  else router.replace("/(tabs)/community");
}

export default function SportsScreen() {
  const router = useRouter();
  const params = useLocalSearchParams<{ sport?: string }>();
  const insets = useSafeAreaInsets();
  const { data: catalog, loading, error } = useSportsCatalog();
  const { find: findClub } = useClubs();
  // Every register CTA ("Join" on a team card, the closing "Register to
  // join") is gated through check() so an existing squad spot opens the
  // status sheet instead of skipping to the registration form.
  const { check } = useMyRegistration();
  const [already, setAlready] = useState<{
    reg: MyRegistration;
    teamId?: string;
  } | null>(null);

  const sports = catalog?.sports ?? [];
  // The active sport follows the ?sport= param, so a deep link lands on the
  // right tab once the catalogue has arrived.
  const activeSport: RelateSport = useMemo(() => {
    const wanted =
      typeof params.sport === "string"
        ? (params.sport as RelateSport)
        : undefined;
    if (wanted && SPORT_THEME[wanted]?.image && sports.includes(wanted))
      return wanted;
    return "Football";
  }, [params.sport, sports]);

  const selectSport = (s: RelateSport) => {
    router.setParams({ sport: s });
  };

  const theme = SPORT_THEME[activeSport];
  const teamsForSport = (sport: RelateSport) =>
    catalog?.teamsForSport(sport) ?? [];
  const teams = teamsForSport(activeSport);

  /** true → safe to open the form; false → the status sheet is showing. */
  const guardRegister = async (teamId: string) => {
    const mine = await check();
    if (mine) {
      setAlready({ reg: mine, teamId });
      return false;
    }
    return true;
  };

  // Hero carousel in the clubs-screen style — one slide per Relate team.
  const teamSlides: HeroSlide[] = (catalog?.teams ?? []).map((team) => {
    const club = findClub(team.clubSlug);
    const spTheme = SPORT_THEME[team.sport];
    return {
      key: team.id,
      image: teamHeroPhoto(team),
      gradient: [colors.forestDark, spTheme.colors[1], spTheme.colors[0]],
      chip: team.sport,
      title: team.name,
      tagline: team.tagline,
      meta: [
        { label: "Club", value: club?.name ?? "Relate" },
        { label: "Sport", value: team.sport },
        { label: "Entry", value: "Free" },
      ],
      cta: {
        label: `Open ${team.name}`,
        onPress: () =>
          router.push({
            pathname: "/sports/[teamId]" as any,
            params: { teamId: team.id },
          }),
      },
    };
  });

  if (loading) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={s.stateWrap}>
            <ActivityIndicator size="large" color={colors.goldDark} />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (error || !catalog) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={s.stateWrap}>
            <Ionicons
              name="alert-circle-outline"
              size={40}
              color={colors.gold}
            />
            <Text style={s.stateTitle}>Teams unavailable</Text>
            <Text style={s.stateText}>{error ?? ""}</Text>
            <TouchableOpacity
              style={s.stateBtn}
              onPress={() => goBackHome(router)}
              activeOpacity={0.85}
              accessibilityRole="button"
              accessibilityLabel="Back to clubs"
            >
              <Text style={s.stateBtnText}>Back to clubs</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider>
      <SafeAreaView style={s.safe} edges={["top"]}>
        <StatusBar style="dark" />
        <ScrollView
          contentContainerStyle={[
            s.content,
            { paddingBottom: 40 + insets.bottom },
          ]}
          showsVerticalScrollIndicator={false}
        >
          {/* ── Hero: every Relate team as a clubs-style carousel slide ── */}
          <View style={s.heroCarousel}>
            <AutoCarousel
              intervalMs={5500}
              sidePadding={20}
            >
              {teamSlides.map((slide) => (
                <LandingHeroSlide key={slide.key} slide={slide} />
              ))}
            </AutoCarousel>
            <TouchableOpacity
              style={s.heroBackFloat}
              onPress={() => goBackHome(router)}
              activeOpacity={0.85}
              accessibilityRole="button"
              accessibilityLabel="Back to clubs"
            >
              <Ionicons name="chevron-back" size={20} color={colors.white} />
            </TouchableOpacity>
          </View>

          {/* Sport tabs */}
          <View style={s.pills}>
            {sports.map((sp) => {
              const spTheme = SPORT_THEME[sp];
              const active = sp === activeSport;
              return (
                <TouchableOpacity
                  key={sp}
                  onPress={() => selectSport(sp)}
                  activeOpacity={0.85}
                  style={[
                    s.pill,
                    active && { backgroundColor: theme.accent, borderWidth: 0 },
                  ]}
                  accessibilityLabel={`${sp} teams`}
                  accessibilityState={{ selected: active }}
                >
                  <MaterialCommunityIcons
                    name={(spTheme?.icon ?? "trophy-outline") as any}
                    size={16}
                    color={active ? colors.white : colors.muted}
                  />
                  <Text
                    style={[
                      s.pillText,
                      active ? { color: colors.white } : { color: colors.ink },
                    ]}
                  >
                    {sp}
                  </Text>
                  <View
                    style={[
                      s.pillCount,
                      active
                        ? { backgroundColor: "rgba(255,255,255,0.24)" }
                        : { backgroundColor: colors.bgSoft },
                    ]}
                  >
                    <Text
                      style={[
                        s.pillCountText,
                        active
                          ? { color: colors.white }
                          : { color: colors.muted },
                      ]}
                    >
                      {teamsForSport(sp).length}
                    </Text>
                  </View>
                </TouchableOpacity>
              );
            })}
          </View>

          {/* Sport section head */}
          <View style={s.sportHead}>
            <Text style={s.sportEyebrow}>Relate · {activeSport}</Text>
            <Text style={s.sportTitle}>{activeSport}</Text>
            <Text style={s.sportLine}>{theme.line}</Text>
          </View>

          {/* Team cards */}
          <View style={s.teamList}>
            {teams.length === 0 ? (
              <EmptyState
                eyebrow="Relate · Sports"
                title="No teams published yet"
                subtitle="Squads appear here as soon as the league publishes them — registration opens again then."
                actionLabel="All teams"
                onAction={() => router.push("/sports" as any)}
              />
            ) : null}
            {teams.map((team) => {
              const openTeam = () =>
                router.push({
                  pathname: "/sports/[teamId]" as any,
                  params: { teamId: team.id },
                });
              const openRegister = async () => {
                if (!(await guardRegister(team.id))) return;
                router.push({
                  pathname: "/sports/[teamId]/register" as any,
                  params: { teamId: team.id },
                });
              };
              return (
                <View key={team.id} style={s.teamCard}>
                  <TouchableOpacity
                    style={s.teamCardMain}
                    activeOpacity={0.9}
                    onPress={openTeam}
                    accessibilityRole="button"
                    accessibilityLabel={`Open ${team.name}`}
                    accessibilityHint={team.tagline}
                  >
                    <View style={s.teamCardCrestWrap}>
                      <TeamCrest team={team} size={168} />
                    </View>
                  </TouchableOpacity>
                  <View style={s.teamCardFoot}>
                    <TouchableOpacity
                      onPress={openTeam}
                      activeOpacity={0.7}
                      hitSlop={{ top: 8, bottom: 8, left: 6, right: 6 }}
                      accessibilityRole="link"
                      accessibilityLabel={`${team.name} page`}
                    >
                      <Text style={s.teamCardLink}>{team.name} page →</Text>
                    </TouchableOpacity>
                    <TouchableOpacity
                      style={s.teamCardJoin}
                      onPress={() => void openRegister()}
                      activeOpacity={0.85}
                      accessibilityRole="button"
                      accessibilityLabel={`Join ${team.name}`}
                    >
                      <Text style={s.teamCardJoinText}>Join</Text>
                    </TouchableOpacity>
                  </View>
                </View>
              );
            })}
          </View>

          {/* Closing CTA — web's navy register card */}
          <View style={s.footerCard}>
            <View style={[s.footerGlow, { top: -70, left: -60 }]} />
            <View style={[s.footerGlow, { bottom: -70, right: -60 }]} />
            <Text style={s.footerTitle}>Want to play for a Relate team?</Text>
            <Text style={s.footerText}>
              Register your details and you&rsquo;re on the team straight away —
              the squad fills in on your team page.
            </Text>
            <View style={s.footerActions}>
              <TouchableOpacity
                style={s.footerPrimary}
                activeOpacity={0.85}
                onPress={async () => {
                  if (!teams[0] || !(await guardRegister(teams[0].id))) return;
                  router.push({
                    pathname: "/sports/[teamId]/register" as any,
                    params: { teamId: teams[0].id },
                  });
                }}
                accessibilityRole="button"
                accessibilityLabel="Register to join"
              >
                <Text style={s.footerPrimaryText}>Register to join</Text>
                <Ionicons
                  name="arrow-forward"
                  size={15}
                  color={colors.forestDark}
                />
              </TouchableOpacity>
              <TouchableOpacity
                style={s.footerGhost}
                activeOpacity={0.85}
                onPress={() => Linking.openURL(`https://wa.me/${WHATSAPP}`)}
                accessibilityRole="button"
                accessibilityLabel="Ask a question on WhatsApp"
              >
                <Text style={s.footerGhostText}>Ask a question</Text>
              </TouchableOpacity>
            </View>
          </View>
        </ScrollView>
      </SafeAreaView>
      <AlreadyOnTeamModal
        registration={already?.reg ?? null}
        currentTeamId={already?.teamId}
        onClose={() => setAlready(null)}
      />
    </SafeAreaProvider>
  );
}

