import Constants from "expo-constants";

/** Latest published build info from GET /api/app-version. */
export type AppVersionInfo = {
  latestVersion: string;
  minSupportedVersion: string;
  apkUrl: string;
  releaseNotes: string;
  forceUpdate: boolean;
};

/** The public web app origin — it serves GET /api/app-version. */
const SITE_URL = "https://relateworld.org";

/**
 * The version this build reports as installed — app.json's `version`, which
 * the Android versionName is set from. Read from expo-constants only (no
 * native module), so it stays safe to ship over the air to older binaries.
 */
export function installedVersion(): string | null {
  return Constants.expoConfig?.version ?? null;
}

/**
 * true when `latest` is a strictly higher dotted version than `current`
 * ("1.0.1" > "1.0.0" → true; equal, older or malformed → false).
 */
export function isNewerVersion(latest: string, current: string): boolean {
  const parse = (v: string) =>
    v.split(".").map((n) => Number.parseInt(n, 10) || 0);
  const a = parse(latest);
  const b = parse(current);
  const len = Math.max(a.length, b.length);
  for (let i = 0; i < len; i++) {
    const diff = (a[i] ?? 0) - (b[i] ?? 0);
    if (diff !== 0) return diff > 0;
  }
  return false;
}

/**
 * The latest published APK info, or null on any network, timeout or shape
 * problem — the launch-time update prompt must never block the app.
 */
export async function fetchAppVersion(): Promise<AppVersionInfo | null> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 8000);
  try {
    const res = await fetch(`${SITE_URL}/api/app-version`, {
      headers: { Accept: "application/json" },
      signal: controller.signal,
    });
    if (!res.ok) return null;
    const data = await res.json().catch(() => null);
    if (
      !data ||
      typeof data.latestVersion !== "string" ||
      typeof data.apkUrl !== "string"
    ) {
      return null;
    }
    return {
      latestVersion: data.latestVersion,
      minSupportedVersion:
        typeof data.minSupportedVersion === "string"
          ? data.minSupportedVersion
          : data.latestVersion,
      apkUrl: data.apkUrl,
      releaseNotes: typeof data.releaseNotes === "string" ? data.releaseNotes : "",
      forceUpdate: data.forceUpdate === true,
    };
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}
