import { LinearGradient } from 'expo-linear-gradient';
import React, { useState } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import Svg, { Text as SvgText, Defs, Stop, LinearGradient as SvgGradient } from 'react-native-svg';
import type { ViewStyle } from 'react-native';

export const gradients = {
  darkGreen: ['#151f3a', '#1d2a4d'] as const,
  darkGreenReversed: ['#1d2a4d', '#151f3a'] as const,
  lime: ['#13c5dd', '#1d2a4d'] as const,
  limeReversed: ['#1d2a4d', '#13c5dd'] as const,
  green: ['#1d2a4d', '#2a4070'] as const,
  red: ['#dc2626', '#b91c1c'] as const,
  greenSuccess: ['#16a34a', '#15803d'] as const,
  whatsapp: ['#25D366', '#128C7E'] as const,
  invoiceHeader: ['#151f3a', '#1d2a4d', '#151f3a'] as const,
  invoiceAccent: ['#13c5dd', '#1d2a4d', '#13c5dd'] as const,
  bgToWhite: ['#eff5f9', '#ffffff'] as const,
  bgToWhiteRev: ['#ffffff', '#eff5f9'] as const,
} as const;

type GradientName = keyof typeof gradients;

interface GradientBoxProps {
  gradient: GradientName;
  style?: ViewStyle | ViewStyle[];
  children?: React.ReactNode;
}

export type { GradientName };

export function GradientBox({ gradient, style, children }: GradientBoxProps): React.ReactElement {
  const g = gradients[gradient];
  return (
    <LinearGradient
      colors={g as any}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 0 }}
      style={style}
    >
      {children}
    </LinearGradient>
  );
}

interface GradientTextProps {
  gradient: GradientName;
  children: string;
  style?: any;
}

const gradientIds: Record<string, number> = {};
let idCounter = 0;
function getGid(gradient: string) {
  if (!gradientIds[gradient]) gradientIds[gradient] = ++idCounter;
  return `gt${gradientIds[gradient]}`;
}

export function GradientText({ gradient, children, style }: GradientTextProps): React.ReactElement {
  const colors = gradients[gradient];
  const [size, setSize] = useState({ width: 0, height: 0 });
  const fs = style?.fontSize || 16;
  const fw = style?.fontWeight || '400';
  const gid = getGid(gradient);

  return (
    <View
      onLayout={(e) => setSize({ width: e.nativeEvent.layout.width, height: e.nativeEvent.layout.height })}
      style={[{ position: 'relative' }, style]}
    >
      <Text style={{ opacity: 0, fontSize: fs, fontWeight: fw }}>{children}</Text>
      {size.width > 0 && (
        <Svg width={size.width} height={size.height} style={StyleSheet.absoluteFill}>
          <Defs>
            <SvgGradient id={gid} x1="0" y1="0" x2="1" y2="0">
              {colors.map((c, i) => (
                <Stop
                  key={i}
                  offset={`${(i / (colors.length - 1)) * 100}%`}
                  stopColor={c as string}
                />
              ))}
            </SvgGradient>
          </Defs>
          <SvgText
            fill={`url(#${gid})`}
            fontSize={fs}
            fontWeight={fw}
            x={0}
            y={fs}
          >
            {children}
          </SvgText>
        </Svg>
      )}
    </View>
  );
}
