import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { StyleSheet, Text, useColorScheme, View } from "react-native";
import { useLocalSearchParams, useRouter } from "expo-router";
import { StatusBar } from "expo-status-bar";
import { SafeAreaView } from "react-native-safe-area-context";
import { useSQLiteContext } from "expo-sqlite";
import { markBibleRead, getTodayKey } from "@/utils/streaks";
import { getBookByName, getChapters, type BookInfo } from "@/lib/bible-queries";
import {
  addHighlight,
  removeHighlight,
  getHighlightsForChapter,
  addBookmark,
  removeBookmark,
  updateBookmarkNote,
  getBookmarksForChapter,
  getAllBookmarks,
  type BookmarkRow,
} from "@/lib/bible-sync";
import {
  BibleThemeProvider,
  resolveBibleTheme,
} from "@/lib/bible-theme";
import {
  DEFAULT_SETTINGS,
  getReaderSettings,
  saveReaderSettings,
  READER_FONTS,
  type ReaderFontKey,
  type ReaderLayoutKey,
  type ReaderSettings,
  type ReaderThemeKey,
} from "@/lib/reader-settings";
import BibleDatabaseProvider from "@/components/bible/BibleDatabaseProvider";
import VerseReader from "@/components/bible/VerseReader";
import BookChapterSheet from "@/components/bible/BookChapterSheet";
import VersionSheet, {
  BIBLE_VERSIONS,
  type BibleVersionId,
} from "@/components/bible/VersionSheet";
import BookmarksSheet from "@/components/bible/BookmarksSheet";
import { IS_WEB } from "@/services/config";

function BibleScreenInner() {
  const params = useLocalSearchParams<{
    book?: string;
    chapter?: string;
    verse?: string;
    plan?: string;
    day?: string;
  }>();
  const router = useRouter();

  const db = useSQLiteContext();
  const deviceScheme = useColorScheme();

  const [version, setVersion] = useState<BibleVersionId>("KJV");
  const [fontKey, setFontKey] = useState<ReaderFontKey>(DEFAULT_SETTINGS.fontFamily);
  const [fontSize, setFontSize] = useState(DEFAULT_SETTINGS.fontSize);
  const [fontWeight, setFontWeight] = useState(DEFAULT_SETTINGS.fontWeight);
  const [themePref, setThemePref] = useState<ReaderThemeKey>(DEFAULT_SETTINGS.theme);
  const [layout, setLayout] = useState<ReaderLayoutKey>(DEFAULT_SETTINGS.layout);

  const [ready, setReady] = useState(false);
  const [selectedBook, setSelectedBook] = useState<BookInfo | null>(null);
  const [selectedChapter, setSelectedChapter] = useState(1);
  const [showPicker, setShowPicker] = useState(false);
  const [showVersion, setShowVersion] = useState(false);
  const [targetVerse, setTargetVerse] = useState<number | null>(null);

  const [highlightColors, setHighlightColors] = useState<Map<number, string>>(new Map());
  const [bookmarks, setBookmarks] = useState<Map<number, { id: number; note: string }>>(new Map());
  const [allBookmarks, setAllBookmarks] = useState<BookmarkRow[]>([]);
  const [showBookmarks, setShowBookmarks] = useState(false);

  const fontFamily = fontWeight;
  const posRef = useRef({ book: "", chapter: 1 });
  const awardedRef = useRef(false);
  const userId = "local";

  const theme = useMemo(
    () =>
      resolveBibleTheme(
        themePref,
        deviceScheme === "dark" ? "dark" : "light",
      ),
    [themePref, deviceScheme],
  );

  const versionLabel =
    BIBLE_VERSIONS.find((v) => v.id === version)?.label ?? version;

  // Load saved reader settings + reopen where the reader last left off.
  useEffect(() => {
    let active = true;
    void (async () => {
      try {
        // Settings are optional: a failed read must never strand the reader on
        // the loading screen, so fall back to the defaults and keep going.
        const settings = await getReaderSettings(db).catch((e) => {
          console.warn("[bible] failed to load reader settings", e);
          return DEFAULT_SETTINGS;
        });
        if (!active) return;
        setFontKey(settings.fontFamily);
        setFontSize(settings.fontSize);
        setFontWeight(settings.fontWeight);
        setThemePref(settings.theme);
        setLayout(settings.layout);

        const paramBook = params.book
          ? getBookByName(db, version, params.book)
          : null;
        const savedBook =
          !paramBook && settings.lastBook
            ? getBookByName(db, version, settings.lastBook)
            : null;
        const book = paramBook ?? savedBook ?? getBookByName(db, version, "Genesis");

        let chapter = 1;
        if (paramBook && params.chapter) {
          chapter = parseInt(params.chapter, 10) || 1;
        } else if (savedBook && settings.lastChapter) {
          chapter = settings.lastChapter;
        }

        if (book) {
          const total = getChapters(db, version, book.book).length || 1;
          setSelectedBook(book);
          setSelectedChapter(Math.min(Math.max(chapter, 1), total));
          const linkedVerse = params.verse
            ? parseInt(params.verse, 10) || null
            : null;
          setTargetVerse(paramBook ? linkedVerse : null);
        }

        // First launch — or no book could be resolved: open the navigator like
        // YouVersion instead of leaving the placeholder up forever.
        if (!book || (!paramBook && !savedBook)) setShowPicker(true);
      } catch (e) {
        console.warn("[bible] failed to initialise the reader", e);
        if (active) setShowPicker(true);
      } finally {
        if (active) setReady(true);
      }
    })();
    return () => {
      active = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [db]);

  // Deep links from plans / search / VOTD move the reader to the passage
  // (render-phase adjustment — re-applies whenever the linked passage changes).
  const paramVerse = params.verse ? parseInt(params.verse, 10) || null : null;
  const paramKey = params.book
    ? `${params.book}:${parseInt(params.chapter || "1", 10) || 1}:${paramVerse ?? ""}`
    : null;
  const [appliedParamKey, setAppliedParamKey] = useState<string | null>(paramKey);
  if (ready && paramKey && paramKey !== appliedParamKey) {
    const [paramBook, paramChapterStr] = paramKey.split(":");
    const linkedBook = getBookByName(db, version, paramBook);
    if (linkedBook) {
      const linkedChapter = parseInt(paramChapterStr, 10) || 1;
      const total = getChapters(db, version, linkedBook.book).length || 1;
      setAppliedParamKey(paramKey);
      setSelectedBook(linkedBook);
      setSelectedChapter(Math.min(Math.max(linkedChapter, 1), total));
      setTargetVerse(paramVerse);
    }
  }

  useEffect(() => {
    if (selectedBook) {
      posRef.current = { book: selectedBook.book_name, chapter: selectedChapter };
    }
  }, [selectedBook, selectedChapter]);

  const persistSettings = useCallback(
    async (next: Partial<ReaderSettings>) => {
      try {
        await saveReaderSettings(db, {
          fontFamily: fontKey,
          fontSize,
          fontWeight,
          theme: themePref,
          layout,
          lastBook: posRef.current.book || null,
          lastChapter: posRef.current.chapter,
          ...next,
        });
      } catch (e) {
        console.warn("[bible] failed to save reader settings", e);
      }
    },
    [db, fontKey, fontSize, fontWeight, themePref, layout],
  );

  // Persist the open passage so Home "Continue reading" and the next cold
  // start resume here — even if this session never changed chapter.
  useEffect(() => {
    if (!ready || !selectedBook) return;
    void persistSettings({
      lastBook: selectedBook.book_name,
      lastChapter: selectedChapter,
    });
  }, [ready, selectedBook, selectedChapter, persistSettings]);

  const handleFontSizeChange = useCallback(
    (size: number) => {
      setFontSize(size);
      void persistSettings({ fontSize: size });
    },
    [persistSettings],
  );

  const handleFontFamilyChange = useCallback(
    (key: ReaderFontKey) => {
      const family =
        READER_FONTS.find((f) => f.key === key)?.defaultWeight ?? "Eczar_500Medium";
      setFontKey(key);
      setFontWeight(family);
      void persistSettings({ fontFamily: key, fontWeight: family });
    },
    [persistSettings],
  );

  const handleFontWeightChange = useCallback(
    (family: string) => {
      setFontWeight(family);
      void persistSettings({ fontWeight: family });
    },
    [persistSettings],
  );

  const handleThemeChange = useCallback(
    (next: ReaderThemeKey) => {
      setThemePref(next);
      void persistSettings({ theme: next });
    },
    [persistSettings],
  );

  const handleLayoutChange = useCallback(
    (next: ReaderLayoutKey) => {
      setLayout(next);
      void persistSettings({ layout: next });
    },
    [persistSettings],
  );

  // Highlights for the open chapter.
  useEffect(() => {
    if (!selectedBook) return;
    void (async () => {
      const colors = await getHighlightsForChapter(
        db,
        userId,
        0,
        selectedBook.book_name,
        selectedChapter,
      );
      setHighlightColors(colors);
    })();
  }, [db, selectedBook, selectedChapter]);

  // Bookmarks for the open chapter (verse -> { id, note }).
  useEffect(() => {
    if (!selectedBook) return;
    void (async () => {
      const rows = await getBookmarksForChapter(
        db,
        userId,
        selectedBook.book_name,
        selectedChapter,
      );
      const map = new Map<number, { id: number; note: string }>();
      for (const r of rows) map.set(r.verse, { id: r.id, note: r.note });
      setBookmarks(map);
    })();
  }, [db, selectedBook, selectedChapter]);

  const refreshAllBookmarks = useCallback(async () => {
    setAllBookmarks(await getAllBookmarks(db, userId));
  }, [db]);

  useEffect(() => {
    void (async () => {
      setAllBookmarks(await getAllBookmarks(db, userId));
    })();
  }, [db]);

  const handleToggleBookmark = useCallback(
    async (verse: number) => {
      if (!selectedBook) return;
      const existing = bookmarks.get(verse);
      if (existing) {
        await removeBookmark(db, existing.id);
        setBookmarks((prev) => {
          const next = new Map(prev);
          next.delete(verse);
          return next;
        });
      } else {
        const id = await addBookmark(
          db,
          userId,
          selectedBook.book_name,
          selectedChapter,
          verse,
        );
        setBookmarks((prev) => new Map(prev).set(verse, { id, note: "" }));
      }
      void refreshAllBookmarks();
    },
    [db, selectedBook, selectedChapter, bookmarks, refreshAllBookmarks],
  );

  const handleSaveNote = useCallback(
    async (verse: number, note: string) => {
      if (!selectedBook) return;
      const existing = bookmarks.get(verse);
      if (existing) {
        await updateBookmarkNote(db, existing.id, note);
        setBookmarks((prev) =>
          new Map(prev).set(verse, { id: existing.id, note }),
        );
      } else {
        const id = await addBookmark(
          db,
          userId,
          selectedBook.book_name,
          selectedChapter,
          verse,
          note,
        );
        setBookmarks((prev) => new Map(prev).set(verse, { id, note }));
      }
      void refreshAllBookmarks();
    },
    [db, selectedBook, selectedChapter, bookmarks, refreshAllBookmarks],
  );

  const handleOpenBookmark = useCallback(
    (book: string, chapter: number, verse: number) => {
      const info = getBookByName(db, version, book);
      if (!info) return;
      const total = getChapters(db, version, info.book).length || 1;
      setSelectedBook(info);
      setSelectedChapter(Math.min(Math.max(chapter, 1), total));
      setTargetVerse(verse > 0 ? verse : null);
      setShowBookmarks(false);
    },
    [db, version],
  );

  const handleDeleteBookmark = useCallback(
    async (id: number) => {
      await removeBookmark(db, id);
      setBookmarks((prev) => {
        const next = new Map(prev);
        for (const [v, b] of next) if (b.id === id) next.delete(v);
        return next;
      });
      void refreshAllBookmarks();
    },
    [db, refreshAllBookmarks],
  );

  const markRead = useCallback(async () => {
    if (awardedRef.current) return;
    awardedRef.current = true;
    await markBibleRead(getTodayKey());
  }, []);

  useEffect(() => {
    void markRead();
  }, [markRead]);

  const handleChapterNav = useCallback(
    (chapter: number) => {
      setSelectedChapter(chapter);
      setTargetVerse(null);
      awardedRef.current = false;
      void markRead();
      void persistSettings({
        lastBook: selectedBook?.book_name ?? null,
        lastChapter: chapter,
      });
    },
    [markRead, persistSettings, selectedBook],
  );

  const handleSelectBook = useCallback((book: BookInfo) => {
    setSelectedBook(book);
    setSelectedChapter(1);
    setTargetVerse(null);
  }, []);

  const handleSelectChapter = useCallback(
    (chapter: number) => {
      setSelectedChapter(chapter);
      setShowPicker(false);
      setTargetVerse(null);
      awardedRef.current = false;
      void markRead();
      void persistSettings({
        lastBook: selectedBook?.book_name ?? null,
        lastChapter: chapter,
      });
    },
    [markRead, persistSettings, selectedBook],
  );

  const handleHighlight = useCallback(
    async (verse: number, color: string) => {
      if (!selectedBook) return;
      await addHighlight(db, userId, {
        user_id: userId,
        version_id: 0,
        book: selectedBook.book_name,
        chapter: selectedChapter,
        verse,
        color,
      });
      setHighlightColors((prev) => {
        const next = new Map(prev);
        next.set(verse, color);
        return next;
      });
    },
    [db, selectedBook, selectedChapter],
  );

  const handleRemoveHighlight = useCallback(
    async (verse: number) => {
      if (!selectedBook) return;
      await removeHighlight(
        db,
        userId,
        0,
        selectedBook.book_name,
        selectedChapter,
        verse,
      );
      setHighlightColors((prev) => {
        const next = new Map(prev);
        next.delete(verse);
        return next;
      });
    },
    [db, selectedBook, selectedChapter],
  );

  const totalChapters = selectedBook
    ? getChapters(db, version, selectedBook.book).length
    : 0;

  return (
    <SafeAreaView
      style={[styles.root, { backgroundColor: theme.bg }]}
      edges={["top", "bottom"]}
    >
      <StatusBar style={theme.isDark ? "light" : "dark"} />

      <BibleThemeProvider theme={theme}>
        {ready && selectedBook ? (
          <VerseReader
            version={version}
            versionLabel={versionLabel}
            bookNumber={selectedBook.book}
            bookName={selectedBook.book_name}
            chapter={selectedChapter}
            targetVerse={targetVerse}
            totalChapters={totalChapters}
            fontSize={fontSize}
            fontFamily={fontFamily}
            themePref={themePref}
            layout={layout}
            onLayoutChange={handleLayoutChange}
            onFontSizeChange={handleFontSizeChange}
            onFontFamilyChange={handleFontFamilyChange}
            onFontWeightChange={handleFontWeightChange}
            onThemeChange={handleThemeChange}
            onChapterChange={handleChapterNav}
            onOpenPicker={() => setShowPicker(true)}
            onOpenVersion={() => setShowVersion(true)}
            onSearch={() => router.push("/bible-search")}
            highlightedVerses={highlightColors}
            onHighlight={handleHighlight}
            onRemoveHighlight={handleRemoveHighlight}
            bookmarkedVerses={bookmarks}
            onToggleBookmark={handleToggleBookmark}
            onSaveNote={handleSaveNote}
            onOpenBookmarks={() => setShowBookmarks(true)}
          />
        ) : (
          <View style={styles.center}>
            <Text style={{ color: theme.textMuted }}>Opening the Bible…</Text>
          </View>
        )}

        <BookChapterSheet
          visible={showPicker}
          version={version}
          bookNumber={selectedBook?.book ?? null}
          bookName={selectedBook?.book_name ?? null}
          chapter={selectedChapter}
          onClose={() => setShowPicker(false)}
          onSelectBook={handleSelectBook}
          onSelectChapter={handleSelectChapter}
        />

        <VersionSheet
          visible={showVersion}
          version={version}
          onSelect={setVersion}
          onClose={() => setShowVersion(false)}
        />

        <BookmarksSheet
          visible={showBookmarks}
          bookmarks={allBookmarks}
          onOpen={handleOpenBookmark}
          onDelete={handleDeleteBookmark}
          onClose={() => setShowBookmarks(false)}
        />
      </BibleThemeProvider>
    </SafeAreaView>
  );
}

export default function BibleScreen() {
  const router = useRouter();

  useEffect(() => {
    if (IS_WEB) router.replace("/");
  }, [router]);

  if (IS_WEB) return null;

  return (
    <BibleDatabaseProvider fallback={null}>
      <BibleScreenInner />
    </BibleDatabaseProvider>
  );
}

const styles = StyleSheet.create({
  root: {
    flex: 1,
  },
  center: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
  },
});
