import { File } from "expo-file-system";
import { API_BASE } from "./config";
import { getRequestHeaders } from "./auth";
import { cachedFetch, type CachedFetchOptions } from "./cache";

export type RsvpStatus = "ATTENDING" | "APOLOGY" | "PENDING";
export type MeetingStatus = "SCHEDULED" | "COMPLETED" | "CANCELLED";
export type TaskStatus = "PENDING" | "IN_PROGRESS" | "DONE";

export type BoardMember = {
  id: string;
  name: string;
  email: string;
  role: string;
};

export type BoardRsvp = {
  userId: string;
  name: string;
  role: string;
  status: RsvpStatus;
  reason: string;
};

export type MeetingCounts = {
  attending: number;
  apologies: number;
  pending: number;
  total: number;
};

export type AgendaItem = { text: string; subs: string[] };

export type BoardMeeting = {
  _id: string;
  title: string;
  scheduledDate: string | null;
  location: string;
  meetingLink: string;
  agenda: AgendaItem[];
  rsvps: BoardRsvp[];
  status: MeetingStatus;
  createdAt: string | null;
  updatedAt: string | null;
  counts: MeetingCounts;
};

/** List-card shape — no agenda or attendee list; open the meeting for those. */
export type BoardMeetingCard = {
  _id: string;
  title: string;
  scheduledDate: string | null;
  location: string;
  meetingLink: string;
  status: MeetingStatus;
};

export type BoardActionItem = {
  taskId: string;
  assigneeId: string;
  assigneeName: string;
  taskDescription: string;
  dueDate: string | null;
  status: TaskStatus;
};

export type TaskCounts = {
  pending: number;
  inProgress: number;
  done: number;
  total: number;
};

export type MinutesSection = { title: string; points: string[] };

export type BoardMinutes = {
  _id: string;
  meetingId: string;
  meetingTitle: string;
  meetingDate: string | null;
  publishedBy: string;
  publishedByName: string;
  publishedAt: string | null;
  hoursAfterMeeting: number | null;
  within48h: boolean;
  summary: string;
  sections: MinutesSection[];
  minutesDocumentUrl: string;
  actionItems: BoardActionItem[];
  createdAt: string | null;
  updatedAt: string | null;
  counts: TaskCounts;
};

export type MinutesCardCounts = { total: number; done: number; open: number };

/** List-card shape — no sections or tasks; open the detail for those. */
export type BoardMinutesSummary = {
  _id: string;
  meetingId: string;
  meetingTitle: string;
  meetingDate: string | null;
  publishedBy: string;
  publishedByName: string;
  publishedAt: string | null;
  within48h: boolean;
  counts: MinutesCardCounts;
};

export type AttendanceInput = {
  userId: string;
  status: "ATTENDING" | "APOLOGY";
  reason?: string;
};

export type ActionItemInput = {
  taskId?: string;
  assigneeId: string;
  taskDescription: string;
  dueDate?: string | null;
};

export type PublishMinutesInput = {
  meetingId: string;
  summary?: string;
  sections?: MinutesSection[];
  minutesDocumentUrl: string;
  attendance: AttendanceInput[];
  actionItems: ActionItemInput[];
};

export type UpdateMinutesInput = {
  summary?: string;
  sections?: MinutesSection[];
  minutesDocumentUrl?: string;
  attendance?: AttendanceInput[];
  actionItems?: ActionItemInput[];
};

function apiFetch<T>(path: string, options: CachedFetchOptions = {}): Promise<T> {
  return cachedFetch<T>(path, options, ["/api/board"]);
}

export const boardApi = {
  listMeetings: (scope: "upcoming" | "past" | "all" = "upcoming") =>
    apiFetch<{ data: BoardMeeting[]; boardMembers: BoardMember[] }>(
      `/api/board/meetings?scope=${scope}`,
      { cacheTtl: 0 },
    ),

  /** Card-only list: no agenda, RSVP or board member payload. */
  listMeetingCards: (scope: "upcoming" | "past" | "all" = "upcoming") =>
    apiFetch<{ data: BoardMeetingCard[] }>(
      `/api/board/meetings?scope=${scope}&view=cards`,
      { cacheTtl: 0 },
    ),

  getMeeting: (id: string) =>
    apiFetch<{ data: BoardMeeting; currentUserId?: string }>(
      `/api/board/meetings/${id}`,
      { cacheTtl: 0 },
    ),

  createMeeting: (input: {
    title: string;
    scheduledDate: string;
    location: string;
    meetingLink: string;
    agenda: AgendaItem[];
  }) =>
    apiFetch<{ data: BoardMeeting }>("/api/board/meetings", {
      method: "POST",
      body: JSON.stringify(input),
    }),

  updateMeeting: (
    id: string,
    input: Partial<{
      title: string;
      scheduledDate: string;
      location: string;
      meetingLink: string;
      agenda: AgendaItem[];
      status: MeetingStatus;
    }>,
  ) =>
    apiFetch<{ data: BoardMeeting }>(`/api/board/meetings/${id}`, {
      method: "PATCH",
      body: JSON.stringify(input),
    }),

  deleteMeeting: (id: string) =>
    apiFetch<{ success: boolean }>(`/api/board/meetings/${id}`, {
      method: "DELETE",
    }),

  rsvp: (id: string, status: "ATTENDING" | "APOLOGY", reason?: string) =>
    apiFetch<{ data: BoardMeeting }>(`/api/board/meetings/${id}/rsvp`, {
      method: "PATCH",
      body: JSON.stringify(
        status === "APOLOGY" && reason !== undefined ? { status, reason } : { status },
      ),
    }),

  listMinutes: (search = "", filter = "all") =>
    apiFetch<{ data: BoardMinutes[]; boardMembers: BoardMember[] }>(
      `/api/board/minutes?filter=${encodeURIComponent(filter)}&search=${encodeURIComponent(search)}`,
      { cacheTtl: 0 },
    ),

  /** Card-only archive list: no sections, decisions or action items. */
  listMinutesCards: () =>
    apiFetch<{ data: BoardMinutesSummary[]; boardMembers: BoardMember[] }>(
      "/api/board/minutes?view=cards",
      { cacheTtl: 0 },
    ),

  getMinutes: (id: string) =>
    apiFetch<{ data: BoardMinutes }>(`/api/board/minutes/${id}`, {
      cacheTtl: 0,
    }),

  publishMinutes: (input: PublishMinutesInput) =>
    apiFetch<{ data: BoardMinutes }>("/api/board/minutes", {
      method: "POST",
      body: JSON.stringify(input),
    }),

  updateMinutes: (id: string, input: UpdateMinutesInput) =>
    apiFetch<{ data: BoardMinutes }>(`/api/board/minutes/${id}`, {
      method: "PATCH",
      body: JSON.stringify(input),
    }),

  deleteMinutes: (id: string) =>
    apiFetch<{ success: boolean }>(`/api/board/minutes/${id}`, {
      method: "DELETE",
    }),

  updateTask: (minutesId: string, taskId: string, status: TaskStatus) =>
    apiFetch<{ data: { task: BoardActionItem | null; counts: TaskCounts } }>(
      `/api/board/minutes/${minutesId}/tasks/${taskId}`,
      { method: "PATCH", body: JSON.stringify({ status }) },
    ),

  /**
   * Upload a signed PDF or a photo of the signed pages. The backend forwards
   * it to Cloudinary, so the device never needs a storage secret.
   */
  uploadMinutesDocument: async (asset: {
    uri: string;
    name: string;
  }): Promise<{ url: string; path: string; fileName: string | null }> => {
    const body = new FormData();
    body.append("file", new File(asset.uri), asset.name);

    const res = await fetch(`${API_BASE}/api/board/uploads`, {
      method: "POST",
      headers: await getRequestHeaders(),
      body,
    });
    const json = (await res.json().catch(() => ({}))) as {
      url?: string;
      path?: string;
      fileName?: string | null;
      error?: string;
    };
    if (!res.ok || !json.url) {
      throw new Error(json.error || "Upload failed. Please try again.");
    }
    return {
      url: json.url,
      path: json.path || json.url,
      fileName: json.fileName ?? asset.name,
    };
  },
};
