import { Ionicons } from "@expo/vector-icons";
import { KeyboardAvoidingView, Platform, ScrollView, StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { SafeAreaProvider, SafeAreaView } from "react-native-safe-area-context";
import { router, useLocalSearchParams } from "expo-router";
import { colors } from "@/constants/colors";
import { PaymentManager } from "@/components/EventPayments";

/**
 * Dedicated, full-space payment management screen for event owners/admins.
 * Opened from the event detail via "Manage payments". Gives the ledger room
 * to breathe: aggregate totals on top, then one card per attendee with the
 * full payment history, POP links and approve/reject actions.
 */
export default function EventPaymentsScreen() {
  const params = useLocalSearchParams<{
    eventId?: string;
    title?: string;
    feeSymbol?: string;
  }>();
  const eventId = params.eventId || "";
  const title = params.title || "";
  const feeSymbol = params.feeSymbol || "K";

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.header}>
          <TouchableOpacity
            onPress={() => router.back()}
            style={styles.headerBtn}
            activeOpacity={0.8}
          >
            <Ionicons name="chevron-down" size={22} color={colors.darkGreen} />
          </TouchableOpacity>
          <View style={styles.headerTitleWrap}>
            <Text style={styles.headerTitle}>Payments</Text>
            {title ? (
              <Text style={styles.headerSub} numberOfLines={1}>
                {title}
              </Text>
            ) : null}
          </View>
          <View style={styles.headerSpacer} />
        </View>

        <KeyboardAvoidingView
          behavior={Platform.OS === "ios" ? "padding" : "height"}
          style={{ flex: 1 }}
        >
          <ScrollView
            contentContainerStyle={styles.list}
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator={false}
          >
          {eventId ? (
            <PaymentManager eventId={eventId} feeSymbol={feeSymbol} />
          ) : (
            <Text style={styles.missing}>Event not found.</Text>
          )}
        </ScrollView>
        </KeyboardAvoidingView>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },

  header: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
    paddingHorizontal: 16,
    paddingVertical: 14,
  },
  headerBtn: {
    width: 36,
    height: 36,
    borderRadius: 18,
    backgroundColor: colors.white,
    alignItems: "center",
    justifyContent: "center",
    borderWidth: 0.5,
    borderColor: colors.lightGreen,
  },
  headerTitleWrap: {
    flex: 1,
    alignItems: "center",
    paddingHorizontal: 8,
  },
  headerTitle: {
    fontSize: 20,
    fontWeight: "700",
    fontFamily: "Poppins_700Bold",
    color: colors.darkGreen,
  },
  headerSub: {
    fontSize: 11,
    lineHeight: 15,
    fontWeight: "400",
    fontFamily: "Poppins_400Regular",
    color: colors.muted,
    marginTop: 1,
    maxWidth: "85%",
  },
  headerSpacer: {
    width: 36,
  },

  list: {
    paddingHorizontal: 16,
    paddingBottom: 32,
  },
  missing: {
    marginTop: 24,
    fontSize: 13,
    textAlign: "center",
    color: colors.muted,
    fontFamily: "Poppins_400Regular",
  },
});
