import { appStorage } from "./app-storage";

const KEY = "relate_device_id_v1";
let cached: string | null = null;

/**
 * Random id for this install. Push registrations and chat sends both carry it
 * so the backend can skip the exact device that sent a message — a member
 * never gets a notification for the message they just typed.
 */
export async function getDeviceId(): Promise<string> {
  if (cached) return cached;
  try {
    const existing = await appStorage.getItemAsync(KEY);
    if (existing) {
      cached = existing;
      return existing;
    }
  } catch {}
  const id = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 12)}`;
  cached = id;
  try {
    await appStorage.setItemAsync(KEY, id);
  } catch {}
  return id;
}
