import GoogleIcon from "@/components/GoogleIcon";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { GradientBox } from "@/constants/gradients";
import { Ionicons } from "@expo/vector-icons";
import { Image } from "expo-image";
import { LinearGradient } from "expo-linear-gradient";
import { useLocalSearchParams, useRouter } from "expo-router";
import { useState } from "react";
import {
  ActivityIndicator,
  Alert,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { signIn, signInWithGoogle, signInWithGitHub } from "@/services/auth";
import { APP_LOGO_URL } from "@/services/config";

export default function LoginScreen() {
  const router = useRouter();
  const { next } = useLocalSearchParams<{ next?: string }>();
  const nextPath =
    typeof next === "string" && next.startsWith("/") && !next.includes("://")
      ? next
      : "/(tabs)";
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [googleLoading, setGoogleLoading] = useState(false);
  const [githubLoading, setGithubLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  // Pop the login screen back onto the existing tabs route. Replacing it with
  // another "/(tabs)" entry would leave a second Home in the stack, and
  // hardware Back would then resurface that stale instance's welcome screen.
  const finishAuth = () => {
    if (router.canDismiss()) {
      router.dismissAll();
      if (nextPath !== "/(tabs)") router.replace(nextPath as any);
      return;
    }
    router.replace(nextPath as any);
  };

  const handleSignIn = async () => {
    if (!email.trim() || !password.trim()) {
      Alert.alert("Error", "Please enter both email and password.");
      return;
    }
    setLoading(true);
    try {
      await signIn(email.trim(), password);
      finishAuth();
    } catch (err: any) {
      Alert.alert(
        "Sign In Failed",
        err?.message || "Invalid email or password.",
      );
    } finally {
      setLoading(false);
    }
  };

  const handleGoogle = async () => {
    setGoogleLoading(true);
    try {
      await signInWithGoogle(nextPath);
      finishAuth();
    } catch (err: any) {
      Alert.alert(
        "Google Sign In Failed",
        err?.message || "Unable to sign in with Google.",
      );
    } finally {
      setGoogleLoading(false);
    }
  };

  const handleGitHub = async () => {
    setGithubLoading(true);
    try {
      await signInWithGitHub(nextPath);
      finishAuth();
    } catch (err: any) {
      Alert.alert(
        "GitHub Sign In Failed",
        err?.message || "Unable to sign in with GitHub.",
      );
    } finally {
      setGithubLoading(false);
    }
  };

  const goToSignUp = () =>
    router.push({
      pathname: "/signup",
      params: next ? { next: String(next) } : undefined,
    });

  return (
    <SafeAreaView style={styles.safe} edges={["top", "bottom"]}>
      <LinearGradient
        colors={["#eef6f9", "#f6fafc", "#ffffff"]}
        style={styles.flex}
      >
        <KeyboardAvoidingView
          style={styles.flex}
          behavior={Platform.OS === "ios" ? "padding" : "height"}
        >
          <ScrollView
            contentContainerStyle={styles.scroll}
            keyboardShouldPersistTaps="handled"
            keyboardDismissMode="none"
            automaticallyAdjustKeyboardInsets
          >
            <View style={styles.header}>
              <TouchableOpacity
                onPress={() => router.replace("/(tabs)")}
                activeOpacity={0.8}
                accessibilityRole="button"
                accessibilityLabel="Go to home"
              >
                <View style={styles.logoWrap}>
                  <Image
                    source={{ uri: APP_LOGO_URL }}
                    placeholder={require("../../assets/images/relateworld_logo.png")}
                    style={styles.logo}
                    contentFit="contain"
                    accessibilityLabel="Relate World"
                  />
                </View>
              </TouchableOpacity>

              <Text style={styles.title}>Welcome Back</Text>
              <Text style={styles.subtitle}>
                Sign in to your prayer community
              </Text>
            </View>

            <View style={styles.form}>
              <Text style={styles.label}>Email</Text>
              <View style={styles.inputWrap}>
                <Ionicons
                  name="mail-outline"
                  size={18}
                  color={colors.gray[400]}
                />
                <TextInput
                  style={styles.input}
                  placeholder="you@example.com"
                  placeholderTextColor={colors.gray[400]}
                  value={email}
                  onChangeText={setEmail}
                  keyboardType="email-address"
                  autoCapitalize="none"
                  autoCorrect={false}
                />
              </View>

              <Text style={styles.label}>Password</Text>
              <View style={styles.inputWrap}>
                <Ionicons
                  name="lock-closed-outline"
                  size={18}
                  color={colors.gray[400]}
                />
                <TextInput
                  style={styles.input}
                  placeholder="Enter your password"
                  placeholderTextColor={colors.gray[400]}
                  value={password}
                  onChangeText={setPassword}
                  secureTextEntry={!showPassword}
                />
                <TouchableOpacity
                  onPress={() => setShowPassword(!showPassword)}
                  hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
                >
                  <Ionicons
                    name={showPassword ? "eye-off-outline" : "eye-outline"}
                    size={20}
                    color={colors.gray[500]}
                  />
                </TouchableOpacity>
              </View>

              <TouchableOpacity
                style={styles.button}
                onPress={handleSignIn}
                disabled={loading}
                activeOpacity={0.8}
              >
                <GradientBox
                  gradient="limeReversed"
                  style={styles.buttonGradient}
                >
                  {loading ? (
                    <ActivityIndicator color={colors.white} />
                  ) : (
                    <Text style={styles.buttonText}>Sign In</Text>
                  )}
                </GradientBox>
              </TouchableOpacity>

              <View>
                <View style={styles.divider}>
                  <View style={styles.dividerLine} />
                  <Text style={styles.dividerText}>or continue with</Text>
                  <View style={styles.dividerLine} />
                </View>
                <View style={styles.authActions}>
                  <TouchableOpacity
                    style={[styles.authBtn, styles.authGoogle]}
                    onPress={handleGoogle}
                    disabled={googleLoading}
                    activeOpacity={0.85}
                    accessibilityRole="button"
                    accessibilityLabel="Continue with Google"
                  >
                    {googleLoading ? (
                      <ActivityIndicator
                        color={colors.forestDark}
                        size="small"
                      />
                    ) : (
                      <GoogleIcon size={20} />
                    )}
                    <Text style={styles.authBtnText}>
                      Continue with Google
                    </Text>
                  </TouchableOpacity>

                  <TouchableOpacity
                    style={[styles.authBtn, styles.authGithub]}
                    onPress={handleGitHub}
                    disabled={githubLoading}
                    activeOpacity={0.85}
                    accessibilityRole="button"
                    accessibilityLabel="Continue with GitHub"
                  >
                    {githubLoading ? (
                      <ActivityIndicator color={colors.white} size="small" />
                    ) : (
                      <Ionicons
                        name="logo-github"
                        size={18}
                        color={colors.white}
                      />
                    )}
                    <Text style={[styles.authBtnText, styles.authGithubText]}>
                      Continue with GitHub
                    </Text>
                  </TouchableOpacity>
                </View>
              </View>

              <TouchableOpacity onPress={goToSignUp} activeOpacity={0.7}>
                <Text style={styles.footerText}>
                  Don&apos;t have an account?{" "}
                  <Text style={styles.footerLink}>Sign Up</Text>
                </Text>
              </TouchableOpacity>
            </View>
          </ScrollView>
        </KeyboardAvoidingView>
      </LinearGradient>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: {
    flex: 1,
    backgroundColor: colors.white,
  },
  flex: {
    flex: 1,
  },
  scroll: {
    flexGrow: 1,
    justifyContent: "center",
  },
  header: {
    alignItems: "center",
    paddingTop: 36,
    paddingBottom: 14,
    paddingHorizontal: 24,
  },
  logoWrap: {
    height: 44,
    overflow: "hidden",
    alignItems: "center",
    marginBottom: 14,
  },
  logo: {
    width: 96,
    height: 96,
    marginTop: -26,
  },
  title: {
    fontSize: 20,
    fontWeight: "800",
    color: colors.forestDark,
    fontFamily: "Poppins_700Bold",
  },
  subtitle: {
    fontSize: 11,
    lineHeight: 15,
    fontWeight: "400",
    color: colors.muted,
    fontFamily: "Poppins_400Regular",
    marginTop: 6,
  },
  form: {
    paddingHorizontal: 24,
    paddingTop: 28,
    paddingBottom: 36,
  },
  label: {
    fontSize: 13,
    fontWeight: "600",
    color: colors.gray[600],
    fontFamily: "Poppins_400Regular",
    marginBottom: 8,
  },
  inputWrap: {
    flexDirection: "row",
    alignItems: "center",
    gap: 10,
    backgroundColor: colors.bg,
    borderWidth: 1,
    borderColor: "#d4eef5",
    borderRadius: 32,
    paddingHorizontal: 14,
    marginBottom: 16,
  },
  input: {
    flex: 1,
    paddingVertical: 14,
    fontSize: 14,
    color: colors.darkGreen,
    fontFamily: "Poppins_400Regular",
  },
  button: {
    marginTop: 8,
    borderRadius: 32,
    overflow: "hidden",
    ...colors.shadow.sm,
  },
  buttonGradient: {
    alignItems: "center",
    justifyContent: "center",
    paddingVertical: 16,
    borderRadius: 32,
  },
  buttonText: {
    fontSize: 15,
    fontWeight: "700",
    color: colors.white,
    fontFamily: "Poppins_700Bold",
  },
  divider: {
    flexDirection: "row",
    alignItems: "center",
    marginVertical: 24,
  },
  dividerLine: {
    flex: 1,
    height: 1,
    backgroundColor: colors.gray[400],
    opacity: 0.4,
  },
  dividerText: {
    marginHorizontal: 12,
    fontSize: 13,
    color: colors.gray[500],
    fontFamily: "Poppins_400Regular",
  },
  authActions: {
    gap: 12,
  },
  authBtn: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    gap: 10,
    minHeight: 52,
    paddingHorizontal: 24,
    borderRadius: 25,
  },
  authGoogle: {
    backgroundColor: colors.white,
    shadowColor: "#03100B",
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.06,
    shadowRadius: 6,
    elevation: 2,
  },
  authGithub: {
    backgroundColor: "#000000",
  },
  authBtnText: {
    fontFamily: fonts.sansBold,
    fontSize: 13,
    color: colors.forestDark,
  },
  authGithubText: {
    color: colors.white,
  },
  footerText: {
    textAlign: "center",
    fontSize: 13,
    color: colors.gray[500],
    fontFamily: "Poppins_400Regular",
    marginTop: 32,
  },
  footerLink: {
    color: colors.green,
    fontWeight: "700",
    fontFamily: "Poppins_700Bold",
  },
});
