import React from "react";
import {
  ActivityIndicator,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
  type StyleProp,
  type ViewStyle,
} from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { GradientBox } from "@/constants/gradients";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";

type Props = {
  label: string;
  onPress: () => void;
  disabled?: boolean;
  loading?: boolean;
  icon?: keyof typeof Ionicons.glyphMap;
  /** "md" (default) for screen CTAs; "sm" for in-card actions. */
  size?: "md" | "sm";
  style?: StyleProp<ViewStyle>;
};

/**
 * The app's primary call-to-action — the same navy→cyan gradient pill
 * used by the Sign In button. Use this instead of a solid forest/ink
 * button for main actions (submit, apply, checkout, join, etc.).
 */
export function PrimaryButton({
  label,
  onPress,
  disabled = false,
  loading = false,
  icon,
  size = "md",
  style,
}: Props) {
  const sm = size === "sm";
  return (
    <TouchableOpacity
      onPress={onPress}
      disabled={disabled || loading}
      activeOpacity={0.85}
      accessibilityRole="button"
      style={[s.btn, style]}
    >
      {disabled ? (
        <View style={sm ? [s.inner, s.innerSm, s.innerDisabled] : [s.inner, s.innerDisabled]}>
          <Text style={[s.text, s.textDisabled, sm && s.textSm]}>{label}</Text>
          {icon ? (
            <Ionicons name={icon} size={sm ? 13 : 16} color={colors.gray[500]} />
          ) : null}
        </View>
      ) : (
        <GradientBox gradient="limeReversed" style={sm ? [s.inner, s.innerSm] : s.inner}>
          {loading ? (
            <ActivityIndicator size="small" color={colors.white} />
          ) : (
            <>
              <Text style={[s.text, sm && s.textSm]}>{label}</Text>
              {icon ? (
                <Ionicons name={icon} size={sm ? 13 : 16} color={colors.white} />
              ) : null}
            </>
          )}
        </GradientBox>
      )}
    </TouchableOpacity>
  );
}

const s = StyleSheet.create({
  btn: {
    borderRadius: 32,
    overflow: "hidden",
    alignSelf: "stretch",
    ...colors.shadow.sm,
  },
  inner: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    gap: 8,
    paddingVertical: 16,
    paddingHorizontal: 28,
    borderRadius: 32,
  },
  innerSm: {
    gap: 6,
    paddingVertical: 9,
    paddingHorizontal: 16,
  },
  innerDisabled: {
    backgroundColor: colors.gray[200],
  },
  text: {
    fontFamily: fonts.sansBold,
    fontWeight: "700",
    fontSize: 15,
    color: colors.white,
  },
  textDisabled: {
    color: colors.gray[500],
  },
  textSm: {
    fontSize: 13,
  },
});
