import { Ionicons } from "@expo/vector-icons";
import { StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import type { MinutesSection } from "@/services/board-governance";
import AutoGrowInput from "./AutoGrowInput";

/**
 * Minutes body: titled sections (1. Budget, 2. Safeguarding…) each holding
 * bullet points, so long minutes stay readable and editable point by point.
 */
export default function MinutesSectionsEditor({
  value,
  onChange,
}: {
  value: MinutesSection[];
  onChange: (next: MinutesSection[]) => void;
}) {
  const patch = (index: number, next: Partial<MinutesSection>) => {
    onChange(value.map((item, i) => (i === index ? { ...item, ...next } : item)));
  };

  const addSection = () =>
    onChange([...value, { title: "", points: [""] }]);

  const removeSection = (index: number) => {
    onChange(value.filter((_, i) => i !== index));
  };

  const addPoint = (index: number) => {
    patch(index, { points: [...value[index].points, ""] });
  };

  const updatePoint = (index: number, pointIndex: number, text: string) => {
    patch(index, {
      points: value[index].points.map((point, i) => (i === pointIndex ? text : point)),
    });
  };

  const removePoint = (index: number, pointIndex: number) => {
    patch(index, {
      points: value[index].points.filter((_, i) => i !== pointIndex),
    });
  };

  return (
    <View style={styles.wrap}>
      <View style={styles.head}>
        <Text style={styles.label}>Minutes</Text>
        <TouchableOpacity onPress={addSection} activeOpacity={0.8}>
          <Text style={styles.addLink}>+ Add section</Text>
        </TouchableOpacity>
      </View>

      {value.length === 0 ? (
        <Text style={styles.empty}>
          No sections yet — add one per agenda item, then record the decisions as
          points underneath.
        </Text>
      ) : null}

      {value.map((section, index) => (
        <View key={`section-${index}`} style={styles.section}>
          <View style={styles.sectionTop}>
            <View style={styles.numberBadge}>
              <Text style={styles.numberText}>{index + 1}</Text>
            </View>
            <AutoGrowInput
              value={section.title}
              onChangeText={(title) => patch(index, { title })}
              placeholder="Budget, safeguarding, venue…"
              placeholderTextColor={colors.muted}
              maxLength={160}
              minHeight={42}
              style={styles.titleInput}
            />
            <TouchableOpacity
              onPress={() => removeSection(index)}
              style={styles.iconBtn}
              accessibilityLabel={`Delete section ${index + 1}`}
            >
              <Ionicons name="trash-outline" size={15} color={colors.muted} />
            </TouchableOpacity>
          </View>

          <View style={styles.pointList}>
            {section.points.map((point, pointIndex) => (
              <View key={`section-${index}-point-${pointIndex}`} style={styles.pointRow}>
                <View style={styles.bullet} />
                <AutoGrowInput
                  value={point}
                  onChangeText={(text) => updatePoint(index, pointIndex, text)}
                  placeholder="What was decided or noted?"
                  placeholderTextColor={colors.muted}
                  maxLength={2000}
                  minHeight={42}
                  style={styles.pointInput}
                />
                <TouchableOpacity
                  onPress={() => removePoint(index, pointIndex)}
                  style={styles.pointBtn}
                  accessibilityLabel={`Delete point ${index + 1}.${pointIndex + 1}`}
                >
                  <Ionicons name="close" size={14} color={colors.muted} />
                </TouchableOpacity>
              </View>
            ))}
          </View>

          <TouchableOpacity
            onPress={() => addPoint(index)}
            style={styles.addPoint}
            activeOpacity={0.8}
          >
            <Ionicons name="add-outline" size={13} color={colors.goldDark} />
            <Text style={styles.addPointText}>Add point</Text>
          </TouchableOpacity>
        </View>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: { gap: 8, marginTop: 2 },
  head: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
  },
  label: {
    fontSize: 11,
    lineHeight: 15,
    letterSpacing: 0.8,
    textTransform: "uppercase",
    color: colors.muted,
    fontFamily: fonts.sansSemiBold,
  },
  addLink: {
    fontSize: 12.5,
    color: colors.goldDark,
    fontFamily: fonts.sansSemiBold,
  },
  empty: {
    fontSize: 12.5,
    lineHeight: 18,
    color: colors.gray[400],
    fontFamily: fonts.sans,
  },
  section: {
    gap: 7,
    padding: 10,
    borderRadius: 12,
    backgroundColor: colors.bg,
    borderWidth: 0.5,
    borderColor: colors.border,
  },
  sectionTop: { flexDirection: "row", alignItems: "flex-start", gap: 8 },
  numberBadge: {
    width: 24,
    height: 24,
    marginTop: 6,
    borderRadius: 12,
    backgroundColor: `${colors.gold}1f`,
    alignItems: "center",
    justifyContent: "center",
  },
  numberText: {
    fontSize: 11.5,
    color: colors.goldDark,
    fontFamily: fonts.sansBold,
  },
  titleInput: {
    flex: 1,
    backgroundColor: colors.white,
  },
  iconBtn: {
    width: 32,
    height: 32,
    marginTop: 2,
    borderRadius: 16,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: colors.white,
  },
  pointList: { gap: 5, paddingLeft: 32 },
  pointRow: { flexDirection: "row", alignItems: "flex-start", gap: 6 },
  bullet: {
    width: 6,
    height: 6,
    borderRadius: 3,
    marginTop: 17,
    backgroundColor: colors.goldDark,
  },
  pointInput: { flex: 1, backgroundColor: colors.white },
  pointBtn: {
    width: 28,
    height: 28,
    marginTop: 4,
    borderRadius: 14,
    alignItems: "center",
    justifyContent: "center",
  },
  addPoint: {
    flexDirection: "row",
    alignItems: "center",
    gap: 3,
    marginLeft: 32,
    paddingVertical: 2,
    alignSelf: "flex-start",
  },
  addPointText: {
    fontSize: 12,
    color: colors.goldDark,
    fontFamily: fonts.sansSemiBold,
  },
});
