import { type SQLiteDatabase } from "expo-sqlite";
import { cleanScriptureText } from "@/lib/bible-queries";

/**
 * Local cache of the Verse of the Day, keyed by calendar day. Storing the
 * yanked text + passage id means the Home card renders instantly and stays
 * usable offline: the YouVersion API is only hit once per day (per version).
 */

export type VotdCache = {
  dayKey: string;
  dayOfYear: number;
  versionId: number;
  passageId: string;
  reference: string;
  text: string;
};

type VotdRow = {
  day_of_year: number;
  version_id: number;
  passage_id: string;
  reference: string;
  text: string;
};

export function loadVotd(db: SQLiteDatabase, dayKey: string): VotdCache | null {
  try {
    const row = db.getFirstSync<VotdRow>(
      `SELECT day_of_year, version_id, passage_id, reference, text
       FROM votd_cache WHERE day_key = ?`,
      [dayKey],
    );
    if (!row || !row.text) return null;
    return {
      dayKey,
      dayOfYear: row.day_of_year,
      versionId: row.version_id,
      passageId: row.passage_id,
      reference: row.reference,
      text: cleanScriptureText(row.text),
    };
  } catch {
    return null;
  }
}

export function saveVotd(db: SQLiteDatabase, entry: VotdCache): void {
  try {
    db.runSync(
      `INSERT INTO votd_cache (day_key, day_of_year, version_id, passage_id, reference, text, fetched_at)
       VALUES (?, ?, ?, ?, ?, ?, datetime('now'))
       ON CONFLICT(day_key) DO UPDATE SET
         day_of_year = excluded.day_of_year,
         version_id = excluded.version_id,
         passage_id = excluded.passage_id,
         reference = excluded.reference,
         text = excluded.text,
         fetched_at = excluded.fetched_at`,
      [
        entry.dayKey,
        entry.dayOfYear,
        entry.versionId,
        entry.passageId,
        entry.reference,
        entry.text,
      ],
    );
  } catch {}
}