import { getRequestHeaders } from "./auth";
import { API_BASE, IS_WEB } from "./config";

let lastRunAt = 0;

export async function catchUpScheduledReminders(): Promise<void> {
  if (!IS_WEB) return;
  const now = Date.now();
  if (now - lastRunAt < 60_000) return;
  lastRunAt = now;

  try {
    const res = await fetch(`${API_BASE}/api/scheduled-reminders/catch-up`, {
      method: "POST",
      headers: await getRequestHeaders({ "Content-Type": "application/json" }),
      credentials: "include",
    });
    if (!res.ok) return;
    await res.json().catch(() => null);
  } catch {}
}
