import { FlatList, Modal, StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { useBibleTheme, type BibleTheme } from "@/lib/bible-theme";
import { type BookmarkRow } from "@/lib/bible-sync";

type Props = {
  visible: boolean;
  bookmarks: BookmarkRow[];
  onOpen: (book: string, chapter: number, verse: number) => void;
  onDelete: (id: number) => void;
  onClose: () => void;
};

function referenceOf(b: BookmarkRow): string {
  return b.verse > 0 ? `${b.book} ${b.chapter}:${b.verse}` : `${b.book} ${b.chapter}`;
}

export default function BookmarksSheet({
  visible,
  bookmarks,
  onOpen,
  onDelete,
  onClose,
}: Props) {
  const theme = useBibleTheme();
  const s = createStyles(theme);

  return (
    <Modal
      visible={visible}
      transparent
      animationType="slide"
      onRequestClose={onClose}
    >
      <TouchableOpacity style={s.overlay} activeOpacity={1} onPress={onClose}>
        <TouchableOpacity activeOpacity={1} style={s.sheet} onPress={() => {}}>
          <View style={s.grabber} />
          <View style={s.titleRow}>
            <Text style={s.title}>Bookmarks</Text>
            <TouchableOpacity
              onPress={onClose}
              style={s.closeBtn}
              accessibilityRole="button"
              accessibilityLabel="Close"
            >
              <Ionicons name="close" size={20} color={theme.textMuted} />
            </TouchableOpacity>
          </View>

          {bookmarks.length === 0 ? (
            <View style={s.empty}>
              <Ionicons name="bookmarks-outline" size={30} color={theme.textMuted} />
              <Text style={s.emptyTitle}>No bookmarks yet</Text>
              <Text style={s.emptyText}>
                Tap a verse, then Save to bookmark it — add a note to remember
                why it matters.
              </Text>
            </View>
          ) : (
            <FlatList
              data={bookmarks}
              keyExtractor={(item) => String(item.id)}
              contentContainerStyle={s.list}
              renderItem={({ item }) => (
                <View style={s.item}>
                  <TouchableOpacity
                    style={s.itemBody}
                    activeOpacity={0.7}
                    onPress={() => {
                      onOpen(item.book, item.chapter, item.verse);
                      onClose();
                    }}
                    accessibilityRole="button"
                    accessibilityLabel={`Open ${referenceOf(item)}`}
                  >
                    <Text style={s.itemRef}>{referenceOf(item)}</Text>
                    {item.note ? (
                      <Text style={s.itemNote} numberOfLines={2}>
                        {item.note}
                      </Text>
                    ) : null}
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={s.deleteBtn}
                    onPress={() => onDelete(item.id)}
                    accessibilityRole="button"
                    accessibilityLabel={`Delete bookmark ${referenceOf(item)}`}
                  >
                    <Ionicons
                      name="trash-outline"
                      size={18}
                      color={theme.isDark ? "#FF8A8A" : "#D64545"}
                    />
                  </TouchableOpacity>
                </View>
              )}
            />
          )}
        </TouchableOpacity>
      </TouchableOpacity>
    </Modal>
  );
}

function createStyles(theme: BibleTheme) {
  return StyleSheet.create({
    overlay: {
      flex: 1,
      backgroundColor: "rgba(0,0,0,0.5)",
      justifyContent: "flex-end",
    },
    sheet: {
      maxHeight: "70%",
      backgroundColor: theme.cardBg,
      borderTopLeftRadius: 24,
      borderTopRightRadius: 24,
      paddingTop: 10,
      paddingBottom: 30,
    },
    grabber: {
      alignSelf: "center",
      width: 40,
      height: 4,
      borderRadius: 2,
      backgroundColor: theme.borderStrong,
      marginBottom: 8,
    },
    titleRow: {
      flexDirection: "row",
      alignItems: "center",
      justifyContent: "space-between",
      paddingHorizontal: 20,
      marginBottom: 6,
    },
    title: {
      fontWeight: "700",
      fontSize: 22,
      color: theme.text,
    },
    closeBtn: {
      padding: 6,
    },
    list: {
      paddingBottom: 10,
    },
    item: {
      flexDirection: "row",
      alignItems: "center",
      paddingHorizontal: 20,
      paddingVertical: 12,
      borderBottomWidth: StyleSheet.hairlineWidth,
      borderBottomColor: theme.border,
    },
    itemBody: {
      flex: 1,
      marginRight: 12,
    },
    itemRef: {
      fontWeight: "700",
      fontSize: 16,
      color: theme.text,
    },
    itemNote: {
      fontSize: 13,
      color: theme.textMuted,
      marginTop: 3,
      lineHeight: 18,
    },
    deleteBtn: {
      padding: 8,
    },
    empty: {
      alignItems: "center",
      paddingHorizontal: 32,
      paddingVertical: 36,
      gap: 8,
    },
    emptyTitle: {
      fontWeight: "700",
      fontSize: 16,
      color: theme.text,
      marginTop: 4,
    },
    emptyText: {
      fontSize: 13,
      color: theme.textMuted,
      textAlign: "center",
      lineHeight: 19,
    },
  });
}