async function openSmartSaver() {
  try {
    await Linking.openURL(SMART_SAVER_URL);
  } catch {
    Alert.alert(
      "Smart Saver not found",
      "Install the Smart Saver app on this device, then tap Open Smart Saver again.",
    );
  }
}

