import { cachedFetch, type CachedFetchOptions } from "./cache";

export type TrainingTimelineItem = {
  startTime: string;
  endTime: string;
  title: string;
  details: string;
};

export type TrainingDay = {
  date: string;
  topic: string;
  startTime: string;
  endTime: string;
  details: string;
  notes: string;
  timeline: TrainingTimelineItem[];
};

export type TrainingAttendanceStatus = "ATTENDING" | "NOT_ATTENDING";

export type TrainingAttendance = {
  userId: string;
  name: string;
  role: string;
  status: TrainingAttendanceStatus;
  reason: string;
};

export type Training = {
  _id: string;
  title: string;
  description: string;
  scheduledDate: string | null;
  location: string;
  meetingLink: string;
  imageUrl: string;
  days: TrainingDay[];
  attendance: TrainingAttendance[];
  counts: { attending: number; notAttending: number; total: number };
  createdBy: string;
  createdByName: string;
  createdAt: string | null;
  updatedAt: string | null;
};

export type TrainingInput = {
  title: string;
  description: string;
  scheduledDate: string;
  location: string;
  meetingLink: string;
  imageUrl: string;
  days: TrainingDay[];
};

function apiFetch<T>(path: string, options: CachedFetchOptions = {}): Promise<T> {
  return cachedFetch<T>(path, options, ["/api/trainings"]);
}

export const trainingsApi = {
  list: () =>
    apiFetch<{ data: Training[] }>("/api/trainings", { cacheTtl: 0 }),

  get: (id: string) =>
    apiFetch<{ data: Training; currentUserId?: string; canManage?: boolean }>(
      `/api/trainings/${id}`,
      { cacheTtl: 0 },
    ),

  create: (input: TrainingInput) =>
    apiFetch<{ data: Training }>("/api/trainings", {
      method: "POST",
      body: JSON.stringify(input),
    }),

  update: (id: string, input: Partial<TrainingInput>) =>
    apiFetch<{ data: Training }>(`/api/trainings/${id}`, {
      method: "PATCH",
      body: JSON.stringify(input),
    }),

  markAttendance: (
    id: string,
    status: TrainingAttendanceStatus,
    reason?: string,
  ) =>
    apiFetch<{ data: Training }>(`/api/trainings/${id}/attendance`, {
      method: "PATCH",
      body: JSON.stringify(
        reason === undefined ? { status } : { status, reason },
      ),
    }),

  remove: (id: string) =>
    apiFetch<{ success: boolean }>(`/api/trainings/${id}`, {
      method: "DELETE",
    }),
};
