import DiscoverCard from "@/components/DiscoverCard";
import type { EventCard } from "@/services/community";
import { formatEventBadge } from "@/utils/event-dates";
import { memo } from "react";

/**
 * Event card for club pages — renders the shared Discover card so it matches
 * the home rail exactly (image on top, overlay type chip, gradient icon tile,
 * title and meta rows). Tapping opens the full event details (RSVP, admin
 * edit) — the heavy detail/registration modals are reused from the community
 * screen.
 */
function ClubEventCard({
  event,
  onPress,
  width,
}: {
  event: EventCard;
  onPress: () => void;
  /** Card width for horizontal rails. Omit for full-width layout. */
  width?: number;
}) {
  const badge = formatEventBadge(event.date, event.time, event.dateTo, event.timeTo);

  const meta = [
    { icon: "time-outline", text: badge || "Date to be confirmed" },
    ...(event.location
      ? [{ icon: "location-outline", text: event.location }]
      : []),
  ];

  return (
    <DiscoverCard
      type="event"
      title={event.title}
      meta={meta}
      image={event.imageUrl}
      onPress={onPress}
      width={width}
      accessibilityLabel={`${event.title} — view event details`}
    />
  );
}

export default memo(ClubEventCard);