import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { useState } from "react";
import {
  ActivityIndicator,
  Alert,
  KeyboardAvoidingView,
  Modal,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Switch,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { colors } from "@/constants/colors";
import type { EventRegistrationDetails } from "@/services/community";
import { formatEventBadge } from "@/utils/event-dates";
import { DEFAULT_PHONE_PREFIX, hasValidPhone } from "@/utils/phone";

type EventLike = {
  id: string;
  title: string;
  date: string;
  time: string;
  dateTo?: string;
  timeTo?: string;
};

function Field({
  label,
  required,
  optional,
  error,
  children,
}: {
  label: string;
  required?: boolean;
  optional?: boolean;
  error?: string;
  children: React.ReactNode;
}) {
  return (
    <View style={styles.field}>
      <View style={styles.fieldLabelRow}>
        <Text style={styles.fieldLabel}>{label}</Text>
        {required ? (
          <Text style={styles.req}>*</Text>
        ) : optional ? (
          <Text style={styles.opt}>(optional)</Text>
        ) : null}
      </View>
      {children}
      {error ? (
        <View style={styles.errorRow}>
          <Text style={styles.errorMark}>!</Text>
          <Text style={styles.fieldError}>{error}</Text>
        </View>
      ) : null}
    </View>
  );
}

export default function EventRegistrationModal({
  event,
  onClose,
  onSubmit,
}: {
  event: EventLike;
  onClose: () => void;
  onSubmit: (details: EventRegistrationDetails) => Promise<boolean>;
}) {
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState(DEFAULT_PHONE_PREFIX);
  const [emergencyContact, setEmergencyContact] = useState("");
  const [notes, setNotes] = useState("");
  const [bringingPartner, setBringingPartner] = useState(true);
  const [partnerName, setPartnerName] = useState("");
  const [partnerPhone, setPartnerPhone] = useState(DEFAULT_PHONE_PREFIX);
  const [partnerEmail, setPartnerEmail] = useState("");
  const [agreed, setAgreed] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [submitting, setSubmitting] = useState(false);
  const [success, setSuccess] = useState(false);

  // The modal is mounted on demand (see SocialTab), so all state starts
  // fresh for every event — no reset effect needed.
  const badge = formatEventBadge(
    event.date,
    event.time,
    event.dateTo,
    event.timeTo,
  );

  const clearError = (key: string) =>
    setErrors((prev) => {
      if (!prev[key]) return prev;
      const next = { ...prev };
      delete next[key];
      return next;
    });

  const handleSubmit = async () => {
    const errs: Record<string, string> = {};
    if (!fullName.trim()) errs.fullName = "Please enter your full name.";
    if (!email.trim() || !/^\S+@\S+\.\S+$/.test(email)) errs.email = "Please enter a valid email.";
    if (!hasValidPhone(phone)) errs.phone = "Phone is required.";
    if (!emergencyContact.trim()) errs.emergencyContact = "Emergency contact is required for outdoor events.";
    if (bringingPartner) {
      if (!partnerName.trim()) errs.partnerName = "Please enter your partner's name.";
      if (!hasValidPhone(partnerPhone)) errs.partnerPhone = "Partner's phone is required.";
    }
    if (!agreed) errs.terms = "Please accept the event waiver.";
    setErrors(errs);
    if (Object.keys(errs).length > 0) return;

    setSubmitting(true);
    const ok = await onSubmit({
      fullName: fullName.trim(),
      email: email.trim(),
      phone: phone.trim(),
      dob: "",
      emergencyContact: emergencyContact.trim(),
      notes: notes.trim(),
      bringingPartner,
      partner: bringingPartner
        ? {
            fullName: partnerName.trim(),
            phone: partnerPhone.trim(),
            dob: "",
            email: partnerEmail.trim(),
          }
        : null,
    });
    setSubmitting(false);
    if (ok) setSuccess(true);
  };

  const firstName = fullName.trim().split(" ")[0] || "friend";
  const partnerFirst = partnerName.trim().split(" ")[0];

  return (
    <Modal
      visible
      animationType="slide"
      presentationStyle="fullScreen"
      statusBarTranslucent
      onRequestClose={() => !submitting && onClose()}
    >
      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : "height"}
        style={styles.overlay}
      >
        <View style={styles.container}>
          <LinearGradient
            colors={[colors.gold, colors.goldDark]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 0 }}
            style={styles.goldBar}
          />

          {success ? (
            <ScrollView
              contentContainerStyle={styles.successWrap}
              keyboardShouldPersistTaps="handled"
              showsVerticalScrollIndicator={false}
            >
              <LinearGradient
                colors={[colors.gold, colors.goldDark]}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={styles.successIcon}
              >
                <Ionicons name="checkmark" size={30} color={colors.white} />
              </LinearGradient>
              <Text style={styles.successTitle}>{"You're in!"}</Text>
              <Text style={styles.successText}>
                See you there,{" "}
                <Text style={styles.successName}>
                  {firstName}
                  {bringingPartner && partnerFirst ? ` and ${partnerFirst}` : ""}
                </Text>
                . A confirmation has been sent to your email.
              </Text>
              <TouchableOpacity style={styles.doneBtn} onPress={onClose} activeOpacity={0.85}>
                <Text style={styles.doneBtnText}>Done</Text>
              </TouchableOpacity>
            </ScrollView>
          ) : (
            <>
              <View style={styles.header}>
                <View style={styles.headerTextWrap}>
                  <Text style={styles.eyebrow}>
                    Registration{badge ? ` · ${badge}` : ""}
                  </Text>
                  <Text style={styles.title}>
                    Join <Text style={styles.titleAccent}>{event.title}</Text>
                  </Text>
                  <Text style={styles.sub}>Fill in your details to reserve your spot.</Text>
                </View>
                <TouchableOpacity
                  style={styles.closeBtn}
                  onPress={onClose}
                  disabled={submitting}
                  activeOpacity={0.8}
                  accessibilityLabel="Close registration"
                >
                  <Ionicons name="close" size={16} color={colors.muted} />
                </TouchableOpacity>
              </View>

              <ScrollView
                style={styles.formScroll}
                contentContainerStyle={styles.formContent}
                keyboardShouldPersistTaps="handled"
                keyboardDismissMode="none"
                showsVerticalScrollIndicator={false}
              >
                <Field label="Full name" required error={errors.fullName}>
                  <TextInput
                    value={fullName}
                    onChangeText={(t) => {
                      setFullName(t);
                      clearError("fullName");
                    }}
                    placeholder="Jane Doe"
                    placeholderTextColor="#a3aebc"
                    style={[styles.input, !!errors.fullName && styles.inputError]}
                  />
                </Field>

                <Field label="Email address" required error={errors.email}>
                  <TextInput
                    value={email}
                    onChangeText={(t) => {
                      setEmail(t);
                      clearError("email");
                    }}
                    placeholder="jane@example.com"
                    placeholderTextColor="#a3aebc"
                    keyboardType="email-address"
                    autoCapitalize="none"
                    style={[styles.input, !!errors.email && styles.inputError]}
                  />
                </Field>

                <Field label="Phone" required error={errors.phone}>
                  <TextInput
                    value={phone}
                    onChangeText={(t) => {
                      setPhone(t);
                      clearError("phone");
                    }}
                    placeholder="+1 555 000 0000"
                    placeholderTextColor="#a3aebc"
                    keyboardType="phone-pad"
                    style={[styles.input, !!errors.phone && styles.inputError]}
                  />
                </Field>

                <Field label="Emergency contact" required error={errors.emergencyContact}>
                  <TextInput
                    value={emergencyContact}
                    onChangeText={(t) => {
                      setEmergencyContact(t);
                      clearError("emergencyContact");
                    }}
                    placeholder="Contact name · phone number"
                    placeholderTextColor="#a3aebc"
                    style={[styles.input, !!errors.emergencyContact && styles.inputError]}
                  />
                </Field>

                <View style={styles.partnerToggle}>
                  <Switch
                    value={bringingPartner}
                    onValueChange={(v) => {
                      setBringingPartner(v);
                      if (!v) {
                        setErrors((prev) => {
                          const next = { ...prev };
                          delete next.partnerName;
                          delete next.partnerPhone;
                          return next;
                        });
                      }
                    }}
                    trackColor={{ false: "rgba(29,42,77,0.2)", true: colors.gold }}
                    thumbColor={colors.white}
                    ios_backgroundColor="rgba(29,42,77,0.2)"
                  />
                  <View style={styles.partnerTextWrap}>
                    <Text style={styles.partnerLabel}>{"I'm bringing a partner"}</Text>
                    <Text style={styles.partnerSub}>
                      {"They'll be registered alongside you."}
                    </Text>
                  </View>
                </View>

                {bringingPartner && (
                  <View style={styles.partnerSection}>
                    <View style={styles.sectionLabelRow}>
                      <Text style={styles.sectionLabel}>Partner details</Text>
                      <View style={styles.sectionLabelLine} />
                    </View>

                    <Field label="Partner's full name" required error={errors.partnerName}>
                      <TextInput
                        value={partnerName}
                        onChangeText={(t) => {
                          setPartnerName(t);
                          clearError("partnerName");
                        }}
                        placeholder="Partner's name"
                        placeholderTextColor="#a3aebc"
                        style={[styles.input, !!errors.partnerName && styles.inputError]}
                      />
                    </Field>

                    <Field label="Partner's phone" required error={errors.partnerPhone}>
                      <TextInput
                        value={partnerPhone}
                        onChangeText={(t) => {
                          setPartnerPhone(t);
                          clearError("partnerPhone");
                        }}
                        placeholder="+27 00 000 0000"
                        placeholderTextColor="#a3aebc"
                        keyboardType="phone-pad"
                        style={[styles.input, !!errors.partnerPhone && styles.inputError]}
                      />
                    </Field>

                    <Field label="Partner's email" optional>
                      <TextInput
                        value={partnerEmail}
                        onChangeText={setPartnerEmail}
                        placeholder="partner@example.com"
                        placeholderTextColor="#a3aebc"
                        keyboardType="email-address"
                        autoCapitalize="none"
                        style={styles.input}
                      />
                    </Field>
                  </View>
                )}

                <Field label="Notes" optional>
                  <TextInput
                    value={notes}
                    onChangeText={setNotes}
                    placeholder="Medical info, dietary needs, or anything we should know…"
                    placeholderTextColor="#a3aebc"
                    multiline
                    style={[styles.input, styles.textArea]}
                  />
                </Field>

                <Pressable style={styles.terms} onPress={() => setAgreed(!agreed)}>
                  <View
                    style={[
                      styles.checkbox,
                      agreed && styles.checkboxOn,
                      !!errors.terms && styles.checkboxError,
                    ]}
                  >
                    {agreed && (
                      <Ionicons name="checkmark" size={12} color={colors.white} />
                    )}
                  </View>
                  <Text style={styles.termsText}>
                    I agree to the{" "}
                    <Text
                      style={styles.termsLink}
                      onPress={() =>
                        Alert.alert(
                          "Event Waiver",
                          "By joining this event you agree to participate responsibly and follow the event host's guidelines. Outdoor activities carry inherent risk — please ensure your emergency contact details are accurate.",
                        )
                      }
                    >
                      event waiver
                    </Text>{" "}
                    and understand this is an outdoor activity.
                  </Text>
                </Pressable>
                {!!errors.terms && (
                  <View style={[styles.errorRow, { marginTop: 4 }]}>
                    <Text style={styles.errorMark}>!</Text>
                    <Text style={styles.fieldError}>{errors.terms}</Text>
                  </View>
                )}

                <View style={styles.actions}>
                  <TouchableOpacity
                    style={styles.cancelBtn}
                    onPress={onClose}
                    disabled={submitting}
                    activeOpacity={0.8}
                  >
                    <Text style={styles.cancelText}>Cancel</Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={styles.submitBtn}
                    onPress={handleSubmit}
                    disabled={submitting}
                    activeOpacity={0.85}
                  >
                    {submitting ? (
                      <ActivityIndicator size="small" color={colors.forestDark} />
                    ) : (
                      <>
                        <Ionicons name="checkmark" size={15} color={colors.forestDark} />
                        <Text style={styles.submitText}>Confirm registration</Text>
                      </>
                    )}
                  </TouchableOpacity>
                </View>
              </ScrollView>
            </>
          )}
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
}

