/**
 * Formats an event's date + time as a compact uppercase badge that always
 * includes the year, e.g. "OCT 04, 2026 · 9:00 AM". Supports multi-day
 * events via `dateTo` / `timeTo`, rendering a range like
 * "OCT 04 - OCT 06, 2026 · 9:00 AM". Falls back gracefully when either is
 * missing.
 */
export function formatEventBadge(
  date: string,
  time: string,
  dateTo?: string,
  timeTo?: string,
) {
  let d = "";
  let to = "";
  try {
    const dt = new Date(date);
    if (!isNaN(dt.getTime())) {
      const end = dateTo ? new Date(dateTo) : null;
      const hasEnd = end && !isNaN(end.getTime());
      const sameYear =
        !!hasEnd && end!.getFullYear() === dt.getFullYear();
      d = dt
        .toLocaleDateString("en-US", {
          month: "short",
          day: "2-digit",
          ...(sameYear ? {} : { year: "numeric" }),
        })
        .toUpperCase();
      if (hasEnd) {
        to = end!
          .toLocaleDateString("en-US", {
            month: "short",
            day: "2-digit",
            year: "numeric",
          })
          .toUpperCase();
      }
    }
  } catch {}
  const t = (time || "").trim();
  const tTo = (timeTo || "").trim();
  let out = d;
  if (to) out = `${d} - ${to}`;
  if (out) {
    const timePart = tTo && tTo !== t ? `${t} - ${tTo}` : t;
    out = timePart ? `${out} · ${timePart}` : out;
  } else {
    out = t;
  }
  return out;
}

// Parses a stored "YYYY-MM-DD" date as local time (avoids the UTC midnight
// shift that makes `new Date("2026-10-04")` land on the previous day in
// negative timezones). Falls back to `new Date(s)` for full timestamps.
const parseLocal = (s: string) => {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s.trim());
  return m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : new Date(s);
};

/**
 * Splits an event's date range into "from" / "to" strings plus an inclusive
 * day count and night count, so multi-day events can be shown stacked
 * (From / To / "3 days · 2 nights") instead of a single ambiguous line.
 * Returns `{ from: "" }` when the start date can't be parsed.
 */
export function eventDateRange(date: string, dateTo?: string) {
  const fmt = (dt: Date) =>
    dt
      .toLocaleDateString("en-US", {
        month: "short",
        day: "2-digit",
        year: "numeric",
      })
      .toUpperCase();
  try {
    const from = parseLocal(date);
    if (isNaN(from.getTime())) return { from: "" };
    if (!dateTo) return { from: fmt(from) };
    const end = parseLocal(dateTo);
    if (isNaN(end.getTime())) return { from: fmt(from) };
    const days = Math.round((end.getTime() - from.getTime()) / 86400000) + 1;
    return {
      from: fmt(from),
      to: fmt(end),
      days: Math.max(1, days),
      nights: Math.max(0, days - 1),
    };
  } catch {
    return { from: "" };
  }
}
