import { cachedFetch } from "./cache";

export type PerformanceMonth = {
  month: number;
  label: string;
  period: string;
  income: number;
  expenses: number;
  net: number;
  /** Report income without the balance brought in. */
  raised: number;
};

export type IncomeMixRow = {
  key: string;
  label: string;
  value: number;
};

export type PerformanceImpact = {
  families: number;
  mealsServed: number;
  children: number;
  placements: number;
  events: number;
};

export type AppDownloadStats = {
  downloads: number;
  latestVersion: string | null;
  latestDownloads: number;
  releases: number;
};

export type IndividualAppraisalRow = {
  id: string;
  name: string;
  department: string | null;
  score: number;
  band: string | null;
};

export type DepartmentAppraisalRow = {
  id: string;
  department: string;
  lead: string | null;
  score: number;
  band: string | null;
  collected: number;
  revenueTarget: number;
};

export type AppraisalPerformance = {
  season: { name: string; year: number };
  individuals: IndividualAppraisalRow[];
  departments: DepartmentAppraisalRow[];
};

export type PerformanceSummary = {
  year: number;
  target: number;
  coffer: {
    raised: number;
    target: number;
    remaining: number;
    progressPct: number;
  };
  totals: { income: number; expenses: number };
  /** Carried balance plus what the window raised, less what it spent. */
  balance: number;
  months: PerformanceMonth[];
  incomeMix: IncomeMixRow[];
  /** Approved appraisal scores — null until the first is signed off. */
  appraisals: AppraisalPerformance | null;
  /** APK downloads from the public GitHub releases; null when unavailable. */
  app: AppDownloadStats | null;
  latestImpact: PerformanceImpact | null;
  latestReport: {
    period: string;
    preparedBy: string | null;
    createdAt: string | null;
  } | null;
  reportCount: number;
  season: { name: string; ends: string; year: number };
};

export const performanceApi = {
  /** Organisation performance for a year, built from published financial reports. */
  get: (options: { year?: number; forceRefresh?: boolean } = {}) =>
    cachedFetch<{ data: PerformanceSummary }>(
      `/api/performance${options.year ? `?year=${options.year}` : ""}`,
      { cacheTtl: 60_000, forceRefresh: options.forceRefresh },
    ),
};
