import { Ionicons } from "@expo/vector-icons";
import { Image } from "expo-image";
import * as ImagePicker from "expo-image-picker";
import {
  Alert,
  ActivityIndicator,
  KeyboardAvoidingView,
  Modal,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { useState } from "react";
import { LinearGradient } from "expo-linear-gradient";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { type Club, useClubs } from "@/services/clubs";
import ClubSelect from "@/components/ClubSelect";
import {
  communityApi,
  type Event,
  type EventAgendaItem,
  type EventDetail,
} from "@/services/community";
import { getSession } from "@/services/auth";
import InlineCalendar from "@/components/InlineCalendar";
import InlineTimePicker from "@/components/InlineTimePicker";
import { getOptimizedImageUrl } from "@/services/cloudinary";
import { GradientBox } from "@/constants/gradients";

type Props = {
  visible: boolean;
  club?: Club | null;
  /** Event being edited, or null to create. */
  editing?: Event | null;
  onClose: () => void;
  onSaved: () => void;
  /** Offer a "Relate" choice (no club) — used by the Events manager. */
  allowOrganization?: boolean;
};

function formatDate(d: Date) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function formatTime(d: Date) {
  let h = d.getHours();
  const min = String(d.getMinutes()).padStart(2, "0");
  const ampm = h >= 12 ? "PM" : "AM";
  h = h % 12 || 12;
  return `${h}:${min} ${ampm}`;
}

function parseDateInput(date?: string | null): Date | null {
  if (!date) return null;
  const m = date.trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) {
    const d = new Date(+m[1], +m[2] - 1, +m[3]);
    return isNaN(d.getTime()) ? null : d;
  }
  const d = new Date(date);
  return isNaN(d.getTime()) ? null : d;
}

function parseTimeToDate(time?: string | null): Date | null {
  if (!time) return null;
  const m = time.trim().match(/^(\d{1,2}):(\d{2})\s*(am|pm)?$/i);
  if (!m) return null;
  let h = parseInt(m[1], 10);
  const min = parseInt(m[2], 10);
  const ap = (m[3] || "").toLowerCase();
  if (ap === "pm" && h < 12) h += 12;
  if (ap === "am" && h === 12) h = 0;
  const d = new Date(1970, 0, 1, h, min, 0, 0);
  return isNaN(d.getTime()) ? null : d;
}

const fmtPickerDate = (d: Date | null) => {
  if (!d) return "";
  const sameYear = d.getFullYear() === new Date().getFullYear();
  return d.toLocaleDateString("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
    ...(sameYear ? {} : { year: "numeric" }),
  });
};

/**
 * Create/edit form for events. Admins can tag an event to a club (shows in
 * that club + the home discover rail) or, when allowOrganization is set, leave
 * it organization-wide (Home + the Events manager). Covers the full event
 * model: agenda, category chip, eyebrow, title accent, details grid, tags,
 * notes, capacity, host and an image uploaded to Supabase Storage.
 */
export default function ClubEventFormModal({
  visible,
  club,
  editing,
  onClose,
  onSaved,
  allowOrganization,
}: Props) {
  const insets = useSafeAreaInsets();
  const [clubSlug, setClubSlug] = useState<string>(club?.slug ?? "");
  const { find } = useClubs();
  const selectedClub = find(clubSlug) ?? club ?? null;
  const orgWide = !selectedClub;
  const clubName = selectedClub?.name ?? "";
  const accent = selectedClub?.color ?? colors.forest;
  const accentDark = selectedClub?.colorDark ?? colors.forestSoft;
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [location, setLocation] = useState("");
  const [fee, setFee] = useState("");
  const [dateObj, setDateObj] = useState<Date | null>(null);
  const [timeObj, setTimeObj] = useState<Date | null>(null);
  const [dateToObj, setDateToObj] = useState<Date | null>(null);
  const [timeToObj, setTimeToObj] = useState<Date | null>(null);
  const [showDatePicker, setShowDatePicker] = useState(false);
  const [showTimePicker, setShowTimePicker] = useState(false);
  const [showDateToPicker, setShowDateToPicker] = useState(false);
  const [showTimeToPicker, setShowTimeToPicker] = useState(false);
  const [category, setCategory] = useState("");
  const [eyebrow, setEyebrow] = useState("");
  const [titleAccent, setTitleAccent] = useState("");
  const [host, setHost] = useState("");
  const [capacity, setCapacity] = useState("");
  const [agenda, setAgenda] = useState<EventAgendaItem[]>([]);
  const [agendaPicker, setAgendaPicker] = useState<{
    idx: number;
    field: "dateFrom" | "timeFrom" | "dateTo" | "timeTo";
  } | null>(null);
  const [notes, setNotes] = useState("");
  const [eventTags, setEventTags] = useState<string[]>([]);
  const [tagInput, setTagInput] = useState("");
  const [eventDetails, setEventDetails] = useState<EventDetail[]>([]);
  const [detailLabel, setDetailLabel] = useState("");
  const [detailValue, setDetailValue] = useState("");
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [imageLoading, setImageLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const isEditing = !!editing;

  const syncForm = () => {
    setClubSlug(editing?.clubSlug || club?.slug || "");
    if (editing) {
      setTitle(editing.title);
      setDescription(editing.description);
      setLocation(editing.location);
      setFee(editing.fee !== "Free" ? editing.fee : "");
      setImageUrl(editing.imageUrl);
      setDateObj(parseDateInput(editing.date));
      setTimeObj(parseTimeToDate(editing.time));
      setDateToObj(parseDateInput(editing.dateTo));
      setTimeToObj(parseTimeToDate(editing.timeTo));
      setCapacity((editing.capacity ?? 0) > 0 ? String(editing.capacity) : "");
      setHost(editing.host || "");
      setCategory(editing.category || "");
      setEyebrow(editing.eyebrow || "");
      setTitleAccent(editing.titleAccent || "");
      setAgenda(Array.isArray(editing.agenda) ? editing.agenda : []);
      setNotes(editing.notes || "");
      setEventTags(Array.isArray(editing.tags) ? editing.tags : []);
      setEventDetails(Array.isArray(editing.details) ? editing.details : []);
    } else {
      setTitle("");
      setDescription("");
      setLocation("");
      setFee("");
      setDateObj(null);
      setTimeObj(null);
      setDateToObj(null);
      setTimeToObj(null);
      setCapacity("");
      setHost("");
      setCategory("");
      setEyebrow("");
      setTitleAccent("");
      setAgenda([]);
      setNotes("");
      setEventTags([]);
      setEventDetails([]);
      setDetailLabel("");
      setDetailValue("");
      setTagInput("");
      setImageUrl(null);
    }
    setShowDatePicker(false);
    setShowTimePicker(false);
    setShowDateToPicker(false);
    setShowTimeToPicker(false);
    setAgendaPicker(null);
  };

  const clearEventDateTime = (which: "date" | "time" | "dateTo" | "timeTo") => {
    if (which === "date") {
      setDateObj(null);
      setDateToObj(null);
      setShowDatePicker(false);
    } else if (which === "time") {
      setTimeObj(null);
      setShowTimePicker(false);
    } else if (which === "dateTo") {
      setDateToObj(null);
      setShowDateToPicker(false);
    } else if (which === "timeTo") {
      setTimeToObj(null);
      setShowTimeToPicker(false);
    }
  };

  const pickImage = async () => {
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
      allowsEditing: true,
      quality: 0.8,
      base64: true,
    });
    if (!result.canceled && result.assets?.length > 0) {
      const asset = result.assets[0];
      setImageLoading(true);
      try {
        const { uploadEventImage } = await import("@/services/cloudinary");
        const url = await uploadEventImage(asset);
        setImageUrl(url);
      } catch (err) {
        Alert.alert(
          "Upload Failed",
          err instanceof Error
            ? err.message
            : "Could not upload the event image. Please try again.",
        );
      }
      setImageLoading(false);
    }
  };

  const submit = async () => {
    if (!title.trim()) {
      Alert.alert("Required", "Please enter a title.");
      return;
    }
    if (!dateObj || !timeObj) {
      Alert.alert("Required", "Please choose a date and time.");
      return;
    }
    if (dateToObj && dateObj > dateToObj) {
      Alert.alert("Check dates", "The end date can't be before the start date.");
      return;
    }
    const session = await getSession();
    if (!session) {
      Alert.alert("Login Required", "Please log in to create events.");
      return;
    }

    setSubmitting(true);
    try {
      const payload: any = {
        title: title.trim(),
        description: description.trim(),
        date: formatDate(dateObj),
        time: formatTime(timeObj),
        dateTo: dateToObj ? formatDate(dateToObj) : undefined,
        timeTo: timeToObj ? formatTime(timeToObj) : undefined,
        location,
        fee: fee.trim() || "Free",
        imageUrl,
        author: session.user.name || "Anonymous",
        clubSlug,
        capacity: capacity ? parseInt(capacity, 10) || undefined : undefined,
        host: host.trim() || undefined,
        category: category.trim().toUpperCase() || undefined,
        eyebrow: eyebrow.trim().toUpperCase() || undefined,
        titleAccent: titleAccent.trim() || undefined,
        agenda: agenda
          .filter((a) => (a.title || "").trim() || (a.time || "").trim())
          .map((a) => ({
            time: (a.time || "").trim(),
            title: (a.title || "").trim(),
            description: (a.description || "").trim(),
            dateFrom: a.dateFrom || undefined,
            dateTo: a.dateTo || undefined,
            timeFrom: a.timeFrom || undefined,
            timeTo: a.timeTo || undefined,
            location: (a.location || "").trim() || undefined,
            category: (a.category || "").trim() || undefined,
            host: (a.host || "").trim() || undefined,
          })),
        notes: notes.trim() || undefined,
        tags: eventTags.map((t) => t.trim().toUpperCase()).filter(Boolean),
        details: eventDetails
          .filter((d) => (d.label || "").trim() && (d.value || "").trim())
          .map((d) => ({
            label: (d.label || "").trim(),
            value: (d.value || "").trim(),
          })),
      };
      if (isEditing && editing) {
        payload._id = editing._id;
        await communityApi.updateEvent(payload);
      } else {
        await communityApi.createEvent(payload);
      }
      onSaved();
      onClose();
    } catch (err: any) {
      Alert.alert("Error", err?.message || "Failed. Please try again.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Modal visible={visible} animationType="slide" statusBarTranslucent onShow={syncForm} onRequestClose={onClose}>
      <View style={[s.safe, { paddingTop: insets.top }]}>
        <LinearGradient
          colors={[accent, accentDark]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={s.head}
        >
          <View style={s.headRow}>
            <View style={s.headIcon}>
              <Ionicons name="calendar-outline" size={20} color={colors.white} />
            </View>
            <View style={{ flex: 1 }}>
              <Text style={s.headEyebrow}>{orgWide ? "RELATE" : `${clubName.toUpperCase()} CLUB`}</Text>
              <Text style={s.headTitle}>
                {isEditing ? "Edit event" : orgWide ? "Create event" : "Create club event"}
              </Text>
            </View>
            <TouchableOpacity onPress={onClose} style={s.closeBtn} accessibilityLabel="Close">
              <Ionicons name="close" size={20} color={colors.white} />
            </TouchableOpacity>
          </View>
          <Text style={s.headSub}>
            {orgWide
              ? "This event is for Relate — it shows on Home and in Events, not tied to a club."
              : `This event is tagged to the ${clubName} club — it shows only in that club and in the home discover rail.`}
          </Text>
        </LinearGradient>

        <KeyboardAvoidingView
          behavior={Platform.OS === "ios" ? "padding" : "height"}
          style={{ flex: 1 }}
        >
          <ScrollView
            style={{ flex: 1 }}
            contentContainerStyle={s.form}
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator={false}
          >
            <ClubSelect
              value={clubSlug}
              onChange={setClubSlug}
              label={allowOrganization ? "Who is this event for?" : "Which club is this event for?"}
              allowOrganization={allowOrganization}
            />

            <Text style={s.label}>
              Title <Text style={s.req}>*</Text>
            </Text>
            <TextInput style={s.input} value={title} onChangeText={setTitle} placeholder="e.g. Spring Garden Day" placeholderTextColor={colors.muted} />

            <View style={s.twoColRow}>
              <View style={s.twoCol}>
                <Text style={s.label}>Category (chip)</Text>
                <TextInput
                  style={s.input}
                  value={category}
                  onChangeText={(t) => setCategory(t.toUpperCase())}
                  placeholder="e.g. HIKING"
                  placeholderTextColor={colors.muted}
                  autoCapitalize="characters"
                  maxLength={12}
                />
              </View>
              <View style={s.twoCol}>
                <Text style={s.label}>Eyebrow</Text>
                <TextInput
                  style={s.input}
                  value={eyebrow}
                  onChangeText={(t) => setEyebrow(t.toUpperCase())}
                  placeholder="e.g. WEEKEND HIKE"
                  placeholderTextColor={colors.muted}
                  autoCapitalize="characters"
                />
              </View>
            </View>

            <Text style={s.label}>Title accent</Text>
            <TextInput
              style={s.input}
              value={titleAccent}
              onChangeText={setTitleAccent}
              placeholder="Second part of the title, e.g. Ridge Hike"
              placeholderTextColor={colors.muted}
            />

            <Text style={s.label}>Description</Text>
            <TextInput
              style={[s.input, s.inputMultiline]}
              value={description}
              onChangeText={setDescription}
              placeholder="What's happening?"
              placeholderTextColor={colors.muted}
              multiline
              textAlignVertical="top"
            />

            <Text style={s.label}>
              Date <Text style={s.req}>*</Text>
            </Text>
            <TouchableOpacity style={s.pickerBtn} onPress={() => { setShowDatePicker(!showDatePicker); setShowTimePicker(false); setShowDateToPicker(false); setShowTimeToPicker(false); }}>
              <Ionicons name="calendar-outline" size={16} color={colors.goldDark} />
              <Text style={[s.pickerBtnText, !dateObj && s.pickerBtnPlaceholder]}>
                {dateObj ? fmtPickerDate(dateObj) : "Choose a date"}
              </Text>
              {dateObj ? (
                <TouchableOpacity onPress={() => clearEventDateTime("date")} hitSlop={8}>
                  <Ionicons name="close-circle" size={18} color={colors.muted} />
                </TouchableOpacity>
              ) : null}
            </TouchableOpacity>
            {showDatePicker && (
              <InlineCalendar
                value={dateObj}
                onSelect={(d) => { setDateObj(d); if (dateToObj && d > dateToObj) setDateToObj(null); setShowDatePicker(false); }}
              />
            )}

            <Text style={s.label}>
              Start time <Text style={s.req}>*</Text>
            </Text>
            <TouchableOpacity style={s.pickerBtn} onPress={() => { setShowTimePicker(!showTimePicker); setShowDatePicker(false); setShowDateToPicker(false); setShowTimeToPicker(false); }}>
              <Ionicons name="time-outline" size={16} color={colors.goldDark} />
              <Text style={[s.pickerBtnText, !timeObj && s.pickerBtnPlaceholder]}>
                {timeObj ? formatTime(timeObj) : "Choose a time"}
              </Text>
              {timeObj ? (
                <TouchableOpacity onPress={() => clearEventDateTime("time")} hitSlop={8}>
                  <Ionicons name="close-circle" size={18} color={colors.muted} />
                </TouchableOpacity>
              ) : null}
            </TouchableOpacity>
            {showTimePicker && (
              <InlineTimePicker
                value={timeObj}
                onSelect={(d) => { setTimeObj(d); setShowTimePicker(false); }}
              />
            )}

            <View style={s.twoColRow}>
              <View style={s.twoCol}>
                <Text style={s.label}>Ends date (multi-day)</Text>
                <TouchableOpacity style={s.pickerBtn} onPress={() => { setShowDateToPicker(!showDateToPicker); setShowDatePicker(false); setShowTimePicker(false); setShowTimeToPicker(false); }}>
                  <Ionicons name="calendar-outline" size={16} color={colors.goldDark} />
                  <Text style={[s.pickerBtnText, !dateToObj && s.pickerBtnPlaceholder]}>
                    {dateToObj ? fmtPickerDate(dateToObj) : "Optional"}
                  </Text>
                  {dateToObj ? (
                    <TouchableOpacity onPress={() => clearEventDateTime("dateTo")} hitSlop={8}>
                      <Ionicons name="close-circle" size={18} color={colors.muted} />
                    </TouchableOpacity>
                  ) : null}
                </TouchableOpacity>
                {showDateToPicker && (
                  <InlineCalendar
                    value={dateToObj}
                    minimumDate={dateObj ?? undefined}
                    onSelect={(d) => { setDateToObj(d); setShowDateToPicker(false); }}
                  />
                )}
              </View>
              <View style={s.twoCol}>
                <Text style={s.label}>Ends time</Text>
                <TouchableOpacity style={s.pickerBtn} onPress={() => { setShowTimeToPicker(!showTimeToPicker); setShowDatePicker(false); setShowTimePicker(false); setShowDateToPicker(false); }}>
                  <Ionicons name="time-outline" size={16} color={colors.goldDark} />
                  <Text style={[s.pickerBtnText, !timeToObj && s.pickerBtnPlaceholder]}>
                    {timeToObj ? formatTime(timeToObj) : "Optional"}
                  </Text>
                  {timeToObj ? (
                    <TouchableOpacity onPress={() => clearEventDateTime("timeTo")} hitSlop={8}>
                      <Ionicons name="close-circle" size={18} color={colors.muted} />
                    </TouchableOpacity>
                  ) : null}
                </TouchableOpacity>
                {showTimeToPicker && (
                  <InlineTimePicker
                    value={timeToObj}
                    onSelect={(d) => { setTimeToObj(d); setShowTimeToPicker(false); }}
                  />
                )}
              </View>
            </View>

            <Text style={s.label}>Location</Text>
            <TextInput style={s.input} value={location} onChangeText={setLocation} placeholder="e.g. Community hall" placeholderTextColor={colors.muted} />

            <Text style={s.label}>Fee</Text>
            <TextInput style={s.input} value={fee} onChangeText={setFee} placeholder='Free, or e.g. "R50 per person"' placeholderTextColor={colors.muted} />

            <View style={s.twoColRow}>
              <View style={s.twoCol}>
                <Text style={s.label}>Host / guide</Text>
                <TextInput style={s.input} value={host} onChangeText={setHost} placeholder="Who leads the event?" placeholderTextColor={colors.muted} />
              </View>
              <View style={s.twoCol}>
                <Text style={s.label}>Seats available</Text>
                <TextInput
                  style={s.input}
                  value={capacity}
                  onChangeText={(t) => setCapacity(t.replace(/[^0-9]/g, ""))}
                  placeholder="e.g. 40"
                  placeholderTextColor={colors.muted}
                  keyboardType="numeric"
                  maxLength={5}
                />
              </View>
            </View>

            <Text style={s.label}>Quick details</Text>
            <Text style={s.optLabel}>
              Small facts shown under the title — distance, level, duration, etc.
            </Text>
            {eventDetails.map((d, idx) => (
              <View key={`${d.label}-${idx}`} style={s.detailRow}>
                <Text style={s.detailLabelText} numberOfLines={1}>{d.label.toUpperCase()}</Text>
                <Text style={s.detailValueText} numberOfLines={1}>{d.value}</Text>
                <TouchableOpacity
                  style={s.agendaRemoveBtn}
                  onPress={() => setEventDetails((prev) => prev.filter((_, i) => i !== idx))}
                  hitSlop={{ top: 6, bottom: 6, left: 6, right: 6 }}
                >
                  <Ionicons name="trash-outline" size={16} color="#dc2626" />
                </TouchableOpacity>
              </View>
            ))}
            <View style={s.detailAddRow}>
              <TextInput
                style={[s.input, s.detailLabelInput]}
                value={detailLabel}
                onChangeText={(t) => setDetailLabel(t.toUpperCase())}
                placeholder="Label (e.g. LEVEL)"
                placeholderTextColor={colors.muted}
                autoCapitalize="characters"
              />
              <TextInput
                style={[s.input, s.detailValueInput]}
                value={detailValue}
                onChangeText={setDetailValue}
                placeholder="Value"
                placeholderTextColor={colors.muted}
              />
            </View>
            <TouchableOpacity
              style={s.agendaAddBtn}
              onPress={() => {
                const label = detailLabel.trim();
                const value = detailValue.trim();
                if (!label || !value) return;
                setEventDetails((prev) => [...prev, { label, value }]);
                setDetailLabel("");
                setDetailValue("");
              }}
              activeOpacity={0.8}
            >
              <Ionicons name="add" size={16} color={colors.gold} />
              <Text style={s.agendaAddText}>Add detail</Text>
            </TouchableOpacity>

            <Text style={s.label}>Tags</Text>
            <Text style={s.optLabel}>Press Add to attach a chip, e.g. BONFIRE, PHOTO.</Text>
            <View style={s.detailAddRow}>
              <TextInput
                style={[s.input, s.detailValueInput]}
                value={tagInput}
                onChangeText={(t) => setTagInput(t.toUpperCase())}
                placeholder="e.g. TRAIL"
                placeholderTextColor={colors.muted}
                autoCapitalize="characters"
                onSubmitEditing={() => {
                  const tag = tagInput.trim();
                  if (!tag) return;
                  setEventTags((prev) => (prev.includes(tag) ? prev : [...prev, tag]));
                  setTagInput("");
                }}
              />
              <TouchableOpacity
                style={s.tagAddBtn}
                onPress={() => {
                  const tag = tagInput.trim();
                  if (!tag) return;
                  setEventTags((prev) => (prev.includes(tag) ? prev : [...prev, tag]));
                  setTagInput("");
                }}
                activeOpacity={0.8}
              >
                <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                <Text style={s.tagAddText}>Add</Text>
              </TouchableOpacity>
            </View>
            {eventTags.length > 0 && (
              <View style={s.eventTagWrap}>
                {eventTags.map((tag) => (
                  <View key={tag} style={s.eventTagChip}>
                    <Text style={s.eventTagChipText}>{tag}</Text>
                    <TouchableOpacity
                      onPress={() => setEventTags((prev) => prev.filter((t) => t !== tag))}
                      hitSlop={{ top: 6, bottom: 6, left: 6, right: 6 }}
                    >
                      <Ionicons name="close" size={12} color={colors.forestDark} />
                    </TouchableOpacity>
                  </View>
                ))}
              </View>
            )}

            <Text style={s.label}>Itinerary &amp; Activities</Text>
            <Text style={s.optLabel}>Add the program so people can plan around it.</Text>
            {agenda.map((entry, idx) => (
              <View key={idx} style={s.agendaCard}>
                <View style={s.agendaHeadRow}>
                  <Text style={s.agendaIndex}>{String(idx + 1).padStart(2, "0")}</Text>
                  <TouchableOpacity
                    style={s.agendaRemoveBtn}
                    onPress={() => setAgenda((prev) => prev.filter((_, i) => i !== idx))}
                    hitSlop={{ top: 6, bottom: 6, left: 6, right: 6 }}
                  >
                    <Ionicons name="trash-outline" size={16} color="#dc2626" />
                  </TouchableOpacity>
                </View>
                <View style={s.agendaRow}>
                  <TextInput
                    style={[s.input, s.agendaTimeInput]}
                    placeholder="Time"
                    placeholderTextColor={colors.muted}
                    value={entry.time}
                    onChangeText={(t) => setAgenda((prev) => prev.map((a, i) => (i === idx ? { ...a, time: t } : a)))}
                  />
                  <TextInput
                    style={[s.input, s.agendaActivityInput]}
                    placeholder="Activity"
                    placeholderTextColor={colors.muted}
                    value={entry.title}
                    multiline
                    onChangeText={(t) => setAgenda((prev) => prev.map((a, i) => (i === idx ? { ...a, title: t } : a)))}
                  />
                </View>
                <TextInput
                  style={[s.input, s.inputMultiline]}
                  placeholder="Details (optional)"
                  placeholderTextColor={colors.muted}
                  value={entry.description || ""}
                  multiline
                  onChangeText={(t) => setAgenda((prev) => prev.map((a, i) => (i === idx ? { ...a, description: t } : a)))}
                />
                <View style={s.agendaRow}>
                  <TextInput
                    style={[s.input, s.agendaTypeInput]}
                    placeholder="Type (Worship, Workshop…)"
                    placeholderTextColor={colors.muted}
                    value={entry.category || ""}
                    onChangeText={(t) => setAgenda((prev) => prev.map((a, i) => (i === idx ? { ...a, category: t } : a)))}
                  />
                  <TextInput
                    style={[s.input, s.agendaVenueInput]}
                    placeholder="Venue / room"
                    placeholderTextColor={colors.muted}
                    value={entry.location || ""}
                    onChangeText={(t) => setAgenda((prev) => prev.map((a, i) => (i === idx ? { ...a, location: t } : a)))}
                  />
                </View>
                <TextInput
                  style={s.input}
                  placeholder="Speaker / host (optional)"
                  placeholderTextColor={colors.muted}
                  value={entry.host || ""}
                  onChangeText={(t) => setAgenda((prev) => prev.map((a, i) => (i === idx ? { ...a, host: t } : a)))}
                />
                <Text style={s.agendaRangeLabel}>Optional date / time window</Text>
                <View style={s.agendaRangeRow}>
                  <TouchableOpacity
                    style={[s.pickerBtn, s.agendaRangePicker]}
                    onPress={() =>
                      setAgendaPicker((prev) =>
                        prev && prev.idx === idx && prev.field === "dateFrom"
                          ? null
                          : { idx, field: "dateFrom" },
                      )
                    }
                    activeOpacity={0.8}
                  >
                    <Ionicons name="calendar-outline" size={14} color={colors.muted} />
                    <Text style={entry.dateFrom ? s.pickerBtnText : s.pickerBtnPlaceholder} numberOfLines={1}>
                      {entry.dateFrom || "From date"}
                    </Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={[s.pickerBtn, s.agendaRangePicker]}
                    onPress={() =>
                      setAgendaPicker((prev) =>
                        prev && prev.idx === idx && prev.field === "timeFrom"
                          ? null
                          : { idx, field: "timeFrom" },
                      )
                    }
                    activeOpacity={0.8}
                  >
                    <Ionicons name="time-outline" size={14} color={colors.muted} />
                    <Text style={entry.timeFrom ? s.pickerBtnText : s.pickerBtnPlaceholder} numberOfLines={1}>
                      {entry.timeFrom || "Time"}
                    </Text>
                  </TouchableOpacity>
                </View>
                <View style={s.agendaRangeRow}>
                  <TouchableOpacity
                    style={[s.pickerBtn, s.agendaRangePicker]}
                    onPress={() =>
                      setAgendaPicker((prev) =>
                        prev && prev.idx === idx && prev.field === "dateTo"
                          ? null
                          : { idx, field: "dateTo" },
                      )
                    }
                    activeOpacity={0.8}
                  >
                    <Ionicons name="calendar-outline" size={14} color={colors.muted} />
                    <Text style={entry.dateTo ? s.pickerBtnText : s.pickerBtnPlaceholder} numberOfLines={1}>
                      {entry.dateTo || "To date"}
                    </Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={[s.pickerBtn, s.agendaRangePicker]}
                    onPress={() =>
                      setAgendaPicker((prev) =>
                        prev && prev.idx === idx && prev.field === "timeTo"
                          ? null
                          : { idx, field: "timeTo" },
                      )
                    }
                    activeOpacity={0.8}
                  >
                    <Ionicons name="time-outline" size={14} color={colors.muted} />
                    <Text style={entry.timeTo ? s.pickerBtnText : s.pickerBtnPlaceholder} numberOfLines={1}>
                      {entry.timeTo || "To time"}
                    </Text>
                  </TouchableOpacity>
                </View>
                {agendaPicker && agendaPicker.idx === idx ? (
                  agendaPicker.field.startsWith("time") ? (
                    <View style={s.agendaPanel}>
                      <InlineTimePicker
                        value={parseTimeToDate(entry[agendaPicker.field])}
                        onSelect={(d) => {
                          const val = formatTime(d);
                          setAgenda((prev) =>
                            prev.map((a, i) => (i === idx ? { ...a, [agendaPicker.field]: val } : a)),
                          );
                          setAgendaPicker(null);
                        }}
                      />
                    </View>
                  ) : (
                    <View style={s.agendaPanel}>
                      <InlineCalendar
                        value={parseDateInput(entry[agendaPicker.field])}
                        minimumDate={
                          agendaPicker.field === "dateTo"
                            ? (parseDateInput(entry.dateFrom) ?? undefined)
                            : undefined
                        }
                        onSelect={(d) => {
                          const val = formatDate(d);
                          setAgenda((prev) =>
                            prev.map((a, i) => (i === idx ? { ...a, [agendaPicker.field]: val } : a)),
                          );
                          setAgendaPicker(null);
                        }}
                      />
                    </View>
                  )
                ) : null}
              </View>
            ))}
            <TouchableOpacity
              style={s.agendaAddBtn}
              onPress={() => setAgenda((prev) => [...prev, { time: "", title: "", description: "" }])}
              activeOpacity={0.8}
            >
              <Ionicons name="add" size={16} color={colors.gold} />
              <Text style={s.agendaAddText}>Add activity</Text>
            </TouchableOpacity>

            <Text style={s.label}>Additional notes</Text>
            <TextInput
              style={[s.input, s.inputMultiline]}
              placeholder="What to bring, parking, dress code, etc."
              placeholderTextColor={colors.muted}
              value={notes}
              onChangeText={setNotes}
              multiline
              numberOfLines={3}
              textAlignVertical="top"
            />

            <Text style={s.label}>Event image</Text>
            {imageUrl ? (
              <View style={s.imagePreviewWrap}>
                <View style={s.imagePreview}>
                  <Image source={{ uri: getOptimizedImageUrl(imageUrl, 720) }} style={s.imagePreviewImg} contentFit="cover" transition={250} />
                  <TouchableOpacity style={s.imagePreviewBtn} onPress={pickImage} activeOpacity={0.85}>
                    <Text style={s.imagePreviewBtnText}>Tap to change image</Text>
                  </TouchableOpacity>
                </View>
                <TouchableOpacity style={s.imageRemove} onPress={() => setImageUrl(null)} accessibilityLabel="Remove image">
                  <Ionicons name="trash-outline" size={16} color={colors.error} />
                </TouchableOpacity>
              </View>
            ) : (
              <TouchableOpacity style={s.imageAdd} onPress={imageLoading ? undefined : pickImage} activeOpacity={0.8} disabled={imageLoading}>
                {imageLoading ? (
                  <ActivityIndicator size="small" color={colors.goldDark} />
                ) : (
                  <>
                    <Ionicons name="image-outline" size={22} color={colors.goldDark} />
                    <Text style={s.imageAddText}>Add an image (stored in Supabase)</Text>
                  </>
                )}
              </TouchableOpacity>
            )}

            <TouchableOpacity
              style={[s.submitBtn, { backgroundColor: accentDark }]}
              activeOpacity={0.9}
              onPress={submit}
              disabled={submitting}
            >
              {submitting ? (
                <ActivityIndicator size="small" color={colors.white} />
              ) : (
                <>
                  <Ionicons name="checkmark-circle-outline" size={18} color={colors.white} />
                  <Text style={s.submitText}>{isEditing ? "Save changes" : "Create event"}</Text>
                </>
              )}
            </TouchableOpacity>
          </ScrollView>
        </KeyboardAvoidingView>
      </View>
    </Modal>
  );
}

