import { Ionicons } from "@expo/vector-icons";
import { useEffect, useState } from "react";
import {
  Linking,
  Modal,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import {
  fetchAppVersion,
  installedVersion,
  isNewerVersion,
  type AppVersionInfo,
} from "@/services/app-version";

/**
 * Launch-time APK update prompt, mounted once in the root layout. Fetches
 * GET /api/app-version, compares the published version against this install
 * and shows the download sheet when a newer build exists. With `forceUpdate`
 * the sheet can't be dismissed until the download starts.
 */
export default function AppUpdateChecker() {
  const insets = useSafeAreaInsets();
  const [update, setUpdate] = useState<AppVersionInfo | null>(null);
  const [current, setCurrent] = useState<string | null>(null);

  useEffect(() => {
    let active = true;
    (async () => {
      const info = await fetchAppVersion();
      if (!active || !info) return;
      const version = installedVersion();
      if (version && isNewerVersion(info.latestVersion, version)) {
        setCurrent(version);
        setUpdate(info);
      }
    })();
    return () => {
      active = false;
    };
  }, []);

  const close = () => setUpdate(null);
  const download = async () => {
    if (!update) return;
    try {
      await Linking.openURL(update.apkUrl);
    } catch {}
    close();
  };

  const force = update?.forceUpdate === true;
  const dismissible = !!update && !force;
  const notes = update
    ? update.releaseNotes.split("\n").filter((line) => line.trim())
    : [];

  return (
    <Modal
      visible={!!update}
      transparent
      animationType="slide"
      onRequestClose={() => {
        if (dismissible) close();
      }}
    >
      <TouchableOpacity
        style={u.backdrop}
        activeOpacity={1}
        onPress={dismissible ? close : undefined}
        accessibilityLabel="Close"
      >
        <TouchableOpacity style={[u.card, { paddingBottom: 12 + insets.bottom }]}>
          <View style={u.head}>
            <View style={u.headIcon}>
              <Ionicons
                name="cloud-download-outline"
                size={24}
                color={colors.forest}
              />
            </View>
            <View style={{ flex: 1 }}>
              <Text style={u.title}>A new version is here</Text>
              <Text style={u.sub}>
                {current ? `You're on ${current} — ` : ""}
                Relate {update?.latestVersion} is ready to install.
              </Text>
            </View>
            {dismissible ? (
              <TouchableOpacity
                onPress={close}
                style={u.close}
                accessibilityRole="button"
                accessibilityLabel="Close"
              >
                <Ionicons name="close" size={18} color={colors.muted} />
              </TouchableOpacity>
            ) : null}
          </View>

          {notes.length > 0 ? (
            <View style={u.notes}>
              <Text style={u.notesLabel}>What&apos;s new</Text>
              {notes.map((line) => (
                <Text key={line} style={u.noteLine}>
                  {line}
                </Text>
              ))}
            </View>
          ) : null}

          <TouchableOpacity
            style={u.primary}
            activeOpacity={0.9}
            onPress={() => void download()}
            accessibilityRole="button"
            accessibilityLabel={`Download version ${update?.latestVersion ?? ""}`}
          >
            <Text style={u.primaryText}>Download update</Text>
            <Ionicons name="arrow-forward" size={15} color={colors.forestDark} />
          </TouchableOpacity>
          {dismissible ? (
            <TouchableOpacity onPress={close} style={u.later}>
              <Text style={u.laterText}>Later</Text>
            </TouchableOpacity>
          ) : null}
        </TouchableOpacity>
      </TouchableOpacity>
    </Modal>
  );
}

const u = StyleSheet.create({
  backdrop: {
    flex: 1,
    backgroundColor: "rgba(9,23,15,0.55)",
    justifyContent: "flex-end",
  },
  card: {
    backgroundColor: colors.white,
    borderTopLeftRadius: 24,
    borderTopRightRadius: 24,
    padding: 20,
    paddingBottom: 12,
  },
  head: {
    flexDirection: "row",
    alignItems: "flex-start",
    gap: 12,
    marginBottom: 14,
  },
  headIcon: {
    width: 46,
    height: 46,
    borderRadius: 23,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: `${colors.gold}1A`,
  },
  title: {
    fontFamily: fonts.sansBold,
    fontSize: 17,
    color: colors.forest,
  },
  sub: {
    fontFamily: fonts.sans,
    fontSize: 12.5,
    lineHeight: 18,
    color: colors.muted,
    marginTop: 3,
  },
  close: {
    width: 30,
    height: 30,
    borderRadius: 15,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: "rgba(29,42,77,0.06)",
  },
  notes: {
    backgroundColor: colors.bg,
    borderRadius: 16,
    padding: 14,
    gap: 6,
    marginBottom: 14,
  },
  notesLabel: {
    fontFamily: fonts.sansBold,
    fontWeight: "700",
    fontSize: 10,
    letterSpacing: 1.4,
    textTransform: "uppercase",
    color: colors.goldDark,
    marginBottom: 2,
  },
  noteLine: {
    fontFamily: fonts.sans,
    fontSize: 13,
    lineHeight: 19,
    color: colors.ink,
  },
  primary: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    gap: 8,
    backgroundColor: colors.gold,
    borderRadius: 999,
    paddingVertical: 14,
  },
  primaryText: {
    fontFamily: fonts.sansBold,
    fontWeight: "700",
    fontSize: 14.5,
    color: colors.forestDark,
  },
  later: {
    alignItems: "center",
    paddingVertical: 10,
    marginTop: 2,
    marginBottom: 8,
  },
  laterText: {
    fontFamily: fonts.sansSemiBold,
    fontWeight: "600",
    fontSize: 13,
    color: colors.muted,
  },
});
