import { SkeletonPulse } from "@/components/Skeleton";
import { colors } from "@/constants/colors";
import type { Publication } from "@/data/publications/types";
import {
  getSelectedClubSlug,
  setSelectedClubSlug,
} from "@/services/club-preference";
import { fetchClubs, useClubs, type Club } from "@/services/clubs";
import { fetchPublications } from "@/services/publications";
import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { useRouter } from "expo-router";
import { StatusBar } from "expo-status-bar";
import { useEffect, useState } from "react";
import {
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

function PublicationCard({
  item,
  club,
  onPress,
}: {
  item: Publication;
  club?: Club;
  onPress: () => void;
}) {
  const isMagazine = item.kind === "magazine";
  const accent = club?.color || colors.gold;
  const accentDark = club?.colorDark || colors.goldDark;

  // Magazine cards read as "<Series> <Year>" + theme; the club is already
  // obvious from the tab chip, so we drop the club name from the card.
  const series = item.series;
  const heading = isMagazine && series ? `${series} ${item.year}` : item.title;
  const themeLine =
    isMagazine && series
      ? item.theme ||
        item.coverLines?.[0] ||
        item.title.replace(`${series} — `, "")
      : "";
  const issueLine = item.season
    ? `${item.season.label} · ${item.issue}`
    : `${item.month} ${item.year} · ${item.issue}`;

  return (
    <TouchableOpacity
      activeOpacity={0.85}
      onPress={onPress}
      style={styles.card}
      accessibilityLabel={`Open ${item.title}`}
    >
      {
        <LinearGradient
          colors={[accent, accentDark]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={styles.cardCover}
        >
          <Ionicons
            name={(club?.icon as any) || "leaf"}
            size={24}
            color={colors.white}
          />
        </LinearGradient>
      }

      <View style={styles.cardBody}>
        <View style={styles.metaRow}>
          <Text style={[styles.typeBadge, { color: colors.muted }]}>
            {isMagazine ? (series || "MAGAZINE").toUpperCase() : "BULLETIN"}
          </Text>
        </View>
        <Text
          style={[styles.cardTitle, { color: accentDark }]}
          numberOfLines={1}
        >
          {themeLine || heading}
        </Text>

        <Text style={styles.cardIssue}>{issueLine}</Text>
      </View>

      <Ionicons name="chevron-forward" size={18} color={colors.muted} />
    </TouchableOpacity>
  );
}

function openPublication(
  router: ReturnType<typeof useRouter>,
  pub: Publication,
) {
  router.push({
    pathname: "/library/[slug]",
    params: { slug: pub.id },
  });
}

function PublicationCardSkeleton() {
  return (
    <View style={styles.card}>
      <SkeletonPulse style={styles.cardCover} />
      <View style={styles.cardBody}>
        <SkeletonPulse style={styles.skelBadge} />
        <SkeletonPulse style={styles.skelTitle} />
        <SkeletonPulse style={styles.skelTheme} />
        <SkeletonPulse style={styles.skelIssue} />
        <SkeletonPulse style={styles.skelBlurb} />
        <SkeletonPulse style={styles.skelBlurbShort} />
      </View>
      <SkeletonPulse style={styles.skelChevron} />
    </View>
  );
}

export default function LibraryScreen() {
  const router = useRouter();
  const [clubSlug, setClubSlug] = useState<string>("relate");
  const [allPublications, setAllPublications] = useState<Publication[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(false);
  const { allClubs, find, loading: clubsLoading, error: clubsError } = useClubs();
  const contentClubs = allClubs.filter((c) => c.slug !== "sprout");

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const [pubs, chosenClub, catalog] = await Promise.all([
          fetchPublications(),
          getSelectedClubSlug(),
          fetchClubs(),
        ]);
        if (!alive) return;
        setAllPublications(pubs);
        // The saved club is both the default filter and "my club"; the chips
        // below keep the two in sync via setSelectedClubSlug.
        // "sprout" is an umbrella and has no content — fall back to Relate.
        const contentSlugs = new Set(
          [...catalog.clubs, ...catalog.subClubs].map((c) => c.slug),
        );
        const saved =
          chosenClub && chosenClub !== "sprout" && contentSlugs.has(chosenClub)
            ? chosenClub
            : "relate";
        setClubSlug(saved);
      } catch {
        if (!alive) return;
        setLoadError(true);
      } finally {
        if (alive) setLoading(false);
      }
    })();
    return () => {
      alive = false;
    };
  }, []);

  const isRelate = clubSlug === "relate";

  // Magazines belong to a club via their club tag ("PRIME", "SPROUT-KIDS"…)
  // or — as a fallback for docs published before the tag was guaranteed —
  // their clubSlug field.
  const magazines = allPublications.filter(
    (p) =>
      p.kind === "magazine" &&
      (isRelate
        ? (p.tags || []).includes("RELATE")
        : (p.tags || []).includes(clubSlug.toUpperCase()) ||
          p.clubSlug === clubSlug),
  );

  const bulletins = isRelate
    ? allPublications.filter((p) => p.kind === "bulletin" && !p.clubSlug)
    : allPublications.filter(
        (p) => p.kind === "bulletin" && p.clubSlug === clubSlug,
      );

  return (
    <SafeAreaView style={styles.root} edges={["top", "bottom"]}>
      <StatusBar style="dark" />

      <ScrollView
        contentContainerStyle={styles.content}
        showsVerticalScrollIndicator={false}
      >
        <View style={styles.header}>
          <Text style={styles.eyebrow}>Reading Room</Text>
          <Text style={styles.title}>Library</Text>
          <Text style={styles.subtitle}>
            Bulletins and magazines written by Relate, for Relate and each club
          </Text>
        </View>

        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.chipsRow}
        >
          {clubsLoading ? (
            [0, 1, 2, 3].map((i) => (
              <SkeletonPulse key={i} style={styles.chipSkeleton} />
            ))
          ) : (
            <>
              <TouchableOpacity
                style={[
                  styles.chip,
                  isRelate && { backgroundColor: colors.goldDark },
                ]}
                activeOpacity={0.8}
                onPress={() => {
                  setClubSlug("relate");
                  setSelectedClubSlug("relate");
                }}
              >
                <Text style={[styles.chipText, isRelate && styles.chipTextActive]}>
                  Relate
                </Text>
              </TouchableOpacity>
              {contentClubs.map((club) => {
                const active = clubSlug === club.slug;
                return (
                  <TouchableOpacity
                    key={club.slug}
                    style={[styles.chip, active && { backgroundColor: club.color }]}
                    activeOpacity={0.8}
                    onPress={() => {
                      setClubSlug(club.slug);
                      setSelectedClubSlug(club.slug);
                    }}
                  >
                    <Text
                      style={[styles.chipText, active && styles.chipTextActive]}
                    >
                      {club.name}
                    </Text>
                  </TouchableOpacity>
                );
              })}
            </>
          )}
        </ScrollView>

        {loading || clubsLoading ? (
          <>
            <Text style={styles.sectionTitle}>Magazines</Text>
            <View style={styles.list}>
              {[0, 1, 2].map((i) => (
                <PublicationCardSkeleton key={i} />
              ))}
            </View>
            <Text style={styles.sectionTitle}>Club Bulletins</Text>
            <View style={styles.list}>
              {[0, 1].map((i) => (
                <PublicationCardSkeleton key={i} />
              ))}
            </View>
          </>
        ) : loadError || clubsError ? (
          <Text style={styles.errorText}>
            Couldn&apos;t load the library. Check your connection and try again.
          </Text>
        ) : (
          <>
            <Text style={styles.sectionTitle}>Magazines</Text>
            {magazines.length === 0 ? (
              <Text style={styles.emptyText}>
                No magazines for {isRelate ? "Relate" : clubSlug} yet — check
                back soon.
              </Text>
            ) : (
              <View style={styles.list}>
                {magazines.map((item) => (
                  <PublicationCard
                    key={item.id}
                    item={item}
                    club={find(item.clubSlug)}
                    onPress={() => openPublication(router, item)}
                  />
                ))}
              </View>
            )}

            <Text style={styles.sectionTitle}>Club Bulletins</Text>
            {bulletins.length === 0 ? (
              <Text style={styles.emptyText}>
                No bulletins for {isRelate ? "Relate" : "this club"} yet — check
                back soon.
              </Text>
            ) : (
              <View style={styles.list}>
                {bulletins.map((item) => (
                  <PublicationCard
                    key={item.id}
                    item={item}
                    club={find(item.clubSlug)}
                    onPress={() => openPublication(router, item)}
                  />
                ))}
              </View>
            )}
          </>
        )}
      </ScrollView>
    </SafeAreaView>
  );
}

