import { Ionicons } from "@expo/vector-icons";
import { router, useFocusEffect } from "expo-router";
import { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useSQLiteContext } from "expo-sqlite";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import {
  getTodayKey,
  loadPrayerFocus,
  loadStreakData,
  type DayRecord,
  type PrayerKey,
  type PrayerRequestEntry,
  type StreakData,
} from "@/utils/streaks";

const WEEKDAYS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];
const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

const PRAYERS: {
  key: PrayerKey;
  label: string;
  caption: string;
  icon: keyof typeof Ionicons.glyphMap;
}[] = [
  { key: "dawn", label: "Dawn", caption: "Begin with gratitude", icon: "moon-outline" },
  { key: "sunrise", label: "Sunrise", caption: "Begin with gratitude", icon: "sunny-outline" },
  { key: "noon", label: "Noon", caption: "Pause for guidance", icon: "sunny" },
  { key: "afternoon", label: "Afternoon", caption: "Pause for guidance", icon: "partly-sunny-outline" },
  { key: "sunset", label: "Sunset", caption: "Give thanks for the day", icon: "cloudy-night-outline" },
  { key: "evening", label: "Evening", caption: "Rest in God's peace", icon: "moon" },
];

function toISO(date: Date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

function longDate(iso: string) {
  const [year, month, day] = iso.split("-").map(Number);
  return new Date(year, month - 1, day).toLocaleDateString("en-GB", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  });
}

function prayedCount(day?: DayRecord) {
  if (!day) return 0;
  return PRAYERS.filter((p) => day[p.key] === true).length;
}

/**
 * Prayer history — the same month grid the Calendar uses, with days the user
 * prayed tinted light blue. Tapping a day lists its prayers below. Read-only:
 * history can only be restored by an admin.
 */
export default function PrayerHistoryScreen() {
  const db = useSQLiteContext();
  const insets = useSafeAreaInsets();
  const todayKey = getTodayKey();
  const now = new Date();

  const [data, setData] = useState<StreakData>({});
  const [loading, setLoading] = useState(true);
  const [year, setYear] = useState(now.getFullYear());
  const [month, setMonth] = useState(now.getMonth());
  const [selected, setSelected] = useState(todayKey);
  const [focusByKey, setFocusByKey] = useState<Record<string, PrayerRequestEntry>>({});

  // Each prayer session can carry a focus ("what I want to pray for"); the
  // latest one is previewed on the row and opens the editor on tap.
  useFocusEffect(
    useCallback(() => {
      let alive = true;
      (async () => {
        const all = await loadPrayerFocus(db);
        if (!alive) return;
        const map: Record<string, PrayerRequestEntry> = {};
        for (const key of Object.keys(all)) {
          const sep = key.indexOf("_");
          if (sep < 0) continue;
          if (key.slice(0, sep) !== selected) continue;
          const list = all[key];
          if (list.length) map[key.slice(sep + 1)] = list[list.length - 1];
        }
        setFocusByKey(map);
      })();
      return () => {
        alive = false;
      };
    }, [db, selected]),
  );

  const openFocus = (prayer: (typeof PRAYERS)[number]) => {
    router.push({
      pathname: "/prayer-request",
      params: {
        title: prayer.label,
        icon: prayer.icon,
        prayerKey: prayer.key,
        dateKey: selected,
      },
    } as any);
  };

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const streaks = await loadStreakData();
        if (alive) setData(streaks || {});
      } finally {
        if (alive) setLoading(false);
      }
    })();
    return () => {
      alive = false;
    };
  }, []);

  const shiftMonth = (delta: number) => {
    const next = new Date(year, month + delta, 1);
    setYear(next.getFullYear());
    setMonth(next.getMonth());
  };

  const jumpToday = () => {
    setYear(now.getFullYear());
    setMonth(now.getMonth());
    setSelected(todayKey);
  };

  const selectDay = (iso: string) => {
    setSelected(iso);
  };

  const offset = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells: (number | null)[] = [];
  for (let i = 0; i < 42; i++) {
    const day = i - offset + 1;
    cells.push(day >= 1 && day <= daysInMonth ? day : null);
  }

  const monthPrayed = Object.keys(data).filter((iso) => {
    const [y, m] = iso.split("-").map(Number);
    return y === year && m === month + 1 && prayedCount(data[iso]) > 0;
  }).length;

  const dayRecord = data[selected];
  const selectedCount = prayedCount(dayRecord);

  return (
    <View style={[s.safe, { paddingTop: insets.top }]}>
      <View style={s.header}>
        <TouchableOpacity
          style={s.backBtn}
          onPress={() => router.back()}
          accessibilityLabel="Back"
        >
          <Ionicons name="chevron-back" size={22} color={colors.forest} />
        </TouchableOpacity>
        <View style={{ flex: 1 }}>
          <Text style={s.headerTitle}>Prayer History</Text>
          <Text style={s.headerSub}>Your prayers, day by day</Text>
        </View>
      </View>

      <ScrollView
        style={{ flex: 1 }}
        contentContainerStyle={[s.body, { paddingBottom: insets.bottom + 32 }]}
        showsVerticalScrollIndicator={false}
      >
        <View style={s.card}>
          <View style={s.monthHead}>
            <TouchableOpacity
              style={s.stepBtn}
              onPress={() => shiftMonth(-1)}
              accessibilityLabel="Previous month"
            >
              <Ionicons name="chevron-back" size={16} color={colors.forestDark} />
            </TouchableOpacity>
            <View style={{ flex: 1, alignItems: "center" }}>
              <Text style={s.monthTitle}>
                {MONTHS[month]} {year}
              </Text>
              <Text style={s.monthCount}>
                {monthPrayed === 0
                  ? "No prayers marked"
                  : `${monthPrayed} day${monthPrayed === 1 ? "" : "s"} prayed`}
              </Text>
            </View>
            <TouchableOpacity
              style={s.todayBtn}
              onPress={jumpToday}
              accessibilityLabel="Jump to today"
            >
              <Text style={s.todayText}>Today</Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={s.stepBtn}
              onPress={() => shiftMonth(1)}
              accessibilityLabel="Next month"
            >
              <Ionicons name="chevron-forward" size={16} color={colors.forestDark} />
            </TouchableOpacity>
          </View>

          <View style={s.weekRow}>
            {WEEKDAYS.map((w) => (
              <Text key={w} style={s.weekLabel}>
                {w}
              </Text>
            ))}
          </View>

          {loading ? (
            <View style={s.loading}>
              <ActivityIndicator size="small" color="#13c5dd" />
            </View>
          ) : (
            <View style={s.grid}>
              {cells.map((day, i) => {
                if (day === null) return <View key={i} style={s.cell} />;
                const iso = toISO(new Date(year, month, day));
                const prayed = prayedCount(data[iso]) > 0;
                const isSelected = iso === selected;
                const isToday = iso === todayKey;
                return (
                  <View key={i} style={s.cell}>
                    <TouchableOpacity
                      style={[
                        s.day,
                        prayed && !isSelected && s.dayPrayed,
                        isToday && !isSelected && s.dayToday,
                        isSelected && s.daySelected,
                      ]}
                      onPress={() => selectDay(iso)}
                      activeOpacity={0.7}
                      accessibilityLabel={`${longDate(iso)}${prayed ? ", prayed" : ", no prayers marked"}`}
                      accessibilityState={{ selected: isSelected }}
                    >
                      <Text
                        style={[
                          s.dayText,
                          prayed && !isSelected && s.dayTextPrayed,
                          isSelected && s.dayTextActive,
                        ]}
                      >
                        {day}
                      </Text>
                    </TouchableOpacity>
                  </View>
                );
              })}
            </View>
          )}
        </View>

        <View style={s.daySection}>
          <View style={s.dayHead}>
            <View style={{ flex: 1 }}>
              <Text style={s.dayTitle}>{longDate(selected)}</Text>
              <Text style={s.daySub}>
                {selectedCount === 0
                  ? "No prayers marked"
                  : `${selectedCount} of ${PRAYERS.length} prayers`}
              </Text>
            </View>
          </View>

          {PRAYERS.map((prayer) => {
            const done = dayRecord?.[prayer.key] === true;
            const focus = focusByKey[prayer.key];
            return (
              <TouchableOpacity
                key={prayer.key}
                style={s.item}
                onPress={() => openFocus(prayer)}
                activeOpacity={0.75}
                accessibilityLabel={`${prayer.label}${focus ? ` — focus: ${focus.text}` : ""}. Add or edit prayer focus`}
              >
                <View style={[s.itemIcon, done && s.itemIconDone]}>
                  <Ionicons
                    name={prayer.icon}
                    size={18}
                    color={done ? colors.white : "#0fa3c4"}
                  />
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={s.itemLabel}>{prayer.label}</Text>
                  <Text style={s.itemCaption} numberOfLines={1}>
                    {focus ? `Focus: ${focus.text}` : prayer.caption}
                  </Text>
                </View>
                <View style={[s.check, done && s.checkDone]}>
                  {done ? (
                    <Ionicons name="checkmark" size={14} color={colors.white} />
                  ) : null}
                </View>
                <Ionicons name="chevron-forward" size={15} color={colors.gray[400]} />
              </TouchableOpacity>
            );
          })}
        </View>
      </ScrollView>
    </View>
  );
}

