import { cachedFetch, type CachedFetchOptions } from "./cache";

/** A service the admin posted (gig): bug fix, design work, or other. */
export type ServiceType = "bug" | "design" | "other";
export type ServiceStatus = "open" | "accepted" | "submitted" | "approved" | "closed";

export type ServiceSubmission = {
  note: string;
  githubLink: string | null;
  imageUrl: string | null;
  imageUrls: string[];
  submittedAt: string;
};

export type ServiceReview = {
  approved: boolean;
  note: string | null;
  reviewedBy: string;
  reviewedAt: string;
};

export type ClubService = {
  _id: string;
  title: string;
  description: string;
  type: ServiceType;
  clubSlug: string | null;
  rewardAmount: number | null;
  posterId: string;
  posterName: string;
  status: ServiceStatus;
  acceptedById: string | null;
  acceptedByName: string | null;
  acceptedAt: string | null;
  /** Optional target date for the work (ISO string). */
  dueDate?: string | null;
  submission: ServiceSubmission | null;
  review: ServiceReview | null;
  createdAt: string;
  updatedAt: string;
  isClaimedByMe?: boolean;
};

export type ServiceAction = "approve" | "reopen" | "close";

/** An open club/ops office members can apply to fill. */
export type OfficeStatus = "open" | "filled" | "closed";
export type OfficeApplicationStatus = "pending" | "approved" | "rejected";

export type VolunteerOffice = {
  _id: string;
  title: string;
  description: string;
  area: string | null;
  clubSlug: string | null;
  /** Optional vacancy-style bullet lists (or raw newline text when posting). */
  responsibilities?: string[] | null;
  qualifications?: string[] | null;
  /** Optional custom questions the admin wants each applicant to answer. */
  applicationQuestions?: string[] | null;
  postedById: string;
  postedByName: string;
  status: OfficeStatus;
  createdAt: string;
  updatedAt: string;
  myApplication?: OfficeApplication | null;
};

export type OfficeApplication = {
  _id: string;
  officeId: string;
  officeTitle: string;
  userId: string;
  name: string;
  email: string | null;
  motivation: string;
  /** Per-question answers when the office defines applicationQuestions. */
  answers?: { question: string; answer: string }[] | null;
  status: OfficeApplicationStatus;
  reviewNote: string | null;
  createdAt: string;
  reviewedAt: string | null;
  reviewedBy: string | null;
  office?: {
    _id: string;
    title: string;
    description: string;
    area: string | null;
    status: OfficeStatus;
    clubSlug: string | null;
  } | null;
};

async function apiFetch<T>(path: string, options: CachedFetchOptions = {}): Promise<T> {
  return cachedFetch<T>(path, options, ["/api/community/services", "/api/community/offices"]);
}

export const servicesApi = {
  /** List services; `status` filters, `mine` returns only the caller's claims. */
  list: (opts: { status?: ServiceStatus; mine?: boolean } = {}) => {
    const params: string[] = [];
    if (opts.status) params.push(`status=${opts.status}`);
    if (opts.mine) params.push("mine=1");
    const query = params.length ? `?${params.join("&")}` : "";
    return apiFetch<{ data: ClubService[] }>(`/api/community/services${query}`, {
      cacheTtl: 0,
    });
  },

  get: (id: string) =>
    apiFetch<{ data: ClubService }>(`/api/community/services/${id}`, { cacheTtl: 0 }),

  /** Admin-only: post a new service (notifies every member). */
  create: (input: {
    title: string;
    description: string;
    type: ServiceType;
    clubSlug?: string | null;
    dueDate?: string | null;
    rewardAmount: number;
  }) =>
    apiFetch<{ data: ClubService }>("/api/community/services", {
      method: "POST",
      body: JSON.stringify(input),
    }),

  /** Admin-only: edit fields or run approve / reopen / close. */
  update: (
    id: string,
    input: Partial<{
      title: string;
      description: string;
      type: ServiceType;
      clubSlug: string | null;
      dueDate: string | null;
      action: ServiceAction;
      note: string;
    }>,
  ) =>
    apiFetch<{ data: ClubService }>(`/api/community/services/${id}`, {
      method: "PATCH",
      body: JSON.stringify(input),
    }),

  /** Claim an open service (single-claim). */
  accept: (id: string) =>
    apiFetch<{ data: ClubService }>(`/api/community/services/${id}/accept`, {
      method: "POST",
    }),

  /** Release a claimed service back to the open list. */
  withdraw: (id: string) =>
    apiFetch<{ data: ClubService }>(`/api/community/services/${id}/withdraw`, {
      method: "POST",
    }),

  /**
   * Submit completed work. Deliverable by type: bug needs a GitHub link,
   * design needs an image URL, other takes either — plus a short note.
   */
  submit: (
    id: string,
    input: {
      note: string;
      githubLink?: string | null;
      imageUrl?: string | null;
      imageUrls?: string[];
    },
  ) =>
    apiFetch<{ data: ClubService }>(`/api/community/services/${id}/submit`, {
      method: "POST",
      body: JSON.stringify(input),
    }),
};

export const officesApi = {
  /** Open + filled offices (admins see everything), with `myApplication`. */
  list: () =>
    apiFetch<{ data: VolunteerOffice[] }>("/api/community/offices", { cacheTtl: 0 }),

  get: (id: string) =>
    apiFetch<{ data: VolunteerOffice }>(`/api/community/offices/${id}`, { cacheTtl: 0 }),

  /** Admin-only: post an open office (notifies every member). */
  create: (input: {
    title: string;
    description: string;
    area?: string | null;
    clubSlug?: string | null;
    responsibilities?: string | string[] | null;
    qualifications?: string | string[] | null;
    applicationQuestions?: string | string[] | null;
  }) =>
    apiFetch<{ data: VolunteerOffice }>("/api/community/offices", {
      method: "POST",
      body: JSON.stringify(input),
    }),

  /** Admin-only: edit fields or run fill / reopen / close. */
  update: (
    id: string,
    input: Partial<{
      title: string;
      description: string;
      area: string | null;
      clubSlug: string | null;
      responsibilities: string | string[] | null;
      qualifications: string | string[] | null;
      applicationQuestions: string | string[] | null;
      action: "fill" | "reopen" | "close";
    }>,
  ) =>
    apiFetch<{ data: VolunteerOffice }>(`/api/community/offices/${id}`, {
      method: "PATCH",
      body: JSON.stringify(input),
    }),

  /** Admin-only. */
  remove: (id: string) =>
    apiFetch<{ success: boolean }>(`/api/community/offices/${id}`, {
      method: "DELETE",
    }),

  /** Apply for an open office. When the office has custom questions, send
   *  per-question answers; otherwise send a short motivation note. */
  apply: (
    id: string,
    input: { motivation?: string; answers?: { question: string; answer: string }[] },
  ) =>
    apiFetch<{ data: OfficeApplication }>(`/api/community/offices/${id}/apply`, {
      method: "POST",
      body: JSON.stringify(input),
    }),

  /** Admin-only: applications across all offices (optionally by status). */
  applications: (status?: OfficeApplicationStatus) =>
    apiFetch<{ data: OfficeApplication[] }>(
      status
        ? `/api/community/offices/applications?status=${status}`
        : "/api/community/offices/applications",
      { cacheTtl: 0 },
    ),

  /** Admin-only: approve (fills the office) or reject. */
  review: (applicationId: string, action: "approve" | "reject", note?: string) =>
    apiFetch<{ data: OfficeApplication }>(
      `/api/community/offices/applications/${applicationId}`,
      { method: "PATCH", body: JSON.stringify({ action, note }) },
    ),

  /** The caller's applications, each joined with its office. */
  mine: () =>
    apiFetch<{ data: OfficeApplication[] }>("/api/community/offices/mine", {
      cacheTtl: 0,
    }),
};

