const CARD_GAP = 12;
const DAY_MS = 86_400_000;

type DiscoverType = "event" | "skill" | "group";

type BookmarkRef = { section: string; itemId: string };

type DiscoverItem = {
  key: string;
  type: DiscoverType;
  title: string;
  meta: { icon: string; text: string }[];
  sortAt: number;
  onPress: () => void;
  bookmark?: BookmarkRef;
  live?: boolean;
  image?: string | null;
};

function atMs(value?: string | null) {
  return value ? new Date(value).getTime() || 0 : 0;
}

/** Start time (ms) of an event from its date + time fields, or null. */
function eventStartMs(e: DiscoverEventCard): number | null {
  if (!e.date) return null;
  const day = new Date(`${String(e.date).slice(0, 10)}T00:00:00`);
  if (isNaN(day.getTime())) return null;
  const m = /^(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/i.exec(String(e.time).trim());
  let h = 12;
  let min = 0;
  if (m) {
    h = parseInt(m[1], 10);
    min = m[2] ? parseInt(m[2], 10) : 0;
    const ampm = m[3] ? m[3].toLowerCase() : null;
    if (ampm) {
      if (ampm === "pm" && h < 12) h += 12;
      if (ampm === "am" && h === 12) h = 0;
    } else if (h >= 24) {
      h = h % 24;
    }
  }
  day.setHours(h, min, 0, 0);
  return day.getTime();
}

const DAYS = [
  "sunday",
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday",
];

/**
 * The next occurrence (ms) of a group's recurring meeting, parsed from its
 * free-text meetingTime (e.g. "Every Sunday 7:00 PM"). Falls back to today /
 * tomorrow at the stated time when no weekday is given; null when unparseable.
 */
function groupNextMeetingMs(g: DiscoverGroupCard, now: number): number | null {
  const text = String(g.meetingTime || "")
    .toLowerCase()
    .trim();
  if (!text) return null;
  const dayIdx = DAYS.findIndex((d) => text.includes(d));
  const tm = /(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/.exec(text);
  if (!tm) return null;
  let h = parseInt(tm[1], 10);
  const min = tm[2] ? parseInt(tm[2], 10) : 0;
  const ampm = tm[3] ? tm[3].toLowerCase() : null;
  if (ampm) {
    if (ampm === "pm" && h < 12) h += 12;
    if (ampm === "am" && h === 12) h = 0;
  } else if (h >= 24) {
    h = h % 24;
  }
  const next = new Date(now);
  next.setHours(h, min, 0, 0);
  if (dayIdx === -1) {
    if (next.getTime() <= now) next.setDate(next.getDate() + 1);
    return next.getTime();
  }
  const delta = (dayIdx - next.getDay() + 7) % 7;
  next.setDate(next.getDate() + delta);
  if (next.getTime() <= now) next.setDate(next.getDate() + 7);
  return next.getTime();
}

/**
 * Whether an event is already over (date + time, with a one-hour grace
 * period for its duration). Falls back to date-only when the time can't be
 * parsed, so a stale snapshot never keeps showing finished events.
 */
function eventEnded(e: DiscoverEventCard, now: number) {
  const base = e.dateTo || e.date;
  if (!base) return false;
  const day = new Date(`${String(base).slice(0, 10)}T00:00:00`).getTime();
  if (isNaN(day)) return false;
  const m = (e.timeTo || e.time || "")
    .trim()
    .match(/^(\d{1,2}):(\d{2})\s*(am|pm)$/i);
  let end = day + DAY_MS - 1;
  if (m) {
    let h = parseInt(m[1], 10);
    const min = parseInt(m[2], 10);
    if (m[3].toLowerCase() === "pm" && h < 12) h += 12;
    if (m[3].toLowerCase() === "am" && h === 12) h = 0;
    end = day + h * 3_600_000 + min * 60_000 + 3_600_000;
  }
  return end < now;
}

/** Human-readable date (and time) range for an event card. */
function formatEventDate(e: DiscoverEventCard) {
  const d = new Date(e.date);
  if (isNaN(d.getTime())) return e.date || "";
  const dateStr = d.toLocaleDateString("en-US", {
    weekday: "short",
    day: "numeric",
    month: "short",
    year: "numeric",
  });
  const time = e.time ? ` · ${e.time}` : "";
  if (!e.dateTo) return `${dateStr}${time}`;
  const end = new Date(e.dateTo);
  if (isNaN(end.getTime())) return `${dateStr}${time}`;
  const endStr = end.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    ...(end.getFullYear() !== d.getFullYear() ? { year: "numeric" } : {}),
  });
  return `${dateStr} – ${endStr}${time}`;
}

function eventDurationDays(e: DiscoverEventCard): number | null {
  if (!e.dateTo) return null;
  const start = new Date(e.date);
  const end = new Date(e.dateTo);
  if (isNaN(start.getTime()) || isNaN(end.getTime())) return null;
  const days = Math.round((end.getTime() - start.getTime()) / DAY_MS) + 1;
  return days > 0 ? days : null;
}

function pushToCommunity() {
  router.push("/(tabs)/community");
}

/** Build the rail's serializable items from the stored card data. */
function buildItems(
  events: DiscoverEventCard[],
  groups: DiscoverGroupCard[],
  skills: DiscoverSkillCard[],
): DiscoverItem[] {
  const now = Date.now();
  const built: DiscoverItem[] = [];

  // Items without a date sort to the end of the rail (newest first).
  const undatedAt = (createdAt?: string) =>
    Number.MAX_SAFE_INTEGER - atMs(createdAt || "");

  events
    .filter((e) => !eventEnded(e, now))
    .forEach((e) => {
      const at = eventStartMs(e);
      built.push({
        key: `event-${e._id}`,
        type: "event",
        title: e.title,
        meta: [
          { icon: "time-outline", text: formatEventDate(e) },
          ...(eventDurationDays(e)
            ? [
                {
                  icon: "calendar-outline" as string,
                  text: `${eventDurationDays(e)} day${eventDurationDays(e)! > 1 ? "s" : ""}`,
                },
              ]
            : []),
          ...(e.location
            ? [{ icon: "location-outline" as string, text: e.location }]
            : []),
        ],
        sortAt: at !== null ? at : undatedAt(e.createdAt),
        onPress: () => pushToCommunity(),
        bookmark: { section: "events", itemId: e._id },
        image: e.imageUrl,
      });
    });

  groups.forEach((g) => {
    const at = g.live ? now : groupNextMeetingMs(g, now);
    built.push({
      key: `group-${g._id}`,
      type: "group",
      title: g.name,
      meta: [
        {
          icon: "people-outline",
          text: `${g.members}${g.maxMembers ? `/${g.maxMembers}` : ""} members`,
        },
        ...(g.meetingTime
          ? [{ icon: "time-outline" as string, text: g.meetingTime }]
          : []),
      ],
      sortAt: at !== null ? at : undatedAt(g.createdAt),
      onPress: () => pushToCommunity(),
      bookmark: { section: "groups", itemId: g._id },
      live: g.live,
      image: g.imageUrl,
    });
  });

  skills
    .slice()
    .sort((a, b) => atMs(b.createdAt) - atMs(a.createdAt))
    .slice(0, 3)
    .forEach((sk) => {
      built.push({
        key: `skill-${sk._id}`,
        type: "skill",
        title: sk.title,
        meta: [
          { icon: "pricetag-outline", text: sk.category },
          {
            icon: sk.offering ? "arrow-up-outline" : "arrow-down-outline",
            text: sk.offering ? "Offering" : "Seeking",
          },
        ],
        sortAt: undatedAt(sk.createdAt),
        onPress: () => pushToCommunity(),
        bookmark: { section: "skills", itemId: sk._id },
      });
    });

  built.sort((a, b) => a.sortAt - b.sortAt);
  return built;
}

/** Card-shaped placeholder mirroring DiscoverCard's media + details layout. */
function DiscoverCardSkeleton({ width }: { width: number }) {
  return (
    <View style={[s.skeletonCard, { width }]}>
      <SkeletonPulse style={s.skeletonMedia} />
      <View style={s.skeletonBody}>
        <View style={s.skeletonTitleRow}>
          <SkeletonPulse style={s.skeletonTile} />
          <View style={s.skeletonTitleLines}>
            <SkeletonPulse style={s.skeletonLineWide} />
            <SkeletonPulse style={s.skeletonLineNarrow} />
          </View>
        </View>
        <View style={s.skeletonMetaBlock}>
          <SkeletonPulse style={s.skeletonMetaLine} />
          <SkeletonPulse style={s.skeletonMetaLine} />
        </View>
      </View>
    </View>
  );
}

/**
 * "What's new" — a horizontal rail of events, skills and groups. The cards'
 * display data lives in a SQLite snapshot so the rail renders instantly and
 * stays intact offline. Refocusing only paints that snapshot; the server is
 * consulted on pull-to-refresh, or when there is nothing stored to show.
 */
export default function DiscoverRail({
  refreshSignal = 0,
}: {
  /** Bumped by Home's pull-to-refresh to force a version check. */
  refreshSignal?: number;
}) {
  const db = useSQLiteContext();
  const { width } = useWindowDimensions();
  const [items, setItems] = useState<DiscoverItem[] | null>(null);
  const [loaded, setLoaded] = useState(false);
  const [bookmarked, setBookmarked] = useState<Record<string, boolean>>({});

  const netInfo = NetInfo.useNetInfo();
  const isOnline =
    !!netInfo.isConnected && netInfo.isInternetReachable !== false;
  const isOnlineRef = useRef(isOnline);
  useEffect(() => {
    isOnlineRef.current = isOnline;
  }, [isOnline]);

  const paint = useCallback((snap: DiscoverSnapshot) => {
    setItems(buildItems(snap.events, snap.groups, snap.skills));
    // The snapshot is authoritative — toggles are written back to it, so
    // replacing (not merging) also clears bookmarks removed elsewhere.
    const bmMap: Record<string, boolean> = {};
    for (const b of snap.bookmarks) bmMap[`${b.section}:${b.itemId}`] = true;
    setBookmarked(bmMap);
  }, []);

  const load = useCallback(async () => {
    const local = loadDiscoverSnapshot(db);
    const hasCards =
      !!local &&
      (local.events.length > 0 ||
        local.groups.length > 0 ||
        local.skills.length > 0);

    // Coming back to Home paints the stored rail and stops there — refreshing
    // is pull-to-refresh's job. Only a rail with nothing to show fetches, so a
    // first launch (or a snapshot saved empty by a failed pull) still fills.
    if (hasCards) {
      paint(local!);
      setLoaded(true);
      return;
    }

    if (!isOnlineRef.current) {
      setLoaded(true);
      return;
    }

    const fresh = await syncDiscover(db);
    setLoaded(true);
    if (fresh) paint(fresh);
  }, [db, paint]);

  const handleCardPress = useCallback((item: DiscoverItem) => {
    if (isOnlineRef.current) {
      item.onPress();
    } else {
      Alert.alert(
        "Connect to view",
        "You need to be online to view this event or group.",
      );
    }
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load]),
  );

  // Pull-to-refresh: bypass the throttle but keep the version compare, so an
  // unchanged feed costs one probe instead of four list requests. The cached
  // cards are already on screen, so only a genuinely new snapshot repaints.
  useEffect(() => {
    if (refreshSignal === 0 || !isOnlineRef.current) return;
    let alive = true;
    syncDiscover(db, true).then((fresh) => {
      if (alive && fresh) paint(fresh);
    });
    return () => {
      alive = false;
    };
  }, [refreshSignal, db, paint]);

  const handleToggleBookmark = useCallback(
    async (item: DiscoverItem) => {
      const bm = item.bookmark;
      if (!bm) return;
      if (!isOnlineRef.current) {
        Alert.alert("Connect to view", "You need to be online to bookmark this.");
        return;
      }
      const session = await getSession();
      if (!session?.user) {
        router.push("/login");
        return;
      }
      const key = `${bm.section}:${bm.itemId}`;
      // Functional updates so rapid taps each flip from the latest state.
      setBookmarked((prev) => ({ ...prev, [key]: !prev[key] }));
      try {
        const res = await communityApi.toggleBookmark(bm.section, bm.itemId);
        const saved = !!res.data?.bookmarked;
        setBookmarked((prev) => ({ ...prev, [key]: saved }));
        // Write through so the toggle survives the next cached paint.
        setDiscoverBookmark(db, bm.section, bm.itemId, saved);
      } catch {
        // Revert the optimistic update on failure.
        setBookmarked((prev) => ({ ...prev, [key]: !prev[key] }));
      }
    },
    [db],
  );

  // Cards fill the device width (rail has 16 horizontal padding) so they
  // read like the other full-width cards on the home screen.
  const cardWidth = width - 32;

  const renderCard = useCallback(
    (item: DiscoverItem) => {
      const bmKey = item.bookmark
        ? `${item.bookmark.section}:${item.bookmark.itemId}`
        : null;
      const isSaved = bmKey ? !!bookmarked[bmKey] : false;
      return (
        <DiscoverCard
          key={item.key}
          type={item.type}
          title={item.title}
          meta={item.meta}
          image={item.image}
          live={item.live}
          isSaved={isSaved}
          bookmark={item.bookmark}
          onToggleBookmark={() => handleToggleBookmark(item)}
          onPress={() => handleCardPress(item)}
          width={cardWidth}
        />
      );
    },
    [bookmarked, cardWidth, handleCardPress, handleToggleBookmark],
  );

  const liveCount = (items ?? []).filter(
    (i) => i.type === "group" && i.live,
  ).length;

  const header = (
    <View style={s.head}>
      <View style={s.headLeft}>
        <Text style={s.eyebrow}>DISCOVER</Text>
        <Text style={s.title}>Up Coming</Text>
        <Text style={s.sub}>Events, skills &amp; groups</Text>
        {liveCount > 0 && (
          <LivePill>
            <View style={s.liveCountPill}>
              <View style={s.liveCountDot} />
              <Text style={s.liveCountText}>
                {liveCount} {liveCount === 1 ? "group" : "groups"} live now
              </Text>
            </View>
          </LivePill>
        )}
      </View>
      <TouchableOpacity
        onPress={() => pushToCommunity()}
        style={s.viewAllBtn}
        activeOpacity={0.7}
      >
        <Text style={s.viewAllText}>View all</Text>
        <Ionicons name="chevron-forward" size={14} color={colors.gold} />
      </TouchableOpacity>
    </View>
  );

  // First-load: nothing stored yet, still resolving connectivity. The static
  // header stays real; only the dynamic rail shows card-shaped skeletons.
  if (items === null && !loaded) {
    return (
      <View style={s.section}>
        {header}
        <View style={s.railWrap}>
          <ScrollView
            horizontal
            scrollEnabled={false}
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={s.rail}
          >
            {[0, 1].map((i) => (
              <DiscoverCardSkeleton key={i} width={cardWidth} />
            ))}
          </ScrollView>
        </View>
      </View>
    );
  }

  // Nothing to show (no stored snapshot yet and offline, or genuinely empty).
  if (items === null || items.length === 0) return null;

  return (
    <View style={s.section}>
      {header}
      <View style={s.railWrap}>
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          snapToInterval={cardWidth + CARD_GAP}
          decelerationRate="fast"
          contentContainerStyle={s.rail}
        >
          {items.map(renderCard)}
        </ScrollView>
      </View>
    </View>
  );
}

