import AsyncStorage from "@react-native-async-storage/async-storage";
import { useSyncExternalStore } from "react";
import type { StoreProduct } from "@/services/store";

/**
 * Cart — a tiny module-level store shared by the store tab, the product
 * detail screen and the cart/checkout screens.
 *
 * It survives app restarts (AsyncStorage) and never re-renders subscribers
 * with a stale snapshot: every mutation swaps in a new state object, so the
 * `useCart` hook can hand `getSnapshot` straight to `useSyncExternalStore`.
 */

export type CartLine = {
  itemId: string;
  name: string;
  /** Unit price the buyer pays (offer price when one applies). */
  price: number;
  image: string;
  /** Apparel only — null for everything else. */
  size: string | null;
  qty: number;
};

type CartState = { lines: CartLine[] };

const STORAGE_KEY = "relate:cart:v1";
const MAX_QTY = 20;

const EMPTY: CartState = { lines: [] };

let state: CartState = EMPTY;
const listeners = new Set<() => void>();

function emit(next: CartState) {
  state = next;
  for (const listener of listeners) listener();
  AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(next.lines)).catch(() => {});
}

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function getSnapshot(): CartState {
  return state;
}

// Hydrate once at module load; later writes go through `emit`.
AsyncStorage.getItem(STORAGE_KEY)
  .then((raw) => {
    if (!raw || state !== EMPTY) return;
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed) && parsed.length > 0) {
      emit({ lines: parsed as CartLine[] });
    }
  })
  .catch(() => {});

export function addToCart(
  product: StoreProduct,
  opts: { qty?: number; size?: string | null; price?: number } = {},
): void {
  const qty = Math.min(MAX_QTY, Math.max(1, Math.floor(opts.qty ?? 1)));
  const size = opts.size ?? null;
  const price = opts.price ?? (product.offerPrice ?? product.price);

  const existing = state.lines.find(
    (l) => l.itemId === product.id && l.size === size,
  );
  if (existing) {
    emit({
      lines: state.lines.map((l) =>
        l === existing ? { ...l, qty: Math.min(MAX_QTY, l.qty + qty) } : l,
      ),
    });
    return;
  }
  emit({
    lines: [
      ...state.lines,
      { itemId: product.id, name: product.name, price, image: product.image, size, qty },
    ],
  });
}

export function setLineQty(itemId: string, size: string | null, qty: number): void {
  const clamped = Math.min(MAX_QTY, Math.max(0, Math.floor(qty)));
  emit({
    lines:
      clamped === 0
        ? state.lines.filter((l) => !(l.itemId === itemId && l.size === size))
        : state.lines.map((l) =>
            l.itemId === itemId && l.size === size ? { ...l, qty: clamped } : l,
          ),
  });
}

export function removeLine(itemId: string, size: string | null): void {
  emit({
    lines: state.lines.filter((l) => !(l.itemId === itemId && l.size === size)),
  });
}

export function clearCart(): void {
  emit(EMPTY);
}

export function cartCount(lines: CartLine[]): number {
  return lines.reduce((sum, l) => sum + l.qty, 0);
}

export function cartSubtotal(lines: CartLine[]): number {
  return lines.reduce((sum, l) => sum + l.price * l.qty, 0);
}

/** Subscribe to the cart — returns the lines, subtotal and mutators. */
export function useCart(): {
  lines: CartLine[];
  count: number;
  subtotal: number;
  add: typeof addToCart;
  setQty: typeof setLineQty;
  remove: typeof removeLine;
  clear: typeof clearCart;
} {
  const snapshot = useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
  return {
    lines: snapshot.lines,
    count: cartCount(snapshot.lines),
    subtotal: cartSubtotal(snapshot.lines),
    add: addToCart,
    setQty: setLineQty,
    remove: removeLine,
    clear: clearCart,
  };
}

/** Re-renders the caller whenever the cart changes (for header badges). */
export function useCartCount(): number {
  const snapshot = useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
  return cartCount(snapshot.lines);
}

/** Read the cart once (e.g. before an imperative checkout). */
export function getCartLines(): CartLine[] {
  return state.lines;
}
