import { Ionicons } from "@expo/vector-icons";
import { useState } from "react";
import { StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";

type Quick = { h: number; m: number; label: string };

const QUICK: Quick[] = [
  { h: 8, m: 0, label: "8:00 AM" },
  { h: 9, m: 0, label: "9:00 AM" },
  { h: 10, m: 0, label: "10:00 AM" },
  { h: 11, m: 0, label: "11:00 AM" },
  { h: 12, m: 0, label: "12:00 PM" },
  { h: 13, m: 0, label: "1:00 PM" },
  { h: 14, m: 0, label: "2:00 PM" },
  { h: 16, m: 0, label: "4:00 PM" },
  { h: 18, m: 0, label: "6:00 PM" },
  { h: 19, m: 0, label: "7:00 PM" },
];

function Stepper({
  label,
  value,
  onUp,
  onDown,
}: {
  label: string;
  value: string;
  onUp: () => void;
  onDown: () => void;
}) {
  return (
    <View style={styles.stepper}>
      <TouchableOpacity
        style={styles.stepperBtn}
        onPress={onUp}
        activeOpacity={0.7}
        accessibilityLabel={`Increase ${label}`}
      >
        <Ionicons name="chevron-up" size={15} color={colors.forestDark} />
      </TouchableOpacity>
      <Text style={styles.stepperValue}>{value}</Text>
      <TouchableOpacity
        style={styles.stepperBtn}
        onPress={onDown}
        activeOpacity={0.7}
        accessibilityLabel={`Decrease ${label}`}
      >
        <Ionicons name="chevron-down" size={15} color={colors.forestDark} />
      </TouchableOpacity>
      <Text style={styles.stepperLabel}>{label}</Text>
    </View>
  );
}

type Props = {
  value?: Date | null;
  onSelect: (d: Date) => void;
};

export default function InlineTimePicker({ value, onSelect }: Props) {
  const seed = value && !isNaN(value.getTime()) ? value : null;
  const [hour, setHour] = useState(seed ? seed.getHours() % 12 || 12 : 9);
  const [min, setMin] = useState(seed ? seed.getMinutes() : 0);
  const [ampm, setAmpm] = useState<"AM" | "PM">(seed && seed.getHours() >= 12 ? "PM" : "AM");

  const compose = (h24: number, m: number) => {
    const base = seed ?? new Date();
    onSelect(new Date(base.getFullYear(), base.getMonth(), base.getDate(), h24, m, 0, 0));
  };

  const stepHour = (delta: number) => setHour(((hour - 1 + delta + 12) % 12) + 1);
  const stepMin = (delta: number) => setMin(((min + delta) % 60 + 60) % 60);

  const applyCustom = () => {
    const h24 = ampm === "PM" ? (hour % 12) + 12 : hour % 12;
    compose(h24, min);
  };

  const isSelected = (h24: number, m: number) =>
    !!seed && seed.getHours() === h24 && seed.getMinutes() === m;

  return (
    <View style={styles.container}>
      <Text style={styles.sectionLabel}>Quick select</Text>
      <View style={styles.quickWrap}>
        {QUICK.map((q) => {
          const selected = isSelected(q.h, q.m);
          return (
            <TouchableOpacity
              key={q.label}
              style={[styles.chip, selected && styles.chipSelected]}
              onPress={() => compose(q.h, q.m)}
              activeOpacity={0.7}
            >
              <Text style={[styles.chipText, selected && styles.chipTextSelected]}>{q.label}</Text>
            </TouchableOpacity>
          );
        })}
      </View>

      <View style={styles.divider} />

      <Text style={styles.sectionLabel}>Or enter a time</Text>
      <View style={styles.customRow}>
        <Stepper label="Hour" value={String(hour)} onUp={() => stepHour(1)} onDown={() => stepHour(-1)} />
        <Text style={styles.colon}>:</Text>
        <Stepper
          label="Min"
          value={String(min).padStart(2, "0")}
          onUp={() => stepMin(5)}
          onDown={() => stepMin(-5)}
        />
        <View style={styles.ampmSeg}>
          {(["AM", "PM"] as const).map((p) => {
            const active = ampm === p;
            return (
              <TouchableOpacity
                key={p}
                style={[styles.ampmBtn, active && styles.ampmBtnOn]}
                onPress={() => setAmpm(p)}
                activeOpacity={0.7}
              >
                <Text style={[styles.ampmText, active && styles.ampmTextOn]}>{p}</Text>
              </TouchableOpacity>
            );
          })}
        </View>
      </View>

      <TouchableOpacity style={styles.applyBtn} onPress={applyCustom} activeOpacity={0.8}>
        <Text style={styles.applyText}>Set time</Text>
      </TouchableOpacity>
    </View>
  );
}

