import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { router } from "expo-router";
import { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator,
  Linking,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaProvider, SafeAreaView } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { getSession } from "@/services/auth";
import {
  sponsorApi,
  financialApi,
  type MySponsorships as MySponsorshipsData,
  type SponsorshipStatus,
  type FinancialReportSummary,
  type BankingDetails,
} from "@/services/sponsorships";
import SponsorModal from "@/components/SponsorModal";
import { GradientBox } from "@/constants/gradients";

const fmtMoney = (n: number) => `R ${(n || 0).toLocaleString("en-US")}`;

const fmtDate = (value?: string) => {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-ZA", { day: "numeric", month: "short", year: "numeric" });
};

const STATUS_META: Record<SponsorshipStatus, { label: string; color: string; bg: string }> = {
  pending: { label: "Pending review", color: "#b45309", bg: "#fef3c7" },
  approved: { label: "Approved", color: "#047857", bg: "#d1fae5" },
  rejected: { label: "Not approved", color: "#be123c", bg: "#ffe4e6" },
};

function StatCard({ label, value, color }: { label: string; value: string; color: string }) {
  return (
    <View style={styles.statCard}>
      <Text style={[styles.statValue, { color }]}>{value}</Text>
      <Text style={styles.statLabel}>{label}</Text>
    </View>
  );
}

export default function Financials() {
  const [loggedIn, setLoggedIn] = useState<boolean | null>(null);
  const [data, setData] = useState<MySponsorshipsData | null>(null);
  const [reports, setReports] = useState<FinancialReportSummary[]>([]);
  const [banking, setBanking] = useState<BankingDetails | null>(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [showSponsorModal, setShowSponsorModal] = useState(false);

  const load = useCallback(async () => {
    try {
      const [me, list, bankingRes] = await Promise.all([
        sponsorApi.me(),
        financialApi.list().catch(() => null),
        sponsorApi.banking().catch(() => null),
      ]);
      setData(me.data);
      setReports(list?.data || []);
      setBanking(bankingRes?.data?.banking || null);
      setError("");
    } catch (e: any) {
      setError(e?.message || "Network error — could not reach the server.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    (async () => {
      const session = await getSession();
      if (!session?.user) {
        setLoggedIn(false);
        setLoading(false);
        return;
      }
      setLoggedIn(true);
      await load();
    })();
  }, [load]);

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    await load();
    setRefreshing(false);
  }, [load]);

  const openPop = (url: string) => {
    Linking.openURL(url).catch(() => {});
  };

  const totalGiven = (data?.sponsorships || []).reduce((s, x) => s + (x.amount || 0), 0);
  const approvedTotal = (data?.sponsorships || [])
    .filter((x) => x.status === "approved")
    .reduce((s, x) => s + (x.amount || 0), 0);
  const pendingTotal = (data?.sponsorships || [])
    .filter((x) => x.status === "pending")
    .reduce((s, x) => s + (x.amount || 0), 0);
  const pledgeCount = (data?.sponsorships || []).length;

  if (loggedIn === null) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <View style={styles.center}>
            <ActivityIndicator color={colors.goldDark} size="large" />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.header}>
          <TouchableOpacity onPress={() => router.back()} style={styles.closeBtn}>
            <Ionicons name="close" size={20} color={colors.darkGreen} />
          </TouchableOpacity>
          <Text style={styles.headerTitle}>Financials</Text>
          <View style={{ width: 36 }} />
        </View>

        {loggedIn ? (
          <ScrollView
            contentContainerStyle={styles.scroll}
            showsVerticalScrollIndicator={false}
            refreshControl={
              <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
            }
          >
            {loading && !data ? (
              <View style={styles.center}>
                {error ? (
                  <>
                    <Ionicons name="cloud-offline-outline" size={40} color={colors.muted} />
                    <Text style={styles.errorText}>{error}</Text>
                    <TouchableOpacity
                      style={styles.retryBtn}
                      onPress={load}
                      activeOpacity={0.85}
                    >
                      <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                      <Text style={styles.retryBtnText}>Try again</Text>
                    </TouchableOpacity>
                  </>
                ) : (
                  <ActivityIndicator color={colors.goldDark} size="large" />
                )}
              </View>
            ) : (
              <>
                <LinearGradient
                  colors={[colors.forestDark, colors.forestSoft]}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 1 }}
                  style={styles.heroCard}
                >
                  <View style={styles.heroHead}>
                    <Ionicons name="wallet" size={16} color={colors.gold} />
                    <Text style={styles.heroEyebrow}>{"FINANCIALS"}</Text>
                  </View>
                  <Text style={styles.heroTitle}>
                    {data?.sponsorId || "Relate partner"}
                  </Text>
                  <Text style={styles.heroSub}>
                    {data?.sponsorId
                      ? `${pledgeCount} pledge${pledgeCount === 1 ? "" : "s"} · total given ${fmtMoney(totalGiven)}`
                      : "Track your pledges and read Relate's financial reports."}
                  </Text>
                </LinearGradient>

                {pledgeCount > 0 ? (
                  <View style={styles.statsRow}>
                    <StatCard label="Total given" value={fmtMoney(totalGiven)} color={colors.darkGreen} />
                    <StatCard label="Approved" value={fmtMoney(approvedTotal)} color="#047857" />
                    <StatCard label="Pending" value={fmtMoney(pendingTotal)} color="#b45309" />
                  </View>
                ) : null}

                <Text style={styles.sectionTitle}>Your transactions</Text>

                {data?.sponsorships.length === 0 ? (
                  <View style={styles.noRows}>
                    <Text style={styles.noRowsText}>
                      No pledges yet — make your first one below.
                    </Text>
                  </View>
                ) : (
                  data?.sponsorships.map((s) => {
                    const meta = STATUS_META[s.status] || STATUS_META.pending;
                    const popUrl = s.popUrl;
                    return (
                      <View key={s._id} style={styles.row}>
                        <View style={styles.rowTop}>
                          <Text style={styles.rowAmount}>{fmtMoney(s.amount)}</Text>
                          <View style={[styles.chip, { backgroundColor: meta.bg }]}>
                            <Text style={[styles.chipText, { color: meta.color }]}>
                              {meta.label}
                            </Text>
                          </View>
                        </View>
                        <Text style={styles.rowRef}>
                          Ref {s.sponsorId} · {fmtDate(s.createdAt)}
                        </Text>
                        {popUrl ? (
                          <TouchableOpacity
                            style={styles.popLink}
                            onPress={() => openPop(popUrl)}
                            activeOpacity={0.8}
                          >
                            <Ionicons name="image-outline" size={14} color={colors.forest} />
                            <Text style={styles.popLinkText}>View proof of payment</Text>
                          </TouchableOpacity>
                        ) : null}
                      </View>
                    );
                  })
                )}

                <Text style={styles.sectionTitle}>Financial reports</Text>

                {reports.length === 0 ? (
                  <View style={styles.noRows}>
                    <Text style={styles.noRowsText}>
                      {"No financial reports published yet. You'll be notified when a new one is available."}
                    </Text>
                  </View>
                ) : (
                  reports.map((r) => (
                    <TouchableOpacity
                      key={r._id}
                      style={styles.reportCard}
                      activeOpacity={0.85}
                      onPress={() =>
                        router.push(`/financial-report-view?reportId=${r._id}`)
                      }
                    >
                      <View style={styles.reportHead}>
                        <View style={styles.reportIcon}>
                          <Ionicons name="receipt-outline" size={16} color={colors.goldDark} />
                        </View>
                        <View style={{ flex: 1 }}>
                          <Text style={styles.reportTitle}>{r.period}</Text>
                          <Text style={styles.reportSub}>
                            Prepared by {r.preparedBy || "Relate Admin"} ·{" "}
                            {fmtDate(r.createdAt)}
                          </Text>
                        </View>
                        <Ionicons name="chevron-forward" size={18} color={colors.muted} />
                      </View>
                      <View style={styles.reportTotals}>
                        <View style={styles.reportStat}>
                          <Text style={styles.reportStatLabel}>Income</Text>
                          <Text style={[styles.reportStatValue, { color: colors.darkGreen }]}>
                            {fmtMoney(r.income)}
                          </Text>
                        </View>
                        <View style={styles.reportStat}>
                          <Text style={styles.reportStatLabel}>Expenses</Text>
                          <Text style={[styles.reportStatValue, { color: "#b45309" }]}>
                            {fmtMoney(r.expenses)}
                          </Text>
                        </View>
                        <View style={styles.reportStat}>
                          <Text style={styles.reportStatLabel}>Net</Text>
                          <Text
                            style={[
                              styles.reportStatValue,
                              { color: r.net >= 0 ? "#047857" : "#be123c" },
                            ]}
                          >
                            {fmtMoney(r.net)}
                          </Text>
                        </View>
                      </View>
                    </TouchableOpacity>
                  ))
                )}

                <Text style={styles.sectionTitle}>Donate</Text>

                <LinearGradient
                  colors={["#151f3a", "#1d2a4d"]}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 1 }}
                  style={styles.bankingCard}
                >
                  <View style={styles.bankingHead}>
                    <Ionicons name="card-outline" size={16} color={colors.goldDark} />
                    <Text style={styles.bankingTitle}>Banking details</Text>
                  </View>
                  {banking ? (
                    <View style={styles.bankingRows}>
                      {[
                        ["Bank", banking.bankName],
                        ["Account holder", banking.accountHolder],
                        ["Account number", banking.accountNumber],
                        ["Branch code", banking.branchCode],
                        ["Account type", banking.accountType],
                        ["Reference", banking.reference],
                      ]
                        .filter(([, v]) => v && v.trim())
                        .map(([k, v]) => (
                          <View key={k} style={styles.bankingRow}>
                            <Text style={styles.bankingLabel}>{k}</Text>
                            <Text style={styles.bankingValue}>{v}</Text>
                          </View>
                        ))}
                      {banking.instructions ? (
                        <Text style={styles.bankingInstructions}>{banking.instructions}</Text>
                      ) : null}
                    </View>
                  ) : (
                    <Text style={styles.bankingEmpty}>Banking details unavailable.</Text>
                  )}
                  <TouchableOpacity
                    style={styles.pledgeBtnWrap}
                    activeOpacity={0.85}
                    onPress={() => setShowSponsorModal(true)}
                  >
                    <LinearGradient
                      colors={["#151f3a", "#1d2a4d"]}
                      start={{ x: 0, y: 0 }}
                      end={{ x: 1, y: 1 }}
                      style={styles.pledgeBtn}
                    >
                      <Text style={styles.pledgeBtnText}>Make a pledge</Text>
                      <Ionicons name="arrow-forward" size={16} color={colors.white} />
                    </LinearGradient>
                  </TouchableOpacity>
                </LinearGradient>
              </>
            )}
          </ScrollView>
        ) : (
          <View style={styles.center}>
            <Ionicons name="person-circle-outline" size={40} color={colors.muted} />
            <Text style={styles.deniedTitle}>Sign in to see your financials</Text>
            <Text style={styles.deniedText}>
              Your sponsor ID, pledge history and financial reports appear here
              once you sign in.
            </Text>
            <TouchableOpacity
              style={styles.signInBtn}
              onPress={() => {
                router.replace({ pathname: "/login", params: { next: "/financials" } });
              }}
              activeOpacity={0.85}
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Text style={styles.signInBtnText}>Sign in</Text>
            </TouchableOpacity>
          </View>
        )}

        {showSponsorModal && <SponsorModal onClose={() => setShowSponsorModal(false)} />}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

