import { Ionicons } from "@expo/vector-icons";
import { router, useLocalSearchParams } from "expo-router";
import { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  InteractionManager,
  KeyboardAvoidingView,
  Platform,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from "react-native";
import {
  SafeAreaProvider,
  SafeAreaView,
  useSafeAreaInsets,
} from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import BoardHeader from "@/components/board/BoardHeader";
import SecretaryMinutesUploadForm from "@/components/board/SecretaryMinutesUploadForm";
import { boardStyles as s } from "@/components/board/styles";
import {
  boardApi,
  type BoardMeeting,
  type BoardMember,
  type BoardMinutes,
} from "@/services/board-governance";

export default function BoardMinutesUploadScreen() {
  const insets = useSafeAreaInsets();
  const params = useLocalSearchParams<{ minutesId?: string }>();
  const minutesId = typeof params.minutesId === "string" ? params.minutesId : "";
  const [meetings, setMeetings] = useState<BoardMeeting[]>([]);
  const [members, setMembers] = useState<BoardMember[]>([]);
  const [editingMinutes, setEditingMinutes] = useState<BoardMinutes | null>(null);
  const [editingMeeting, setEditingMeeting] = useState<BoardMeeting | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [minutedCount, setMinutedCount] = useState(0);

  const load = useCallback(async () => {
    try {
      const [past, cards] = await Promise.all([
        boardApi.listMeetings("past"),
        boardApi.listMinutesCards(),
      ]);
      const logged = new Set((cards.data || []).map((entry) => entry.meetingId));
      setMembers(cards.boardMembers || past.boardMembers || []);
      setMinutedCount(logged.size);

      if (minutesId) {
        try {
          const target = await boardApi.getMinutes(minutesId);
          setEditingMinutes(target.data);
          setEditingMeeting(
            (past.data || []).find(
              (meeting) => meeting._id === target.data.meetingId,
            ) ?? null,
          );
        } catch {
          Alert.alert(
            "Minutes not found",
            "These minutes may have been removed. Returning to the minutes list.",
          );
          router.back();
          return;
        }
      }

      setMeetings(
        (past.data || []).filter(
          (meeting) => meeting.status !== "CANCELLED" && !logged.has(meeting._id),
        ),
      );
    } catch (e: any) {
      Alert.alert("Could not load meetings", e?.message || "Please try again.");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [minutesId]);

  useEffect(() => {
    const task = InteractionManager.runAfterInteractions(() => {
      void load();
    });
    return () => task.cancel();
  }, [load]);

  const onRefresh = () => {
    setRefreshing(true);
    void load();
  };

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <BoardHeader title={minutesId ? "Edit minutes" : "Log minutes"} />
        <KeyboardAvoidingView
          style={styles.flex}
          behavior={Platform.OS === "ios" ? "padding" : "height"}
        >
          {loading ? (
            <View style={s.center}>
              <ActivityIndicator color={colors.goldDark} size="large" />
            </View>
          ) : (
            <ScrollView
              contentContainerStyle={[
                styles.content,
                { paddingBottom: 36 + insets.bottom },
              ]}
              showsVerticalScrollIndicator={false}
              keyboardShouldPersistTaps="handled"
              keyboardDismissMode="none"
              refreshControl={
                <RefreshControl
                  refreshing={refreshing}
                  onRefresh={onRefresh}
                  tintColor={colors.goldDark}
                  colors={[colors.goldDark]}
                />
              }
            >
              <View style={styles.ruleCard}>
                <View style={styles.ruleIcon}>
                  <Ionicons name="time-outline" size={16} color={colors.goldDark} />
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={styles.ruleTitle}>The 48-hour rule</Text>
                  <Text style={styles.ruleBody}>
                    Minutes are due within 48 hours of a sitting. Anything logged later is
                    still accepted, but flagged as late in the archive.
                  </Text>
                  {minutedCount > 0 ? (
                    <Text style={styles.ruleMeta}>
                      {minutedCount} sitting{minutedCount === 1 ? "" : "s"} already minuted
                    </Text>
                  ) : null}
                </View>
              </View>

              <SecretaryMinutesUploadForm
                key={editingMinutes?._id ?? "new"}
                meetings={meetings}
                boardMembers={members}
                minutes={editingMinutes}
                meeting={editingMeeting}
                onSaved={() => {
                  if (editingMinutes) {
                    router.back();
                    return;
                  }
                  void load();
                }}
              />
            </ScrollView>
          )}
        </KeyboardAvoidingView>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}


const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  flex: { flex: 1 },
  content: { paddingHorizontal: 16, paddingTop: 4, gap: 12 },
  ruleCard: {
    flexDirection: "row",
    gap: 10,
    padding: 14,
    borderRadius: 16,
    backgroundColor: `${colors.gold}12`,
    borderWidth: 0.5,
    borderColor: `${colors.gold}55`,
  },
  ruleIcon: {
    width: 34,
    height: 34,
    borderRadius: 12,
    backgroundColor: colors.white,
    alignItems: "center",
    justifyContent: "center",
  },
  ruleTitle: {
    fontSize: 14.5,
    color: colors.darkGreen,
    fontFamily: fonts.sansBold,
  },
  ruleBody: {
    marginTop: 2,
    fontSize: 13,
    lineHeight: 18,
    color: colors.muted,
    fontFamily: fonts.sans,
  },
  ruleMeta: {
    marginTop: 4,
    fontSize: 12,
    color: colors.goldDark,
    fontFamily: fonts.sansSemiBold,
  },
});
