export type EventPaymentParticipant = {
  id: string;
  name: string;
  email: string;
  image: string | null;
  feeAmount: number;
  feeSymbol: string;
  totalDue: number;
  amountPaid: number;
  pendingAmount: number;
  remaining: number;
  paid: boolean;
  popUrl: string | null;
  paidAt: string | null;
  bringingPartner?: boolean;
  partner?: { fullName: string; phone: string; dob?: string; email?: string } | null;
  payments: PaymentEntry[];
};

export type PaymentEntry = {
  _id?: string | null;
  amount: number;
  popUrl?: string | null;
  note?: string | null;
  paidAt?: string | null;
  recordedBy?: string | null;
  status?: "pending" | "approved";
};

function HeroImage({ uri, style }: { uri: string; style?: any }) {
  return <RNImage source={{ uri }} style={style} contentFit="cover" />;
}

/** Pick a proof-of-payment image from the library and upload it to storage. */
export async function pickPopImage(): Promise<string | null> {
  const result = await ImagePicker.launchImageLibraryAsync({
    mediaTypes: ImagePicker.MediaTypeOptions.Images,
    allowsEditing: true,
    quality: 0.7,
    base64: true,
  });
  if (result.canceled || !result.assets?.length) return null;
  const asset = result.assets[0];
  const { uploadEventPop } = await import("@/services/cloudinary");
  return uploadEventPop({
    uri: asset.uri,
    base64: asset.base64 ?? null,
    mimeType: asset.mimeType,
  });
}

export function formatPayDate(value?: string | null): string {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-ZA", { day: "numeric", month: "short" });
}

/**
 * Inline payment form: amount input + optional POP upload, then record.
 * Used both by attendees making a payment and by owners/admin recording one
 * on behalf of an attendee.
 */
export function PaymentFormInline({
  feeSymbol,
  remaining,
  busy,
  submitLabel = "Record payment",
  onRecord,
  onCancel,
}: {
  feeSymbol: string;
  remaining: number;
  busy: boolean;
  submitLabel?: string;
  onRecord: (amount: number, popUrl: string | null) => void;
  onCancel?: () => void;
}) {
  const [amount, setAmount] = useState("");
  const [popUrl, setPopUrl] = useState<string | null>(null);
  const [popBusy, setPopBusy] = useState(false);

  const pick = async () => {
    setPopBusy(true);
    try {
      const url = await pickPopImage();
      if (url) setPopUrl(url);
    } catch (err) {
      Alert.alert(
        "Upload failed",
        err instanceof Error ? err.message : "Could not upload your proof of payment.",
      );
    } finally {
      setPopBusy(false);
    }
  };

  const submit = () => {
    const value = parseFloat(amount.replace(/,/g, "."));
    if (!Number.isFinite(value) || value <= 0) {
      Alert.alert("Amount needed", "Enter an amount greater than zero.");
      return;
    }
    onRecord(Math.round(value * 100) / 100, popUrl);
  };

  return (
    <View style={styles.payForm}>
      <View style={styles.payFormRow}>
        <View style={styles.payAmountBox}>
          <Text style={styles.paySymbol}>{feeSymbol || ""}</Text>
          <TextInput
            style={styles.payAmountInput}
            value={amount}
            onChangeText={setAmount}
            keyboardType="decimal-pad"
            placeholder="0"
            placeholderTextColor={colors.muted}
          />
        </View>
        <TouchableOpacity
          style={[
            styles.payFormPick,
            popUrl ? styles.payFormPickDone : null,
          ]}
          onPress={pick}
          disabled={popBusy}
          activeOpacity={0.8}
          accessibilityLabel="Attach proof of payment"
        >
          {popBusy ? (
            <ActivityIndicator size="small" color={colors.forest} />
          ) : popUrl ? (
            <>
              <Ionicons name="checkmark-circle" size={13} color="#10b981" />
              <Text style={[styles.payFormPickText, { color: "#10b981" }]}>
                POP attached
              </Text>
            </>
          ) : (
            <>
              <Ionicons
                name="cloud-upload-outline"
                size={13}
                color={colors.forest}
              />
              <Text style={styles.payFormPickText}>POP</Text>
            </>
          )}
        </TouchableOpacity>
      </View>
      {remaining > 0 ? (
        <Text style={styles.payFormHint}>
          Remaining balance: {formatFee(feeSymbol, remaining)}
        </Text>
      ) : null}
      <View style={styles.payFormBtns}>
        {onCancel ? (
          <TouchableOpacity
            style={styles.payFormGhost}
            onPress={onCancel}
            activeOpacity={0.8}
          >
            <Text style={styles.payFormGhostText}>Cancel</Text>
          </TouchableOpacity>
        ) : null}
        <TouchableOpacity
          style={styles.payFormSubmit}
          onPress={submit}
          disabled={busy}
          activeOpacity={0.8}
        >
          {busy ? (
            <ActivityIndicator size="small" color={colors.white} />
          ) : (
            <Text style={styles.payFormSubmitText}>{submitLabel}</Text>
          )}
        </TouchableOpacity>
      </View>
    </View>
  );
}

/**
 * Owner/admin payment management. Renders aggregate totals across all
 * attendees, then a card per attendee: status + amounts (partners double the
 * amount due), a full-width ledger (amount · date · status · POP) and actions
 * to record a payment, settle a balance, and approve or reject self-submitted
 * (pending) payments. Designed to sit on its own screen.
 */
export function PaymentManager({
  eventId,
  feeSymbol,
}: {
  eventId: string;
  feeSymbol: string;
}) {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [recordingId, setRecordingId] = useState<string | null>(null);
  const [list, setList] = useState<EventPaymentParticipant[]>([]);
  const [query, setQuery] = useState("");

  const load = async (isRetry = false) => {
    if (isRetry) setLoading(true);
    try {
      setError(null);
      const res = await communityApi.getEventParticipants(eventId);
      setList((res?.data || []) as EventPaymentParticipant[]);
    } catch {
      setError("Could not load attendees. Check your connection and try again.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    // Initial fetch (and only that) — retries go through the Retry button.
    (async () => {
      await load();
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventId]);

  const patchRow = (id: string, patch: Partial<EventPaymentParticipant>) =>
    setList((prev) =>
      prev.map((x) => (x.id === id ? { ...x, ...patch } : x)),
    );

  const record = async (
    p: EventPaymentParticipant,
    amount: number,
    popUrl: string | null,
  ) => {
    setBusyId(p.id);
    try {
      const res = await communityApi.recordEventPayment(
        eventId,
        p.id,
        amount,
        popUrl,
      );
      const d = res?.data;
      patchRow(p.id, {
        amountPaid: d?.amountPaid ?? p.amountPaid + amount,
        pendingAmount: d?.pendingAmount ?? p.pendingAmount,
        remaining: d?.remaining ?? Math.max(0, p.remaining - amount),
        paid: d?.paid ?? p.paid,
        popUrl: popUrl ?? p.popUrl,
        payments: [
          ...(p.payments || []),
          {
            amount,
            popUrl,
            paidAt: new Date().toISOString(),
            status: d?.status ?? "approved",
          },
        ],
      });
      setRecordingId(null);
    } catch {
      Alert.alert("Error", "Failed to record payment.");
    } finally {
      setBusyId(null);
    }
  };

  const settle = async (p: EventPaymentParticipant) => {
    setBusyId(p.id);
    try {
      const res = await communityApi.settleEventPayment(eventId, p.id);
      const d = res?.data;
      patchRow(p.id, {
        amountPaid: d?.amountPaid ?? p.amountPaid + p.remaining,
        pendingAmount: d?.pendingAmount ?? p.pendingAmount,
        remaining: 0,
        paid: true,
        paidAt: new Date().toISOString(),
        payments: [
          ...(p.payments || []),
          { amount: p.remaining, paidAt: new Date().toISOString(), status: "approved" },
        ],
      });
    } catch {
      Alert.alert("Error", "Failed to settle payment.");
    } finally {
      setBusyId(null);
    }
  };

  const approve = async (
    p: EventPaymentParticipant,
    payment: PaymentEntry,
    ok: boolean,
  ) => {
    if (!payment._id) return;
    setBusyId(p.id);
    try {
      const res = await communityApi.approveEventPayment(
        eventId,
        p.id,
        payment._id,
        ok,
      );
      const d = res?.data;
      setList((prev) =>
        prev.map((x) => {
          if (x.id !== p.id) return x;
          const payments = ok
            ? x.payments.map((e) =>
                e._id === payment._id
                  ? { ...e, status: "approved" as const }
                  : e,
              )
            : x.payments.filter((e) => e._id !== payment._id);
          return {
            ...x,
            amountPaid: d?.amountPaid ?? x.amountPaid + (ok ? payment.amount : 0),
            pendingAmount: d?.pendingAmount ?? Math.max(0, x.pendingAmount - payment.amount),
            remaining: d?.remaining ?? Math.max(0, x.remaining - (ok ? payment.amount : 0)),
            paid: d?.paid ?? x.paid,
            payments,
          };
        }),
      );
    } catch {
      Alert.alert("Error", "Failed to update payment.");
    } finally {
      setBusyId(null);
    }
  };

  const viewPop = (url?: string | null) => {
    if (url) Linking.openURL(url).catch(() => {});
  };

  const q = query.trim().toLowerCase();
  const visible = q
    ? list.filter(
        (p) =>
          p.name.toLowerCase().includes(q) ||
          (p.partner?.fullName || "").toLowerCase().includes(q),
      )
    : list;

  // Totals reflect the currently visible (searched) attendees.
  const totals = visible.reduce(
    (acc, p) => ({
      totalDue: acc.totalDue + (p.totalDue || 0),
      amountPaid: acc.amountPaid + (p.amountPaid || 0),
      pendingAmount: acc.pendingAmount + (p.pendingAmount || 0),
      remaining: acc.remaining + (p.remaining || 0),
    }),
    { totalDue: 0, amountPaid: 0, pendingAmount: 0, remaining: 0 },
  );
  const fmt = (n: number) => formatFee(feeSymbol, n);
  const allPaid = totals.totalDue > 0 && totals.remaining <= 0;

  if (loading) {
    return (
      <ActivityIndicator style={styles.paySpinner} color={colors.goldDark} />
    );
  }

  if (error) {
    return (
      <View style={styles.payErrorBox}>
        <Ionicons name="cloud-offline-outline" size={22} color={colors.muted} />
        <Text style={styles.payErrorText}>{error}</Text>
        <TouchableOpacity
          style={styles.payRetryBtn}
          onPress={() => load(true)}
          activeOpacity={0.8}
        >
          <Text style={styles.payRetryText}>Try again</Text>
        </TouchableOpacity>
      </View>
    );
  }

  if (list.length === 0) {
    return (
      <Text style={styles.payEmpty}>No attendees yet.</Text>
    );
  }

  return (
    <View style={styles.payList}>
      <View style={styles.paySearch}>
        <Ionicons name="search" size={15} color={colors.muted} />
        <TextInput
          style={styles.paySearchInput}
          value={query}
          onChangeText={setQuery}
          placeholder="Search attendees"
          placeholderTextColor={colors.muted}
          autoCapitalize="none"
          autoCorrect={false}
          returnKeyType="search"
        />
        {query.length > 0 ? (
          <TouchableOpacity
            onPress={() => setQuery("")}
            hitSlop={8}
            accessibilityLabel="Clear search"
          >
            <Ionicons name="close-circle" size={16} color={colors.muted} />
          </TouchableOpacity>
        ) : null}
      </View>

      {visible.length === 0 ? (
        <Text style={styles.payEmpty}>
          No attendees match {`\u201C${query.trim()}\u201D`}
        </Text>
      ) : (
        <>
          <View style={styles.payTotals}>
            <Text style={styles.payTotalsLine}>
              Collected{" "}
              <Text style={styles.payTotalsStrong}>{fmt(totals.amountPaid)}</Text>{" "}
              of{" "}
              <Text style={styles.payTotalsStrong}>{fmt(totals.totalDue)}</Text>
            </Text>
            {totals.pendingAmount > 0 ? (
              <Text style={styles.payTotalsPending}>
                + {fmt(totals.pendingAmount)} pending approval
              </Text>
            ) : null}
            <Text
              style={[
                styles.payTotalsLine,
                allPaid
                  ? styles.payTotalsAllPaid
                  : styles.payTotalsRemaining,
              ]}
            >
              {allPaid
                ? "All attendees settled"
                : `${fmt(totals.remaining)} left`}
            </Text>
          </View>

          {visible.map((p) => {
        const active = recordingId === p.id;
        return (
          <View
            key={p.id}
            style={[
              styles.payRowBlock,
              active ? styles.payRowBlockActive : null,
            ]}
          >
            <View style={styles.payRowHeader}>
              {p.image ? (
                <View style={styles.attendeeAvatarWrap}>
                  <HeroImage
                    uri={getOptimizedImageUrl(p.image, 160)}
                    style={styles.attendeeAvatar}
                  />
                </View>
              ) : (
                <LinearGradient
                  colors={[colors.forestSoft, colors.forestDark]}
                  style={[
                    styles.attendeeAvatar,
                    styles.attendeeAvatarFallback,
                  ]}
                >
                  <Text style={styles.attendeeAvatarText}>
                    {(p.name || "?")[0].toUpperCase()}
                  </Text>
                </LinearGradient>
              )}
              <View style={styles.attendeeInfo}>
                <Text style={styles.attendeeName} numberOfLines={1}>
                  {p.name}
                </Text>
                {p.bringingPartner && p.partner?.fullName ? (
                  <Text style={styles.payPartner} numberOfLines={1}>
                    + {p.partner.fullName} · partner
                  </Text>
                ) : null}
                <View style={styles.payRowMeta}>
                  <View
                    style={[
                      styles.payDot,
                      p.paid ? styles.payDotOn : styles.payDotPending,
                    ]}
                  />
                  <Text
                    style={[
                      styles.payRowStatus,
                      p.paid
                        ? styles.payRowStatusOn
                        : styles.payRowStatusPending,
                    ]}
                  >
                    {p.paid ? "PAID" : `${fmt(p.remaining)} LEFT`}
                  </Text>
                  {p.pendingAmount > 0 ? (
                    <Text style={styles.payPendingBadge}>
                      {fmt(p.pendingAmount)} PENDING
                    </Text>
                  ) : null}
                </View>
                <Text style={styles.payRowAmount}>
                  {fmt(p.amountPaid)} of {fmt(p.totalDue || p.feeAmount)}
                </Text>
              </View>
              <View style={styles.payActions}>
                {p.remaining > 0 ? (
                  <TouchableOpacity
                    style={[styles.payActionBtn, styles.payActionBtnPaid]}
                    onPress={() => settle(p)}
                    disabled={busyId === p.id}
                    activeOpacity={0.8}
                  >
                    {busyId === p.id ? (
                      <ActivityIndicator size="small" color={colors.white} />
                    ) : (
                      <Text style={styles.payActionText}>Settle</Text>
                    )}
                  </TouchableOpacity>
                ) : null}
                <TouchableOpacity
                  style={[
                    styles.payActionGhost,
                    active ? styles.payActionGhostActive : null,
                  ]}
                  onPress={() => setRecordingId(active ? null : p.id)}
                  disabled={busyId === p.id}
                  activeOpacity={0.8}
                >
                  <Ionicons
                    name={
                      active ? "close-circle-outline" : "add-circle-outline"
                    }
                    size={13}
                    color={colors.forest}
                  />
                  <Text style={styles.payActionGhostText}>
                    {active ? "Close" : "Record"}
                  </Text>
                </TouchableOpacity>
              </View>
            </View>

            {active ? (
              <PaymentFormInline
                feeSymbol={feeSymbol || p.feeSymbol}
                remaining={p.remaining}
                busy={busyId === p.id}
                onRecord={(amount, popUrl) => record(p, amount, popUrl)}
                onCancel={() => setRecordingId(null)}
              />
            ) : null}

            {(p.payments || []).length > 0 ? (
              <View style={styles.payLedger}>
                {p.payments.map((pay, i) => {
                  const pending = pay.status === "pending";
                  return (
                    <View
                      key={i}
                      style={[
                        styles.payLedgerEntry,
                        pending ? styles.payLedgerEntryPending : null,
                      ]}
                    >
                      <View style={styles.payLedgerMain}>
                        <Text style={styles.payLedgerAmount}>
                          +{fmt(pay.amount)}
                          {pay.note ? ` · ${pay.note}` : ""}
                        </Text>
                        <Text style={styles.payLedgerDate}>
                          {formatPayDate(pay.paidAt)}
                        </Text>
                      </View>
                      <View style={styles.payLedgerSide}>
                        <View
                          style={[
                            styles.payStatusChip,
                            pending
                              ? styles.payStatusChipPending
                              : styles.payStatusChipApproved,
                          ]}
                        >
                          <Text
                            style={[
                              styles.payStatusChipText,
                              {
                                color: pending ? "#b45309" : "#10b981",
                              },
                            ]}
                          >
                            {pending ? "PENDING" : "APPROVED"}
                          </Text>
                        </View>
                        {pay.popUrl ? (
                          <TouchableOpacity
                            onPress={() => viewPop(pay.popUrl)}
                            activeOpacity={0.7}
                            hitSlop={6}
                          >
                            <Text style={styles.payPopLink}>VIEW POP</Text>
                          </TouchableOpacity>
                        ) : null}
                        {pending ? (
                          <>
                            <TouchableOpacity
                              style={styles.payApproveBtn}
                              onPress={() => approve(p, pay, true)}
                              disabled={busyId === p.id}
                              activeOpacity={0.8}
                            >
                              <Text style={styles.payApproveText}>Approve</Text>
                            </TouchableOpacity>
                            <TouchableOpacity
                              style={styles.payRejectBtn}
                              onPress={() => approve(p, pay, false)}
                              disabled={busyId === p.id}
                              activeOpacity={0.8}
                            >
                              <Text style={styles.payRejectText}>Reject</Text>
                            </TouchableOpacity>
                          </>
                        ) : null}
                      </View>
                    </View>
                  );
                })}
              </View>
            ) : null}
          </View>
          );
        })}
        </>
      )}
    </View>
  );
}

