/**
 * In-app reader for a magazine/bulletin, plus the guided study-guide reader.
 *
 * Study guides (`weeks.length > 0`) page through the season one week at a
 * time: a cover page, then a page per week with its intro and a list of the
 * seven calendar-locked daily reads. Tapping a day opens the guided Day read
 * (Verse → Read → Reflect → Respond) in /library/[slug]/day.
 *
 * Everything else reads as one continuous article.
 */

type Page =
  | { kind: "cover" }
  | { kind: "week"; week: StudyWeek };

function buildPages(isStudyGuide: boolean, weeks: StudyWeek[]): Page[] {
  if (!isStudyGuide) return [{ kind: "cover" }];
  return [
    { kind: "cover" },
    ...weeks.map((week): Page => ({ kind: "week", week })),
  ];
}

function ReaderSkeleton({ width }: { width: number }) {
  return (
    <View style={{ flex: 1, backgroundColor: colors.bg }}>
      <SkeletonPulse style={{ width, height: width * 0.7, borderRadius: 0 }} />
      <View style={{ paddingHorizontal: 24, paddingTop: 24, gap: 12 }}>
        <SkeletonPulse style={{ width: 90, height: 12 }} />
        <SkeletonPulse style={{ width: "75%", height: 26 }} />
        <SkeletonPulse style={{ width: "50%", height: 13 }} />
        <SkeletonPulse style={{ width: "100%", height: 13, marginTop: 8 }} />
        <SkeletonPulse style={{ width: "85%", height: 13 }} />
        <SkeletonPulse style={{ width: "90%", height: 16, marginTop: 16 }} />
        <SkeletonPulse style={{ width: "70%", height: 16 }} />
      </View>
    </View>
  );
}

function formatDayDate(date: string) {
  try {
    const d = new Date(`${date}T00:00:00`);
    if (isNaN(d.getTime())) return "";
    return d.toLocaleDateString(undefined, { day: "numeric", month: "short" });
  } catch {
    return "";
  }
}

const SHORT_WEEKDAYS: Record<string, string> = {
  Sunday: "Sun",
  Monday: "Mon",
  Tuesday: "Tue",
  Wednesday: "Wed",
  Thursday: "Thu",
  Friday: "Fri",
  Saturday: "Sat",
};

function shortWeekday(name: string) {
  return SHORT_WEEKDAYS[name] || name;
}

/** "1 – 7 Sep" for a same-month week, "30 Sep – 6 Oct" across a month. */
function formatWeekRange(days: DailyStudyRead[]) {
  if (!days?.length) return "";
  const first = new Date(`${days[0].date}T00:00:00`);
  const last = new Date(`${days[days.length - 1].date}T00:00:00`);
  if (isNaN(first.getTime()) || isNaN(last.getTime())) return "";
  const dayF = first.getDate();
  const dayL = last.getDate();
  const monthF = first.toLocaleDateString(undefined, { month: "short" });
  const monthL = last.toLocaleDateString(undefined, { month: "short" });
  return monthF === monthL
    ? `${dayF} – ${dayL} ${monthF}`
    : `${dayF} ${monthF} – ${dayL} ${monthL}`;
}

function WeekDayCard({
  publicationId,
  weekIndex,
  dayIndex,
  weekday,
  date,
  title,
  verse,
  done,
  isToday,
}: {
  publicationId: string;
  weekIndex: number;
  dayIndex: number;
  weekday: string;
  date: string;
  title: string;
  verse?: string;
  done: boolean;
  isToday: boolean;
}) {
  return (
    <TouchableOpacity
      style={[s.dayCard, done && s.dayCardDone]}
      activeOpacity={0.8}
      onPress={() =>
        router.push({
          pathname: "/library/[slug]/day" as any,
          params: {
            slug: publicationId,
            week: String(weekIndex),
            day: String(dayIndex),
          },
        })
      }
      accessibilityLabel={`Open ${title}`}
    >
      <View style={s.dayCardLeft}>
        <Text style={[s.dayCardWeekday, isToday && s.dayCardToday]}>{shortWeekday(weekday)}</Text>
        <Text style={s.dayCardDate}>{formatDayDate(date)}</Text>
      </View>
      <View style={s.dayCardBody}>
        <Text style={[s.dayCardTitle, done && s.dayCardTitleDone]} numberOfLines={1}>
          {title}
        </Text>
        {verse ? (
          <Text style={s.dayCardVerse} numberOfLines={1}>
            {verse}
          </Text>
        ) : null}
        {isToday ? (
          <View style={s.todayChip}>
            <Text style={s.todayChipText}>Today</Text>
          </View>
        ) : null}
      </View>
      {done ? (
        <Ionicons name="checkmark-circle" size={20} color={colors.success} />
      ) : (
        <Ionicons name="chevron-forward" size={18} color={colors.muted} />
      )}
    </TouchableOpacity>
  );
}

export default function ReadingDetailScreen() {
  const { slug } = useLocalSearchParams<{ slug?: string }>();
  const { width } = useWindowDimensions();
  const [publication, setPublication] = useState<Publication | undefined>();
  const [loading, setLoading] = useState(true);
  const [readDays, setReadDays] = useState<string[]>([]);
  const { club, loading: clubsLoading, error: clubsError } = useClub(publication?.clubSlug);

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const p = await fetchPublication(slug);
        if (alive) setPublication(p);
        if (p && p.weeks?.length) {
          setReadDays(await fetchReadingDays());
        }
      } catch {
      } finally {
        if (alive) setLoading(false);
      }
    })();
    return () => {
      alive = false;
    };
  }, [slug]);

  const isStudyGuide = (publication?.weeks?.length ?? 0) > 0;
  const weeks = publication?.weeks || [];
  const pages: Page[] = buildPages(isStudyGuide, weeks);
  const [page, setPage] = useState(0);

  if (loading || clubsLoading) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <ReaderSkeleton width={width} />
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (!publication) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <View style={s.notFound}>
            <Ionicons name="alert-circle-outline" size={40} color={colors.muted} />
            <Text style={s.notFoundText}>Publication not found</Text>
            <TouchableOpacity style={s.backBtn} onPress={() => router.back()}>
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Ionicons name="chevron-back" size={18} color={colors.white} />
              <Text style={s.backBtnText}>Go back</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (clubsError) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <View style={s.notFound}>
            <Ionicons name="alert-circle-outline" size={40} color={colors.muted} />
            <Text style={s.notFoundText}>{clubsError}</Text>
            <TouchableOpacity style={s.backBtn} onPress={() => router.back()}>
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Ionicons name="chevron-back" size={18} color={colors.white} />
              <Text style={s.backBtnText}>Go back</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const accent = club?.colorDark || colors.forest;
  const eyebrow =
    publication.kind === "bulletin"
      ? club
        ? `${club.name} Bulletin`
        : "Relate Bulletin"
      : publication.series || "Relate";
  const meta =
    publication.season?.label ||
    `${publication.month} ${publication.year} · ${publication.issue}`;
  const coverLines = publication.coverLines ?? [];
  const primaryLine = coverLines[0];
  const secondaryLines = coverLines.slice(1, 3);
  const sectionTitle = publication.theme || publication.title;
  const todayKey = getTodayKey();
  const doneSet = new Set(readDays);

  const weekNumber = isStudyGuide ? page : 0;
  const pagerLabel = isStudyGuide
    ? `${publication.season?.name || "Season"} · Week ${weekNumber} of ${weeks.length}`
    : "";

  const renderBlock = (b: Publication["blocks"][number], i: number) => {
    switch (b.type) {
      case "heading":
        return (
          <Text key={i} style={[s.heading, { color: accent }]}>
            {b.text}
          </Text>
        );
      case "quote":
        return (
          <View key={i} style={[s.quote, { borderLeftColor: accent }]}>
            <Text style={s.quoteText}>“{b.text}”</Text>
            {b.by ? <Text style={s.quoteBy}>— {b.by}</Text> : null}
          </View>
        );
      case "image":
        return (
          <View key={i} style={s.imageWrap}>
            <Image
              source={{ uri: getOptimizedImageUrl(b.uri, 720) }}
              style={s.image}
              contentFit="cover"
              transition={300}
              recyclingKey={`pub-${i}`}
            />
            {b.caption ? <Text style={s.caption}>{b.caption}</Text> : null}
          </View>
        );
      case "list":
        return (
          <View key={i} style={s.list}>
            {b.items.map((item, j) => (
              <View key={j} style={s.listRow}>
                <View style={[s.listDot, { backgroundColor: accent }]} />
                <Text style={s.listText}>{item}</Text>
              </View>
            ))}
          </View>
        );
      default:
        return "text" in b ? (
          <Text key={i} style={s.paragraph}>
            {b.text}
          </Text>
        ) : null;
    }
  };

  const renderPage = ({ item, index }: { item: Page; index: number }) => {
    const isCoverPage = item.kind === "cover";
    return (
      <View style={{ width }}>
        <ScrollView
          contentContainerStyle={[
            s.pageContent,
            isCoverPage ? { paddingBottom: 40 } : { paddingTop: 64, paddingBottom: 40 },
          ]}
          showsVerticalScrollIndicator={false}
        >
          {isCoverPage ? (
            <>
              <View style={[s.coverWrap, { width }]}>
                <MagazineCover publication={publication} />
              </View>
              <View style={s.header}>
                <Text style={[s.eyebrow, { color: accent }]}>{eyebrow}</Text>
                <Text style={s.title}>{sectionTitle}</Text>
                <Text style={[s.meta, { color: accent }]}>{meta}</Text>

                {primaryLine ? <Text style={s.lead}>{primaryLine}</Text> : null}
                {secondaryLines.map((line, i) => (
                  <View key={i} style={s.secondaryRow}>
                    <View style={[s.secondaryDot, { backgroundColor: accent }]} />
                    <Text style={s.secondaryLine} numberOfLines={1}>
                      {line}
                    </Text>
                  </View>
                ))}

                <Text style={s.summary}>{publication.summary}</Text>
              </View>
              {publication.blocks.map(renderBlock)}
            </>
          ) : (
            <WeekPage
              week={item.week}
              weekIndex={item.week.index - 1}
              publicationId={publication.id}
              accent={accent}
              doneSet={doneSet}
              todayKey={todayKey}
            />
          )}
        </ScrollView>
      </View>
    );
  };

  const onMomentumScrollEnd = (e: any) => {
    const index = Math.round(e.nativeEvent.contentOffset.x / width);
    setPage(index);
  };

  return (
    <SafeAreaProvider>
      <SafeAreaView style={s.safe} edges={["top", "bottom"]}>
        <StatusBar style="dark" />

        <FlatList
          style={s.pager}
          data={pages}
          horizontal
          pagingEnabled
          showsHorizontalScrollIndicator={false}
          keyExtractor={(_, i) => String(i)}
          getItemLayout={(_, index) => ({
            length: width,
            offset: width * index,
            index,
          })}
          onMomentumScrollEnd={onMomentumScrollEnd}
          renderItem={renderPage}
        />

        {pages.length > 1 ? (
          <View style={s.pagerBar}>
            <Text style={[s.pagerLabel, { color: accent }]}>{pagerLabel}</Text>
            <View style={s.dots}>
              {pages.map((_, i) => (
                <View
                  key={i}
                  style={[s.dot, i === page && { backgroundColor: accent }]}
                />
              ))}
            </View>
          </View>
        ) : null}

        <TouchableOpacity
          style={s.floatBack}
          activeOpacity={0.85}
          onPress={() => router.back()}
          accessibilityLabel="Go back"
        >
          <Ionicons name="chevron-back" size={20} color={colors.white} />
        </TouchableOpacity>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

function WeekPage({
  week,
  weekIndex,
  publicationId,
  accent,
  doneSet,
  todayKey,
}: {
  week: StudyWeek;
  weekIndex: number;
  publicationId: string;
  accent: string;
  doneSet: Set<string>;
  todayKey: string;
}) {
  const dash = week.title.indexOf("—");
  const eyebrow = dash !== -1 ? week.title.slice(0, dash).trim() : "";
  const main = dash !== -1 ? week.title.slice(dash + 1).trim() : week.title;

  return (
    <>
      <View style={s.weekHead}>
        {eyebrow ? (
          <Text style={[s.weekEyebrow, { color: accent }]}>{eyebrow.toUpperCase()}</Text>
        ) : null}
        <Text style={s.weekRange}>{formatWeekRange(week.days)}</Text>
        <Text style={s.chapterTitle}>{main}</Text>
        {week.theme ? <Text style={s.weekTheme}>{week.theme}</Text> : null}
      </View>

      {week.intro.map(renderWeekBlock)}

      <Text style={[s.dayListLabel, { color: accent }]}>THIS WEEK</Text>
      <View style={s.dayList}>
        {week.days.map((day, dayIndex) => (
          <WeekDayCard
            key={day.date}
            publicationId={publicationId}
            weekIndex={weekIndex}
            dayIndex={dayIndex}
            weekday={day.weekday}
            date={day.date}
            title={day.title}
            verse={day.verse?.text}
            done={doneSet.has(day.date)}
            isToday={day.date === todayKey}
          />
        ))}
      </View>
    </>
  );
}

function renderWeekBlock(b: Publication["blocks"][number], i: number) {
  switch (b.type) {
    case "heading":
      return (
        <Text key={i} style={s.heading}>
          {b.text}
        </Text>
      );
    case "quote":
      return (
        <View key={i} style={[s.quote, { borderLeftColor: colors.gold }]}>
          <Text style={s.quoteText}>“{b.text}”</Text>
          {b.by ? <Text style={s.quoteBy}>— {b.by}</Text> : null}
        </View>
      );
    case "list":
      return (
        <View key={i} style={s.list}>
          {b.items.map((item, j) => (
            <View key={j} style={s.listRow}>
              <View style={[s.listDot, { backgroundColor: colors.gold }]} />
              <Text style={s.listText}>{item}</Text>
            </View>
          ))}
        </View>
      );
    default:
      return "text" in b ? (
        <Text key={i} style={s.paragraph}>
          {b.text}
        </Text>
      ) : null;
  }
}

