const fmtDate = (value?: string) => {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-ZA", {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
};

type Tab = "applications" | "offices";

const TABS: { key: Tab; label: string }[] = [
  { key: "applications", label: "Applications" },
  { key: "offices", label: "Offices" },
];

function PostOfficeModal({
  visible,
  onClose,
  onCreated,
}: {
  visible: boolean;
  onClose: () => void;
  onCreated: () => void;
}) {
  const insets = useSafeAreaInsets();
  const officeDraftKey = "form-draft:admin:office";
  const [title, setTitle] = usePersistentFormState(`${officeDraftKey}:title`, "");
  const [description, setDescription] = usePersistentFormState(`${officeDraftKey}:description`, "");
  const [responsibilities, setResponsibilities] = usePersistentFormState(`${officeDraftKey}:responsibilities`, "");
  const [qualifications, setQualifications] = usePersistentFormState(`${officeDraftKey}:qualifications`, "");
  const [applicationQuestions, setApplicationQuestions] = usePersistentFormState(`${officeDraftKey}:questions`, "");
  const [area, setArea] = usePersistentFormState<string | null>(`${officeDraftKey}:area`, null);
  const [clubSlug, setClubSlug] = usePersistentFormState<string | null>(`${officeDraftKey}:clubSlug`, null);
  const [busy, setBusy] = useState(false);

  const reset = () => {
    setTitle("");
    setDescription("");
    setResponsibilities("");
    setQualifications("");
    setApplicationQuestions("");
    setArea(null);
    setClubSlug(null);
  };

  const submit = async () => {
    if (!title.trim() || !description.trim()) {
      Alert.alert("Missing details", "Add a title and description.");
      return;
    }
    setBusy(true);
    try {
      await officesApi.create({
        title: title.trim(),
        description: description.trim(),
        responsibilities: responsibilities.trim() || null,
        qualifications: qualifications.trim() || null,
        applicationQuestions: applicationQuestions.trim() || null,
        area,
        clubSlug,
      });
      await clearPersistentFormDraft(officeDraftKey);
      reset();
      onClose();
      onCreated();
    } catch (e: any) {
      Alert.alert("Could not post", e?.message || "Please try again.");
    }
    setBusy(false);
  };

  return (
    <Modal visible={visible} transparent animationType="slide" onRequestClose={onClose}>
      <View style={[styles.sheetBackdrop, { paddingTop: insets.top }]}>
        <KeyboardAvoidingView
          behavior={Platform.OS === "ios" ? "padding" : "height"}
          style={{ width: "100%" }}
        >
          <View style={[styles.sheet, { paddingBottom: insets.bottom + 16 }]}>
            <View style={styles.sheetHead}>
              <Text style={styles.sheetTitle}>Post a volunteer office</Text>
              <TouchableOpacity onPress={onClose} style={styles.sheetClose}>
                <Ionicons name="close" size={18} color={colors.muted} />
              </TouchableOpacity>
            </View>

            <ScrollView keyboardShouldPersistTaps="handled" showsVerticalScrollIndicator={false}>
              <Text style={styles.fieldLabel}>Title</Text>
              <TextInput
                style={styles.input}
                value={title}
                onChangeText={setTitle}
                placeholder="e.g. Kids Club Coordinator"
                placeholderTextColor={colors.muted}
              />

              <Text style={styles.fieldLabel}>Description</Text>
              <TextInput
                style={[styles.input, styles.textarea]}
                value={description}
                onChangeText={setDescription}
                multiline
                placeholder="What the office involves, time commitment, and who it suits."
                placeholderTextColor={colors.muted}
              />

              <Text style={styles.fieldLabel}>Responsibilities (optional)</Text>
              <TextInput
                style={[styles.input, styles.textarea]}
                value={responsibilities}
                onChangeText={setResponsibilities}
                multiline
                placeholder={"One point per line, e.g.\nRun the weekly kids session\nMentor two new leaders"}
                placeholderTextColor={colors.muted}
              />

              <Text style={styles.fieldLabel}>Qualifications (optional)</Text>
              <TextInput
                style={[styles.input, styles.textarea]}
                value={qualifications}
                onChangeText={setQualifications}
                multiline
                placeholder={"One point per line, e.g.\nLoves working with children\nAvailable on Saturday mornings"}
                placeholderTextColor={colors.muted}
              />

              <Text style={styles.fieldLabel}>Application questions (optional)</Text>
              <TextInput
                style={[styles.input, styles.textarea]}
                value={applicationQuestions}
                onChangeText={setApplicationQuestions}
                multiline
                placeholder={"One question per line, e.g.\nWhy do you want this office?\nWhat relevant experience do you have?"}
                placeholderTextColor={colors.muted}
              />

              <Text style={styles.fieldLabel}>Area (optional)</Text>
              <View style={styles.chipRow}>
                {VOLUNTEER_AREA_OPTIONS.map((option) => {
                  const active = area === option;
                  return (
                    <TouchableOpacity
                      key={option}
                      style={[styles.chip, active && styles.chipActive]}
                      activeOpacity={0.8}
                      onPress={() => setArea(active ? null : option)}
                    >
                      {active && (
                        <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                      )}
                      <Text style={[styles.chipText, active && styles.chipTextActive]}>
                        {option}
                      </Text>
                    </TouchableOpacity>
                  );
                })}
              </View>

              <Text style={styles.fieldLabel}>Club (optional)</Text>
              <View style={styles.chipRow}>
                <TouchableOpacity
                  style={[styles.chip, !clubSlug && styles.chipActive]}
                  activeOpacity={0.8}
                  onPress={() => setClubSlug(null)}
                >
                  {!clubSlug && (
                    <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                  )}
                  <Text style={[styles.chipText, !clubSlug && styles.chipTextActive]}>
                    Whole community
                  </Text>
                </TouchableOpacity>
                {CLUBS.filter((c) => c.slug !== "sprout").map((club) => {
                  const active = clubSlug === club.slug;
                  return (
                    <TouchableOpacity
                      key={club.slug}
                      style={[styles.chip, active && styles.chipActive]}
                      activeOpacity={0.8}
                      onPress={() => setClubSlug(active ? null : club.slug)}
                    >
                      {active && (
                        <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                      )}
                      <Text style={[styles.chipText, active && styles.chipTextActive]}>
                        {club.name}
                      </Text>
                    </TouchableOpacity>
                  );
                })}
              </View>
              <TouchableOpacity
                style={[styles.primaryBtn, busy && styles.btnDisabled]}
                onPress={submit}
                disabled={busy}
                activeOpacity={0.9}
              >
                {busy ? (
                  <ActivityIndicator color={colors.forestDark} />
                ) : (
                  <>
                    <Text style={styles.primaryBtnText}>Post office</Text>
                    <Ionicons name="arrow-forward" size={16} color={colors.forestDark} />
                  </>
                )}
              </TouchableOpacity>
            </ScrollView>
          </View>
        </KeyboardAvoidingView>
      </View>
    </Modal>
  );
}

export default function OfficesAdminScreen() {
  const [authorized, setAuthorized] = useState(false);
  const [checking, setChecking] = useState(true);
  const [tab, setTab] = useState<Tab>("applications");
  const [applications, setApplications] = useState<OfficeApplication[] | null>(null);
  const [offices, setOffices] = useState<VolunteerOffice[] | null>(null);
  const [error, setError] = useState("");
  const [refreshing, setRefreshing] = useState(false);
  const [busy, setBusy] = useState(false);
  const [postOpen, setPostOpen] = useState(false);

  const load = useCallback(async () => {
    try {
      const [appsRes, officesRes] = await Promise.all([
        officesApi.applications(),
        officesApi.list(),
      ]);
      setApplications(appsRes.data);
      setOffices(officesRes.data);
      setError("");
    } catch (e: any) {
      setError(e?.message || "Network error — could not reach the server.");
    }
  }, []);

  useEffect(() => {
    (async () => {
      const session = await getSession();
      if (!session?.user || session.user.role !== "admin") {
        setAuthorized(false);
        setChecking(false);
        return;
      }
      setAuthorized(true);
      await load();
      setChecking(false);
    })();
  }, [load]);

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    await load();
    setRefreshing(false);
  }, [load]);

  const run = async (label: string, action: () => Promise<unknown>) => {
    setBusy(true);
    try {
      await action();
      await load();
    } catch (e: any) {
      Alert.alert(label + " failed", e?.message || "Please try again.");
    }
    setBusy(false);
  };

  const reviewApplication = (app: OfficeApplication, action: "approve" | "reject") => {
    const isApprove = action === "approve";
    Alert.alert(
      isApprove ? "Approve application?" : "Reject application?",
      isApprove
        ? `${app.name} gets the "${app.office?.title || app.officeTitle}" office and it moves to filled.`
        : `${app.name}'s application will be marked as not approved. They can apply again later.`,
      [
        { text: "Cancel", style: "cancel" },
        {
          text: isApprove ? "Approve" : "Reject",
          style: isApprove ? "default" : "destructive",
          onPress: () =>
            run("Review", () => officesApi.review(app._id, action)),
        },
      ],
    );
  };

  const officeAction = (
    office: VolunteerOffice,
    action: "reopen" | "close",
  ) => {
    const label = action === "reopen" ? "Reopen" : "Close";
    Alert.alert(
      `${label} office?`,
      action === "reopen"
        ? `"${office.title}" goes back to the open list.`
        : `"${office.title}" is archived and hidden from members.`,
      [
        { text: "Cancel", style: "cancel" },
        {
          text: label,
          style: action === "close" ? "destructive" : "default",
          onPress: () => run(label, () => officesApi.update(office._id, { action })),
        },
      ],
    );
  };

  const removeOffice = (office: VolunteerOffice) => {
    Alert.alert(
      "Delete office?",
      `"${office.title}" and all its applications will be removed permanently.`,
      [
        { text: "Cancel", style: "cancel" },
        {
          text: "Delete",
          style: "destructive",
          onPress: () => run("Delete", () => officesApi.remove(office._id)),
        },
      ],
    );
  };

  if (checking) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <View style={styles.center}>
            <ActivityIndicator color={colors.goldDark} />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (!authorized) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <View style={styles.center}>
            <Ionicons name="lock-closed-outline" size={40} color={colors.muted} />
            <Text style={styles.deniedTitle}>Admin access required</Text>
            <Text style={styles.deniedText}>
              Only Relate administrators can manage volunteer offices.
            </Text>
            <TouchableOpacity
              onPress={() => router.back()}
              style={styles.deniedBack}
              activeOpacity={0.85}
            >
              <Text style={styles.deniedBackText}>Go back</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const pendingApplications = (applications || []).filter(
    (a) => a.status === "pending",
  );
  const reviewedApplications = (applications || []).filter(
    (a) => a.status !== "pending",
  );

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.header}>
          <TouchableOpacity onPress={() => router.back()} style={styles.closeBtn}>
            <Ionicons name="close" size={20} color={colors.darkGreen} />
          </TouchableOpacity>
          <Text style={styles.headerTitle}>Volunteer offices</Text>
          <TouchableOpacity
            onPress={() => setPostOpen(true)}
            style={styles.addBtn}
            accessibilityLabel="Post an office"
          >
            <Ionicons name="add" size={22} color={colors.forest} />
          </TouchableOpacity>
        </View>

        <View style={styles.tabs}>
          {TABS.map((t) => (
            <TouchableOpacity
              key={t.key}
              style={[styles.tabBtn, tab === t.key && styles.tabBtnActive]}
              onPress={() => setTab(t.key)}
              activeOpacity={0.85}
            >
              {tab === t.key && (
                <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              )}
              <Text style={[styles.tabText, tab === t.key && styles.tabTextActive]}>
                {t.label}
              </Text>
            </TouchableOpacity>
          ))}
        </View>

        <ScrollView
          contentContainerStyle={styles.scroll}
          showsVerticalScrollIndicator={false}
          refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} />}
        >
          {error ? (
            <View style={styles.center}>
              <Ionicons name="cloud-offline-outline" size={40} color={colors.muted} />
              <Text style={styles.errorText}>{error}</Text>
            </View>
          ) : tab === "applications" ? (
            !applications ? (
              <View style={styles.center}>
                <ActivityIndicator color={colors.goldDark} />
              </View>
            ) : (
              <>
                <Text style={styles.sectionLabel}>
                  Awaiting review ({pendingApplications.length})
                </Text>
                {pendingApplications.length === 0 ? (
                  <Text style={styles.emptyText}>No pending applications.</Text>
                ) : (
                  pendingApplications.map((app) => {
                    const meta = OFFICE_APPLICATION_META[app.status];
                    return (
                      <View key={app._id} style={styles.card}>
                        <View style={styles.cardTop}>
                          <Text style={styles.cardTitle} numberOfLines={1}>
                            {app.office?.title || app.officeTitle}
                          </Text>
                          <View style={[styles.pill, { backgroundColor: meta.bg }]}>
                            <Text style={[styles.pillText, { color: meta.color }]}>
                              {meta.label}
                            </Text>
                          </View>
                        </View>
                        <Text style={styles.applicant}>
                          {app.name}
                          {app.email ? ` · ${app.email}` : ""}
                        </Text>
                        <Text style={styles.cardBody}>{app.motivation}</Text>
                        <Text style={styles.cardMeta}>Applied {fmtDate(app.createdAt)}</Text>
                        <View style={styles.actionRow}>
                          <TouchableOpacity
                            style={[styles.actionBtn, styles.actionApprove, busy && styles.btnDisabled]}
                            disabled={busy}
                            activeOpacity={0.85}
                            onPress={() => reviewApplication(app, "approve")}
                          >
                            <Ionicons name="checkmark" size={15} color={colors.forestDark} />
                            <Text style={styles.actionApproveText}>Approve</Text>
                          </TouchableOpacity>
                          <TouchableOpacity
                            style={[styles.actionBtn, styles.actionReject, busy && styles.btnDisabled]}
                            disabled={busy}
                            activeOpacity={0.85}
                            onPress={() => reviewApplication(app, "reject")}
                          >
                            <Ionicons name="close" size={15} color="#be123c" />
                            <Text style={styles.actionRejectText}>Reject</Text>
                          </TouchableOpacity>
                        </View>
                      </View>
                    );
                  })
                )}

                <Text style={styles.sectionLabel}>Reviewed ({reviewedApplications.length})</Text>
                {reviewedApplications.length === 0 ? (
                  <Text style={styles.emptyText}>Nothing reviewed yet.</Text>
                ) : (
                  reviewedApplications.map((app) => {
                    const meta = OFFICE_APPLICATION_META[app.status];
                    return (
                      <View key={app._id} style={[styles.card, styles.cardMuted]}>
                        <View style={styles.cardTop}>
                          <Text style={styles.cardTitle} numberOfLines={1}>
                            {app.office?.title || app.officeTitle}
                          </Text>
                          <View style={[styles.pill, { backgroundColor: meta.bg }]}>
                            <Text style={[styles.pillText, { color: meta.color }]}>
                              {meta.label}
                            </Text>
                          </View>
                        </View>
                        <Text style={styles.applicant}>
                          {app.name}
                          {app.email ? ` · ${app.email}` : ""}
                        </Text>
                        {app.reviewNote ? (
                          <Text style={styles.reviewNote}>Note: {app.reviewNote}</Text>
                        ) : null}
                        <Text style={styles.cardMeta}>
                          {app.reviewedAt ? `Reviewed ${fmtDate(app.reviewedAt)}` : ""}
                        </Text>
                      </View>
                    );
                  })
                )}
              </>
            )
          ) : !offices ? (
            <View style={styles.center}>
              <ActivityIndicator color={colors.goldDark} />
            </View>
          ) : offices.length === 0 ? (
            <View style={styles.center}>
              <Ionicons name="briefcase-outline" size={40} color={colors.muted} />
              <Text style={styles.emptyText}>No offices yet — post the first one.</Text>
            </View>
          ) : (
            offices.map((office) => {
              const status = OFFICE_STATUS_META[office.status];
              return (
                <TouchableOpacity
                  key={office._id}
                  style={styles.card}
                  activeOpacity={0.85}
                  onPress={() => router.push(`/offices/${office._id}`)}
                >
                  <View style={styles.cardTop}>
                    <Text style={styles.cardTitle} numberOfLines={1}>
                      {office.title}
                    </Text>
                    <View style={[styles.pill, { backgroundColor: status.bg }]}>
                      <Text style={[styles.pillText, { color: status.color }]}>
                        {status.label}
                      </Text>
                    </View>
                  </View>
                  <View style={styles.tagRow}>
                    {office.area ? (
                      <View style={styles.tag}>
                        <Text style={styles.tagText}>{office.area}</Text>
                      </View>
                    ) : null}
                    {office.clubSlug ? (
                      <View style={styles.tag}>
                        <Text style={styles.tagText}>
                          {CLUBS.find((c) => c.slug === office.clubSlug)?.name ||
                            office.clubSlug}
                        </Text>
                      </View>
                    ) : null}
                  </View>
                  <Text style={styles.cardBody} numberOfLines={3}>
                    {office.description}
                  </Text>
                  <Text style={styles.cardMeta}>Posted {fmtDate(office.createdAt)}</Text>
                  <View style={styles.actionRow}>
                    {office.status !== "open" ? (
                      <TouchableOpacity
                        style={[styles.actionBtn, styles.actionApprove, busy && styles.btnDisabled]}
                        disabled={busy}
                        activeOpacity={0.85}
                        onPress={() => officeAction(office, "reopen")}
                      >
                        <Ionicons name="refresh" size={14} color={colors.forestDark} />
                        <Text style={styles.actionApproveText}>Reopen</Text>
                      </TouchableOpacity>
                    ) : null}
                    {office.status !== "closed" ? (
                      <TouchableOpacity
                        style={[styles.actionBtn, styles.actionGhost, busy && styles.btnDisabled]}
                        disabled={busy}
                        activeOpacity={0.85}
                        onPress={() => officeAction(office, "close")}
                      >
                        <Ionicons name="archive" size={14} color={colors.muted} />
                        <Text style={styles.actionGhostText}>Close</Text>
                      </TouchableOpacity>
                    ) : null}
                    <TouchableOpacity
                      style={[styles.actionBtn, styles.actionReject, busy && styles.btnDisabled]}
                      disabled={busy}
                      activeOpacity={0.85}
                      onPress={() => removeOffice(office)}
                    >
                      <Ionicons name="trash" size={14} color="#be123c" />
                      <Text style={styles.actionRejectText}>Delete</Text>
                    </TouchableOpacity>
                  </View>
                </TouchableOpacity>
              );
            })
          )}
        </ScrollView>

        <PostOfficeModal
          visible={postOpen}
          onClose={() => setPostOpen(false)}
          onCreated={load}
        />
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

