import { useEffect, useState } from "react";
import { API_BASE } from "@/services/config";

/**
 * Sports catalogue — GET /api/sports/teams.
 *
 * Teams, squads, position slots, squad sizes and the sports director all come
 * from the backend: there is no bundled copy and deliberately no fallback, so
 * a failure surfaces as an explicit error string. Every screen reads through
 * `useSportsCatalog()` (or `fetchSportsCatalog()` from non-React code), which
 * shares one request per app session.
 *
 * The per-sport gradient/icon artwork below is presentation, not catalogue
 * data — the backend publishes no artwork — so it lives here rather than in a
 * constants file.
 */

export type RelateSport = "Football" | "Netball" | "Volleyball";

export type RelateTeam = {
  id: string;
  clubSlug: string;
  sport: RelateSport;
  name: string;
  initials: string;
  tagline: string;
  /** Squad crest — square image hosted on the web app. */
  logo?: string;
};

export type SportsDirector = {
  name: string;
  role: string;
};

export type PositionSlot = {
  /** Position name as the registration form spells it. */
  name: string;
  /** Short badge shown on an open slot (GK, CB, GS…). */
  code: string;
};

export type PlayerStat = {
  label: string;
  value: string;
};

/**
 * One row of a squad. Until somebody registers for the position it is a
 * placeholder: `name` is the position itself ("Goalkeeper") and `image` is
 * empty, so the card renders the position badge instead of a face. The
 * profile fields (age, height, bio, stats…) are only present when the
 * backend publishes a full player profile.
 */
export type Player = {
  name: string;
  position: string;
  number: number;
  /** Public photo URL of the registrant — empty while the slot is open. */
  image: string;
  badge: string;
  /** True while no player has claimed the slot. */
  placeholder: boolean;
  age?: number;
  height?: string;
  side?: string;
  hometown?: string;
  joined?: number;
  bio?: string;
  stats?: PlayerStat[];
};

export type Fixture = {
  date: string;
  time: string;
  competition: string;
  opponent: string;
  venue: string;
  home: boolean;
};

export type Coach = {
  name: string;
  role: string;
};

export type Squad = {
  coach: Coach;
  players: Player[];
  fixtures: Fixture[];
};

/** The loaded catalogue with every lookup the screens need already bound. */
export type SportsCatalog = {
  director: SportsDirector;
  sports: RelateSport[];
  teams: RelateTeam[];
  positionSlots: Record<string, PositionSlot[]>;
  squadSize: Record<string, number>;
  maxPerPosition: number;
  squads: Record<string, Squad>;
  getTeam(id: string): RelateTeam | undefined;
  teamsForSport(sport: RelateSport): RelateTeam[];
  teamsForClub(clubSlug: string): RelateTeam[];
  getSquad(teamId: string): Squad | undefined;
  findPlayer(teamId: string, slug: string): Player | undefined;
  slotsForSport(sport: RelateSport): PositionSlot[];
  positionsForSport(sport: RelateSport): PositionSlot[];
  positionCode(sport: RelateSport, position: string): string;
  playerSlug(name: string): string;
};

export const SPORTS_ERROR =
  "Teams couldn't be loaded — check your connection and try again.";

/** Origin of the web app — hosts the squad crest and sport artwork. */
const WEB_ORIGIN = "https://relateworld.org";

/** Sport-matched hero photo used by the carousel and team pages. */
export const SPORT_HERO: Record<RelateSport, string> = {
  Football: `${WEB_ORIGIN}/images/sports/hero/football.jpg`,
  Netball: `${WEB_ORIGIN}/images/sports/hero/netball.jpg`,
  Volleyball: `${WEB_ORIGIN}/images/sports/hero/volleyball.jpg`,
};

/** Sport-matched portrait shown on a player profile without a photo. */
/** Per-sport visual theme (gradient, icon, accent + hero photo). */
export const SPORT_THEME: Record<
  RelateSport,
  {
    colors: readonly [string, string];
    icon: string;
    accent: string;
    image: string;
    line: string;
  }
> = {
  Football: {
    colors: ["#13c5dd", "#1d2a4d"],
    icon: "football",
    accent: "#13c5dd",
    image: SPORT_HERO.Football,
    line: "Eleven-a-side and small-sided football — training midweek, matches at the weekend.",
  },
  Netball: {
    colors: ["#4caf50", "#1d2a4d"],
    icon: "basketball",
    accent: "#4caf50",
    image: SPORT_HERO.Netball,
    line: "Saturday netball league games and summer tournaments.",
  },
  Volleyball: {
    colors: ["#f97316", "#1d2a4d"],
    icon: "volleyball",
    accent: "#f97316",
    image: SPORT_HERO.Volleyball,
    line: "Friday court sessions and weekend tournaments — all levels welcome.",
  },
};

/** Absolute URL for a team's squad crest, or null when it has none. */
export function teamCrest(team: RelateTeam): string | null {
  return team.logo ? `${WEB_ORIGIN}${team.logo}` : null;
}

/** Full hero photo URL for a team — always the sport's own image. */
export function teamHeroPhoto(team: RelateTeam): string {
  return SPORT_HERO[team.sport] ?? SPORT_THEME[team.sport].image;
}

/** Player portrait URL — a full photo URL passes through untouched. */
export function imgDetail(id: string): string {
  if (/^https?:\/\//i.test(id)) return id;
  return `https://images.unsplash.com/${id}?w=640&h=800&fit=crop&crop=faces`;
}

/** URL-safe slug for a player's name (matches the web app). */
export function playerSlug(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

/** The raw GET /api/sports/teams body — every field optional. */
type SportsPayload = {
  director?: Partial<SportsDirector>;
  sports?: unknown;
  teams?: unknown;
  positionSlots?: unknown;
  squadSize?: unknown;
  maxPerPosition?: unknown;
  squads?: unknown;
};

function isTeam(value: unknown): value is RelateTeam {
  if (!value || typeof value !== "object") return false;
  const team = value as Partial<RelateTeam>;
  return (
    typeof team.id === "string" &&
    typeof team.name === "string" &&
    typeof team.sport === "string"
  );
}

function isSlot(value: unknown): value is PositionSlot {
  if (!value || typeof value !== "object") return false;
  const slot = value as Partial<PositionSlot>;
  return typeof slot.name === "string" && typeof slot.code === "string";
}

function isStat(value: unknown): value is PlayerStat {
  if (!value || typeof value !== "object") return false;
  const stat = value as Partial<PlayerStat>;
  return typeof stat.label === "string" && typeof stat.value === "string";
}

/** Keeps well-formed rows only — a bad row should not take a page down. */
function toPlayer(value: unknown): Player | null {
  if (!value || typeof value !== "object") return null;
  const raw = value as Partial<Player> & Record<string, unknown>;
  if (typeof raw.name !== "string") return null;
  return {
    name: raw.name,
    position: typeof raw.position === "string" ? raw.position : "",
    number: typeof raw.number === "number" ? raw.number : 0,
    image: typeof raw.image === "string" ? raw.image : "",
    badge: typeof raw.badge === "string" ? raw.badge : "",
    placeholder: raw.placeholder === true,
    ...(typeof raw.age === "number" ? { age: raw.age } : {}),
    ...(typeof raw.height === "string" ? { height: raw.height } : {}),
    ...(typeof raw.side === "string" ? { side: raw.side } : {}),
    ...(typeof raw.hometown === "string" ? { hometown: raw.hometown } : {}),
    ...(typeof raw.joined === "number" ? { joined: raw.joined } : {}),
    ...(typeof raw.bio === "string" ? { bio: raw.bio } : {}),
    ...(Array.isArray(raw.stats) ? { stats: raw.stats.filter(isStat) } : {}),
  };
}

function toSquad(value: unknown): Squad | null {
  if (!value || typeof value !== "object") return null;
  const raw = value as Partial<Squad> & { coach?: Partial<Coach> };
  return {
    coach: {
      name: raw.coach?.name ?? "",
      role: raw.coach?.role ?? "",
    },
    players: Array.isArray(raw.players)
      ? raw.players.map(toPlayer).filter((p): p is Player => p !== null)
      : [],
    fixtures: Array.isArray(raw.fixtures)
      ? (raw.fixtures.filter(
          (f) => f && typeof f === "object" && typeof f.date === "string",
        ) as Fixture[])
      : [],
  };
}

/** Shapes one API response (or an empty one) into the catalogue pages read. */
function toSportsCatalog(raw: unknown): SportsCatalog {
  const payload = (raw && typeof raw === "object" ? raw : {}) as SportsPayload;

  const teams = Array.isArray(payload.teams)
    ? payload.teams.filter(isTeam)
    : [];

  const positionSlots: Record<string, PositionSlot[]> = {};
  if (payload.positionSlots && typeof payload.positionSlots === "object") {
    for (const [sport, slots] of Object.entries(payload.positionSlots)) {
      positionSlots[sport] = Array.isArray(slots) ? slots.filter(isSlot) : [];
    }
  }

  const squadSize: Record<string, number> = {};
  if (payload.squadSize && typeof payload.squadSize === "object") {
    for (const [sport, size] of Object.entries(payload.squadSize)) {
      if (typeof size === "number") squadSize[sport] = size;
    }
  }

  const squads: Record<string, Squad> = {};
  if (payload.squads && typeof payload.squads === "object") {
    for (const [teamId, squad] of Object.entries(payload.squads)) {
      const parsed = toSquad(squad);
      if (parsed) squads[teamId] = parsed;
    }
  }

  return {
    director: {
      name: payload.director?.name ?? "",
      role: payload.director?.role ?? "",
    },
    sports: Array.isArray(payload.sports)
      ? (payload.sports.filter(
          (s) => typeof s === "string",
        ) as RelateSport[])
      : [],
    teams,
    positionSlots,
    squadSize,
    maxPerPosition:
      typeof payload.maxPerPosition === "number"
        ? payload.maxPerPosition
        : 0,
    squads,
    getTeam: (id) => teams.find((team) => team.id === id),
    teamsForSport: (sport) => teams.filter((team) => team.sport === sport),
    teamsForClub: (clubSlug) =>
      teams.filter((team) => team.clubSlug === clubSlug),
    getSquad: (teamId) => squads[teamId],
    // Open slots are not people: a placeholder row is the position itself, so
    // it never resolves to a profile — the roster API does that instead.
    findPlayer: (teamId, slug) =>
      squads[teamId]?.players.find(
        (p) => !p.placeholder && playerSlug(p.name) === slug,
      ),
    slotsForSport: (sport) => positionSlots[sport] ?? [],
    positionsForSport: (sport) => {
      const seen = new Set<string>();
      return (positionSlots[sport] ?? []).filter((slot) => {
        if (seen.has(slot.name)) return false;
        seen.add(slot.name);
        return true;
      });
    },
    positionCode: (sport, position) =>
      (positionSlots[sport] ?? []).find((slot) => slot.name === position)
        ?.code ?? "",
    playerSlug,
  };
}

/** Nothing published yet — screens render their empty state from this. */
function emptyCatalog(): SportsCatalog {
  return toSportsCatalog({});
}

let request: Promise<SportsCatalog> | null = null;

/**
 * The whole sports catalogue. One request per app session, shared by every
 * hook and `buildRoster()` call; the settled promise is released on failure
 * so the next caller can retry. Throws — callers decide how to show it, but
 * nobody silently gets substitute data.
 */
export function fetchSportsCatalog(): Promise<SportsCatalog> {
  if (!request) {
    request = fetch(`${API_BASE}/api/sports/teams`, {
      headers: { Accept: "application/json" },
    })
      .then(async (res) => {
        if (res.status === 404) return emptyCatalog();
        if (!res.ok) throw new Error(`sports api ${res.status}`);
        return toSportsCatalog(await res.json());
      })
      .catch((err: unknown) => {
        request = null;
        throw err;
      });
  }
  return request;
}

export type SportsCatalogState = {
  data: SportsCatalog | null;
  loading: boolean;
  error: string | null;
};

const LOADING: SportsCatalogState = { data: null, loading: true, error: null };

/** Set once a request succeeds, so a later mount paints without a loading tick. */
let loaded: SportsCatalogState | null = null;

/**
 * The catalogue for a screen, with loading and error spelled out.
 *
 * `data` is null until the request lands (or fails), so callers render a
 * loading state, an explicit error, or the empty catalogue the API returned —
 * never a blank crash and never substitute data.
 */
export function useSportsCatalog(): SportsCatalogState {
  const [state, setState] = useState<SportsCatalogState>(
    () => loaded ?? LOADING,
  );

  useEffect(() => {
    let cancelled = false;
    fetchSportsCatalog().then(
      (data) => {
        if (cancelled) return;
        if (!loaded) loaded = { data, loading: false, error: null };
        setState(loaded);
      },
      () => {
        if (!cancelled) {
          setState({ data: null, loading: false, error: SPORTS_ERROR });
        }
      },
    );
    return () => {
      cancelled = true;
    };
  }, []);

  return state;
}
