import { useEffect, useMemo, useState } from "react";
import { API_BASE } from "@/services/config";

/**
 * Clubs catalogue — the app's access layer for GET /api/clubs.
 *
 * The backend owns every club and Sprout class definition (Sprout → Synergy
 * plus Sprout Kids/Tweens/Teens). Screens read through the hooks below rather
 * than a bundled copy: the list starts empty, a failed request surfaces
 * `error`, and there is deliberately no bundled fallback.
 */

export type ClubPillar = "Shift" | "Sanctuary" | "Connect";

export const PILLARS: ClubPillar[] = ["Shift", "Sanctuary", "Connect"];

export type ClubProgram = {
  name: string;
  blurb: string;
  /** Which pillar this program sits under (Sprout programs stay ungrouped). */
  pillar?: ClubPillar;
  /** What a typical activity session looks like (shown on the program detail screen). */
  detail?: string;
  /** Extra fields collected when requesting help for this program. */
  helpFields?: {
    key: string;
    label: string;
    placeholder?: string;
    multiline?: boolean;
  }[];
  /** Thumbnail shown on the program card (e.g. a photo children can relate to). */
  image?: string;
};

export type Club = {
  slug: string;
  name: string;
  group: string;
  ageRange: string;
  tagline: string;
  description: string;
  color: string;
  colorDark: string;
  icon: string;
  programs: ClubProgram[];
  /** When set, this club is an age class that belongs under a parent club (e.g. Sprout's Kids/Tweens/Teens). */
  parentSlug?: string;
  /** Hero photo for this club's detail page (overrides the color gradient when set). */
  heroImage?: string;
  /** WhatsApp group invite link for this club's community. */
  whatsappGroupLink: string;
  /** Mission and vision from the foundation blueprint (clubs above Sprout). */
  mission?: string;
  vision?: string;
  /** Club-specific name for each pillar (e.g. Surge's Shift pillar = "Runway"). */
  pillarLabels?: Record<ClubPillar, string>;
  /** Fields collected by the club's unique registration form (before joining the WhatsApp group). */
  registrationFields: {
    key: string;
    label: string;
    placeholder?: string;
    multiline?: boolean;
  }[];
};

export type ClubsCatalog = {
  clubs: Club[];
  subClubs: Club[];
};

const CLUBS_ERROR =
  "Clubs couldn't be loaded — check your connection and try again.";

let request: Promise<ClubsCatalog> | null = null;

/** One request per app session; every hook reuses the same promise. */
export function fetchClubs(): Promise<ClubsCatalog> {
  if (!request) {
    request = fetch(`${API_BASE}/api/clubs`)
      .then(async (res) => {
        if (!res.ok) throw new Error(`clubs api ${res.status}`);
        const json = (await res.json()) as Partial<ClubsCatalog>;
        const clubs = Array.isArray(json.clubs) ? json.clubs : [];
        const subClubs = Array.isArray(json.subClubs) ? json.subClubs : [];
        if (clubs.length === 0) throw new Error("clubs api returned no clubs");
        return { clubs, subClubs };
      })
      .catch((err: unknown) => {
        request = null; // the next caller retries
        throw err;
      });
  }
  return request;
}

/** Group a club's programs by pillar. Clubs whose programs carry no pillar
 *  (Sprout) come back as a single unnamed group. */
export function programsByPillar(
  club: Club,
): { pillar: ClubPillar | null; label: string | null; programs: ClubProgram[] }[] {
  const grouped: {
    pillar: ClubPillar | null;
    label: string | null;
    programs: ClubProgram[];
  }[] = PILLARS.map((pillar) => ({
    pillar,
    label: club.pillarLabels?.[pillar] ?? null,
    programs: club.programs.filter((p) => p.pillar === pillar),
  })).filter((g) => g.programs.length > 0);

  const ungrouped = club.programs.filter((p) => !p.pillar);
  if (ungrouped.length > 0) grouped.push({ pillar: null, label: null, programs: ungrouped });
  return grouped;
}

export type UseClubs = {
  clubs: Club[];
  subClubs: Club[];
  /** Clubs first, then Sprout classes — registry order. */
  allClubs: Club[];
  /** Slug lookup across clubs and classes; undefined while loading or unknown. */
  find: (slug?: string | null) => Club | undefined;
  loading: boolean;
  error: string | null;
};

/** Full catalogue for screens that render lists or resolve slugs. */
export function useClubs(): UseClubs {
  const [catalog, setCatalog] = useState<ClubsCatalog | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    fetchClubs()
      .then((data) => {
        if (!cancelled) setCatalog(data);
      })
      .catch(() => {
        if (!cancelled) setError(CLUBS_ERROR);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const allClubs = useMemo(
    () => (catalog ? [...catalog.clubs, ...catalog.subClubs] : []),
    [catalog],
  );
  const find = useMemo(
    () => (slug?: string | null) =>
      slug ? allClubs.find((c) => c.slug === slug) : undefined,
    [allClubs],
  );

  return {
    clubs: catalog?.clubs ?? [],
    subClubs: catalog?.subClubs ?? [],
    allClubs,
    find,
    loading,
    error,
  };
}

/** Single club (or Sprout class) for detail screens. */
export function useClub(slug?: string | null): {
  club: Club | undefined;
  loading: boolean;
  error: string | null;
} {
  const { find, loading, error } = useClubs();
  return { club: find(slug), loading, error };
}

/** Sprout age classes (kids / tweens / teens) under a parent club. */
export function useClubClasses(slug?: string | null): {
  classes: Club[];
  loading: boolean;
  error: string | null;
} {
  const { subClubs, loading, error } = useClubs();
  return {
    classes: useMemo(
      () => (slug ? subClubs.filter((c) => c.parentSlug === slug) : []),
      [subClubs, slug],
    ),
    loading,
    error,
  };
}
