import { cachedFetch, type CachedFetchOptions } from "@/services/cache";

/**
 * Club membership — the app's access layer for POST/GET /api/club-join.
 *
 * Joining a club issues a Membership ID (e.g. SUR5K2MQ); GET /api/club-join/me
 * returns the signed-in member's latest membership after running the age
 * ladder (members who outgrew their club are promoted first).
 */

export type ClubMembership = {
  id: string;
  reference?: string;
  clubSlug?: string;
  clubName?: string;
  name?: string;
  age?: number | string;
  gender?: string;
  phone?: string;
  area?: string;
  interests?: string[];
  teamId?: string;
  teamName?: string;
  sport?: string;
  status?: string;
  joinedAt?: string;
};

export type ClubJoinInput = {
  clubSlug: string;
  clubName?: string;
  name: string;
  age: number;
  gender: string;
  phone: string;
  area?: string;
  interests?: string[];
  guardian?: { name: string; phone: string };
  parentConsent?: boolean;
  conduct: {
    alcohol: "yes" | "no";
    smoking: "yes" | "no";
    drugs: "yes" | "no";
    sexualActivity?: "yes" | "no";
  };
  commitmentAccepted: boolean;
  clubGatheringAccepted?: boolean;
};

export type ClubJoinResult = {
  id: string;
  reference?: string;
  status: string;
  nextSteps?: string;
};

async function apiFetch<T>(path: string, options: CachedFetchOptions = {}): Promise<T> {
  return cachedFetch<T>(path, options, ["/api/club-join"]);
}

export const clubJoinApi = {
  /** Latest membership for the signed-in user (null when not a member). */
  me: (options: { forceRefresh?: boolean } = {}) =>
    apiFetch<{ data: ClubMembership | null }>("/api/club-join/me", {
      cacheTtl: 60_000,
      forceRefresh: options.forceRefresh,
    }),
  /** Join a club — creates the membership row and issues the Membership ID. */
  join: (input: ClubJoinInput) =>
    apiFetch<ClubJoinResult>("/api/club-join", {
      method: "POST",
      body: JSON.stringify(input),
      cacheTtl: 0,
    }),
};

/**
 * Sprout's age classes in band order — a Sprout registration belongs to the
 * class whose band contains the member's age.
 */
const SPROUT_CLASSES = [
  { slug: "sprout-kids", min: 6, max: 8 },
  { slug: "sprout-tweens", min: 9, max: 12 },
  { slug: "sprout-teens", min: 13, max: 16 },
] as const;

/** The Sprout class a child of this age belongs to, or null outside 6–16. */
export function sproutClassSlugForAge(
  age: number | string | null | undefined,
): string | null {
  const n = Math.trunc(Number(age));
  if (!Number.isInteger(n)) return null;
  for (const c of SPROUT_CLASSES) if (n >= c.min && n <= c.max) return c.slug;
  return null;
}

/**
 * The club a membership actually lives in. Legacy rows joined "sprout" as a
 * whole — those resolve to their age class, so every view can say which
 * Sprout club the member is in.
 */
export function effectiveClubSlug(m: ClubMembership | null | undefined): string {
  const slug = m?.clubSlug ?? "";
  if (slug !== "sprout") return slug;
  return sproutClassSlugForAge(m?.age) ?? "sprout";
}

/** True when the membership belongs to `clubSlug` (Sprout umbrella ↔ class aware). */
export function membershipCoversClub(
  m: ClubMembership | null | undefined,
  clubSlug: string,
): boolean {
  if (!m || m.status === "graduated" || !clubSlug) return false;
  const eff = effectiveClubSlug(m);
  if (eff === clubSlug) return true;
  // The Sprout umbrella page counts any Sprout class member as a member.
  return clubSlug === "sprout" && eff.startsWith("sprout-");
}
